113	export function orderMoney(args: { monthlyCents: number; termMonths: DedicatedTerm; setupCents: number; taxRatePercent: number; taxCountry?: string }): DedicatedOrderMoney {
114	  const monthlyCents = Math.max(0, Math.round(args.monthlyCents));
115	  const setupCents = Math.max(0, Math.round(args.setupCents));
116	  const termCents = monthlyCents * args.termMonths;
117	  const netCents = termCents + setupCents;
118	  const rate = Number.isFinite(args.taxRatePercent) && args.taxRatePercent > 0 ? args.taxRatePercent : 0;
119	  const taxCents = Math.round((netCents * rate) / 100);
120	  return { monthlyCents, termMonths: args.termMonths, termCents, setupCents, netCents, taxCents, taxRatePercent: rate, taxCountry: rate > 0 ? args.taxCountry ?? "" : "", totalCents: netCents + taxCents };
121	}
