123	/** Parse a price stamped into Stripe metadata (null when malformed). */
124	export function parseStampedMoney(raw: unknown): DedicatedOrderMoney | null {
125	  if (!raw || typeof raw !== "object") return null;
126	  const r = raw as Record<string, unknown>;
127	  const int = (v: unknown) => (typeof v === "number" && Number.isInteger(v) && v >= 0 ? v : null);
128	  const monthly = int(r.monthlyCents), setup = int(r.setupCents), total = int(r.totalCents), tax = int(r.taxCents);
129	  const term = r.termMonths === 1 || r.termMonths === 12 ? r.termMonths : null;
130	  if (monthly == null || setup == null || total == null || tax == null || term == null) return null;
131	  const rate = typeof r.taxRatePercent === "number" && Number.isFinite(r.taxRatePercent) ? r.taxRatePercent : 0;
132	  const m = orderMoney({ monthlyCents: monthly, termMonths: term, setupCents: setup, taxRatePercent: 0 });
133	  // Re-derive the totals; refuse a stamp whose arithmetic doesn't add up.
134	  if (m.netCents + tax !== total) return null;
135	  return { ...m, taxCents: tax, taxRatePercent: rate, taxCountry: typeof r.taxCountry === "string" ? r.taxCountry.slice(0, 2) : "", totalCents: total };
136	}
