138	/** Renewal date for a term starting at `from` (calendar months, clamped to month end). */
139	export function addMonths(from: Date, months: number): Date {
140	  const d = new Date(from.getTime());
141	  const day = d.getUTCDate();
142	  d.setUTCDate(1);
143	  d.setUTCMonth(d.getUTCMonth() + months);
144	  const last = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();
145	  d.setUTCDate(Math.min(day, last));
146	  return d;
147	}
