356	/** Regions (offered, not hidden) for one item with "any combo in stock" and the default price. */
357	function regionsFor(it: ItemWithOptions, rows: AvailRow[], rules: PricingRules, enabled: Set<string>): OrderRegion[] {
358	  const any = stockByDc(rows);
359	  const price = priceView(it, rules);
360	  return itemRegions(it.datacenters, any, enabled, it.hiddenRegions)
361	    .filter((r) => r.offered && !r.hidden && !r.code.startsWith("unmapped:"))
362	    .map((r) => ({
363	      code: r.code,
364	      label: r.customerLabel,
365	      area: r.area,
366	      country: r.country,
367	      itemId: it.id,
368	      // In stock = at least one combination of THIS item's own memory x storage
369	      // options is deliverable within 24h (the feed also lists configurations the
370	      // item does not sell, so "any row in stock" is not enough).
371	      inStock: r.dcs.some((dc) => orderableStock(any.get(dc))) && anyComboInStock(it, rows, r.dcs),
372	      fromMonthlyCents: price.sellMonthly,
373	      setupCents: price.sellSetup,
374	    }));
