377	/** The catalogue: one card per hardware build, regional variants merged (cheapest per region wins). */
378	export async function loadOrderCatalog(previewAll: boolean): Promise<OrderCatalogCard[]> {
379	  const { rules, enabledRegions } = await loadRules();
380	  const items = await loadItems(previewAll);
381	  const avail = await loadAvailability(items.map((i) => i.planCode));
382	  const groups = new Map<string, OrderCatalogCard>();
383	  for (const it of items) {
384	    const regions = regionsFor(it, avail.get(it.planCode) ?? [], rules, enabledRegions);
385	    if (!regions.length) continue;
386	    const key = hardwareKey(it);
387	    const g = groups.get(key);
388	    if (!g) {
389	      groups.set(key, { ...cardBase(it), regions, fromMonthlyCents: Math.min(...regions.map((r) => r.fromMonthlyCents)) });
390	      continue;
391	    }
392	    for (const r of regions) {
393	      const have = g.regions.find((x) => x.code === r.code);
394	      if (!have) g.regions.push(r);
395	      else if ((r.inStock && !have.inStock) || (r.inStock === have.inStock && r.fromMonthlyCents < have.fromMonthlyCents)) Object.assign(have, r);
396	    }
397	  }
398	  const out = [...groups.values()];
399	  for (const c of out) {
400	    const inStock = c.regions.filter((r) => r.inStock);
401	    c.fromMonthlyCents = Math.min(...(inStock.length ? inStock : c.regions).map((r) => r.fromMonthlyCents));
402	    c.regions.sort((a, b) => Number(b.inStock) - Number(a.inStock) || a.label.localeCompare(b.label));
403	  }
404	  return out.sort((a, b) => a.fromMonthlyCents - b.fromMonthlyCents);
405	}
