407	/** One build for the configurator (null when it is not orderable by this viewer). */
408	export async function loadOrderBuild(id: string, previewAll: boolean): Promise<OrderBuild | null> {
409	  const seed = await db.dedicatedCatalogItem.findFirst({ where: { id, removedAt: null, currency: "USD", ...(previewAll ? {} : { visible: true }) }, include: { options: true } });
410	  if (!seed) return null;
411	  const key = hardwareKey(seed);
412	  const { rules, enabledRegions } = await loadRules();
413	  const siblings = (await loadItems(previewAll, { cpuModel: seed.cpuModel, cpuBrand: seed.cpuBrand })).filter((it) => hardwareKey(it) === key);
414	  const avail = await loadAvailability(siblings.map((i) => i.planCode));
415	  const byRegion = new Map<string, OrderVariant & { _rank: number }>();
416	  for (const it of siblings) {
417	    const rows = avail.get(it.planCode) ?? [];
418	    const mems = fam(it, "memory");
419	    const disks = fam(it, "storage");
420	    const bws = fam(it, "bandwidth");
421	    const memList: (DedicatedCatalogOption | null)[] = mems.length ? mems : [null];
422	    const diskList: (DedicatedCatalogOption | null)[] = disks.length ? disks : [null];
423	    const bwList: (DedicatedCatalogOption | null)[] = bws.length ? bws : [null];
424	    const base = sellFor(it, rules, defaultOf(it, "memory"), defaultOf(it, "storage"), defaultOf(it, "bandwidth"));
425	    const extra = (f: "memory" | "storage" | "bandwidth", o: DedicatedCatalogOption) =>
426	      sellFor(it, rules, f === "memory" ? o : defaultOf(it, "memory"), f === "storage" ? o : defaultOf(it, "storage"), f === "bandwidth" ? o : defaultOf(it, "bandwidth")).sellMonthly - base.sellMonthly;
427	    const view = (f: "memory" | "storage" | "bandwidth", list: DedicatedCatalogOption[]): OrderOption[] =>
428	      list
429	        .map((o) => ({ id: o.id, label: optLabel(o), isDefault: o.id === defaultOf(it, f)?.id, extraMonthlyCents: Math.max(0, extra(f, o)), ramGb: o.ramGb }))
430	        .sort((a, b) => a.extraMonthlyCents - b.extraMonthlyCents);
431	    for (const r of itemRegions(it.datacenters, stockByDc(rows), enabledRegions, it.hiddenRegions)) {
432	      if (!r.offered || r.hidden || r.code.startsWith("unmapped:")) continue;
433	      const inStock: string[] = [];
434	      const prices: Record<string, number> = {};
435	      for (const m of memList) for (const d of diskList) {
436	        if (!orderableStock(comboStock(rows, r.dcs, m, d).code)) continue;
437	        inStock.push(`${m?.id ?? ""}|${d?.id ?? ""}`);
438	        for (const b of bwList) prices[`${m?.id ?? ""}|${d?.id ?? ""}|${b?.id ?? ""}`] = sellFor(it, rules, m, d, b).sellMonthly;
439	      }
440	      const v: OrderVariant & { _rank: number } = {
441	        region: r.code, label: r.customerLabel, area: r.area, country: r.country, itemId: it.id, setupCents: base.sellSetup,
442	        memory: view("memory", mems), storage: view("storage", disks), bandwidth: view("bandwidth", bws), inStock, prices,
443	        _rank: (inStock.length ? 0 : 1e9) + base.sellMonthly,
444	      };
445	      const prev = byRegion.get(r.code);
446	      if (!prev || v._rank < prev._rank) byRegion.set(r.code, v);
447	    }
448	  }
449	  if (byRegion.size === 0) return null;
450	  const variants = [...byRegion.values()].map(({ _rank, ...v }) => v);
451	  variants.sort((a, b) => Number(b.inStock.length > 0) - Number(a.inStock.length > 0) || a.label.localeCompare(b.label));
452	  const card = cardBase(seed);
453	  const all = variants.flatMap((v) => Object.values(v.prices));
454	  return { ...card, fromMonthlyCents: all.length ? Math.min(...all) : priceView(seed, rules).sellMonthly, variants };
455	}
