512	/**
513	 * Re-price an intent from the catalogue + pricing rules. Throws DedicatedOrderError
514	 * with a customer-safe message when the build, region, option or stock is not orderable.
515	 * `requireStock` is false only at card-leg fulfilment (the card already cleared; a
516	 * stock change in the meantime is handled by staff, never by eating the payment).
517	 */
518	export async function quoteDedicatedOrder(
519	  intent: DedicatedOrderIntent,
520	  user: Pick<User, "billingCountry" | "vatId">,
521	  opts: { previewAll: boolean; requireStock?: boolean },
522	): Promise<InternalQuote> {
523	  const item = await db.dedicatedCatalogItem.findFirst({
524	    where: { id: intent.itemId, currency: "USD", ...(opts.requireStock === false ? {} : { removedAt: null, ...(opts.previewAll ? {} : { visible: true }) }) },
525	    include: { options: true },
526	  });
527	  if (!item) throw new DedicatedOrderError("This build is no longer available.");
528	  const os = osById(intent.os);
529	  if (!os) throw new DedicatedOrderError("Pick an operating system.");
530	  const region = regionByCode(intent.region);
531	  if (!region) throw new DedicatedOrderError("Pick a location.");
532	  const { rules, enabledRegions } = await loadRules();
533	  const rows = (await loadAvailability([item.planCode])).get(item.planCode) ?? [];
534	  const regionRow = itemRegions(item.datacenters, stockByDc(rows), enabledRegions, item.hiddenRegions).find((r) => r.code === intent.region);
535	  if (!regionRow || (opts.requireStock !== false && (!regionRow.offered || regionRow.hidden))) throw new DedicatedOrderError("This build isn't offered in that location.");
536	
537	  const memory = pickOption(item, "memory", intent.memoryId);
538	  const storage = pickOption(item, "storage", intent.storageId);
539	  const bandwidth = pickOption(item, "bandwidth", intent.bandwidthId);
540	  const st = comboStock(rows, regionRow.dcs, memory, storage);
541	  const stock = publicStock(st.code);
542	  if (opts.requireStock !== false && !orderableStock(st.code)) {
543	    throw new DedicatedOrderError(`That configuration isn't in stock in ${region.customerLabel} right now. Try another memory or storage choice, or another location.`);
544	  }
545	  const price = sellFor(item, rules, memory, storage, bandwidth);
546	  const tax = await taxContextForUser(user);
547	  const money = orderMoney({ monthlyCents: price.sellMonthly, termMonths: intent.termMonths, setupCents: price.sellSetup, taxRatePercent: tax.ratePercent, taxCountry: tax.country });
548	  const fallbackDc = regionRow.dcs[0] ?? null;
549	  return {
550	    item,
551	    memory,
552	    storage,
553	    bandwidth,
554	    datacenter: st.dc ?? fallbackDc,
555	    costMonthlyCents: price.costMonthly,
556	    stock,
557	    spec: {
558	      cpu: cpuText(item),
559	      cores: item.cpuCores * Math.max(1, item.cpuCount),
560	      threads: item.cpuThreads * Math.max(1, item.cpuCount),
561	      ramGb: memory?.ramGb ?? item.defaultRamGb ?? 0,
562	      storage: storage ? optLabel(storage) : brandSafe(item.defaultStorage),
563	      bandwidth: bandwidth ? optLabel(bandwidth) : item.defaultBandwidthMbps ? `${bwText(item.defaultBandwidthMbps)} public bandwidth` : "",
564	      gpu: defaultOf(item, "gpu") ? brandSafe(defaultOf(item, "gpu")!.label) : null,
565	    },
566	    regionLabel: region.customerLabel,
567	    osLabel: os.label,
568	    money,
569	  };
570	}
