574	/** Claim an order key exactly once (FulfilledSession's UNIQUE id is the lock). */
575	async function claimOrderKey(userId: string, orderKey: string): Promise<boolean> {
576	  try {
577	    await db.fulfilledSession.create({ data: { stripeSessionId: `dedorder:${userId}:${orderKey}`, kind: "dedicatedOrder" } });
578	    return true;
579	  } catch (e) {
580	    if ((e as { code?: string })?.code === "P2002") return false;
581	    throw e;
582	  }
583	}
