585	/**
586	 * Debit the wallet for the order total, write the PAID invoice and the PENDING
587	 * DedicatedServer row — one transaction. `sold` is the price stamped before a card
588	 * leg cleared (fulfilment path); omitted on the wallet-only path, where the price
589	 * is the fresh quote taken in the same request. Idempotent on intent.orderKey:
590	 * a repeat returns the server created the first time.
591	 */
592	export async function placeDedicatedOrder(
593	  user: User,
594	  intent: DedicatedOrderIntent,
595	  opts: { previewAll: boolean; sold?: DedicatedOrderMoney | null; via: "wallet" | "card" },
596	): Promise<{ serverId: string; created: boolean }> {
597	  const existing = await db.dedicatedServer.findFirst({ where: { userId: user.id, orderKey: intent.orderKey }, select: { id: true } });
598	  if (existing) return { serverId: existing.id, created: false };
599	
600	  const q = await quoteDedicatedOrder(intent, user, { previewAll: opts.previewAll, requireStock: opts.via === "wallet" });
601	  const money = opts.sold ?? q.money;
602	  if (!(await claimOrderKey(user.id, intent.orderKey))) {
603	    const again = await db.dedicatedServer.findFirst({ where: { userId: user.id, orderKey: intent.orderKey }, select: { id: true } });
604	    if (again) return { serverId: again.id, created: false };
605	    throw new DedicatedOrderError("This order is already being placed. Refresh in a moment.");
606	  }
607	
608	  const now = new Date();
609	  const renewalDate = addMonths(now, money.termMonths);
610	  const label = intent.label || `${q.spec.cpu.replace(/^(AMD|Intel)\s+/i, "")} · ${q.regionLabel}`;
611	  const desc = `Dedicated server — ${label}`;
612	  const lines = [
613	    {
614	      description:
615	        `${q.spec.cpu}, ${q.spec.ramGb} GB RAM, ${q.spec.storage}${q.spec.bandwidth ? `, ${q.spec.bandwidth}` : ""} · ${q.regionLabel} · ${q.osLabel}\n` +
616	        `${termLabel(money.termMonths)} term · renews ${renewalLabel(money.monthlyCents, money.termMonths)} on ${renewalDate.toISOString().slice(0, 10)}`,
617	      qty: 1,
618	      unitCents: money.termCents,
619	      amountCents: money.termCents,
620	    },
621	    ...(money.setupCents > 0 ? [{ description: "One-time setup", qty: 1, unitCents: money.setupCents, amountCents: money.setupCents }] : []),
622	  ];
623	  const orderConfig = {
624	    via: opts.via,
625	    catalogItemId: q.item.id,
626	    planCode: q.item.planCode, // ADMIN-ONLY (orderConfig never reaches a customer view)
627	    memory: q.memory ? { id: q.memory.id, label: q.memory.label, productCode: q.memory.productCode } : null,
628	    storage: q.storage ? { id: q.storage.id, label: q.storage.label, productCode: q.storage.productCode } : null,
629	    bandwidth: q.bandwidth ? { id: q.bandwidth.id, label: q.bandwidth.label, productCode: q.bandwidth.productCode } : null,
630	    os: intent.os,
631	    osLabel: q.osLabel,
632	    region: intent.region,
633	    datacenter: q.datacenter,
634	    stockAtOrder: q.stock,
635	    money,
636	  };
637	
638	  try {
639	    const serverId = await db.$transaction(async (tx) => {
640	      await assertSpendCap(user, money.totalCents, tx);
641	      await debitWallet(tx, user.id, money.totalCents);
642	      await tx.walletTransaction.create({ data: { userId: user.id, amountCents: -money.totalCents, description: desc.slice(0, 190) } });
643	      const inv = await tx.invoice.create({
644	        data: invoiceCreateData({
645	          userId: user.id,
646	          description: desc.slice(0, 190),
647	          status: "PAID",
648	          lineItems: lines,
649	          taxCents: money.taxCents,
650	          taxRatePercent: money.taxRatePercent,
651	          taxCountry: money.taxCountry || null,
652	          period: { start: now, end: renewalDate },
653	        }),
654	        select: { id: true },
655	      });
656	      const s = await tx.dedicatedServer.create({
657	        data: {
658	          userId: user.id,
659	          label,
660	          catalogItemId: q.item.id,
661	          cpu: q.spec.cpu,
662	          cores: q.spec.cores,
663	          threads: q.spec.threads,
664	          ramGb: q.spec.ramGb,
665	          storage: q.spec.storage,
666	          bandwidth: q.spec.bandwidth,
667	          region: intent.region,
668	          datacenter: q.datacenter,
669	          costMonthlyCents: q.costMonthlyCents,
670	          os: q.osLabel,
671	          status: "PENDING",
672	          renewalDate,
673	          renewalMonthlyCents: money.monthlyCents,
674	          termMonths: money.termMonths,
675	          setupFeeCents: money.setupCents,
676	          invoiceIds: [inv.id],
677	          orderKey: intent.orderKey,
678	          orderConfig: orderConfig as object,
679	          notes: `Ordered online (${opts.via}). Build: ${q.item.planCode} in ${q.datacenter ?? "?"}; memory ${q.memory?.label ?? "default"}; storage ${q.storage?.label ?? "default"}; bandwidth ${q.bandwidth?.label ?? "default"}; OS ${q.osLabel}. Stock at order: ${q.stock}.`,
680	        },
681	        select: { id: true },
682	      });
683	      await tx.dedicatedServerEvent.create({ data: { dedicatedServerId: s.id, actorId: user.id, action: "ordered", detail: `paid ${money.totalCents}c via ${opts.via}; invoice ${inv.id}` } });
684	      await tx.auditLog.create({ data: { userId: user.id, action: "dedicated.order", detail: `${s.id} item=${q.item.id} region=${intent.region} total=${money.totalCents} via=${opts.via}` } });
685	      return s.id;
686	    });
687	
688	    // Best-effort notices (never undo a placed, paid order).
689	    try {
690	      await db.notification.create({
691	        data: { userId: user.id, title: "Dedicated server ordered", body: `We're building ${label}. It will be online within 24 hours; we'll post its IP and login on the server page.`, href: `/dashboard/dedicated/${serverId}` },
692	      });
693	      const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
694	      if (admins.length) {
695	        await db.notification.createMany({
696	          data: admins.map((a) => ({ userId: a.id, title: `New dedicated server order: ${label}`, body: `${user.email} paid ${renewalLabel(money.monthlyCents, money.termMonths)} (${q.regionLabel}). Build it by hand.`, href: `/admin/dedicated/servers/${serverId}` })),
697	        });
698	      }
699	    } catch {
700	      /* notices are best-effort */
701	    }
702	    return { serverId, created: true };
703	  } catch (e) {
704	    // Release the claim so a retry (after a top-up) can place the order.
705	    await db.fulfilledSession.delete({ where: { stripeSessionId: `dedorder:${user.id}:${intent.orderKey}` } }).catch(() => {});
706	    if (e instanceof InsufficientBalanceError) throw new DedicatedOrderError("Insufficient balance. Top up your wallet or pay the rest by card.");
707	    if (e instanceof SpendCapError) throw new DedicatedOrderError(e.message);
708	    throw e;
709	  }
710	}
