import Link from "next/link";
import type { Metadata } from "next";
import { requireDedicatedAccess } from "@/lib/dedicated/gate";
import { requireUser } from "@/lib/auth";
import { loadCustomerServers } from "@/lib/dedicated/customer-data";
import { PageShell } from "@/components/nx/PageShell";
import { DedicatedServerList } from "@/components/dedicated/DedicatedServerList";

/** Customer dedicated servers. 404 unless public OR a private-preview account (lib/dedicated/gate.ts). */
export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Dedicated servers", robots: { index: false, follow: false } };

export default async function DedicatedServersDashboard({ searchParams }: { searchParams: Promise<{ paid?: string }> }) {
  await requireDedicatedAccess();
  const user = await requireUser();
  const [servers, sp] = await Promise.all([loadCustomerServers(user.id), searchParams]);
  return (
    <PageShell narrow eyebrow="Dedicated" title="Dedicated servers" sub="Single-tenant machines, built and looked after by our team."
      tagline={["YOUR HARDWARE.", "OUR ENGINEERS."]}
      action={servers.length > 0 ? <Link href="/dashboard/dedicated/order" className="btn-primary btn-sm">Order a server <span aria-hidden>→</span></Link> : undefined}>
      {sp.paid === "1" && (
        <p className="rounded-[12px] border border-[rgba(255,196,70,0.38)] bg-[rgba(60,40,0,0.45)] px-3.5 py-2.5 text-[12.5px] text-[#f1d28a]" role="status">
          Your payment went through and is safe in your wallet, but we couldn&apos;t finish placing the order. Our team has been alerted. <Link href="/dashboard/support" className="font-bold underline">Contact support</Link> and we&apos;ll sort it out.
        </p>
      )}
      <DedicatedServerList servers={servers} />
    </PageShell>
  );
}
