/**
 * DB loaders for the customer dedicated-server dashboard (and its admin preview).
 * Always returns the brand-safe projections from customer-view.ts.
 */
import type { DedicatedServer } from "@prisma/client";
import { db } from "../db";
import { toCustomerServerView, type CustomerInvoiceRow, type CustomerServerView } from "./customer-view";

export async function loadCustomerServers(userId: string): Promise<CustomerServerView[]> {
  const rows = await db.dedicatedServer.findMany({
    where: { userId, status: { not: "CANCELLED" } },
    include: { requests: { where: { status: "OPEN" }, select: { id: true, kind: true, status: true, createdAt: true } } },
    orderBy: { createdAt: "desc" },
  });
  return rows.map((r) => toCustomerServerView(r, r.requests));
}

/** One server, ONLY if it belongs to `userId` (pass null from the admin preview to skip the owner check). */
export async function loadCustomerServer(id: string, userId: string | null): Promise<{ view: CustomerServerView; invoices: CustomerInvoiceRow[] } | null> {
  const s = await db.dedicatedServer.findUnique({ where: { id }, include: { requests: { select: { id: true, kind: true, status: true, createdAt: true } } } });
  if (!s || (userId !== null && s.userId !== userId)) return null;
  const invoices = s.invoiceIds.length
    ? await db.invoice.findMany({ where: { id: { in: s.invoiceIds }, userId: s.userId }, orderBy: { createdAt: "desc" }, select: { id: true, number: true, description: true, amountCents: true, status: true, createdAt: true } })
    : [];
  return {
    view: toCustomerServerView(s, s.requests),
    invoices: invoices.map((i) => ({ ...i, status: String(i.status), createdAt: i.createdAt.toISOString() })),
  };
}

