function WhatNext() {
  const steps = [
    { icon: "card", t: "You pay", d: "Your machine is reserved the moment payment clears." },
    { icon: "gear", t: "We build it", d: "Our engineers install your OS, harden it and run burn-in checks." },
    { icon: "checkcircle", t: "Online within 24 hours", d: "Its IP addresses and your login appear on its dashboard." },
  ];
  return (
    <div className="rounded-[12px] border border-rim bg-surface p-3.5">
      <span className="nx-label uppercase">What happens next</span>
