"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): automated controls for a delivered
 * dedicated server — live status, power, rescue, OS reinstall, reverse DNS,
 * firewall and extra IPs. Every button ENQUEUES a job
 * (lib/actions-dedicated-ops.ts); the worker carries it out and this panel
 * polls its progress. Nothing here talks to an upstream API.
 */
import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import type { CustomerJob, DedicatedPanel } from "@/lib/actions-dedicated-ops";
import type { LiveIp } from "@/lib/dedicated/live";
import { enqueueDedicatedAction, loadDedicatedPanel, payDedicatedExtraIps, pollDedicatedJobs, quoteDedicatedExtraIps, revealDedicatedRescueSecret } from "@/lib/actions-dedicated-ops";
import { isTerminal, JOB_STATUS_LABEL } from "@/lib/dedicated/ops-core";
import { Icon } from "@/components/nx/Icon";
import { Panel } from "@/components/nx/PageShell";
import { NxCardFields } from "@/components/nx/NxCardFields";

const usd = (c: number) => `$${(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const when = (iso: string) => new Date(iso).toLocaleString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
const FIELD = "h-[38px] w-full rounded-[10px] border border-rim-hi bg-[rgba(4,11,30,.8)] px-3 text-[13px] text-white outline-none placeholder:text-tx-faint focus:border-brand-400/70";

function newKey(): string {
  const a = new Uint8Array(16);
  crypto.getRandomValues(a);
  return Array.from(a, (b) => b.toString(16).padStart(2, "0")).join("");
}

type Tab = "overview" | "power" | "reinstall" | "network";

export function DedicatedControlPanel({ serverId, label, primaryIp, initial }: { serverId: string; label: string; primaryIp: string | null; initial: DedicatedPanel | null }) {
  const router = useRouter();
  const [panel, setPanel] = useState<DedicatedPanel | null>(initial);
  const [jobs, setJobs] = useState<CustomerJob[]>(initial?.jobs ?? []);
  const [tab, setTab] = useState<Tab>("overview");
  const [msg, setMsg] = useState<{ tone: "ok" | "bad"; text: string } | null>(null);
  const [busy, start] = useTransition();
  const active = jobs.some((j) => !isTerminal(j.status));

  const refresh = useCallback(async (fresh = true) => {
    const p = await loadDedicatedPanel(serverId, fresh);
    if (p.ok) { setPanel(p); setJobs(p.jobs); }
  }, [serverId]);

  // Poll while something runs; refresh the live view when a job finishes.
  const wasActive = useRef(active);
  useEffect(() => {
    if (!active) {
      if (wasActive.current) void refresh(true);
      wasActive.current = false;
      return;
    }
    wasActive.current = true;
    const t = setInterval(async () => {
      const r = await pollDedicatedJobs(serverId);
      if (r.ok) setJobs(r.jobs);
    }, 3500);
    return () => clearInterval(t);
  }, [active, serverId, refresh]);

  const run = (kind: string, input: Record<string, unknown> = {}, okText?: string) =>
    start(async () => {
      setMsg(null);
      const r = await enqueueDedicatedAction(serverId, kind, input);
      if (!r.ok) { setMsg({ tone: "bad", text: r.error }); return; }
      setMsg({ tone: "ok", text: okText ?? "Started. Progress shows below." });
      const p = await pollDedicatedJobs(serverId);
      if (p.ok) setJobs(p.jobs);
      router.refresh();
    });

  if (!panel) {
    return (
      <Panel title="Server controls">
        <p className="text-[12.5px] text-tx-mute">Controls are unavailable right now. <Link href="/dashboard/support" className="font-semibold text-[#8dbde8] hover:text-white">Contact support</Link> if you need anything done on this server.</p>
      </Panel>
    );
  }
  const live = panel.live;
  const tabs: { k: Tab; t: string; icon: string }[] = [
    { k: "overview", t: "Overview", icon: "activity" },
    { k: "power", t: "Power & rescue", icon: "bolt" },
    { k: "reinstall", t: "Reinstall", icon: "terminal" },
    { k: "network", t: "Network", icon: "nodes" },
  ];

  return (
    <section className="card flex min-w-0 flex-col gap-4 p-4" aria-label="Server controls">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <span className="flex flex-col gap-0.5">
          <span className="text-[15px] font-extrabold tracking-[-0.02em] text-white">Server controls</span>
          <span className="text-[11.5px] text-tx-faint">Carried out automatically, usually within a minute or two.</span>
        </span>
        {panel.mode !== "live" && (
          <span className={"chip-tone " + (panel.mode === "mock" ? "chip-violet" : "chip-amber")} title={panel.mode === "dry" ? "Actions are recorded but nothing is sent to the machine yet." : "Demo machine: actions run against a simulated server."}>
            {panel.mode === "mock" ? "Demo machine" : panel.mode === "dry" ? "Test mode: nothing is sent" : "Unavailable"}
          </span>
        )}
      </div>

      <div className="noscroll -mx-1 flex gap-1 overflow-x-auto px-1" role="tablist">
        {tabs.map((t) => (
          <button key={t.k} type="button" role="tab" aria-selected={tab === t.k} onClick={() => setTab(t.k)} className={"chip flex-none " + (tab === t.k ? "chip-on" : "")}>
            <Icon name={t.icon} size={12} tone="inherit" />{t.t}
          </button>
        ))}
      </div>

      {msg && (
        <p role="status" className={"rounded-[10px] border px-3 py-2 text-[12.5px] " + (msg.tone === "ok" ? "border-[rgba(17,200,142,0.35)] bg-[rgba(4,40,30,0.45)] text-tx-body" : "border-[rgba(239,66,108,0.35)] bg-[rgba(60,10,26,0.45)] text-[#ffc2d1]")}>{msg.text}</p>
      )}

      {tab === "overview" && <Overview panel={panel} />}
      {tab === "power" && <Power panel={panel} busy={busy || active} run={run} serverId={serverId} primaryIp={primaryIp} />}
      {tab === "reinstall" && <Reinstall panel={panel} busy={busy || active} run={run} label={label} />}
      {tab === "network" && <Network panel={panel} busy={busy} run={run} serverId={serverId} onPaid={() => refresh(true)} />}

      <Activity jobs={jobs} />
      {!live && panel.liveError && <p className="text-[11.5px] text-tx-faint">{panel.liveError}</p>}
    </section>
  );
}

