/* ---------------- power & rescue ---------------- */

function KeySelect({ keys, value, onChange, optional }: { keys: { id: string; name: string }[]; value: string; onChange: (v: string) => void; optional?: boolean }) {
  if (!keys.length) return <p className="text-[12px] text-tx-mute">No SSH keys on your account. <Link href="/dashboard/settings?tab=ssh" className="font-semibold text-[#8dbde8] hover:text-white">Add one in Settings</Link>.</p>;
  return (
    <select value={value} onChange={(e) => onChange(e.target.value)} className={FIELD + " cursor-pointer"} aria-label="SSH key">
      {optional && <option value="">No key</option>}
      {keys.map((k) => <option key={k.id} value={k.id}>{k.name}</option>)}
    </select>
  );
}

function Power({ panel, busy, run, serverId, primaryIp }: { panel: DedicatedPanel; busy: boolean; run: (k: string, i?: Record<string, unknown>, ok?: string) => void; serverId: string; primaryIp: string | null }) {
  const [confirmReboot, setConfirmReboot] = useState(false);
  const [keyId, setKeyId] = useState(panel.sshKeys[0]?.id ?? "");
  const [secret, setSecret] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const inRescue = panel.live?.bootMode === "rescue";
  return (
    <div className="grid gap-3 lg:grid-cols-2">
      <div className="flex flex-col gap-2.5 rounded-[12px] border border-rim bg-surface p-3.5">
        <span className="flex items-center gap-2 text-[13.5px] font-bold text-white"><Icon name="refresh" size={14} />Hard reboot</span>
        <span className="text-[11.8px] text-tx-faint">Power-cycles the machine, like pressing its reset button. Unsaved data in memory is lost.</span>
        {confirmReboot ? (
          <div className="flex flex-wrap gap-2">
            <button type="button" disabled={busy} onClick={() => { setConfirmReboot(false); run("REBOOT_HARD", {}, "Rebooting. It usually takes 2 to 5 minutes."); }} className="btn-primary btn-xs">Yes, reboot now</button>
            <button type="button" onClick={() => setConfirmReboot(false)} className="btn-ghost btn-xs">Cancel</button>
          </div>
        ) : (
          <button type="button" disabled={busy} onClick={() => setConfirmReboot(true)} className="btn-ghost btn-xs w-fit">Reboot</button>
        )}
        <span className="text-[11px] text-tx-faint">A graceful restart is best done from inside the OS (<code className="font-mono">sudo reboot</code>).</span>
      </div>
      <div className="flex flex-col gap-2.5 rounded-[12px] border border-rim bg-surface p-3.5">
        <span className="flex items-center gap-2 text-[13.5px] font-bold text-white"><Icon name="lifebuoy" size={14} />Rescue mode</span>
        {inRescue ? (
          <>
            <span className="text-[11.8px] text-tx-faint">Running the rescue system. Your disks are untouched; mount them to repair or copy data.</span>
            {primaryIp && <code className="rounded-[8px] bg-well px-2.5 py-1.5 font-mono text-[12px] text-white">ssh root@{primaryIp}</code>}
            {panel.rescueSecretStored && (secret ? <code className="break-all rounded-[8px] bg-well px-2.5 py-1.5 font-mono text-[12px] text-white">{secret}</code> : (
              <button type="button" className="btn-ghost btn-xs w-fit" onClick={async () => { const r = await revealDedicatedRescueSecret(serverId); if (r.ok) setSecret(r.secret); else setErr(r.error); }}>Show rescue password</button>
            ))}
            <button type="button" disabled={busy} onClick={() => run("RESCUE_OFF", {}, "Booting back from disk.")} className="btn-primary btn-xs w-fit">Boot back to disk</button>
          </>
        ) : (
          <>
            <span className="text-[11.8px] text-tx-faint">Restarts into a recovery system loaded over the network. Log in with your SSH key.</span>
            <KeySelect keys={panel.sshKeys} value={keyId} onChange={setKeyId} optional />
            <button type="button" disabled={busy} onClick={() => run("RESCUE_ON", { sshKeyId: keyId || undefined }, "Booting into rescue mode.")} className="btn-ghost btn-xs w-fit">Boot into rescue</button>
          </>
        )}
        {err && <span className="text-[11.5px] text-[#ffc2d1]">{err}</span>}
      </div>
      <div className="flex flex-col gap-1.5 rounded-[12px] border border-dashed border-rim-hi p-3.5 lg:col-span-2">
        <span className="flex items-center gap-2 text-[13px] font-bold text-white"><Icon name="monitor" size={14} />Remote console</span>
        <span className="text-[11.8px] text-tx-faint">Need the screen and keyboard (for example if the network config is broken)? Our engineers open the out-of-band console for you. <Link href="/dashboard/support" className="font-semibold text-[#8dbde8] hover:text-white">Open a ticket</Link>.</span>
      </div>
    </div>
  );
}

