function Reinstall({ panel, busy, run, label }: { panel: DedicatedPanel; busy: boolean; run: (k: string, i?: Record<string, unknown>, ok?: string) => void; label: string }) {
  const templates = panel.live?.templates ?? [];
  const [tpl, setTpl] = useState(templates[0]?.name ?? "");
