      <span className="text-[12px] text-tx-body">This erases every disk on the server. Back up anything you need first. You log in afterwards as <b>root</b> with the SSH key you pick; no password is set.</span>
      <div className="grid gap-2.5 sm:grid-cols-3">
        <label className="flex flex-col gap-1"><span className="nx-label">Operating system</span>
          <select value={tpl} onChange={(e) => setTpl(e.target.value)} className={FIELD + " cursor-pointer"}>
