          </select>
        </label>
        <label className="flex flex-col gap-1"><span className="nx-label">Hostname</span>
          <input value={host} onChange={(e) => setHost(e.target.value)} placeholder="db1.example.com" className={FIELD} />
        </label>
        <label className="flex flex-col gap-1"><span className="nx-label">SSH key</span>
          <KeySelect keys={panel.sshKeys} value={keyId} onChange={setKeyId} />
        </label>
      </div>
      <label className="flex flex-col gap-1"><span className="nx-label">Type <b className="text-white">{label}</b> to confirm</span>
        <input value={typed} onChange={(e) => setTyped(e.target.value)} className={FIELD + " max-w-[360px]"} autoComplete="off" aria-label="Type the server name to confirm" />
      </label>
      <button type="button" disabled={!ok || busy} onClick={() => run("REINSTALL", { templateName: tpl, hostname: host, sshKeyId: keyId, confirm: typed }, "Reinstall started. It usually takes 10 to 20 minutes.")} className="btn-primary btn-sm w-fit">Erase and reinstall</button>
    </div>
  );
}

/* ---------------- network ---------------- */

function Network({ panel, busy, run, serverId, onPaid }: { panel: DedicatedPanel; busy: boolean; run: (k: string, i?: Record<string, unknown>, ok?: string) => void; serverId: string; onPaid: () => void }) {
  const ips = panel.live?.ips ?? [];
  const v4 = ips.filter((i) => i.version === 4 && i.cidr.endsWith("/32"));
  const [open, setOpen] = useState<string | null>(null);
  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-col divide-y divide-[var(--color-rim-soft)] rounded-[12px] border border-rim bg-surface">
        {ips.length === 0 && <p className="p-3 text-[12.5px] text-tx-mute">No addresses found yet.</p>}
        {ips.map((ip) => (
          <IpRow key={ip.cidr} ip={ip} open={open === ip.cidr} onToggle={() => setOpen(open === ip.cidr ? null : ip.cidr)} busy={busy} run={run} />
        ))}
      </div>
      {v4.length > 0 && <p className="text-[11px] text-tx-faint">The network firewall filters traffic before it reaches your server, on top of DDoS protection. Rules apply per IPv4 address.</p>}
      <ExtraIps panel={panel} serverId={serverId} onPaid={onPaid} />
    </div>
  );
}

function IpRow({ ip, open, onToggle, busy, run }: { ip: LiveIp; open: boolean; onToggle: () => void; busy: boolean; run: (k: string, i?: Record<string, unknown>, ok?: string) => void }) {
  const [rev, setRev] = useState(ip.reverse?.replace(/\.$/, "") ?? "");
  const [rule, setRule] = useState({ sequence: "0", action: "permit", protocol: "tcp", ports: "22", source: "" });
  const single = ip.version === 4 && ip.cidr.endsWith("/32");
  const fw = ip.firewall;
  return (
    <div className="flex flex-col gap-2 p-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <span className="flex min-w-0 items-center gap-2">
          <span className="trunc font-mono text-[13px] text-white">{single ? ip.ip : ip.cidr}</span>
          <span className={"chip-tone flex-none " + (ip.version === 6 ? "chip-violet" : "chip-blue")}>{ip.version === 6 ? "IPv6" : single ? "IPv4" : "Block"}</span>
          {fw?.exists && <span className={"chip-tone flex-none " + (fw.enabled ? "chip-mint" : "chip-slate")}>{fw.enabled ? "Firewall on" : "Firewall off"}</span>}
        </span>
        {single && <button type="button" onClick={onToggle} className="btn-ghost btn-xs">{open ? "Close" : "Manage"}</button>}
      </div>
      {single && !open && <span className="trunc text-[11.5px] text-tx-faint">Reverse DNS: {ip.reverse ? ip.reverse.replace(/\.$/, "") : "not set"}</span>}
      {single && open && (
        <div className="flex flex-col gap-3 rounded-[10px] bg-well p-3">
          <div className="flex flex-col gap-1.5">
            <span className="nx-label">Reverse DNS (PTR)</span>
