                    Configure <span aria-hidden>→</span>
                  </Link>
                </div>
              </div>
            </li>
          ))}
        </ul>
      )}
      {shown.length > limit && (
        <div className="flex flex-col items-center gap-1.5 pt-1">
          <button type="button" onClick={() => setLimit((l) => l + PAGE)} className="btn-ghost btn-sm">Show more builds</button>
          <span className="text-[11px] text-tx-faint">Showing {Math.min(limit, shown.length)} of {shown.length}</span>
        </div>
      )}
    </div>
  );
