/**
 * One customer's whole estate, normalised into a single list.
 *
 * The six products live in genuinely different tables — a VPS and a game
 * server are both `Server` rows told apart by `gamePlanId`, shared hosting is
 * a `HostingAccount`, the free Minecraft tier is its own
 * `FreeMinecraftServer`, and domains/business email are `Domain` /
 * `EmailSubscription` rows — so this is the one place that flattens them into
 * a shape a single list can render. Everything below is read from the record;
 * nothing is inferred where the data doesn't exist (hosting has no region
 * column, so its location is geo-resolved from the node's real public IP the
 * same way the primary node's location was confirmed, and is left blank when
 * that lookup can't answer; a domain/email row has no server behind it at
 * all, so its location is left blank rather than guessed).
 */
export type ServiceKind = "vps" | "game" | "hosting" | "free" | "domain" | "email";

/** The five buckets the page's stat row and status pills speak in. */
export type ServiceStatus = "running" | "pending" | "stopped" | "suspended" | "error" | "cancelled";

export type ServiceRow = {
  id: string;
  kind: ServiceKind;
  /** What the customer named it (or the domain, for hosting/domain/email). */
  name: string;
  /** Where "Manage" goes. */
  href: string;
  typeLabel: string;
  /** The address a customer actually connects on. See `connectAddress`. */
  address: string | null;
  /** What that address IS, so the row can label it rather than guess. */
  addressLabel: "IP address" | "Connect" | "Website" | null;
  /** Second line under the name — plan/specs. */
  specs: string | null;
  status: ServiceStatus;
  statusLabel: string;
  location: { label: string; country: string } | null;
  renewalIso: string | null;
  /** Partner-grant policy when this server was granted free (drives "Free until <date>"); null otherwise. */
  grant?: { onExpiry: string; status: string } | null;
  /** Per-term price in cents; null when nothing is charged (free tier). */
  renewalCents: number | null;
  /** Billing term in months, so "/mo" vs "/yr" is honest. */
  termMonths: number;
  /** Game family id, for the box-art thumbnail. */
  gameFamily: string | null;
  /** Hosting/domain/email only — the domain name the row is sold against. */
  domain: string | null;
  createdAtIso: string;

  /* ── card preview art ───────────────────────────────────────────────────
     Every card leads with a picture. Where it comes from depends on the
     product, and the rule is the same one the brief sets out: show the real
     thing if there is one, otherwise the stock plate for that product. */

  /** The image the card leads with. Never null — there is always a fallback. */
  previewSrc: string;
  /** Which of the three sources `previewSrc` came from — the card badges it. */
  previewSource: "game-art" | "customer" | "stock";
  /**
   * Hosting only: the live site can be framed over the stock plate, so a plan
   * that is actually serving something shows THAT instead of the plate. There
   * is no screenshot service behind this — it is the customer's own site or
   * the plate, never a stand-in picture of some other website.
   */
  siteToFrame: string | null;
  /** VPS rows let the customer replace the stock plate with their own image. */
  canSetPreview: boolean;
  /**
   * VPS only: what it is actually running. Every VPS on the stock plate would
   * otherwise be the same picture, and the OS is the one thing that genuinely
   * tells them apart at a glance.
   */
  os: { family: string; name: string } | null;
};

/** Tolerant status mapper: every product spells its states differently, and a
 *  new value should degrade to something sane rather than crash a list. */
function normalizeStatus(raw: string): { status: ServiceStatus; label: string } {
  const s = (raw ?? "").toUpperCase();
  if (["RUNNING", "ACTIVE", "ONLINE"].includes(s)) return { status: "running", label: "Running" };
  // The free tier's container states: READY means the container exists —
  // mc-router owns whether it is awake right now, and this list deliberately
  // doesn't claim to know that, so it says Ready rather than Running.
  if (s === "READY") return { status: "running", label: "Ready" };
  if (["PENDING", "PROVISIONING", "CREATING", "REINSTALLING", "STARTING"].includes(s)) {
    return { status: "pending", label: s === "REINSTALLING" ? "Reinstalling" : "Pending" };
  }
  if (["STOPPED", "SLEEPING", "OFFLINE"].includes(s)) {
    return { status: "stopped", label: s === "SLEEPING" ? "Asleep" : "Stopped" };
  }
  if (["SUSPENDED"].includes(s)) return { status: "suspended", label: "Suspended" };
  // Domain-only inbound-transfer states (DomainStatus) — without these two, the
  // fallback below stringifies "TRANSFER_PENDING" into "Transfer_pending".
  if (s === "TRANSFER_PENDING") return { status: "pending", label: "Transferring" };
  if (s === "TRANSFER_FAILED") return { status: "error", label: "Transfer failed" };
  if (["DELETING", "DELETED", "CANCELLED", "CANCELED", "TERMINATED", "EXPIRED"].includes(s)) {
    return { status: "cancelled", label: s === "DELETING" ? "Deleting" : "Cancelled" };
  }
  if (["ERROR", "FAILED"].includes(s)) return { status: "error", label: "Failed" };
  return { status: "pending", label: raw ? raw.charAt(0) + raw.slice(1).toLowerCase() : "Unknown" };
}

function regionLocation(region: string | null | undefined) {
  if (!region) return null;
  const label = REGION_LABELS[region];
  if (!label) return null;
  return { label, country: REGION_COUNTRY[region] ?? "" };
}



