const STOCK_PREVIEW = {
  vps: "/nx/preview/vps.webp",
  hosting: "/nx/preview/hosting.webp",
  // Neither product has its own wide 16:4 rack plate yet — domains reuse the
  // real hero art from /dashboard/domains rather than a stretched icon; email
  // has no dedicated wide art at all, so it falls back to its own service mark.
  domain: "/nx/hero-domains-globe.webp",
  email: "/nx/svc/email.webp",
