/** Landscape key art for a game family, which every family in the catalogue has. */
function gameHeroArt(family: string | null): string | null {
  const slug = family ? GAME_ART_SLUG[family as GameFamily]?.hero : null;
  return slug ? `/games/art/${slug}_hero.jpg` : null;
}

/**
 * Where a Server row's card image comes from, in priority order: the image the
 * customer set, then the game's own key art, then the stock rack plate. The
 * `v` stamp is the preview's updatedAt, so replacing an image busts the cache
 * without making the route itself uncacheable.
 */
function serverPreview(
  id: string, isGame: boolean, family: string | null, previewStamp: Date | null,
): Pick<ServiceRow, "previewSrc" | "previewSource" | "siteToFrame" | "canSetPreview"> {
  if (previewStamp) {
    return {
      previewSrc: `/api/services/preview/${id}?v=${previewStamp.getTime()}`,
      previewSource: "customer",
      siteToFrame: null,
      canSetPreview: true,
    };
  }
  const art = isGame ? gameHeroArt(family) : null;
  return {
    previewSrc: art ?? STOCK_PREVIEW.vps,
    previewSource: art ? "game-art" : "stock",
    siteToFrame: null,
    // Game servers lead with their own key art, which is better than anything a
    // customer would upload — the swap is offered on VPS rows only.
    canSetPreview: !isGame,
