        ? gamePlanSpecs(s.gamePlan?.name, gameName, s.gamePlan?.slots)
        : s.plan
          ? specLine(s.plan.cpuCores, s.plan.ramMB, s.plan.diskGB, s.plan.storageTier)
          : null,
      status: st.status,
      statusLabel: st.label,
      location: regionLocation(s.node?.region),
      renewalIso: s.expiresAt ? s.expiresAt.toISOString() : null,
      grant: grants.get(s.id) ?? null,
      renewalCents: s.isFree ? null : charge.totalCents,
      termMonths: s.isFree ? 1 : charge.months,
      gameFamily: isGame ? family : null,
      domain: null,
      createdAtIso: s.createdAt.toISOString(),
      ...serverPreview(s.id, isGame, family, s.preview?.updatedAt ?? null),
      os: !isGame && s.osTemplate
        ? {
            family: s.osTemplate.logo || s.osTemplate.family,
            // `name` is often already the full "Ubuntu 24.04 LTS", so appending
            // `version` unconditionally produced "Ubuntu 24.04 LTS 24.04".
            name: s.osTemplate.version && !s.osTemplate.name.includes(s.osTemplate.version)
              ? `${s.osTemplate.name} ${s.osTemplate.version}`
              : s.osTemplate.name,
          }
        : null,
    });
  }

  for (const h of hosting) {
    const st = normalizeStatus(h.status);
    // No region column on HostingNode — resolve the node's real public IP
    // instead of inventing a city, and leave it blank if that can't answer.
    const geo = geoLocateIp(h.node?.publicIp ?? null);
    rows.push({
      id: h.id,
      kind: "hosting",
      name: h.primaryDomain,
      href: `/dashboard/hosting/${h.id}`,
      typeLabel: "Shared Hosting",
      // The name IS the domain here, so repeating it as an address would just
      // print the same string twice in the same card.
      address: null,
      addressLabel: "Website",
      specs: [h.plan?.name, `${Math.round(h.diskQuotaMB / 1024)} GB disk`].filter(Boolean).join(" • ") || null,
      status: st.status,
      statusLabel: st.label,
      location: geo?.city ? { label: geo.city, country: (geo.country ?? "").toLowerCase() } : null,
      renewalIso: h.expiresAt ? h.expiresAt.toISOString() : null,
      // `h.plan.priceCents` is the raw monthly list price — it ignores the
      // annual-term discount and any extra-disk add-on the account is really
      // billed for each cycle. `hostingRenewalPrice` is the SAME function
      // worker/product-renewals.ts charges through, so this is never a display
      // number that drifts from what actually gets charged.
      renewalCents: h.plan ? hostingRenewalPrice(h, prices.annualDiscountPct, prices.extraDiskPerGbCents) : null,
      termMonths: h.termMonths ?? 1,
      gameFamily: null,
      domain: h.primaryDomain,
      createdAtIso: h.createdAt.toISOString(),
      ...(() => {
        const thumb = primaryThumbByAccount.get(h.id);
        return thumb
          ? {
              previewSrc: `/api/hosting/thumb?id=${thumb.id}&v=${thumb.updatedAt.getTime()}`,
              previewSource: "customer" as const,
            }
          : { previewSrc: STOCK_PREVIEW.hosting, previewSource: "stock" as const };
      })(),
      // Only a plan that is actually live is worth framing — a suspended or
      // still-provisioning account would frame an error page. Skipped
      // entirely when a real captured/uploaded picture already exists: the
      // iframe is a LIVE view (can render blank/default-page content the
      // stock plate at least doesn't), the thumbnail is a snapshot the
      // customer chose to keep — once one exists, show THAT, not both
      // layered on top of each other.
      siteToFrame: st.status === "running" && !primaryThumbByAccount.has(h.id) ? h.primaryDomain : null,
      canSetPreview: false,
      os: null,
    });
  }

  for (const d of domains) {
    const st = normalizeStatus(d.status);
    rows.push({
      id: d.id,
      kind: "domain",
      name: d.name,
      href: `/dashboard/domains/${d.id}`,
      typeLabel: "Domain",
      // The name IS the domain — same reasoning as the hosting row above.
      address: null,
      addressLabel: "Website",
      specs: d.nameservers.length === 0 ? "Nxeon DNS" : "Custom DNS",
      status: st.status,
      statusLabel: st.label,
      // DomainStatus has no region: a registration has no server behind it.
      location: null,
      renewalIso: d.expiresAt ? d.expiresAt.toISOString() : null,
      // The FROZEN renewal quote from registration/transfer, not the (often
      // lower) first-term price — domains commonly renew higher than they
      // were bought at. Falls back to priceCents on a row sold before this
      // column existed, same as worker/billing.ts's own renewal charge.
      renewalCents: d.renewPriceCents ?? d.priceCents,
      termMonths: Math.max(1, d.termYears) * 12,
      gameFamily: null,
      domain: d.name,
      createdAtIso: d.createdAt.toISOString(),
      previewSrc: STOCK_PREVIEW.domain,
      previewSource: "stock",
      siteToFrame: null,
      canSetPreview: false,
      os: null,
    });
  }

  for (const e of emailSubs) {
    const st = normalizeStatus(e.status);
    rows.push({
      id: e.id,
      kind: "email",
      name: e.domainName,
      href: "/dashboard/email",
      typeLabel: "Business Email",
      address: null,
      addressLabel: "Website",
      specs: [e.emailPlan.name, `${e.emailPlan.mailboxes} mailbox${e.emailPlan.mailboxes === 1 ? "" : "es"}`].filter(Boolean).join(" • ") || null,
      status: st.status,
      statusLabel: st.label,
      location: null,
      renewalIso: e.expiresAt ? e.expiresAt.toISOString() : null,
      // Same term-aware pricing worker/product-renewals.ts's `emailRenewalPrice`
      // charges through (frozen annual rate wins over the live setting) — built
      // from the same exported primitives rather than a fresh formula.
      renewalCents: productTermRenewalCents(
        emailMonthlyBaseCents(e.emailPlan),
        subscriptionTermMonths(e),
        frozenProductAnnualPct(e) ?? prices.annualDiscountPct,
      ),
      termMonths: e.termMonths ?? 1,
      gameFamily: null,
      domain: e.domainName,
      createdAtIso: e.createdAt.toISOString(),
      previewSrc: STOCK_PREVIEW.email,
      previewSource: "stock",
      siteToFrame: null,
      canSetPreview: false,
      os: null,
    });
  }

  if (freeMc) {
    // The free tier's LIVE state needs an SSH round trip to freemc-host, which
    // is far too expensive to pay on every render of this list — so the row
    // shows the stored state and the live one is fetched on its own page.
    const st = normalizeStatus(freeMc.status);
    rows.push({
      id: freeMc.id,
      kind: "free",
      name: freeMc.name || `${freeMc.subdomain}`,
      href: "/dashboard/free-minecraft",
      typeLabel: "Minecraft (Free)",
      address: `${freeMc.subdomain}.${gameBase}`,
      addressLabel: "Connect",
      // The two-axis game type + mode, NOT the deprecated flat `preset` column
      // the legacy free-MC cards still read.
      specs: [
        FREEMC_GAME_TYPES[freeMc.activeGameType]?.label ?? freeMc.activeGameType,
        FREEMC_GAME_MODES[freeMc.activeGameMode]?.label ?? freeMc.activeGameMode,
      ].join(" • "),
      status: st.status,
      statusLabel: st.label,
      location: null,
      renewalIso: null,
      renewalCents: null,
      termMonths: 1,
      gameFamily: "minecraft",
      domain: null,
      createdAtIso: freeMc.createdAt.toISOString(),
      // The free tier's card shows the art for the game type actually loaded on
      // it — SkyBlock looks like SkyBlock, not like generic Minecraft.
      previewSrc:
        FREEMC_GAME_TYPES[freeMc.activeGameType]?.heroImage
        ?? gameHeroArt("minecraft")
        ?? STOCK_PREVIEW.vps,
      previewSource: "game-art",
      siteToFrame: null,
      canSetPreview: false,
      os: null,
    });
  }

  return rows.sort((a, b) => b.createdAtIso.localeCompare(a.createdAtIso));
}
"use client";

import { useMemo, useState } from "react";
import Link from "next/link";
import { Icon } from "@/components/nx/Icon";
import { ServiceCard } from "./ServiceCard";
import { FilterSelect } from "./FilterSelect";
import { ServicePreviewDialog } from "./ServicePreviewDialog";
import type { ServiceRow, ServiceStatus } from "@/lib/nx/services";

type TabKey = "all" | "vps" | "game" | "hosting" | "email" | "free";

const TABS: { key: TabKey; label: string; icon: string }[] = [
  { key: "all", label: "All Services", icon: "layers" },
  { key: "vps", label: "VPS Servers", icon: "serverstack" },
  { key: "game", label: "Game Servers", icon: "gamepad" },
  { key: "hosting", label: "Shared Hosting", icon: "cloud" },
  { key: "email", label: "Email", icon: "envelope" },
  { key: "free", label: "Free Services", icon: "gift" },
];

type SortKey = "newest" | "oldest" | "name" | "renewal" | "price";

const SORTS: { key: SortKey; label: string }[] = [
  { key: "newest", label: "Newest First" },
  { key: "oldest", label: "Oldest First" },
  { key: "name", label: "Name (A–Z)" },
  { key: "renewal", label: "Renews Soonest" },
  { key: "price", label: "Highest Cost" },
];

const STATUS_OPTIONS: { key: "all" | ServiceStatus; label: string }[] = [
  { key: "all", label: "All Statuses" },
  { key: "running", label: "Running" },
  { key: "pending", label: "Pending" },
  { key: "stopped", label: "Stopped" },
  { key: "suspended", label: "Suspended" },
  { key: "cancelled", label: "Cancelled" },
];

export function ServicesView({ rows, initialTab, freeClaim }: { rows: ServiceRow[]; initialTab?: string; freeClaim: React.ReactNode }) {
  // ?tab=free deep-links here (the dashboard's "Free forever" promo card),
  // same convention as SettingsView's ?tab=integrations. `initialTab` comes
  // from the page's own `searchParams` (a real server read via a prop), not
  // a client-only `window.location` check done during render — that shape
  // is the textbook hydration-mismatch anti-pattern (server always renders
  // the `typeof window === "undefined"` branch, the client's first render
  // takes the other one), and it's exactly what fired real "Minified React
  // error #418" on SettingsView's equivalent `?tab=` deep link. Fixed there
  // the same way: read on the server, pass down as a prop.
  const [tab, setTab] = useState<TabKey>(() => (TABS.some((x) => x.key === initialTab) ? (initialTab as TabKey) : "all"));
  const [q, setQ] = useState("");
  const [status, setStatus] = useState<"all" | ServiceStatus>("all");
  const [location, setLocation] = useState("all");
  const [sort, setSort] = useState<SortKey>("newest");
  const [editing, setEditing] = useState<ServiceRow | null>(null);

  const counts = useMemo(() => ({
    // Excludes email so the badge matches what "All Services" actually shows
    // — mailboxes have their own tab/count just below.
    all: rows.filter((r) => r.kind !== "email").length,
    vps: rows.filter((r) => r.kind === "vps").length,
    // The free tier IS a game server, so it counts under Game Servers too.
    game: rows.filter((r) => r.kind === "game" || r.kind === "free").length,
    hosting: rows.filter((r) => r.kind === "hosting").length,
    email: rows.filter((r) => r.kind === "email").length,
    free: rows.filter((r) => r.kind === "free").length,
  }), [rows]);

  /** Only the locations this account actually has — never a global list. */
  const locations = useMemo(() => {
    const seen = new Map<string, string>();
    for (const r of rows) if (r.location) seen.set(r.location.label, r.location.label);
    return [{ key: "all", label: "All Locations" }, ...[...seen.keys()].sort().map((l) => ({ key: l, label: l }))];
  }, [rows]);

  const shown = useMemo(() => {
    const needle = q.trim().toLowerCase();
    const out = rows.filter((r) => {
      // Mailboxes don't clutter "All Services" — an account with many email
      // domains/plans could otherwise crowd out the VPS/game/hosting cards a
      // customer is actually here to check on. Still fully reachable via its
      // own "Email" tab, just not shown by default alongside everything else.
      if (tab === "all" && r.kind === "email") return false;
      if (tab === "game" && !(r.kind === "game" || r.kind === "free")) return false;
      if (tab !== "all" && tab !== "game" && r.kind !== tab) return false;
      if (status !== "all" && r.status !== status) return false;
      if (location !== "all" && r.location?.label !== location) return false;
      if (needle && !`${r.name} ${r.address ?? ""} ${r.typeLabel} ${r.specs ?? ""}`.toLowerCase().includes(needle)) return false;
      return true;
    });

    const far = "9999-12-31";
    return out.sort((a, b) => {
      switch (sort) {
        case "oldest": return a.createdAtIso.localeCompare(b.createdAtIso);
        case "name": return a.name.localeCompare(b.name);
        // A service with no renewal date sorts last rather than first.
        case "renewal": return (a.renewalIso ?? far).localeCompare(b.renewalIso ?? far);
        case "price": return (b.renewalCents ?? 0) - (a.renewalCents ?? 0);
        default: return b.createdAtIso.localeCompare(a.createdAtIso);
      }
    });
  }, [rows, tab, q, status, location, sort]);

  /** The Free Services tab with nothing claimed yet: an offer, not a list. */
  const claiming = tab === "free" && counts.free === 0;
  const filtered = shown.length !== rows.length;

  return (
    <div className="flex flex-col gap-4">
      {/* ── product tabs ───────────────────────────────────────────────── */}
      <div className="grid grid-cols-2 gap-2.5 sm:grid-cols-3 lg:grid-cols-6">
        {TABS.map((t) => {
          const on = tab === t.key;
          return (
            <button
              key={t.key}
              type="button"
              onClick={() => setTab(t.key)}
              aria-pressed={on}
              className={
                "flex items-center gap-2.5 rounded-[13px] border px-3.5 py-3 text-left transition " +
                (on
                  ? "border-[#8b5cff] bg-[linear-gradient(135deg,rgba(80,40,190,.45),rgba(30,40,120,.35))] shadow-[0_0_0_1px_rgba(139,92,255,.35),0_0_28px_-6px_rgba(139,92,255,.55)]"
                  : "border-rim-hi bg-[rgba(6,14,36,.72)] hover:border-brand-400/40")
              }
            >
              <Icon name={t.icon} size={17} tone="inherit" className={"flex-none " + (on ? "text-white" : "text-[#7f9ad0]")} />
              <span className={"min-w-0 flex-1 truncate text-[13px] font-semibold " + (on ? "text-white" : "text-tx-dim")}>
                {t.label}
              </span>
              {/* An unclaimed free tier has nothing to count, so the badge
                  advertises the offer instead of reporting a zero.
                  `text-emerald-300`/`text-mint` both stay literal Tailwind or
                  theme-token colours either way — the FREE badge uses the
                  app's own `mint` token (as VpsAddonsCard's tier chip does)
                  so it stays legible on the light-mode page instead of pale
                  mint-on-mint. The active-tab count is a genuinely fixed
                  saturated violet chip (bg-[#7b3fef] never changes with the
                  theme), so its digit needs a literal white — `text-white`
                  resolves through --color-white, which is flipped to ink for
                  light mode and made the "9" unreadable on the violet fill. */}
              <span className={
                "grid h-[22px] min-w-[22px] flex-none place-items-center rounded-[7px] px-1.5 text-[11.5px] font-bold " +
                (t.key === "free" && counts.free === 0
                  ? "border border-mint/45 bg-mint/12 text-mint"
                  : on ? "bg-[#7b3fef] text-[#fff]" : "bg-white/[0.06] text-tx-faint")
              }>
                {t.key === "free" && counts.free === 0 ? "FREE" : counts[t.key]}
              </span>
            </button>
          );
        })}
      </div>

      {/* ── search + filters ───────────────────────────────────────────── */}
      {!claiming && (
      <div className="flex flex-wrap items-center gap-2.5">
        <span className="flex h-[46px] min-w-[220px] flex-1 items-center gap-2.5 rounded-[12px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-4">
          <Icon name="search" size={15} tone="inherit" className="flex-none text-tx-faint" />
          <input
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Search your services..."
            className="min-w-0 flex-1 bg-transparent text-[13px] text-white outline-none placeholder:text-tx-faint"
          />
          {q && (
            <button type="button" onClick={() => setQ("")} aria-label="Clear search"
                    className="flex-none text-tx-faint transition hover:text-white">
              <Icon name="xcircle" size={14} tone="inherit" />
            </button>
          )}
        </span>

        <FilterSelect value={status} onChange={(v) => setStatus(v as typeof status)} options={STATUS_OPTIONS} width="w-[168px]" />
        {locations.length > 1 && (
          <FilterSelect value={location} onChange={setLocation} options={locations} width="w-[176px]" />
        )}
        <FilterSelect value={sort} onChange={(v) => setSort(v as SortKey)} options={SORTS} label="Sort by" width="w-[176px]" />
      </div>
      )}

      {/* ── the estate ─────────────────────────────────────────────────── */}
      {claiming ? (
        // The free tier hasn't been claimed, so its tab is the ONE place that
        // shows a thing you don't own yet. It never leaks into All or Game
        // Servers: those list what the account actually has.
        freeClaim
      ) : shown.length === 0 ? (
        <div className="rounded-[17px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-6 py-16 text-center">
          <Icon name="cube" size={30} className="mx-auto" />
          <p className="mt-3.5 text-[15px] font-bold text-white">
            {rows.length === 0 ? "Nothing deployed yet" : "No services match those filters"}
          </p>
          <p className="mx-auto mt-1.5 max-w-[46ch] text-[13px] leading-relaxed text-tx-dim">
            {rows.length === 0
              ? "Your VPS servers, game servers and hosting plans will all appear here the moment you deploy one."
              : "Try a different tab, status, location or search term."}
          </p>
          {rows.length === 0 ? (
            <Link href="/dashboard/deploy" className="btn-deploy mt-5 inline-flex py-2.5 text-[13px]">
              Deploy your first service <span className="dep-arrow">→</span>
            </Link>
          ) : (
            <button
              type="button"
              onClick={() => { setQ(""); setStatus("all"); setLocation("all"); setTab("all"); }}
              className="mt-5 inline-flex items-center gap-2 rounded-[11px] border border-rim-hi bg-well px-4 py-2.5 text-[13px] font-semibold text-tx-dim transition hover:text-white"
            >
              Clear filters
            </button>
          )}
        </div>
      ) : (
        <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
          {shown.map((r) => (
            <ServiceCard key={`${r.kind}-${r.id}`} row={r} onChangeImage={() => setEditing(r)} />
          ))}
        </div>
      )}

      {!claiming && filtered && shown.length > 0 && (
        <p className="text-center text-[12px] text-tx-faint">
          Showing {shown.length} of {rows.length} services
        </p>
      )}

      <ServicePreviewDialog row={editing} onClose={() => setEditing(null)} />
    </div>
  );
}

