import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";

/**
 * Dedicated servers are UNRELEASED: with Setting dedicated_public_enabled off
 * (the default) the customer/public routes must 404 for everyone except a
 * private-preview account (lib/preview-access.ts), must not be in the sitemap,
 * and nothing customer-facing outside the feature may link to them.
 *
 * DATABASE_URL is pointed at a closed port BEFORE the gate is imported, so the
 * flag read fails — which must fail CLOSED (404), never open.
 */
process.env.DATABASE_URL = "postgresql://nobody:nothing@127.0.0.1:1/none?connect_timeout=2";

const ROOT = path.resolve(__dirname, "..");
const read = (p: string) => readFileSync(path.join(ROOT, p), "utf8");

const CUSTOMER_ROUTES = [
  "app/(marketing)/dedicated-servers/page.tsx",
  "app/dashboard/dedicated/page.tsx",
  "app/dashboard/dedicated/[id]/page.tsx",
  "app/dashboard/dedicated/order/page.tsx",
  "app/dashboard/dedicated/order/[id]/page.tsx",
];

test("route decision: off = not-found, on = render, preview user = render", async () => {
  const { dedicatedRouteDecision, dedicatedSitemapPaths } = await import("../lib/dedicated/gate.ts");
  assert.equal(dedicatedRouteDecision(false), "not-found");
  assert.equal(dedicatedRouteDecision(false, false), "not-found");
  assert.equal(dedicatedRouteDecision(false, true), "render");
  assert.equal(dedicatedRouteDecision(true), "render");
  assert.deepEqual(dedicatedSitemapPaths(false), []);
  assert.deepEqual(dedicatedSitemapPaths(true), ["/dedicated-servers"]);
});

test("the gate 404s when the flag / allowlist cannot be read (fail closed)", async () => {
  const { requireDedicatedAccess, dedicatedPublicEnabled, dedicatedAccessFor } = await import("../lib/dedicated/gate.ts");
  assert.equal(await dedicatedPublicEnabled(), false);
  // Even the default preview email is refused when the DB can't be read.
  assert.deepEqual(await dedicatedAccessFor({ email: "nicholas.sj.albanese@gmail.com" }), { allowed: false, isPublic: false, preview: false });
  assert.equal((await dedicatedAccessFor(null)).allowed, false);
  await assert.rejects(requireDedicatedAccess(), (e: unknown) => {
    const digest = String((e as { digest?: string })?.digest ?? (e as Error)?.message ?? "");
    return /NEXT_HTTP_ERROR_FALLBACK;404|NEXT_NOT_FOUND/.test(digest);
  });
});

test("the flag defaults to OFF", async () => {
  const src = read("lib/settings.ts");
  assert.match(src, /dedicated_public_enabled:\s*"false"/);
});

test("every customer/public dedicated route calls the gate before doing anything else", () => {
  for (const f of CUSTOMER_ROUTES) {
    const src = read(f);
    assert.match(src, /import \{[^}]*requireDedicatedAccess[^}]*\} from "@\/lib\/dedicated\/gate"/, f);
    const body = src.slice(src.indexOf("export default async function"));
    const firstAwait = /await\s+([A-Za-z]+)\(/.exec(body);
    assert.equal(firstAwait?.[1], "requireDedicatedAccess", `${f}: the gate must be the first await`);
    // never indexable while unreleased
    if (f.startsWith("app/dashboard/")) assert.match(src, /robots:\s*\{\s*index:\s*false/, `${f}: must be noindex`);
  }
});

test("every customer action re-checks the gate (requests, credentials, checkout)", () => {
  const src = read("lib/actions-dedicated-customer.ts");
  assert.match(src, /async function ownedDedicated[\s\S]*?dedicatedAccessFor\(user\)/);
  for (const fn of ["requestDedicatedAction", "revealDedicatedCredentials"]) {
    const body = src.slice(src.indexOf(`export async function ${fn}`));
    assert.match(body.slice(0, 600), /ownedDedicated\(/, fn);
  }
});

test("checkout actions re-check the gate before anything else", () => {
  const src = read("lib/actions-dedicated-order.ts");
  assert.match(src, /async function gatedUser[\s\S]*?dedicatedAccessFor\(user\)[\s\S]*?throw new Error\(NOT_FOUND\)/);
  for (const fn of ["quoteDedicatedOrderAction", "payDedicatedOrder"]) {
    const body = src.slice(src.indexOf(`export async function ${fn}`));
    assert.match(body.slice(0, 900), /gatedUser\(\)/, fn);
  }
});

test("the portal nav entry is added only for viewers who pass the gate", () => {
  const layout = read("app/dashboard/layout.tsx");
  assert.match(layout, /if \(\(await dedicatedAccessFor\(user\)\.catch\(\(\) => \(\{ allowed: false \}\)\)\)\.allowed\) extraNav\.push\(DEDICATED_NAV_ITEM\)/);
  const nav = read("lib/nx/nav.ts");
  assert.doesNotMatch(nav, /dedicated/i, "the designed rail itself must not list dedicated servers");
});

test("not in the sitemap while off: static paths, live marketing routes, and the gated core entry", () => {
