 */
const ORDER = "/dashboard/dedicated/order";
const LOGO: Record<string, string> = { amd: "/nxm/home/logos-amd.svg", intel: "/nxm/home/logos-intel.svg", nvidia: "/nxm/home/logos-nvidia.svg" };
// inline !important: the site's layered image rules (height:auto !important) would otherwise win
const logo = (b: string | null, cls = "") => (b ? `<img class="dd-logo ${cls}" src="${LOGO[b]}" alt="${b === "amd" ? "AMD" : b === "intel" ? "Intel" : "NVIDIA"}" style="height:${cls === "lg" ? 22 : 16}px !important;width:auto !important">` : "");

async function inStockCards(): Promise<OrderCatalogCard[]> {
  const access = await requireDedicatedAccess();
  const cards = await loadOrderCatalog(await orderPreviewAll(access.preview));
  return cards.filter((c) => c.regions.some((r) => r.inStock));
}

export async function meta(_p: Record<string, string>) {
