    noindex: !on,
  };
}

export async function load(_p: Record<string, string>): Promise<NxmLoad> {
  const cards = await inStockCards();
  const user = await currentUser();
  const hrefFor = (id: string, region?: string) => {
    const dest = `${ORDER}/${encodeURIComponent(id)}${region ? `?region=${region}` : ""}`;
    return user ? dest : `/register?next=${encodeURIComponent(dest)}`;
  };
  const fromOf = (c: OrderCatalogCard) => Math.min(...c.regions.filter((r) => r.inStock).map((r) => r.fromMonthlyCents));
  const sorted = [...cards].sort((a, b) => fromOf(a) - fromOf(b));
  const cheapest = sorted[0] ?? null;

  // locations: every listed location, with how many builds are in stock there. Several
  // region codes can share one customer label (two campuses in one metro): the
  // page groups by the label, so a visitor never sees the same place twice.
  const keyOf = (label: string) => label.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  const regions = new Map<string, { code: string; label: string; area: string; inStock: number; listed: number }>();
  for (const c of cards) {
    const seen = new Map<string, boolean>();
    for (const r of c.regions) seen.set(keyOf(r.label), (seen.get(keyOf(r.label)) ?? false) || r.inStock);
    for (const [k, inStock] of seen) {
      const r = c.regions.find((x) => keyOf(x.label) === k)!;
      const e = regions.get(k) ?? { code: k, label: r.label, area: r.area, inStock: 0, listed: 0 };
      e.listed++;
      if (inStock) e.inStock++;
      regions.set(k, e);
    }
  }
  const regionList = [...regions.values()].sort((a, b) => b.inStock - a.inStock || a.label.localeCompare(b.label));
  const regionsInStock = regionList.filter((r) => r.inStock > 0).length;

  const plate = cheapest
    ? `<div class="au-glass dd-plate"><div class="dd-plate-top"><b>In stock</b><span>${esc(cheapest.tier)}</span></div>
<div class="dd-face" aria-hidden="true">${"<i></i>".repeat(14)}</div>
<div class="dd-plate-body"><p class="dd-plate-cpu">${logo(cpuBrandOf(cheapest.cpu), "lg")}${esc(cheapest.cpu.replace(/^(AMD|Intel)\s+/i, ""))}</p>
<p class="dd-plate-sub">${cheapest.cores} cores · ${cheapest.threads} threads${cheapest.baseGhz ? ` · ${cheapest.baseGhz} GHz` : ""}</p>
<div class="dd-plate-spec"><div><span>Memory</span><b>${cheapest.ramGb} GB</b></div><div><span>Storage</span><b title="${esc(cheapest.storage)}">${esc(cheapest.storage.split("(")[0].trim() || "—")}</b></div></div>
<div class="dd-plate-foot"><span class="dd-price">${usd(fromOf(cheapest))}<small>/mo</small></span><a class="nxm-btn nxm-sm" href="${esc(hrefFor(cheapest.id))}"><span class="nxm-bt">Configure</span><span class="nxm-arw" aria-hidden="true">→</span></a></div></div></div>`
    : `<div class="au-glass dd-plate"><div class="dd-plate-body"><p class="dd-plate-cpu">Stock is being refreshed</p><p class="dd-plate-sub">Check back shortly, or ask our team for a custom build.</p></div></div>`;

  const locations = regionList.length
    ? `<ul class="dd-locs">${regionList.map((r) => `<li class="au-glass dd-loc${r.inStock ? " on" : ""}"><small>${esc(r.area)}</small><b>${esc(r.label)}</b><span>${r.inStock ? `${r.inStock} build${r.inStock === 1 ? "" : "s"} in stock` : "Sold out right now"}</span></li>`).join("")}</ul>`

