export const dynamic = "force-dynamic";

/* The data half of the dashboard. The view is a verbatim port of the design
   sandbox and must stay that way; everything variable is assembled here.

   Uptime is now real: the worker samples every server every 5 minutes and
   lib/uptime.ts folds that into daily counters. It reads "—" until enough
   samples exist, never "0%", because unmeasured is not the same as down.

   Live CPU / memory / storage / network utilisation is real too, as of
   2026-09-17, but deliberately NOT assembled here: it needs one live Proxmox
   round trip per provisioned VM, which is too slow to await in this
   server component without delaying the whole page's first paint. See
   /api/dashboard/resource-usage and components/nx/ResourceUsageCard.tsx,
   which fetches it client-side after the shell above has already rendered. */

const money = (cents: number) =>
  "$" + (cents / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/* One bucket per audit action, so the feed reads as icons rather than dots. */
function actIcon(action: string): { icon: string; tone: "" | "c" | "v" | "m" } {
  if (action.startsWith("wallet") || action.includes("invoice") || action.includes("topup")) return { icon: "card", tone: "m" };
  if (action.includes("create") || action.includes("provision")) return { icon: "cloudup", tone: "c" };
  if (action.includes("restore") || action.includes("snapshot") || action.includes("backup")) return { icon: "refresh", tone: "" };
  if (action.startsWith("domain")) return { icon: "nodes", tone: "c" };
  if (action.includes("delete") || action.includes("suspend")) return { icon: "warntriangle", tone: "m" };
  if (action.includes("build") || action.includes("matrix")) return { icon: "terminal", tone: "v" };
  return { icon: "activity", tone: "v" };
}

function nxStatus(status: string): Row["status"] {
  if (status === "RUNNING") return "Online";
  if (["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(status)) return "Maintenance";
  return "Offline";
}

/* "Jan 12, 2026" + "in 45 days", the two lines the Renewal column shows. */
         to expand it. Found live 2026-09-17: a customer with a base 25GB
         plan plus a 25GB expansion had a real 50GB disk but saw "25 GB". */
      cpu: `${s.gamePlan?.cpuCores ?? s.plan.cpuCores} vCPU`,
      ram: `${(s.gamePlan?.ramMB ?? s.plan.ramMB) / 1024} GB`,
      disk: `${effectiveDiskGB(baseDiskGBFor(s), s.extraDiskGB)} GB`,
      flag: REGION_COUNTRY[region] ?? "sg",
      loc: REGION_LABELS[region] ?? region,
      status: nxStatus(s.status),
      ...renewal(s.expiresAt),
      // "Free until <date>" for an EXPIRE grant; RENEW_WALLET keeps the plain renewal date (it really renews).
      ...(isGrantFree(grants.get(s.id)) && s.expiresAt ? { renew: `Free until ${renewal(s.expiresAt).renew}` } : {}),
    };
  });

  const totalServiceCount = servers.length + hostingCount + (hasFree ? 1 : 0);
  const stats: Stat[] = [
    {
      label: "Total Services", value: String(totalServiceCount), icon: "server", tone: "c",
      delta: newThisMonth > 0 ? { dir: "up", text: String(newThisMonth) } : undefined,
      foot: "Active services",
    },
    { label: "Monthly Spend", value: money(monthlySpendCents), icon: "card", tone: "", delta: spendDelta, foot: "vs. last month" },
    {
      label: "Uptime Average", value: formatUptime(uptime), icon: "clock", tone: "v",
      foot: uptime.percent === null ? "Not measured yet" : `Last ${uptime.days} day${uptime.days === 1 ? "" : "s"}`,
    },
    {
      label: "Support Tickets", value: String(openTickets), icon: "users2", tone: "m",
      foot: openTickets === 1 ? "Open ticket" : "Open tickets",
    },
  ];

  const counts = {
    vps: rows.filter((r) => r.kind === "VPS").length,
    game: rows.filter((r) => r.kind === "Game Server").length,
  };
  /* This widget's own table only ever holds VPS/game rows (a "recent
     activity" preview, not the full inventory — see the query comment
     above) — so its filter tabs stay scoped to what's actually in that
     table ("All Services" here means "all rows below", not the account's
     grand total) rather than advertising a "Shared Hosting" tab that would
     show an accurate count and then filter to nothing. The real total,
     across every kind, is the "Total Services" STAT above instead — that's
     the number that was actually wrong (silently 3 short, one per missing
     hosting account plus the free server), and the full breakdown lives on
     /dashboard/services via "View All". */
  const filters = [
    { label: "All Services", count: rows.length },
    { label: "VPS", count: counts.vps },
    { label: "Game Servers", count: counts.game },
  ];

  // Real per-VM CPU/Memory/Storage/Network usage now lives entirely behind
  // /api/dashboard/resource-usage, fetched client-side by
  // components/nx/ResourceUsageCard.tsx AFTER this page paints — see that
  // route's doc comment. Not computed here: it needs one live Proxmox call
  // per provisioned VM, which is exactly the round-trip cost this page's
  // former TODO comment flagged as too slow to await in SSR.

  const activity: Act[] = auditLogs.map((log) => ({
    title: log.detail || humanizeAction(log.action),
    when: ago(log.createdAt),
    ...actIcon(log.action),
  }));

  const from = (cents: number | undefined, unit = "/mo") =>
    cents === undefined ? "—" : money(cents) + unit;
  // A real per-customer check, not the general "this product has a promo"
  // badge the comment here used to defend — a customer who already redeemed
  // it on a prior hosting order kept seeing this on every dashboard visit,
  // which reads as a broken promise the moment they actually order and it
  // isn't free. Same three-part check the deploy wizard itself gates on
  // (app/dashboard/deploy/page.tsx), minus the IP-based cap: this is a
  // display hint, not the enforcement point, so a null ipHash is fine here.
  const hostingPromoEligible =
    firstMonthFreeAppliesTo("HOSTING") &&
    (await firstMonthFreeEnabled()) &&
    (await firstMonthFreeEligible(user.id, null));
  const services: Svc[] = [
    { key: "vps", name: "VPS Servers", icon: "vps", price: from(plans[0]?.priceCents) },
    { key: "game", name: "Game Servers", icon: "game", price: from(gamePlans[0]?.priceCents) },
    {
      key: "hosting", name: "Cloud Hosting", icon: "hosting", price: from(hostingPlans[0]?.priceCents),
      badge: hostingPromoEligible ? "First month free" : undefined,
    },
    { key: "email", name: "Business Email", icon: "email", price: from(emailPlans[0]?.priceCents) },
    // Domains has no fixed plan row — its real price is set per TLD by a live
    // registrar quote, so there is no single number here that isn't either
    // stale or made up. "$9.99/yr" was a guess presented as a real price;
    // this names what's actually true instead.
    { key: "domains", name: "Domains", icon: "domains", price: "Priced per TLD" },
  ];

  // Global Network card (components/nx/DashboardView.tsx) — real regions,
  // deduped from the actual Node table, each marked online/degraded from a
  // real Proxmox reachability check (lib/monitoring's nodeRamUsage, the same
  // read node-capacity alerting uses). No fabricated latency number — see
  // NetRegion's own doc comment for why.
  const [dbNodes, ramByNode] = await Promise.all([
    db.node.findMany({ where: { enabled: true }, select: { name: true, region: true } }),
    nodeRamUsage(),
  ]);
  const reachableByNodeName = new Map(ramByNode.map((r) => [r.node, r.reachable]));
  const regionOnline = new Map<string, boolean>();
  for (const n of dbNodes) {
    const reachable = reachableByNodeName.get(n.name) ?? true; // unreachable ONLY on a confirmed-down read, never assumed
    regionOnline.set(n.region, (regionOnline.get(n.region) ?? true) && reachable);
  }
  const network: NetRegion[] = [...regionOnline.entries()].map(([region, online]) => ({
    key: region,
    name: customerRegionLabel(region),
    lon: REGION_COORDS[region]?.lon ?? 0,
    lat: REGION_COORDS[region]?.lat ?? 0,
    country: REGION_COUNTRY[region] ?? "",
    online,
  }));

  return (
    <>
      {transitional && <AutoRefresh />}
      <DashboardView
        first={user.name.split(" ")[0]}
        stats={stats}
        rows={rows}
        filters={filters}
        activity={activity}
        services={services}
        network={network}
      />
    </>
  );
}

/* "Jan 12, 2026" + "in 45 days", the two lines the Renewal column shows. */
function renewal(expiresAt: Date | null): { renew: string; inDays: string } {
  if (!expiresAt) return { renew: "—", inDays: "no term" };
  const days = Math.round((expiresAt.getTime() - Date.now()) / 86_400_000);
  return {
    renew: expiresAt.toLocaleDateString("en-US", { month: "short", day: "2-digit", year: "numeric" }),
    inDays: days < 0 ? `${-days} days ago` : days === 0 ? "today" : `in ${days} day${days === 1 ? "" : "s"}`,
  };
}

function ago(d: Date): string {
  const m = Math.floor((Date.now() - d.getTime()) / 60_000);
  if (m < 1) return "just now";
  if (m < 60) return `${m} min ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h} hour${h === 1 ? "" : "s"} ago`;
  const dd = Math.floor(h / 24);
  return dd === 1 ? "Yesterday" : `${dd} days ago`;
}

export default async function DashboardPage() {
  const user = await requireUser();
  const monthAgo = new Date(Date.now() - 30 * 86_400_000);

  const [servers, hostingCount, hasFree, auditLogs, openTickets, newThisMonth, plans, gamePlans, hostingPlans, emailPlans] =
    await Promise.all([
      db.server.findMany({
        where: { userId: user.id },
        // `gamePlan` and `dedicatedIp` are what `renewalCharge` needs; `node`
        // carries the region the Location column shows.
        // `portForwards` joins `dedicatedIp`/`node` as what connectAddress needs
        // to work out the address a customer can actually reach the box on.
        include: {
          plan: true, osTemplate: true, gamePlan: true, dedicatedIp: true, node: true,
          portForwards: { select: { publicPort: true, guestPort: true } },
        },
        orderBy: { createdAt: "desc" },
      }),
      /* This dashboard's own "Total Services" stat and its widget's per-type
         tab counts used to come from `servers.length`/`rows` alone — which
         only ever holds VPS + game-server rows (this same `db.server`
         query). Shared Hosting and a claimed free server are real services
         (lib/nx/services.ts's `listServices()`, which /dashboard/services
         correctly uses, counts them) but live in different tables
         (HostingAccount, FreeMinecraftServer) this page never queried, so
         they silently read as 0 here — the exact "undercounts your own
         services" bug audited today. Two cheap counts, not a full re-fetch
         of listServices()'s richer rows (this page's own `rows` table is
         VPS/game-only by design, showing recent server activity — these are
         only for getting the STAT AND TAB NUMBERS honest). */
      db.hostingAccount.count({ where: { userId: user.id } }),
      db.freeMinecraftServer.findUnique({ where: { userId: user.id }, select: { id: true } }),
      db.auditLog.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 8 }),
      db.ticket.count({ where: { userId: user.id, status: { in: ["OPEN", "CUSTOMER_REPLY"] } } }),
      db.server.count({ where: { userId: user.id, createdAt: { gte: monthAgo } } }),
      db.plan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" }, take: 1 }),
      db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" }, take: 1 }),
      db.hostingPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" }, take: 1 }),
      /* `active: true` matters here specifically: staging (and, presumably,
         any long-lived install) accumulates retired $0 plan rows — this fork
         has 5 of them ("Unlimited", a few bundled-hosting-email leftovers,
         "Free Domain Inbox") — and a query with no active filter, sorted
         priceCents ascending, picks one of those up first. That is the exact
         "Business Email $0.00/mo" bug: real Starter is $1.99, not $0. */
      db.emailPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" }, take: 1 }),
    ]);

  const uptime = await uptimeFor(servers.map((s) => s.id));
  // Servers an admin GRANTED: their renewal wording and the monthly-spend figure follow the grant
  // policy (EXPIRE = free until the date, nothing is charged), not the plan price.
  const grants = await grantBillingFor(servers.map((s) => s.id));
  // The play-subdomain base is an admin setting shared by free and paid game
  // servers, so the connect address stays right if the owner ever moves it.
  const gameBase = await gameSubdomainBase();

  /* Was anything removed in the window? If so, last month's estate cannot be
     reconstructed from what is still in the table, and any delta computed from
     the survivors could only ever point up. Better no delta than a number that
     is wrong in one direction by construction. */
  const removals = await db.auditLog.count({
    where: {
      userId: user.id,
      createdAt: { gte: monthAgo },
      OR: [{ action: { contains: "delete" } }, { action: { contains: "terminate" } }, { action: { contains: "cancel" } }],
    },
  });

  // "Monthly spend" is priced through `renewalCharge` — the single function
  // worker/billing.ts, the saved-card path and the "Renew now" button all charge
  // through (lib/renewal-charge.ts). Summing `plan.priceCents` instead is a
  // SECOND formula and a different number: it bills a $4.99 game server at its
  // $8.99 base VPS plan and counts nothing for purchased extra disk or a
  // dedicated IP the customer really does pay for every cycle.
  const paid = servers.filter((s) => !s.isFree && s.status !== "DELETING" && !isGrantFree(grants.get(s.id)));
  const spendTaxRatePercent = (await taxContextForUser(user)).ratePercent;
  const spendPrices =
    paid.length > 0
      ? {
          ipMonthlyCents: await dedicatedIpMonthlyCents(),
          extraDiskPerGbCents: await extraDiskPerGbCents(),
          backupPlusCents: await backupPlusMonthlyCents(),
          annualDiscountPct: await annualDiscountPct(),
          taxRatePercent: spendTaxRatePercent,
        }
      : { ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct: DEFAULT_ANNUAL_DISCOUNT_PCT, taxRatePercent: spendTaxRatePercent };
  const monthlySpendCents = paid.reduce((sum, s) => {
    const charge = renewalCharge(s, spendPrices);
    return sum + Math.round(charge.totalCents / Math.max(1, charge.months));
  }, 0);

  /* Last month's recurring cost, priced the same way through `renewalCharge` —
     the estate as it stood 30 days ago is the servers that already existed then.
     Only trustworthy when nothing was removed since (see `removals`). */
  const priorPaid = paid.filter((s) => s.createdAt < monthAgo);
  const priorSpendCents = priorPaid.reduce((sum, s) => {
    const charge = renewalCharge(s, spendPrices);
    return sum + Math.round(charge.totalCents / Math.max(1, charge.months));
  }, 0);
  const spendDelta =
    removals > 0 || priorSpendCents === 0 || priorSpendCents === monthlySpendCents
      ? undefined
      : {
          dir: (monthlySpendCents > priorSpendCents ? "up" : "down") as "up" | "down",
          text: `${Math.round((Math.abs(monthlySpendCents - priorSpendCents) / priorSpendCents) * 100)}%`,
        };

  const transitional = servers.some((s) =>
    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
  );

  const KIND = (s: (typeof servers)[number]) =>
    s.gamePlan ? "Game Server" : "VPS";

  const tagMap = await loadOwnershipTags(servers);
  const rows: Row[] = servers.map((s) => {
    const kind = KIND(s);
    const region = s.node?.region ?? "sgp1";
    return {
      id: s.id,
      name: s.label || s.hostname,
      tags: tagMap.get(s.id) ?? [],
      /* Through the one derivation the "your server is ready" email also uses
         (lib/nx/connect-address.ts), so the dashboard and that email can never
         disagree about where to connect.

         This line used to lead with `s.ipAddress`, which is the INTERNAL
         10.20.x.x address behind the host's NAT — unreachable from outside and
         worse than showing nothing. The comment that was here warned that the
         rewritten dashboard has to re-carry main's fixes or the design would
         reintroduce them; it did exactly that, and this is the repair. */
      addr: connectAddress(s, gameBase).address ?? s.hostname,
      kind,
      icon: kind === "Game Server" ? "gamepad" : "server",
      tone: kind === "Game Server" ? "v" : "c",
      /* A game server's real cpu/ram/disk is its GAME plan's, not the larger,
         differently-named base VPS plan it rides on. main fixed this across
         the codebase in 6248659; that commit's hunk patched the markup this
         rewrite deleted, so it is re-applied here by intent rather than lost
