import { test } from "node:test";
import assert from "node:assert/strict";
import {
  DEFAULT_RULES,
  roundPrice,
  sellMonthlyCents,
  sellSetupCents,
  margin,
  firstYearMargin,
  setupPaybackMonths,
  rulesFromSettings,
  clampPercent,
  effectiveSetupCost,
  money,
  type PricingRules,
} from "../lib/dedicated/pricing.ts";
import { priceView } from "../lib/dedicated/catalog-view.ts";

/** Dedicated-server markup math. Pure; every figure is integer cents. */
const R = (o: Partial<PricingRules> = {}): PricingRules => ({ ...DEFAULT_RULES, ...o });

test("rounding modes always round UP, never below the computed price", () => {
  assert.equal(roundPrice(13375, "none"), 13375);
  assert.equal(roundPrice(13375, "whole"), 13400);
  assert.equal(roundPrice(13400, "whole"), 13400);
  assert.equal(roundPrice(13375, "ninety-nine"), 13399);
  assert.equal(roundPrice(13399, "ninety-nine"), 13399);
  assert.equal(roundPrice(13400, "ninety-nine"), 13499);
  assert.equal(roundPrice(0, "ninety-nine"), 99);
  assert.equal(roundPrice(13375, "five"), 13500);
  assert.equal(roundPrice(-50, "none"), 0);
  for (const c of [1, 99, 100, 101, 9999, 123456]) {
    for (const m of ["none", "whole", "ninety-nine", "five"] as const) assert.ok(roundPrice(c, m) >= c, `${m} ${c}`);
  }
});

test("percent + fixed markup, then rounding", () => {
  // $107.00 at +25% = $133.75 -> $133.99
  assert.equal(sellMonthlyCents(10700, R()), 13399);
  // +25% + $5 fixed = $138.75 -> $138.99
  assert.equal(sellMonthlyCents(10700, R({ markupFixedCents: 500 })), 13899);
  // 0% and no rounding = cost
  assert.equal(sellMonthlyCents(10700, R({ markupPercent: 0, rounding: "none" })), 10700);
});

test("per-item overrides win over the global rule", () => {
  assert.equal(sellMonthlyCents(10700, R(), { markupPercent: 50 }), 16099); // 160.50 -> 160.99
  assert.equal(sellMonthlyCents(10700, R(), { markupFixedCents: 1000 }), 14399); // 133.75+10 -> 143.99
  assert.equal(sellMonthlyCents(10700, R(), { overrideMonthlyCents: 9900 }), 9900); // hard price, unrounded
});

test("options are marked up too — even on top of a hard override", () => {
  // base 107 + option 49.60 = 156.60 * 1.25 = 195.75 -> 195.99
  assert.equal(sellMonthlyCents(10700, R(), {}, 4960), 19599);
  // override 99.00 + option 49.60*1.25 = 62.00 -> 161.00
  assert.equal(sellMonthlyCents(10700, R(), { overrideMonthlyCents: 9900 }, 4960), 16100);
});

test("setup-fee policies: pass-through (promotion-aware), waived, custom", () => {
  assert.equal(sellSetupCents(10700, R()), 10700);
  assert.equal(sellSetupCents(33100, R(), {}, 0), 0); // a live free-setup promo passes through
  assert.equal(sellSetupCents(10700, R({ setupPolicy: "waived" })), 0);
  assert.equal(sellSetupCents(10700, R({ setupPolicy: "custom", setupCustomCents: 4900 })), 4900);
  assert.equal(sellSetupCents(10700, R(), { setupPolicy: "waived" }), 0);
  assert.equal(sellSetupCents(10700, R(), { setupPolicy: "custom", setupCustomCents: 2500 }), 2500);
  assert.equal(sellSetupCents(10700, R(), { setupPolicy: "bogus" }), 10700); // unknown item policy -> global
  assert.equal(effectiveSetupCost(33100, 0), 0);
  assert.equal(effectiveSetupCost(33100, null), 33100);
});

test("margin is gross margin on the sell price", () => {
  assert.deepEqual(margin(10700, 13399), { cents: 2699, percent: 20.1 });
  assert.deepEqual(margin(10700, 9900), { cents: -800, percent: -8.1 });
  assert.equal(margin(100, 0).percent, null);
});

