/**
 * PURE + client-safe: Nxeon's own names for bare-metal builds.
 *
 * Customers never see a supplier range or plan name. Every build gets an
 * NX family (its class) and a model code (its size), derived ONLY from the
 * hardware, so the same machine always gets the same name and the rules can be
 * read off this file:
 *
 *   family   (first rule that matches, in this order)
 *     NX-GPU    a GPU is fitted
 *     NX-Titan  32+ cores in total, or a dual-socket board
 *     NX-Pulse  a current high-clock desktop CPU (Ryzen 5000+, Core 10th gen+, X3D)
 *     NX-Forge  a current server CPU (EPYC, Xeon Gold/Silver/6, Xeon-E 23xx+), or 12+ cores
 *     NX-Core   everything else: earlier-generation and entry hardware
 *
 *   model    "<total cores>-<default RAM GB>"            e.g. NX-Forge 8-64
 *
 * When two DIFFERENT builds would share a name (same family, cores and RAM but a
 * different CPU or disk), `disambiguateNames` appends a lower-case letter
 * (a, b, c ...) to each, ordered by CPU model then storage, so the result does
 * not depend on stock or on the order rows arrive in.
 *
 * The real specs (CPU model, cores, threads, clocks, RAM, disks) are always
 * shown next to the name. test/dedicated-nx-names.test.ts pins the rules.
 */

export const NX_FAMILIES = ["NX-Core", "NX-Pulse", "NX-Forge", "NX-Titan", "NX-GPU"] as const;
export type NxFamily = (typeof NX_FAMILIES)[number];

export const NX_FAMILY_INFO: Record<NxFamily, { blurb: string; order: number; short: string }> = {
  "NX-Core": { blurb: "Proven single-tenant hardware at an entry price", order: 1, short: "Entry" },
  "NX-Pulse": { blurb: "High-clock CPUs for game servers and latency-sensitive apps", order: 2, short: "High clock" },
  "NX-Forge": { blurb: "Current-generation server CPUs for production workloads", order: 3, short: "Production" },
  "NX-Titan": { blurb: "Many-core and dual-socket platforms for virtualisation and data", order: 4, short: "Many-core" },
  "NX-GPU": { blurb: "Dedicated GPUs for AI inference, rendering and transcoding", order: 5, short: "Accelerated" },
};

export type NxNameInput = {
  /** Full CPU string, e.g. "AMD EPYC 4344P" or "2x Intel Xeon Gold 6526Y". */
  cpu: string;
  /** Sockets; 1 when unknown. */
  cpuCount?: number | null;
  /** TOTAL cores across sockets. */
  cores: number;
  ramGb: number;
  gpu?: string | null;
};

/** Earlier-generation CPUs (sold as NX-Core even when they have many cores, unless Titan-sized). */
function legacy(s: string): boolean {
  return (
    /ryzen\s*\d\s*(pro\s*)?[1-3]\d{3}/.test(s) ||               // Ryzen 1000-3000
    /\bi[3579]-?\s*[2-9]\d{3}/.test(s) ||                        // Core 2nd-9th gen (i7-7700K, i7-6700k)
    /xeon[\s-]*e3|xeon[\s-]*e5|xeon[\s-]*d[\s-]*\d|atom|celeron|opteron/.test(s) ||
    /xeon[\s-]*e[\s-]*2[12]\d{2}/.test(s)                         // Xeon-E 21xx / 22xx
  );
}

function highClockDesktop(s: string): boolean {
  if (/x3d/.test(s)) return true;
  if (/ryzen/.test(s)) return true;
  if (/core\s*ultra|\bi[579]-?\s*1\d{4}/.test(s)) return true;
  return false;
}

function serverClass(s: string): boolean {
  return /epyc|xeon[\s-]*(gold|silver|platinum|6\d{3}|w-)|xeon[\s-]*e[\s-]*2[3-9]\d{2}/.test(s);
}

export function nxFamily(i: NxNameInput): NxFamily {
  const s = (i.cpu ?? "").toLowerCase();
  if (i.gpu && i.gpu.trim()) return "NX-GPU";
  if (i.cores >= 32 || (i.cpuCount ?? 1) >= 2 || /^\s*[2-9]\s*x\s/.test(s)) return "NX-Titan";
  if (legacy(s)) return i.cores >= 12 && serverClass(s) ? "NX-Forge" : "NX-Core";
  if (highClockDesktop(s)) return "NX-Pulse";
  if (serverClass(s) || i.cores >= 12) return "NX-Forge";
  return "NX-Core";
}

export function nxModel(i: Pick<NxNameInput, "cores" | "ramGb">): string {
  return `${Math.max(0, Math.round(i.cores))}-${Math.max(0, Math.round(i.ramGb))}`;
}

export function nxName(i: NxNameInput): string {
  return `${nxFamily(i)} ${nxModel(i)}`;
}

/**
 * Names for a whole catalogue. `key` identifies one hardware build; `sortKey`
 * orders colliding builds (CPU model + storage). Returns key -> final name.
 */
export function disambiguateNames(builds: { key: string; input: NxNameInput; sortKey: string }[]): Map<string, string> {
  const byName = new Map<string, { key: string; sortKey: string }[]>();
  const uniq = new Map<string, { input: NxNameInput; sortKey: string }>();
  for (const b of builds) if (!uniq.has(b.key)) uniq.set(b.key, { input: b.input, sortKey: b.sortKey });
  for (const [key, b] of uniq) {
    const n = nxName(b.input);
    const list = byName.get(n) ?? [];
    list.push({ key, sortKey: b.sortKey });
    byName.set(n, list);
  }
  const out = new Map<string, string>();
  for (const [name, list] of byName) {
    if (list.length === 1) { out.set(list[0].key, name); continue; }
    list.sort((a, b) => a.sortKey.localeCompare(b.sortKey) || a.key.localeCompare(b.key));
    list.forEach((b, i) => out.set(b.key, `${name}${letter(i)}`));
  }
  return out;
}

function letter(i: number): string {
  // a..z, then aa, ab ...
  let s = "";
  let n = i;
  do { s = String.fromCharCode(97 + (n % 26)) + s; n = Math.floor(n / 26) - 1; } while (n >= 0);
  return s;
}

