 * vanish when a filter changes.
 *
 *   Most popular      an admin pinned it (DedicatedCatalogItem.popularPinned); if
 *                     nothing is pinned, the build with the most real paid orders
 *                     in the last 180 days, when it has at least POPULAR_MIN_ORDERS.
 *   Recommended       only when neither of the above exists: the cheapest in-stock
 *                     NX-Forge build with at least 64 GB RAM. Labelled
 *                     "Recommended", NOT "Most popular": with no orders there is no
 *                     popularity to claim.
 *   Best value        the cheapest builds per unit of capacity, where
 *                     unit = cores + RAM GB / 8 (8 GB of RAM counts like one core).
 *                     Lowest 10% of in-stock non-GPU builds (at least one).
 *   High performance  the top CPU class: the highest 10% of in-stock non-GPU
 *                     builds by threads x boost clock (base clock when no boost).
 *   GPU               a GPU is fitted.
 *   New               first seen in the catalogue within the last 30 days AND at
 *                     least 7 days after the catalogue's first sync (so the launch
 *                     catalogue is not all "New").
 *
 * test/dedicated-tags.test.ts covers every rule.
 */

export const TAG_KINDS = ["popular", "recommended", "value", "performance", "gpu", "new"] as const;
export type TagKind = (typeof TAG_KINDS)[number];

export const TAG_LABEL: Record<TagKind, string> = {
  popular: "Most popular",
  recommended: "Recommended",
  value: "Best value",
  performance: "High performance",
  gpu: "GPU",
  new: "New",
};

export const TAG_RULE: Record<TagKind, string> = {
  popular: "Our most-ordered build, or one our team pinned.",
  recommended: "Our team's starting point for production workloads.",
  value: "Among the lowest prices per core and per GB of memory in stock.",
  performance: "Among the fastest CPUs in stock (threads x clock speed).",
  gpu: "A dedicated GPU is fitted.",
  new: "Added to the catalogue in the last 30 days.",
};

export const POPULAR_MIN_ORDERS = 3;

export type TagInput = {
  key: string;
  family: string;
  cores: number;
  threads: number;
  ramGb: number;
  baseGhz: number | null;
  boostGhz: number | null;
  gpu: string | null;
  fromMonthlyCents: number;
  inStock: boolean;
  pinned: boolean;
  /** Paid orders in the last 180 days. */
  orders: number;
  firstSeenAt: Date | string | null;
};

export const valueUnit = (c: Pick<TagInput, "cores" | "ramGb">) => Math.max(1, c.cores) + Math.max(0, c.ramGb) / 8;
export const pricePerUnit = (c: Pick<TagInput, "cores" | "ramGb" | "fromMonthlyCents">) => c.fromMonthlyCents / valueUnit(c);
export const perfScore = (c: Pick<TagInput, "threads" | "cores" | "boostGhz" | "baseGhz">) => Math.max(c.threads, c.cores) * (c.boostGhz ?? c.baseGhz ?? 3);

const top = (n: number) => Math.max(1, Math.ceil(n * 0.1));
const ts = (d: Date | string | null) => (d == null ? NaN : new Date(d).getTime());

export function computeTags(cards: TagInput[], now: Date = new Date()): Map<string, TagKind[]> {
  const out = new Map<string, TagKind[]>(cards.map((c) => [c.key, []]));
  const add = (k: string, t: TagKind) => { const l = out.get(k); if (l && !l.includes(t)) l.push(t); };
  const live = cards.filter((c) => c.inStock);
  const cpuOnly = live.filter((c) => !c.gpu);

  const pinned = live.filter((c) => c.pinned);
  if (pinned.length) pinned.forEach((c) => add(c.key, "popular"));
  else {
    const best = [...live].sort((a, b) => b.orders - a.orders || a.fromMonthlyCents - b.fromMonthlyCents)[0];
    if (best && best.orders >= POPULAR_MIN_ORDERS) add(best.key, "popular");
    else {
      const rec = [...cpuOnly].filter((c) => c.family === "NX-Forge" && c.ramGb >= 64).sort((a, b) => a.fromMonthlyCents - b.fromMonthlyCents || a.key.localeCompare(b.key))[0];
      if (rec) add(rec.key, "recommended");
    }
  }

  if (cpuOnly.length) {
    [...cpuOnly].sort((a, b) => pricePerUnit(a) - pricePerUnit(b) || a.key.localeCompare(b.key)).slice(0, top(cpuOnly.length)).forEach((c) => add(c.key, "value"));
    [...cpuOnly].sort((a, b) => perfScore(b) - perfScore(a) || a.fromMonthlyCents - b.fromMonthlyCents).slice(0, top(cpuOnly.length)).forEach((c) => add(c.key, "performance"));
  }

  const firsts = cards.map((c) => ts(c.firstSeenAt)).filter((x) => Number.isFinite(x));
  const epoch = firsts.length ? Math.min(...firsts) : NaN;
  for (const c of cards) {
    if (c.gpu) add(c.key, "gpu");
    const f = ts(c.firstSeenAt);
    if (Number.isFinite(f) && now.getTime() - f <= 30 * 86_400_000 && f - epoch >= 7 * 86_400_000) add(c.key, "new");
  }
  for (const [k, l] of out) out.set(k, l.sort((a, b) => TAG_KINDS.indexOf(a) - TAG_KINDS.indexOf(b)));
  return out;
}

