/**
 * In-process cache of the bare-metal catalogue, for the customer pages.
 *
 * Why: every catalogue / configure request used to read every live item, its
 * ~5k options and ~36k stock rows from Postgres and recompute the merged cards
 * (about 0.6-1 s per request on the shared box), and the "back to the
 * catalogue" step paid that again. The data only changes when the worker's
 * catalogue sync runs (hours apart) or an admin edits a price or an item.
 *
 * Rule: the snapshot is reused while BOTH hold
 *   - it is younger than SNAPSHOT_TTL_MS (60 s), and
 *   - the cheap "stamp" query (newest sync row, newest item edit, the pricing
 *     settings, the visible-item count) is unchanged — re-checked at most every
 *     STAMP_CHECK_MS (5 s).
 * So an admin price change shows within ~5 s, a sync within ~5 s, and the
 * worst case is the TTL.
 *
 * The CHARGE path never reads this cache: quoteDedicatedOrder() re-prices from
 * the database on the Review step and again at payment, so a stale display can
 * never be charged (the customer sees the fresh quote before paying).
 */
import type { DedicatedCatalogItem, DedicatedCatalogOption } from "@prisma/client";
import { db } from "../db";
import { loadAvailability, loadRules, type AvailRow } from "./catalog-view";
import type { PricingRules } from "./pricing";

export type SnapItem = DedicatedCatalogItem & { options: DedicatedCatalogOption[] };

export type CatalogSnapshot = {
  stamp: string;
  at: number;
  items: SnapItem[];
  avail: Map<string, AvailRow[]>;
  rules: PricingRules;
  enabledRegions: Set<string>;
  /** catalogItemId -> paid orders in the last 180 days (for the "Most popular" tag). */
  orders: Map<string, number>;
  /** Derived values memoised per snapshot (catalogue cards, builds, names). */
  memo: Map<string, unknown>;
};

export const SNAPSHOT_TTL_MS = 60_000;
export const STAMP_CHECK_MS = 5_000;

let current: CatalogSnapshot | null = null;
let lastStampCheck = 0;
let inflight: Promise<CatalogSnapshot> | null = null;

const PRICE_KEYS = ["dedicated_markup_percent", "dedicated_markup_fixed_cents", "dedicated_rounding", "dedicated_setup_policy", "dedicated_setup_custom_cents", "dedicated_price_uplift_percent", "dedicated_enabled_regions"];

async function readStamp(): Promise<string> {
  const [sync, item, visible, settings] = await Promise.all([
    db.dedicatedCatalogSync.findFirst({ orderBy: { startedAt: "desc" }, select: { id: true, finishedAt: true } }),
    db.dedicatedCatalogItem.aggregate({ _max: { updatedAt: true } }),
    db.dedicatedCatalogItem.count({ where: { visible: true, removedAt: null } }),
    db.setting.findMany({ where: { key: { in: PRICE_KEYS } }, select: { key: true, value: true } }),
  ]);
  const s = settings.sort((a, b) => a.key.localeCompare(b.key)).map((r) => `${r.key}=${r.value}`).join("&");
  return `${sync?.id ?? ""}:${sync?.finishedAt?.getTime() ?? ""}|${item._max.updatedAt?.getTime() ?? ""}|${visible}|${s}`;
}

async function build(stamp: string): Promise<CatalogSnapshot> {
  const since = new Date(Date.now() - 180 * 86_400_000);
  const [{ rules, enabledRegions }, items, orderRows] = await Promise.all([
    loadRules(),
    db.dedicatedCatalogItem.findMany({ where: { removedAt: null, currency: "USD" }, include: { options: true }, orderBy: { monthlyCents: "asc" } }),
    db.dedicatedServer.groupBy({ by: ["catalogItemId"], where: { createdAt: { gte: since }, catalogItemId: { not: null }, status: { not: "CANCELLED" }, NOT: { invoiceIds: { isEmpty: true } } }, _count: { _all: true } }).catch(() => []),
  ]);
  const avail = await loadAvailability(items.map((i) => i.planCode));
  const orders = new Map<string, number>();
  for (const r of orderRows as { catalogItemId: string | null; _count: { _all: number } }[]) if (r.catalogItemId) orders.set(r.catalogItemId, r._count._all);
  return { stamp, at: Date.now(), items, avail, rules, enabledRegions, orders, memo: new Map() };
}

/** The current snapshot (built on first use, refreshed per the rule above). */
export async function catalogSnapshot(): Promise<CatalogSnapshot> {
  const now = Date.now();
  if (current && now - current.at < SNAPSHOT_TTL_MS && now - lastStampCheck < STAMP_CHECK_MS) return current;
  if (inflight) return inflight;
  inflight = (async () => {
    try {
      const stamp = await readStamp();
      lastStampCheck = Date.now();
      if (current && current.stamp === stamp && Date.now() - current.at < SNAPSHOT_TTL_MS) return current;
      current = await build(stamp);
      return current;
    } finally {
      inflight = null;
    }
  })();
  return inflight;
}

/** Memoise a derived value on the current snapshot. */
export function memo<T>(snap: CatalogSnapshot, key: string, f: () => T): T {
  if (snap.memo.has(key)) return snap.memo.get(key) as T;
  const v = f();
  snap.memo.set(key, v);
  return v;
}

/** Tests / admin "Sync now": drop the cache. */
export function invalidateCatalogSnapshot(): void {
  current = null;
  lastStampCheck = 0;
}

