function buildCatalog(snap: CatalogSnapshot, previewAll: boolean): OrderCatalogCard[] {
  const { rules, enabledRegions } = snap;
  const names = nxNames(snap);
  const items = snapItems(snap, previewAll);
  const groups = new Map<string, OrderCatalogCard & { _items: ItemWithOptions[] }>();
  for (const it of items) {
