/**
 * PURE + client-safe: hand-drawn SVG flags for every country a bare-metal
 * location can be in (lib/dedicated/regions.ts). Inline markup, no CDN, no
 * external file — shared by the portal (components/dedicated/Flag.tsx) and the
 * NXM marketing page (server-rendered HTML strings).
 *
 * Drawn on a 30x20 grid (3:2), simplified where a full emblem would be noise
 * at 16-24 px (Canada's leaf, Singapore's stars, India's chakra are outline-
 * accurate but not heraldic). Unknown codes fall back to a neutral globe.
 */

const W = 30;
const H = 20;

const star = (cx: number, cy: number, r: number, fill: string) => {
  const pts: string[] = [];
  for (let i = 0; i < 10; i++) {
    const a = -Math.PI / 2 + (i * Math.PI) / 5;
    const rr = i % 2 ? r * 0.42 : r;
    pts.push(`${(cx + rr * Math.cos(a)).toFixed(2)},${(cy + rr * Math.sin(a)).toFixed(2)}`);
  }
  return `<polygon points="${pts.join(" ")}" fill="${fill}"/>`;
};

const UNION = (w: number, h: number) =>
  `<rect width="${w}" height="${h}" fill="#012169"/>` +
  `<path d="M0 0L${w} ${h}M${w} 0L0 ${h}" stroke="#fff" stroke-width="${h * 0.2}"/>` +
  `<path d="M0 0L${w} ${h}M${w} 0L0 ${h}" stroke="#C8102E" stroke-width="${h * 0.08}"/>` +
  `<path d="M${w / 2} 0V${h}M0 ${h / 2}H${w}" stroke="#fff" stroke-width="${h * 0.33}"/>` +
  `<path d="M${w / 2} 0V${h}M0 ${h / 2}H${w}" stroke="#C8102E" stroke-width="${h * 0.2}"/>`;

const BODY: Record<string, string> = {
  fr: `<rect width="10" height="20" fill="#0055A4"/><rect x="10" width="10" height="20" fill="#fff"/><rect x="20" width="10" height="20" fill="#EF4135"/>`,
  de: `<rect width="30" height="6.67" fill="#000"/><rect y="6.67" width="30" height="6.67" fill="#DD0000"/><rect y="13.33" width="30" height="6.67" fill="#FFCE00"/>`,
  pl: `<rect width="30" height="10" fill="#fff"/><rect y="10" width="30" height="10" fill="#DC143C"/>`,
  sg:
    `<rect width="30" height="10" fill="#EF3340"/><rect y="10" width="30" height="10" fill="#fff"/>` +
    `<circle cx="7" cy="5" r="3.4" fill="#fff"/><circle cx="8.3" cy="5" r="3.1" fill="#EF3340"/>` +
    star(10.6, 2.9, 0.75, "#fff") + star(12.4, 4.2, 0.75, "#fff") + star(11.7, 6.4, 0.75, "#fff") + star(9.5, 6.4, 0.75, "#fff") + star(8.8, 4.2, 0.75, "#fff"),
  ca:
    `<rect width="30" height="20" fill="#fff"/><rect width="7.5" height="20" fill="#D52B1E"/><rect x="22.5" width="7.5" height="20" fill="#D52B1E"/>` +
    `<path fill="#D52B1E" d="M15 3.2l1.1 2.1 1.2-.6-.5 3 1.9-2 .5 1.1 2-.4-.7 2.3.9.4-3.2 2.7.4 1.1-3.1-.4.1 3.2h-1.2l.1-3.2-3.1.4.4-1.1-3.2-2.7.9-.4-.7-2.3 2 .4.5-1.1 1.9 2-.5-3 1.2.6z"/>`,
  gb: UNION(30, 20),
  au:
    `<rect width="30" height="20" fill="#012169"/>` +
    `<svg width="15" height="10" viewBox="0 0 30 20">${UNION(30, 20)}</svg>` +
    star(7.5, 15, 2, "#fff") + star(22.5, 4, 1, "#fff") + star(19.5, 9, 1, "#fff") + star(25.5, 8, 1, "#fff") + star(22.5, 16, 1.1, "#fff") + star(24.5, 12, 0.6, "#fff"),
  in:
    `<rect width="30" height="6.67" fill="#FF9933"/><rect y="6.67" width="30" height="6.67" fill="#fff"/><rect y="13.33" width="30" height="6.67" fill="#138808"/>` +
    `<circle cx="15" cy="10" r="2.6" fill="none" stroke="#000080" stroke-width="0.55"/><circle cx="15" cy="10" r="0.6" fill="#000080"/>` +
    `<path d="M15 7.4V12.6M12.4 10H17.6M13.16 8.16l3.68 3.68M16.84 8.16l-3.68 3.68" stroke="#000080" stroke-width="0.3"/>`,
  us:
    Array.from({ length: 13 }, (_, i) => `<rect y="${(i * 20) / 13}" width="30" height="${20 / 13 + 0.02}" fill="${i % 2 ? "#fff" : "#B22234"}"/>`).join("") +
    `<rect width="12" height="${(7 * 20) / 13}" fill="#3C3B6E"/>` +
    Array.from({ length: 4 }, (_, r) => Array.from({ length: 5 }, (_, c) => `<circle cx="${1.4 + c * 2.3}" cy="${1.3 + r * 2.6}" r="0.45" fill="#fff"/>`).join("")).join(""),
};

const GLOBE =
  `<rect width="30" height="20" fill="#2a3446"/><circle cx="15" cy="10" r="6" fill="none" stroke="#b8c4d8" stroke-width="1"/>` +
  `<path d="M9 10h12M15 4c-2.4 2.8-2.4 9.2 0 12M15 4c2.4 2.8 2.4 9.2 0 12" fill="none" stroke="#b8c4d8" stroke-width="0.8"/>`;

export const FLAG_COUNTRIES = Object.keys(BODY);

/** Full <svg> markup for a country flag (rounded, with a hairline edge so white flags read on white). */
export function flagSvg(country: string | null | undefined, opts: { width?: number; title?: string } = {}): string {
  const w = opts.width ?? 20;
  const h = Math.round((w * H) / W);
  const body = BODY[(country ?? "").toLowerCase()] ?? GLOBE;
  const id = `f${(country ?? "x").toLowerCase()}${w}`;
  const title = opts.title ? `<title>${opts.title.replace(/[<>&"]/g, "")}</title>` : "";
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${W} ${H}" role="img" aria-hidden="${title ? "false" : "true"}" class="bm-flag">${title}` +
    `<defs><clipPath id="${id}"><rect width="${W}" height="${H}" rx="3"/></clipPath></defs>` +
    `<g clip-path="url(#${id})">${body}</g>` +
    `<rect x="0.35" y="0.35" width="${W - 0.7}" height="${H - 0.7}" rx="2.7" fill="none" stroke="rgba(0,0,0,.28)" stroke-width="0.7"/></svg>`
  );
}

