.bm-art .led.l4 { animation-duration: 1.3s; animation-delay: -0.3s; }
.bm-art .pkt { animation: bm-flow 3.2s linear infinite; }
.bm-art .pkt.p2 { animation-delay: -1.1s; animation-duration: 2.7s; }
.bm-art .pkt.p3 { animation-delay: -2s; animation-duration: 3.8s; }
.bm-art .float { animation: bm-float 7s ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
.bm-art .float.f2 { animation-delay: -3.5s; }
.bm-art .scan { animation: bm-scan 5.5s ease-in-out infinite; }
.bm-art .glow { animation: bm-glow 4.5s ease-in-out infinite; }

