.bm-range input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none; pointer-events: auto; width: 18px; height: 18px; border-radius: 99px;
  background: #fff; border: 2px solid var(--bm-accent); box-shadow: 0 2px 6px rgba(0, 0, 0, 0.35); cursor: grab;
}
.bm-range input[type="range"]::-moz-range-thumb {
  pointer-events: auto; width: 14px; height: 14px; border-radius: 99px; background: #fff; border: 2px solid var(--bm-accent); cursor: grab;
}
.bm-range input[type="range"]::-webkit-slider-runnable-track { background: transparent; }
.bm-range input[type="range"]::-moz-range-track { background: transparent; }
.bm-range input[type="range"]:focus-visible::-webkit-slider-thumb { box-shadow: 0 0 0 4px var(--bm-accent-soft); }

/* ---------- skeletons ---------- */
.bm-skel { background: linear-gradient(90deg, var(--bm-card-2) 0%, var(--bm-card-3) 50%, var(--bm-card-2) 100%); background-size: 200% 100%; animation: bm-shimmer 1.4s ease-in-out infinite; border-radius: 10px; }

/* ---------- hero art ---------- */
.bm-hero {
  position: relative; overflow: hidden; border-radius: 22px; isolation: isolate;
  background:
    radial-gradient(80% 120% at 85% 10%, rgba(123, 63, 239, 0.32), transparent 60%),
    radial-gradient(60% 90% at 70% 100%, rgba(59, 107, 232, 0.28), transparent 65%),
    linear-gradient(180deg, #080d1a 0%, #060a14 100%);
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.bm-hero-grid {
  position: absolute; inset: 0; z-index: -1; opacity: 0.35;
  background-image: linear-gradient(rgba(255, 255, 255, 0.05) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 32px 32px;
  -webkit-mask-image: radial-gradient(70% 90% at 70% 40%, #000, transparent 75%);
  mask-image: radial-gradient(70% 90% at 70% 40%, #000, transparent 75%);
}
.bm-art .led { animation: bm-blink 2.6s steps(1, end) infinite; }
.bm-art .led.l2 { animation-duration: 1.9s; animation-delay: -0.7s; }
.bm-art .led.l3 { animation-duration: 3.3s; animation-delay: -1.4s; }
.bm-art .led.l4 { animation-duration: 1.3s; animation-delay: -0.3s; }
.bm-art .pkt { animation: bm-flow 3.2s linear infinite; }
.bm-art .pkt.p2 { animation-delay: -1.1s; animation-duration: 2.7s; }
.bm-art .pkt.p3 { animation-delay: -2s; animation-duration: 3.8s; }
.bm-art .float { animation: bm-float 7s ease-in-out infinite; transform-box: fill-box; transform-origin: center; }
.bm-art .float.f2 { animation-delay: -3.5s; }
.bm-art .scan { animation: bm-scan 5.5s ease-in-out infinite; }
.bm-art .glow { animation: bm-glow 4.5s ease-in-out infinite; }

/* ---------- view transitions between catalogue and configure ---------- */
.bm-enter { animation: bm-in 0.22s ease-out both; }

@keyframes bm-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
@keyframes bm-blink { 0%, 100% { opacity: 1; } 45% { opacity: 0.25; } 60% { opacity: 1; } 80% { opacity: 0.55; } }
@keyframes bm-flow { 0% { stroke-dashoffset: 120; opacity: 0; } 10% { opacity: 1; } 90% { opacity: 1; } 100% { stroke-dashoffset: 0; opacity: 0; } }
@keyframes bm-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }
@keyframes bm-scan { 0%, 100% { transform: translateY(0); opacity: 0; } 15% { opacity: 0.8; } 50% { transform: translateY(150px); opacity: 0.8; } 65% { opacity: 0; } }
@keyframes bm-glow { 0%, 100% { opacity: 0.55; } 50% { opacity: 1; } }
@keyframes bm-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }

@media (prefers-reduced-motion: reduce) {
  .bm-art .led, .bm-art .pkt, .bm-art .float, .bm-art .scan, .bm-art .glow, .bm-skel, .bm-enter { animation: none !important; }
  .bm-art .pkt { stroke-dashoffset: 0; opacity: 0.6; }
  .bm-art .scan { opacity: 0; }
}

