"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): small shared pieces of the bare-metal
 * surfaces, styled by components/dedicated/bm.css (scoped under `.bm`).
 */
import { useId } from "react";
import { flagSvg } from "@/lib/dedicated/flags";
import { TAG_LABEL, TAG_RULE, type TagKind } from "@/lib/dedicated/tags";
import { Icon } from "@/components/nx/Icon";

export const usd = (c: number) => `$${(Math.round(c) / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
/** Whole-dollar price for big headline numbers ("$203.99" stays exact; this only drops ".00"). */
export const usdShort = (c: number) => (c % 100 === 0 ? `$${(c / 100).toLocaleString("en-US")}` : usd(c));
export const gbText = (n: number) => (n >= 1000 ? `${+(n / 1000).toFixed(n % 1000 ? 2 : 0)} TB` : `${n} GB`);

/** A country flag from the bundled set (lib/dedicated/flags.ts). */
export function Flag({ country, width = 20, title }: { country: string | null | undefined; width?: number; title?: string }) {
  return <span className="inline-flex flex-none" style={{ lineHeight: 0 }} dangerouslySetInnerHTML={{ __html: flagSvg(country, { width, title }) }} />;
}

export function Tag({ kind }: { kind: TagKind }) {
  return (
    <span className={`bm-tag bm-tag-${kind}`} title={TAG_RULE[kind]}>
      {kind === "popular" && <Icon name="star" size={9} tone="inherit" />}
      {TAG_LABEL[kind]}
    </span>
  );
}

export function Tags({ tags, max = 2 }: { tags: TagKind[]; max?: number }) {
  if (!tags.length) return null;
  return <span className="flex flex-wrap items-center gap-1.5">{tags.slice(0, max).map((t) => <Tag key={t} kind={t} />)}</span>;
}

export function StockDot({ on }: { on: boolean }) {
  return <span aria-hidden className={"bm-dot " + (on ? "" : "bm-dot-off")} />;
}

/** Dual-thumb range over a list of steps (index based, so uneven steps like 32/64/128 GB work). */
export function RangeSlider({ label, steps, value, onChange, format }: {
  label: string;
  steps: number[];
  value: [number, number];
  onChange: (v: [number, number]) => void;
  format: (n: number, edge: "min" | "max") => string;
}) {
  const id = useId();
  const max = steps.length - 1;
  const [lo, hi] = value;
  const pct = (i: number) => (max === 0 ? 0 : (i / max) * 100);
  const active = lo > 0 || hi < max;
  return (
    <div className="flex min-w-0 flex-col gap-2">
      <div className="flex items-baseline justify-between gap-2">
        <span className="bm-label" id={`${id}-l`}>{label}</span>
        <span className={"bm-num text-[12px] font-bold " + (active ? "bm-ink" : "bm-ink-3")}>
          {lo === 0 && hi === max ? "Any" : `${format(steps[lo], "min")} – ${format(steps[hi], "max")}`}
        </span>
      </div>
      <div className="bm-range">
        <span className="bm-track" />
        <span className="bm-fill" style={{ left: `${pct(lo)}%`, width: `${pct(hi) - pct(lo)}%` }} />
        <input type="range" min={0} max={max} step={1} value={lo} aria-labelledby={`${id}-l`} aria-label={`${label} minimum`}
               aria-valuetext={format(steps[lo], "min")}
               onChange={(e) => onChange([Math.min(Number(e.target.value), hi), hi])} />
        <input type="range" min={0} max={max} step={1} value={hi} aria-label={`${label} maximum`}
               aria-valuetext={format(steps[hi], "max")}
               onChange={(e) => onChange([lo, Math.max(Number(e.target.value), lo)])} />
      </div>
    </div>
  );
}

