input.content:
"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): step 1 of the bare-metal flow — the
 * catalogue. Hero, an interactive filter card (locations with flags, CPU brand
 * toggles with logos, NX families, range sliders for price / cores / memory /
 * storage, live result count, reset) and a card or list view.
 *
 * Receives brand-safe OrderCatalogCard rows only (lib/dedicated/order.ts). It
 * stays MOUNTED while a build is being configured (BareMetalFlow hides it), so
 * filters, view mode and scroll survive the trip back.
 */
import { useEffect, useMemo, useState, type ReactNode } from "react";
import type { OrderCatalogCard } from "@/lib/dedicated/order";
import { NX_FAMILIES, NX_FAMILY_INFO, type NxFamily } from "@/lib/dedicated/nx-names";
import { pricePerUnit } from "@/lib/dedicated/tags";
import { cpuBrandOf, gpuBrandOf } from "@/lib/dedicated/brand";
import { Icon } from "@/components/nx/Icon";
import { BrandLogo } from "../BrandLogo";
import { Flag, RangeSlider, StockDot, Tags, gbText, usd } from "../ui";

const PRICE = [0, 50, 100, 150, 200, 300, 500, 750, 1000, 1500, 2500, 5000];
const CORES = [0, 4, 6, 8, 12, 16, 24, 32, 48, 64, 96, 128, 192];
const RAM = [0, 16, 32, 64, 96, 128, 192, 256, 384, 512, 768];
const DISK = [0, 500, 1000, 2000, 4000, 8000, 16000, 32000, 64000];
type Sort = "price" | "price-desc" | "value" | "cores" | "ram" | "disk";
type Brand = "AMD" | "Intel" | "GPU";
const PAGE = 24;

const full = (steps: number[]): [number, number] => [0, steps.length - 1];
const within = (v: number, steps: number[], [lo, hi]: [number, number]) => v >= steps[lo] && (hi === steps.length - 1 || v <= steps[hi]);
const top = (steps: number[], fmt: (n: number) => string) => (n: number, edge: "min" | "max") =>
  edge === "max" && n === steps[steps.length - 1] ? `${fmt(n)}+` : fmt(n);

export function Catalogue({ cards, preview, previewAll, hero, onConfigure, onPrefetch }: {
  cards: OrderCatalogCard[];
  preview: boolean;
  previewAll: boolean;
  hero: ReactNode;
  onConfigure: (id: string, region: string | null) => void;
  onPrefetch: (id: string) => void;
}) {
  const locations = useMemo(() => {
    const m = new Map<string, { code: string; label: string; area: string; country: string; inStock: number }>();
    for (const c of cards) for (const r of c.regions) {
      const p = m.get(r.code) ?? { code: r.code, label: r.label, area: r.area, country: r.country, inStock: 0 };
      if (r.inStock) p.inStock++;
      m.set(r.code, p);
    }
    return [...m.values()].sort((a, b) => b.inStock - a.inStock || a.label.localeCompare(b.label));
  }, [cards]);

  const [regions, setRegions] = useState<string[]>([]);
  const [brands, setBrands] = useState<Brand[]>([]);
  const [families, setFamilies] = useState<NxFamily[]>([]);
  const [price, setPrice] = useState<[number, number]>(full(PRICE));
  const [cores, setCores] = useState<[number, number]>(full(CORES));
  const [ram, setRam] = useState<[number, number]>(full(RAM));
  const [disk, setDisk] = useState<[number, number]>(full(DISK));
  const [q, setQ] = useState("");
  const [sort, setSort] = useState<Sort>("price");
  const [view, setView] = useState<"cards" | "list">("cards");
  const [limit, setLimit] = useState(PAGE);
  const [filtersOpen, setFiltersOpen] = useState(false);

  // remember the viewer's layout choice (convenience only; works without storage)
  useEffect(() => { try { const v = localStorage.getItem("bm-view"); if (v === "list" || v === "cards") setView(v); } catch { /* none */ } }, []);
  const chooseView = (v: "cards" | "list") => { setView(v); try { localStorage.setItem("bm-view", v); } catch { /* none */ } };

  const toggle = <T,>(list: T[], v: T) => (list.includes(v) ? list.filter((x) => x !== v) : [...list, v]);

  const shown = useMemo(() => {
    const needle = q.trim().toLowerCase();
    const rows = cards
      .map((c) => {
        const rs = c.regions.filter((r) => r.inStock && (regions.length === 0 || regions.includes(r.code)));
        const from = rs.length ? Math.min(...rs.map((r) => r.fromMonthlyCents)) : Infinity;
        return { c, rs, from };
      })
      .filter(({ c, rs, from }) =>
        rs.length > 0 &&
        (brands.length === 0 || brands.some((b) => (b === "GPU" ? !!c.gpu : c.cpuBrand === b))) &&
        (families.length === 0 || families.includes(c.family)) &&
        within(from / 100, PRICE, price) &&
        within(c.cores, CORES, cores) &&
        (within(c.ramGb, RAM, ram) || within(c.maxRamGb, RAM, ram)) &&
        within(c.storageGb, DISK, disk) &&
        (!needle || `${c.name} ${c.cpu} ${c.gpu ?? ""} ${c.storage}`.toLowerCase().includes(needle)));
    rows.sort((a, b) =>
      sort === "price" ? a.from - b.from
        : sort === "price-desc" ? b.from - a.from
        : sort === "value" ? pricePerUnit({ ...a.c, fromMonthlyCents: a.from }) - pricePerUnit({ ...b.c, fromMonthlyCents: b.from })
        : sort === "cores" ? b.c.cores - a.c.cores || a.from - b.from
        : sort === "ram" ? b.c.maxRamGb - a.c.maxRamGb || a.from - b.from
        : b.c.storageGb - a.c.storageGb || a.from - b.from);
    return rows;
  }, [cards, regions, brands, families, price, cores, ram, disk, q, sort]);
  useEffect(() => setLimit(PAGE), [regions, brands, families, price, cores, ram, disk, q, sort]);

  const inStockTotal = useMemo(() => cards.filter((c) => c.regions.some((r) => r.inStock)).length, [cards]);
  const activeCount = regions.length + brands.length + families.length + [price, cores, ram, disk].filter((v, i) => v[0] > 0 || v[1] < [PRICE, CORES, RAM, DISK][i].length - 1).length + (q ? 1 : 0);
  const reset = () => { setRegions([]); setBrands([]); setFamilies([]); setPrice(full(PRICE)); setCores(full(CORES)); setRam(full(RAM)); setDisk(full(DISK)); setQ(""); };
  const hasGpu = cards.some((c) => c.gpu);
  const singleRegion = regions.length === 1 ? regions[0] : null;

  return (
    <div className="flex flex-col gap-5">
      {hero}

      {preview && (
        <p className="bm-sub flex items-start gap-2.5 px-4 py-3 text-[12.5px] bm-ink-2">
          <Icon name="eye" size={14} tone="inherit" className="mt-[1px] bm-accent" />
          <span><b className="bm-ink">Private preview.</b> Only accounts on the preview list can see bare metal.{previewAll ? " No builds are published yet, so every live build is listed for you." : ""}</span>
        </p>
      )}

      {/* ── filters ─────────────────────────────────────────────── */}
      <section className="bm-card p-4 sm:p-5" aria-label="Filter builds">
        <div className="flex flex-wrap items-center gap-3">
          <span className="flex items-center gap-2">
            <span className="grid h-8 w-8 place-items-center rounded-[10px] bm-sub"><Icon name="sliders" size={14} tone="inherit" className="bm-accent" /></span>
            <span className="flex flex-col leading-tight">
              <span className="text-[14px] font-extrabold bm-ink">Find your build</span>
              <span className="text-[11.5px] bm-ink-3" aria-live="polite"><b className="bm-ink bm-num">{shown.length}</b> of {inStockTotal} in-stock builds match</span>
            </span>
          </span>
          <label className="ml-auto flex h-[38px] min-w-[200px] max-w-[320px] flex-1 items-center gap-2 rounded-[10px] px-3 bm-sub">
            <Icon name="search" size={13} tone="inherit" className="bm-ink-3" />
            <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search name, CPU or GPU" aria-label="Search builds"
                   className="min-w-0 flex-1 bg-transparent text-[13px] outline-none bm-ink placeholder:text-[var(--bm-ink-4)]" />
          </label>
          <button type="button" onClick={reset} disabled={activeCount === 0} className="bm-btn-ghost">
            <Icon name="refresh" size={12} tone="inherit" />Reset{activeCount ? ` (${activeCount})` : ""}
          </button>
          <button type="button" onClick={() => setFiltersOpen((o) => !o)} className="bm-btn-ghost lg:hidden" aria-expanded={filtersOpen}>
            <Icon name="filter" size={12} tone="inherit" />{filtersOpen ? "Hide filters" : "More filters"}
          </button>
        </div>

        <div className="mt-4 flex flex-col gap-2">
          <span className="bm-label">Location</span>
          <div className="noscroll -mx-1 flex gap-2 overflow-x-auto px-1 pb-1 lg:flex-wrap">
            <button type="button" className="bm-chip" aria-pressed={regions.length === 0} onClick={() => setRegions([])}>
              <Icon name="globe" size={12} tone="inherit" />All locations
            </button>
            {locations.map((l) => (
              <button key={l.code} type="button" className="bm-chip" aria-pressed={regions.includes(l.code)} disabled={!l.inStock}
                      onClick={() => setRegions(toggle(regions, l.code))} title={l.inStock ? `${l.inStock} builds in stock` : "Sold out right now"}
                      style={l.inStock ? undefined : { opacity: 0.45, cursor: "not-allowed" }}>
                <Flag country={l.country} width={18} />
                {l.label}
                <span className="bm-num text-[11px] bm-ink-3">{l.inStock || "0"}</span>
              </button>
            ))}
          </div>
        </div>

        <div className={"mt-4 flex-col gap-4 lg:flex " + (filtersOpen ? "flex" : "hidden")}>
          <div className="grid gap-4 lg:grid-cols-[auto_minmax(0,1fr)]">
            <div className="flex flex-col gap-2">
              <span className="bm-label">Processor</span>
              <div className="flex flex-wrap gap-2">
                {(["AMD", "Intel"] as const).map((b) => (
                  <button key={b} type="button" className="bm-chip px-4" aria-pressed={brands.includes(b)} onClick={() => setBrands(toggle(brands, b))} aria-label={b}>
                    <BrandLogo brand={b === "AMD" ? "amd" : "intel"} h={b === "AMD" ? 12 : 14} />
                  </button>
                ))}
                {hasGpu && (
                  <button type="button" className="bm-chip px-4" aria-pressed={brands.includes("GPU")} onClick={() => setBrands(toggle(brands, "GPU"))} aria-label="With a GPU">
                    <BrandLogo brand="nvidia" h={13} /><span>GPU</span>
                  </button>
                )}
              </div>
            </div>
            <div className="flex min-w-0 flex-col gap-2">
              <span className="bm-label">Class</span>
              <div className="flex flex-wrap gap-2">
                {NX_FAMILIES.filter((f) => cards.some((c) => c.family === f)).map((f) => (
                  <button key={f} type="button" className="bm-chip" aria-pressed={families.includes(f)} onClick={() => setFamilies(toggle(families, f))} title={NX_FAMILY_INFO[f].blurb}>
                    <Icon name={f === "NX-GPU" ? "bmgpu" : f === "NX-Titan" ? "bmstack" : f === "NX-Pulse" ? "bolt" : f === "NX-Forge" ? "bmchip" : "bmblade"} size={12} tone="inherit" />
                    {f}<span className="hidden text-[11px] font-semibold bm-ink-3 sm:inline">{NX_FAMILY_INFO[f].short}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>
          <div className="grid gap-x-8 gap-y-4 sm:grid-cols-2 xl:grid-cols-4">
            <RangeSlider label="Monthly price" steps={PRICE} value={price} onChange={setPrice} format={top(PRICE, (n) => `$${n.toLocaleString("en-US")}`)} />
            <RangeSlider label="CPU cores" steps={CORES} value={cores} onChange={setCores} format={top(CORES, (n) => String(n))} />
            <RangeSlider label="Memory" steps={RAM} value={ram} onChange={setRam} format={top(RAM, (n) => `${n} GB`)} />
            <RangeSlider label="Storage" steps={DISK} value={disk} onChange={setDisk} format={top(DISK, (n) => gbText(n))} />
          </div>
        </div>
      </section>

      {/* ── toolbar ─────────────────────────────────────────────── */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p className="text-[12px] bm-ink-3">Prices in USD per month, from the cheapest in-stock location. Every build is online within 24 hours.</p>
        <div className="flex items-center gap-2">
          <label className="relative flex items-center">
            <span className="sr-only">Sort</span>
            <select value={sort} onChange={(e) => setSort(e.target.value as Sort)} className="bm-field h-[38px] w-[176px] cursor-pointer appearance-none pr-8 text-[12.5px] font-semibold">
              <option value="price">Lowest price</option>
              <option value="price-desc">Highest price</option>
              <option value="value">Best value</option>
              <option value="cores">Most cores</option>
              <option value="ram">Most memory</option>
              <option value="disk">Most storage</option>
            </select>
            <svg aria-hidden width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" className="pointer-events-none absolute right-3 bm-ink-3"><path d="m6 9 6 6 6-6" /></svg>
          </label>
          <div className="bm-seg" role="group" aria-label="Layout">
            <button type="button" aria-pressed={view === "cards"} onClick={() => chooseView("cards")}><Icon name="grid" size={12} tone="inherit" />Cards</button>
            <button type="button" aria-pressed={view === "list"} onClick={() => chooseView("list")}><Icon name="headerlist" size={12} tone="inherit" />List</button>
          </div>
        </div>
      </div>

      {/* ── results ─────────────────────────────────────────────── */}
      {cards.length === 0 ? (
        <Empty title="No builds are in stock right now" body="Stock moves through the day as machines are reserved and freed up. Check back shortly." />
      ) : shown.length === 0 ? (
        <Empty title="Nothing in stock matches those filters" body="Widen a range or pick another location." action={<button type="button" onClick={reset} className="bm-btn bm-btn-sm">Reset filters</button>} />
      ) : view === "cards" ? (
        <ul className="grid gap-4 md:grid-cols-2 2xl:grid-cols-3">
          {shown.slice(0, limit).map(({ c, rs, from }) => (
            <li key={c.id}><BuildCard c={c} rs={rs} from={from} onConfigure={() => onConfigure(c.id, singleRegion)} onPrefetch={() => onPrefetch(c.id)} /></li>
          ))}
        </ul>
      ) : (
        <div className="bm-card overflow-hidden">
          <div className="hidden grid-cols-[minmax(0,2.2fr)_minmax(0,1fr)_minmax(0,1.3fr)_minmax(0,1.2fr)_auto] gap-4 border-b px-5 py-3 bm-rule md:grid">
            {["Build", "CPU", "Memory · Storage", "In stock in", "Price"].map((h) => <span key={h} className="bm-label">{h}</span>)}
          </div>
          <ul>
            {shown.slice(0, limit).map(({ c, rs, from }) => (
              <li key={c.id}><BuildRow c={c} rs={rs} from={from} onConfigure={() => onConfigure(c.id, singleRegion)} onPrefetch={() => onPrefetch(c.id)} /></li>
            ))}
          </ul>
        </div>
      )}
      {shown.length > limit && (
        <div className="flex flex-col items-center gap-1.5">
          <button type="button" onClick={() => setLimit((l) => l + PAGE)} className="bm-btn-ghost">Show more builds</button>
          <span className="text-[11px] bm-ink-3">Showing {Math.min(limit, shown.length)} of {shown.length}</span>
        </div>
      )}
    </div>
  );
}

type Row = { c: OrderCatalogCard; rs: OrderCatalogCard["regions"]; from: number; onConfigure: () => void; onPrefetch: () => void };

function FamilyIcon({ family, size = 15 }: { family: NxFamily; size?: number }) {
  const name = family === "NX-GPU" ? "bmgpu" : family === "NX-Titan" ? "bmstack" : family === "NX-Forge" ? "bmchip" : family === "NX-Pulse" ? "bolt" : "bmblade";
  return <Icon name={name} size={size} tone="inherit" className="bm-accent" />;
}

function Flags({ rs, max = 5 }: { rs: OrderCatalogCard["regions"]; max?: number }) {
  const uniq = rs.filter((r, i) => rs.findIndex((x) => x.country === r.country) === i);
  return (
    <span className="flex items-center gap-1.5" aria-label={`In stock in ${rs.map((r) => r.label).join(", ")}`} title={rs.map((r) => r.label).join(", ")}>
      {uniq.slice(0, max).map((r) => <Flag key={r.country} country={r.country} width={18} />)}
      {uniq.length > max && <span className="text-[11px] font-bold bm-ink-3">+{uniq.length - max}</span>}
      <span className="ml-0.5 text-[11.5px] bm-ink-3">{rs.length === 1 ? rs[0].label : `${rs.length} locations`}</span>
    </span>
  );
}

function BuildCard({ c, rs, from, onConfigure, onPrefetch }: Row) {
  const cpuShort = c.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1");
  return (
    <article className="bm-card group flex h-full flex-col transition-[border-color,transform] duration-150 hover:border-[var(--bm-line-2)]" onMouseEnter={onPrefetch} onFocus={onPrefetch}>
      <div className="flex flex-col gap-3 p-5 pb-4">
        <div className="flex items-center justify-between gap-2">
          <span className="flex items-center gap-1.5 text-[11px] font-bold bm-ink-3"><FamilyIcon family={c.family} size={11} />{NX_FAMILY_INFO[c.family].short}</span>
          <Tags tags={c.tags} />
        </div>
        <div>
          <h3 className="text-[21px] font-extrabold leading-tight tracking-[-0.03em] bm-ink">{c.name}</h3>
          <p className="mt-1 flex min-w-0 items-center gap-2 text-[13px] font-semibold bm-ink-2" title={c.cpu}>
            <BrandLogo brand={cpuBrandOf(c.cpu)} h={12} />
            <span className="trunc">{cpuShort}</span>
          </p>
        </div>
        <dl className="grid grid-cols-2 gap-x-4 gap-y-3 pt-1">
          <Spec k="Cores" v={`${c.cores} cores · ${c.threads} threads`} sub={c.boostGhz ? `up to ${c.boostGhz} GHz` : c.baseGhz ? `${c.baseGhz} GHz` : undefined} />
          <Spec k="Memory" v={`${c.ramGb} GB`} sub={c.maxRamGb > c.ramGb ? `up to ${c.maxRamGb} GB` : undefined} />
          <Spec k="Storage" v={c.storage.replace(/\s*\((Soft|Hard) RAID\)/i, "") || "—"} sub={c.storageChoose ? "more options when you configure" : /\((Soft|Hard) RAID\)/i.exec(c.storage)?.[0].replace(/[()]/g, "")} />
          <Spec k="Network" v={c.bandwidth || "—"} sub="DDoS protection included" />
        </dl>
        {c.gpu && (
          <div className="flex items-center gap-2.5 rounded-[11px] px-3 py-2 bm-sub">
            <BrandLogo brand={gpuBrandOf(c.gpu)} h={13} />
            <span className="text-[12.5px] font-bold bm-ink">{c.gpu.replace(/\b(NVIDIA|AMD)\s+/i, "")}</span>
          </div>
        )}
      </div>
      <div className="mt-auto flex flex-wrap items-center justify-between gap-3 border-t px-5 py-4 bm-rule">
        <div className="flex min-w-0 flex-col gap-1.5">
          <Flags rs={rs} />
          <span className="flex items-baseline gap-1"><span className="text-[11px] bm-ink-3">from</span><span className="bm-price text-[24px]">{usd(from)}</span><span className="text-[12px] bm-ink-3">/mo</span></span>
        </div>
        <button type="button" onClick={onConfigure} className="bm-btn">Configure <span aria-hidden>→</span></button>
      </div>
    </article>
  );
}

function BuildRow({ c, rs, from, onConfigure, onPrefetch }: Row) {
  return (
    <div className="grid items-center gap-3 border-b px-5 py-4 bm-rule last:border-b-0 md:grid-cols-[minmax(0,2.2fr)_minmax(0,1fr)_minmax(0,1.3fr)_minmax(0,1.2fr)_auto] md:gap-4" onMouseEnter={onPrefetch} onFocus={onPrefetch}>
      <div className="flex min-w-0 flex-col gap-1">
        <span className="flex flex-wrap items-center gap-2">
          <span className="text-[15px] font-extrabold tracking-[-0.02em] bm-ink">{c.name}</span>
          <Tags tags={c.tags} max={1} />
        </span>
        <span className="flex min-w-0 items-center gap-2 text-[12.5px] bm-ink-2"><BrandLogo brand={cpuBrandOf(c.cpu)} h={11} /><span className="trunc">{c.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1")}</span>{c.gpu && <span className="trunc bm-ink-3">· {c.gpu}</span>}</span>
      </div>
      <span className="text-[12.5px] font-semibold bm-ink-2"><span className="bm-num bm-ink">{c.cores}</span> cores · {c.threads}t</span>
      <span className="min-w-0 text-[12.5px] bm-ink-2"><b className="bm-ink">{c.ramGb} GB</b> · <span className="trunc">{c.storage.replace(/\s*\((Soft|Hard) RAID\)/i, "")}</span></span>
      <Flags rs={rs} max={4} />
      <span className="flex items-center justify-between gap-4 md:justify-end">
        <span className="flex items-baseline gap-1"><span className="bm-price text-[18px]">{usd(from)}</span><span className="text-[11px] bm-ink-3">/mo</span></span>
        <button type="button" onClick={onConfigure} className="bm-btn bm-btn-sm">Configure</button>
      </span>
    </div>
  );
}

function Spec({ k, v, sub }: { k: string; v: string; sub?: string }) {
  return (
    <div className="min-w-0">
      <dt className="bm-label">{k}</dt>
      <dd className="mt-0.5 text-[13.5px] font-bold leading-snug bm-ink">{v}</dd>
      {sub && <dd className="text-[11.5px] bm-ink-3">{sub}</dd>}
    </div>
  );
}

function Empty({ title, body, action }: { title: string; body: string; action?: ReactNode }) {
  return (
    <section className="bm-card flex flex-col items-center gap-2 px-6 py-14 text-center">
      <span className="grid h-12 w-12 place-items-center rounded-[14px] bm-sub"><Icon name="bmrack" size={20} tone="inherit" className="bm-accent" /></span>
      <span className="mt-1 text-[16px] font-extrabold bm-ink">{title}</span>
      <span className="max-w-[48ch] text-[13px] bm-ink-3">{body}</span>
      {action && <div className="mt-2">{action}</div>}
    </section>
  );
}

export { StockDot };

toolu_013U8fmWEFHmGXffWBgWiSWY.content:
"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): step 1 of the bare-metal flow — the
 * catalogue. Hero, an interactive filter card (locations with flags, CPU brand
 * toggles with logos, NX families, range sliders for price / cores / memory /
 * storage, live result count, reset) and a card or list view.
 *
 * Receives brand-safe OrderCatalogCard rows only (lib/dedicated/order.ts). It
 * stays MOUNTED while a build is being configured (BareMetalFlow hides it), so
 * filters, view mode and scroll survive the trip back.
 */
import { useEffect, useMemo, useState, type ReactNode } from "react";
import type { OrderCatalogCard } from "@/lib/dedicated/order";
import { NX_FAMILIES, NX_FAMILY_INFO, type NxFamily } from "@/lib/dedicated/nx-names";
import { pricePerUnit } from "@/lib/dedicated/tags";
import { cpuBrandOf, gpuBrandOf } from "@/lib/dedicated/brand";
import { Icon } from "@/components/nx/Icon";
import { BrandLogo } from "../BrandLogo";
import { Flag, RangeSlider, StockDot, Tags, gbText, usd } from "../ui";

const PRICE = [0, 50, 100, 150, 200, 300, 500, 750, 1000, 1500, 2500, 5000];
const CORES = [0, 4, 6, 8, 12, 16, 24, 32, 48, 64, 96, 128, 192];
const RAM = [0, 16, 32, 64, 96, 128, 192, 256, 384, 512, 768];
const DISK = [0, 500, 1000, 2000, 4000, 8000, 16000, 32000, 64000];
type Sort = "price" | "price-desc" | "value" | "cores" | "ram" | "disk";
type Brand = "AMD" | "Intel" | "GPU";
const PAGE = 24;

const full = (steps: number[]): [number, number] => [0, steps.length - 1];
const within = (v: number, steps: number[], [lo, hi]: [number, number]) => v >= steps[lo] && (hi === steps.length - 1 || v <= steps[hi]);
const top = (steps: number[], fmt: (n: number) => string) => (n: number, edge: "min" | "max") =>
  edge === "max" && n === steps[steps.length - 1] ? `${fmt(n)}+` : fmt(n);

export function Catalogue({ cards, preview, previewAll, hero, onConfigure, onPrefetch }: {
  cards: OrderCatalogCard[];
  preview: boolean;
  previewAll: boolean;
  hero: ReactNode;
  onConfigure: (id: string, region: string | null) => void;
  onPrefetch: (id: string) => void;
}) {
  const locations = useMemo(() => {
    const m = new Map<string, { code: string; label: string; area: string; country: string; inStock: number }>();
    for (const c of cards) for (const r of c.regions) {
      const p = m.get(r.code) ?? { code: r.code, label: r.label, area: r.area, country: r.country, inStock: 0 };
      if (r.inStock) p.inStock++;
      m.set(r.code, p);
    }
    return [...m.values()].sort((a, b) => b.inStock - a.inStock || a.label.localeCompare(b.label));
  }, [cards]);

  const [regions, setRegions] = useState<string[]>([]);
  const [brands, setBrands] = useState<Brand[]>([]);
  const [families, setFamilies] = useState<NxFamily[]>([]);
  const [price, setPrice] = useState<[number, number]>(full(PRICE));
  const [cores, setCores] = useState<[number, number]>(full(CORES));
  const [ram, setRam] = useState<[number, number]>(full(RAM));
  const [disk, setDisk] = useState<[number, number]>(full(DISK));
  const [q, setQ] = useState("");
  const [sort, setSort] = useState<Sort>("price");
  const [view, setView] = useState<"cards" | "list">("cards");
  const [limit, setLimit] = useState(PAGE);
  const [filtersOpen, setFiltersOpen] = useState(false);

  // remember the viewer's layout choice (convenience only; works without storage)
  useEffect(() => { try { const v = localStorage.getItem("bm-view"); if (v === "list" || v === "cards") setView(v); } catch { /* none */ } }, []);
  const chooseView = (v: "cards" | "list") => { setView(v); try { localStorage.setItem("bm-view", v); } catch { /* none */ } };

  const toggle = <T,>(list: T[], v: T) => (list.includes(v) ? list.filter((x) => x !== v) : [...list, v]);

  const shown = useMemo(() => {
    const needle = q.trim().toLowerCase();
    const rows = cards
      .map((c) => {
        const rs = c.regions.filter((r) => r.inStock && (regions.length === 0 || regions.includes(r.code)));
        const from = rs.length ? Math.min(...rs.map((r) => r.fromMonthlyCents)) : Infinity;
        return { c, rs, from };
      })
      .filter(({ c, rs, from }) =>
        rs.length > 0 &&
        (brands.length === 0 || brands.some((b) => (b === "GPU" ? !!c.gpu : c.cpuBrand === b))) &&
        (families.length === 0 || families.includes(c.family)) &&
        within(from / 100, PRICE, price) &&
        within(c.cores, CORES, cores) &&
        (within(c.ramGb, RAM, ram) || within(c.maxRamGb, RAM, ram)) &&
        within(c.storageGb, DISK, disk) &&
        (!needle || `${c.name} ${c.cpu} ${c.gpu ?? ""} ${c.storage}`.toLowerCase().includes(needle)));
    rows.sort((a, b) =>
      sort === "price" ? a.from - b.from
        : sort === "price-desc" ? b.from - a.from
        : sort === "value" ? pricePerUnit({ ...a.c, fromMonthlyCents: a.from }) - pricePerUnit({ ...b.c, fromMonthlyCents: b.from })
        : sort === "cores" ? b.c.cores - a.c.cores || a.from - b.from
        : sort === "ram" ? b.c.maxRamGb - a.c.maxRamGb || a.from - b.from
        : b.c.storageGb - a.c.storageGb || a.from - b.from);
    return rows;
  }, [cards, regions, brands, families, price, cores, ram, disk, q, sort]);
  useEffect(() => setLimit(PAGE), [regions, brands, families, price, cores, ram, disk, q, sort]);

  const inStockTotal = useMemo(() => cards.filter((c) => c.regions.some((r) => r.inStock)).length, [cards]);
  const activeCount = regions.length + brands.length + families.length + [price, cores, ram, disk].filter((v, i) => v[0] > 0 || v[1] < [PRICE, CORES, RAM, DISK][i].length - 1).length + (q ? 1 : 0);
  const reset = () => { setRegions([]); setBrands([]); setFamilies([]); setPrice(full(PRICE)); setCores(full(CORES)); setRam(full(RAM)); setDisk(full(DISK)); setQ(""); };
  const hasGpu = cards.some((c) => c.gpu);
  const singleRegion = regions.length === 1 ? regions[0] : null;

  return (
    <div className="flex flex-col gap-5">
      {hero}

      {preview && (
        <p className="bm-sub flex items-start gap-2.5 px-4 py-3 text-[12.5px] bm-ink-2">
          <Icon name="eye" size={14} tone="inherit" className="mt-[1px] bm-accent" />
          <span><b className="bm-ink">Private preview.</b> Only accounts on the preview list can see bare metal.{previewAll ? " No builds are published yet, so every live build is listed for you." : ""}</span>
        </p>
      )}

      {/* ── filters ─────────────────────────────────────────────── */}
      <section className="bm-card p-4 sm:p-5" aria-label="Filter builds">
        <div className="flex flex-wrap items-center gap-3">
          <span className="flex items-center gap-2">
            <span className="grid h-8 w-8 place-items-center rounded-[10px] bm-sub"><Icon name="sliders" size={14} tone="inherit" className="bm-accent" /></span>
            <span className="flex flex-col leading-tight">
              <span className="text-[14px] font-extrabold bm-ink">Find your build</span>
              <span className="text-[11.5px] bm-ink-3" aria-live="polite"><b className="bm-ink bm-num">{shown.length}</b> of {inStockTotal} in-stock builds match</span>
            </span>
          </span>
          <label className="ml-auto flex h-[38px] min-w-[200px] max-w-[320px] flex-1 items-center gap-2 rounded-[10px] px-3 bm-sub">
            <Icon name="search" size={13} tone="inherit" className="bm-ink-3" />
            <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search name, CPU or GPU" aria-label="Search builds"
                   className="min-w-0 flex-1 bg-transparent text-[13px] outline-none bm-ink placeholder:text-[var(--bm-ink-4)]" />
          </label>
          <button type="button" onClick={reset} disabled={activeCount === 0} className="bm-btn-ghost">
            <Icon name="refresh" size={12} tone="inherit" />Reset{activeCount ? ` (${activeCount})` : ""}
          </button>
          <button type="button" onClick={() => setFiltersOpen((o) => !o)} className="bm-btn-ghost lg:hidden" aria-expanded={filtersOpen}>
            <Icon name="filter" size={12} tone="inherit" />{filtersOpen ? "Hide filters" : "More filters"}
          </button>
        </div>

        <div className="mt-4 flex flex-col gap-2">
          <span className="bm-label">Location</span>
          <div className="noscroll -mx-1 flex gap-2 overflow-x-auto px-1 pb-1 lg:flex-wrap">
            <button type="button" className="bm-chip" aria-pressed={regions.length === 0} onClick={() => setRegions([])}>
              <Icon name="globe" size={12} tone="inherit" />All locations
            </button>
            {locations.map((l) => (
              <button key={l.code} type="button" className="bm-chip" aria-pressed={regions.includes(l.code)} disabled={!l.inStock}
                      onClick={() => setRegions(toggle(regions, l.code))} title={l.inStock ? `${l.inStock} builds in stock` : "Sold out right now"}
                      style={l.inStock ? undefined : { opacity: 0.45, cursor: "not-allowed" }}>
                <Flag country={l.country} width={18} />
                {l.label}
                <span className="bm-num text-[11px] bm-ink-3">{l.inStock || "0"}</span>
              </button>
            ))}
          </div>
        </div>

        <div className={"mt-4 flex-col gap-4 lg:flex " + (filtersOpen ? "flex" : "hidden")}>
          <div className="grid gap-4 lg:grid-cols-[auto_minmax(0,1fr)]">
            <div className="flex flex-col gap-2">
              <span className="bm-label">Processor</span>
              <div className="flex flex-wrap gap-2">
                {(["AMD", "Intel"] as const).map((b) => (
                  <button key={b} type="button" className="bm-chip px-4" aria-pressed={brands.includes(b)} onClick={() => setBrands(toggle(brands, b))} aria-label={b}>
                    <BrandLogo brand={b === "AMD" ? "amd" : "intel"} h={b === "AMD" ? 12 : 14} />
                  </button>
                ))}
                {hasGpu && (
                  <button type="button" className="bm-chip px-4" aria-pressed={brands.includes("GPU")} onClick={() => setBrands(toggle(brands, "GPU"))} aria-label="With a GPU">
                    <BrandLogo brand="nvidia" h={13} /><span>GPU</span>
                  </button>
                )}
              </div>
            </div>
            <div className="flex min-w-0 flex-col gap-2">
              <span className="bm-label">Class</span>
              <div className="flex flex-wrap gap-2">
                {NX_FAMILIES.filter((f) => cards.some((c) => c.family === f)).map((f) => (
                  <button key={f} type="button" className="bm-chip" aria-pressed={families.includes(f)} onClick={() => setFamilies(toggle(families, f))} title={NX_FAMILY_INFO[f].blurb}>
                    <Icon name={f === "NX-GPU" ? "bmgpu" : f === "NX-Titan" ? "bmstack" : f === "NX-Pulse" ? "bolt" : f === "NX-Forge" ? "bmchip" : "bmblade"} size={12} tone="inherit" />
                    {f}<span className="hidden text-[11px] font-semibold bm-ink-3 sm:inline">{NX_FAMILY_INFO[f].short}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>
          <div className="grid gap-x-8 gap-y-4 sm:grid-cols-2 xl:grid-cols-4">
            <RangeSlider label="Monthly price" steps={PRICE} value={price} onChange={setPrice} format={top(PRICE, (n) => `$${n.toLocaleString("en-US")}`)} />
            <RangeSlider label="CPU cores" steps={CORES} value={cores} onChange={setCores} format={top(CORES, (n) => String(n))} />
            <RangeSlider label="Memory" steps={RAM} value={ram} onChange={setRam} format={top(RAM, (n) => `${n} GB`)} />
            <RangeSlider label="Storage" steps={DISK} value={disk} onChange={setDisk} format={top(DISK, (n) => gbText(n))} />
          </div>
        </div>
      </section>

      {/* ── toolbar ─────────────────────────────────────────────── */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p className="text-[12px] bm-ink-3">Prices in USD per month, from the cheapest in-stock location. Every build is online within 24 hours.</p>
        <div className="flex items-center gap-2">
          <label className="relative flex items-center">
            <span className="sr-only">Sort</span>
            <select value={sort} onChange={(e) => setSort(e.target.value as Sort)} className="bm-field h-[38px] w-[176px] cursor-pointer appearance-none pr-8 text-[12.5px] font-semibold">
              <option value="price">Lowest price</option>
              <option value="price-desc">Highest price</option>
              <option value="value">Best value</option>
              <option value="cores">Most cores</option>
              <option value="ram">Most memory</option>
              <option value="disk">Most storage</option>
            </select>
            <svg aria-hidden width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" className="pointer-events-none absolute right-3 bm-ink-3"><path d="m6 9 6 6 6-6" /></svg>
          </label>
          <div className="bm-seg" role="group" aria-label="Layout">
            <button type="button" aria-pressed={view === "cards"} onClick={() => chooseView("cards")}><Icon name="grid" size={12} tone="inherit" />Cards</button>
            <button type="button" aria-pressed={view === "list"} onClick={() => chooseView("list")}><Icon name="headerlist" size={12} tone="inherit" />List</button>
          </div>
        </div>
      </div>

      {/* ── results ─────────────────────────────────────────────── */}
      {cards.length === 0 ? (
        <Empty title="No builds are in stock right now" body="Stock moves through the day as machines are reserved and freed up. Check back shortly." />
      ) : shown.length === 0 ? (
        <Empty title="Nothing in stock matches those filters" body="Widen a range or pick another location." action={<button type="button" onClick={reset} className="bm-btn bm-btn-sm">Reset filters</button>} />
      ) : view === "cards" ? (
        <ul className="grid gap-4 md:grid-cols-2 2xl:grid-cols-3">
          {shown.slice(0, limit).map(({ c, rs, from }) => (
            <li key={c.id}><BuildCard c={c} rs={rs} from={from} onConfigure={() => onConfigure(c.id, singleRegion)} onPrefetch={() => onPrefetch(c.id)} /></li>
          ))}
        </ul>
      ) : (
        <div className="bm-card overflow-hidden">
          <div className="hidden grid-cols-[minmax(0,2.2fr)_minmax(0,1fr)_minmax(0,1.3fr)_minmax(0,1.2fr)_auto] gap-4 border-b px-5 py-3 bm-rule md:grid">
            {["Build", "CPU", "Memory · Storage", "In stock in", "Price"].map((h) => <span key={h} className="bm-label">{h}</span>)}
          </div>
          <ul>
            {shown.slice(0, limit).map(({ c, rs, from }) => (
              <li key={c.id}><BuildRow c={c} rs={rs} from={from} onConfigure={() => onConfigure(c.id, singleRegion)} onPrefetch={() => onPrefetch(c.id)} /></li>
            ))}
          </ul>
        </div>
      )}
      {shown.length > limit && (
        <div className="flex flex-col items-center gap-1.5">
          <button type="button" onClick={() => setLimit((l) => l + PAGE)} className="bm-btn-ghost">Show more builds</button>
          <span className="text-[11px] bm-ink-3">Showing {Math.min(limit, shown.length)} of {shown.length}</span>
        </div>
      )}
    </div>
  );
}

type Row = { c: OrderCatalogCard; rs: OrderCatalogCard["regions"]; from: number; onConfigure: () => void; onPrefetch: () => void };

function FamilyIcon({ family, size = 15 }: { family: NxFamily; size?: number }) {
  const name = family === "NX-GPU" ? "bmgpu" : family === "NX-Titan" ? "bmstack" : family === "NX-Forge" ? "bmchip" : family === "NX-Pulse" ? "bolt" : "bmblade";
  return <Icon name={name} size={size} tone="inherit" className="bm-accent" />;
}

function Flags({ rs, max = 5 }: { rs: OrderCatalogCard["regions"]; max?: number }) {
  const uniq = rs.filter((r, i) => rs.findIndex((x) => x.country === r.country) === i);
  return (
    <span className="flex items-center gap-1.5" aria-label={`In stock in ${rs.map((r) => r.label).join(", ")}`} title={rs.map((r) => r.label).join(", ")}>
      {uniq.slice(0, max).map((r) => <Flag key={r.country} country={r.country} width={18} />)}
      {uniq.length > max && <span className="text-[11px] font-bold bm-ink-3">+{uniq.length - max}</span>}
      <span className="ml-0.5 text-[11.5px] bm-ink-3">{rs.length === 1 ? rs[0].label : `${rs.length} locations`}</span>
    </span>
  );
}

function BuildCard({ c, rs, from, onConfigure, onPrefetch }: Row) {
  const cpuShort = c.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1");
  return (
    <article className="bm-card group flex h-full flex-col transition-[border-color,transform] duration-150 hover:border-[var(--bm-line-2)]" onMouseEnter={onPrefetch} onFocus={onPrefetch}>
      <div className="flex flex-col gap-3 p-5 pb-4">
        <div className="flex items-center justify-between gap-2">
          <span className="flex items-center gap-1.5 text-[11px] font-bold bm-ink-3"><FamilyIcon family={c.family} size={11} />{NX_FAMILY_INFO[c.family].short}</span>
          <Tags tags={c.tags} />
        </div>
        <div>
          <h3 className="text-[21px] font-extrabold leading-tight tracking-[-0.03em] bm-ink">{c.name}</h3>
          <p className="mt-1 flex min-w-0 items-center gap-2 text-[13px] font-semibold bm-ink-2" title={c.cpu}>
            <BrandLogo brand={cpuBrandOf(c.cpu)} h={12} />
            <span className="trunc">{cpuShort}</span>
          </p>
        </div>
        <dl className="grid grid-cols-2 gap-x-4 gap-y-3 pt-1">
          <Spec k="Cores" v={`${c.cores} cores · ${c.threads} threads`} sub={c.boostGhz ? `up to ${c.boostGhz} GHz` : c.baseGhz ? `${c.baseGhz} GHz` : undefined} />
          <Spec k="Memory" v={`${c.ramGb} GB`} sub={c.maxRamGb > c.ramGb ? `up to ${c.maxRamGb} GB` : undefined} />
          <Spec k="Storage" v={c.storage.replace(/\s*\((Soft|Hard) RAID\)/i, "") || "—"} sub={c.storageChoose ? "more options when you configure" : /\((Soft|Hard) RAID\)/i.exec(c.storage)?.[0].replace(/[()]/g, "")} />
          <Spec k="Network" v={c.bandwidth || "—"} sub="DDoS protection included" />
        </dl>
        {c.gpu && (
          <div className="flex items-center gap-2.5 rounded-[11px] px-3 py-2 bm-sub">
            <BrandLogo brand={gpuBrandOf(c.gpu)} h={13} />
            <span className="text-[12.5px] font-bold bm-ink">{c.gpu.replace(/\b(NVIDIA|AMD)\s+/i, "")}</span>
          </div>
        )}
      </div>
      <div className="mt-auto flex flex-wrap items-center justify-between gap-3 border-t px-5 py-4 bm-rule">
        <div className="flex min-w-0 flex-col gap-1.5">
          <Flags rs={rs} />
          <span className="flex items-baseline gap-1"><span className="text-[11px] bm-ink-3">from</span><span className="bm-price text-[24px]">{usd(from)}</span><span className="text-[12px] bm-ink-3">/mo</span></span>
        </div>
        <button type="button" onClick={onConfigure} className="bm-btn">Configure <span aria-hidden>→</span></button>
      </div>
    </article>
  );
}

function BuildRow({ c, rs, from, onConfigure, onPrefetch }: Row) {
  return (
    <div className="grid items-center gap-3 border-b px-5 py-4 bm-rule last:border-b-0 md:grid-cols-[minmax(0,2.2fr)_minmax(0,1fr)_minmax(0,1.3fr)_minmax(0,1.2fr)_auto] md:gap-4" onMouseEnter={onPrefetch} onFocus={onPrefetch}>
      <div className="flex min-w-0 flex-col gap-1">
        <span className="flex flex-wrap items-center gap-2">
          <span className="text-[15px] font-extrabold tracking-[-0.02em] bm-ink">{c.name}</span>
          <Tags tags={c.tags} max={1} />
        </span>
        <span className="flex min-w-0 items-center gap-2 text-[12.5px] bm-ink-2"><BrandLogo brand={cpuBrandOf(c.cpu)} h={11} /><span className="trunc">{c.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1")}</span>{c.gpu && <span className="trunc bm-ink-3">· {c.gpu}</span>}</span>
      </div>
      <span className="text-[12.5px] font-semibold bm-ink-2"><span className="bm-num bm-ink">{c.cores}</span> cores · {c.threads}t</span>
      <span className="min-w-0 text-[12.5px] bm-ink-2"><b className="bm-ink">{c.ramGb} GB</b> · <span className="trunc">{c.storage.replace(/\s*\((Soft|Hard) RAID\)/i, "")}</span></span>
      <Flags rs={rs} max={4} />
      <span className="flex items-center justify-between gap-4 md:justify-end">
        <span className="flex items-baseline gap-1"><span className="bm-price text-[18px]">{usd(from)}</span><span className="text-[11px] bm-ink-3">/mo</span></span>
        <button type="button" onClick={onConfigure} className="bm-btn bm-btn-sm">Configure</button>
      </span>
    </div>
  );
}

function Spec({ k, v, sub }: { k: string; v: string; sub?: string }) {
  return (
    <div className="min-w-0">
      <dt className="bm-label">{k}</dt>
      <dd className="mt-0.5 text-[13.5px] font-bold leading-snug bm-ink">{v}</dd>
      {sub && <dd className="text-[11.5px] bm-ink-3">{sub}</dd>}
    </div>
  );
}

function Empty({ title, body, action }: { title: string; body: string; action?: ReactNode }) {
  return (
    <section className="bm-card flex flex-col items-center gap-2 px-6 py-14 text-center">
      <span className="grid h-12 w-12 place-items-center rounded-[14px] bm-sub"><Icon name="bmrack" size={20} tone="inherit" className="bm-accent" /></span>
      <span className="mt-1 text-[16px] font-extrabold bm-ink">{title}</span>
      <span className="max-w-[48ch] text-[13px] bm-ink-3">{body}</span>
      {action && <div className="mt-2">{action}</div>}
    </section>
  );
}

export { StockDot };

input.content:
"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): steps 2-4 of the bare-metal flow —
 * Configure (location, memory, storage, network, OS, term, name) -> Review (the
 * server's own quote) -> Pay (card or wallet).
 *
 * Every price on Review/Pay is the SERVER quote (lib/actions-dedicated-order.ts);
 * the Configure figures come from the same server-computed price table, so
 * displayed === charged.
 *
 * Payment: the portal's standard card path — the same Stripe Custom Checkout
 * session + inline card form (components/nx/NxCardFields) the VPS / game
 * deploy wizard uses — or the wallet balance, or both (balance first, card
 * for the rest). The customer picks; nothing is charged before they press Pay.
 */
import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import type { OrderBuild, OrderOption, OrderVariant } from "@/lib/dedicated/order";
import type { DedicatedQuoteResult } from "@/lib/actions-dedicated-order";
import { payDedicatedOrder, quoteDedicatedOrderAction } from "@/lib/actions-dedicated-order";
import { DEDICATED_OS, renewalLabel, type DedicatedTerm } from "@/lib/dedicated/order-core";
import { NX_FAMILY_INFO } from "@/lib/dedicated/nx-names";
import { cpuBrandOf, gpuBrandOf } from "@/lib/dedicated/brand";
import { Icon } from "@/components/nx/Icon";
import { NxCardFields } from "@/components/nx/NxCardFields";
import { BrandLogo } from "../BrandLogo";
import { Flag, StockDot, Tags, usd } from "../ui";

export const FLOW_STEPS = ["Choose a build", "Configure", "Review", "Pay"] as const;

function newKey(): string {
  const a = new Uint8Array(16);
  crypto.getRandomValues(a);
  return Array.from(a, (b) => b.toString(16).padStart(2, "0")).join("");
}

const comboKey = (m: string | null, d: string | null) => `${m ?? ""}|${d ?? ""}`;
const priceKey = (m: string | null, d: string | null, b: string | null) => `${m ?? ""}|${d ?? ""}|${b ?? ""}`;
const defId = (list: OrderOption[]) => list.find((o) => o.isDefault)?.id ?? list[0]?.id ?? null;

function bestPartner(v: OrderVariant, fixed: "memory" | "storage", id: string | null): string | null {
  const other = fixed === "memory" ? v.storage : v.memory;
  if (!other.length) return null;
  const ok = other.filter((o) => v.inStock.includes(fixed === "memory" ? comboKey(id, o.id) : comboKey(o.id, id)));
  return (ok[0] ?? other.find((o) => o.isDefault) ?? other[0]).id;
}

type Method = "card" | "wallet" | "split";

export function Stepper({ at, onJump }: { at: number; onJump: (i: number) => void }) {
  return (
    <ol className="flex items-center gap-1.5 overflow-x-auto noscroll" aria-label="Order progress">
      {FLOW_STEPS.map((s, i) => {
        const done = i < at, on = i === at;
        return (
          <li key={s} className="flex flex-none items-center gap-1.5">
            <button type="button" disabled={i > at} onClick={() => onJump(i)} aria-current={on ? "step" : undefined}
                    className={"flex items-center gap-2 rounded-full px-2.5 py-1.5 text-[12px] font-bold transition " + (on ? "bm-ink" : done ? "bm-ink-2 hover:bm-ink" : "bm-ink-4")}
                    style={on ? { background: "var(--bm-accent-soft)", boxShadow: "0 0 0 1px var(--bm-accent) inset" } : undefined}>
              <span className="grid h-5 w-5 place-items-center rounded-full text-[10.5px]"
                    style={{ background: done ? "var(--bm-ok-soft)" : on ? "var(--bm-grad)" : "var(--bm-card-3)", color: done ? "var(--bm-ok)" : on ? "#fff" : "var(--bm-ink-3)" }}>
                {done ? <Icon name="check" size={9} tone="inherit" /> : i + 1}
              </span>
              <span className={i === at ? "" : "hidden sm:inline"}>{s}</span>
            </button>
            {i < FLOW_STEPS.length - 1 && <span aria-hidden className="h-px w-4 flex-none sm:w-8" style={{ background: "var(--bm-line-2)" }} />}
          </li>
        );
      })}
    </ol>
  );
}

export function Configurator({ build, initialRegion, balanceCents, email, onBack }: {
  build: OrderBuild; initialRegion: string | null; balanceCents: number; email: string; onBack: () => void;
}) {
  const router = useRouter();
  const firstRegion = build.variants.find((v) => v.region === initialRegion && v.inStock.length) ?? build.variants.find((v) => v.inStock.length) ?? build.variants[0];
  const [step, setStep] = useState(1);
  const [region, setRegion] = useState(firstRegion.region);
  const variant = build.variants.find((v) => v.region === region) ?? firstRegion;
  const initialCombo = (v: OrderVariant): { m: string | null; d: string | null } => {
    const m = defId(v.memory), d = defId(v.storage);
    if (v.inStock.includes(comboKey(m, d)) || !v.inStock.length) return { m, d };
    const [mm, dd] = v.inStock[0].split("|");
    return { m: mm || null, d: dd || null };
  };
  const [memoryId, setMemoryId] = useState<string | null>(initialCombo(firstRegion).m);
  const [storageId, setStorageId] = useState<string | null>(initialCombo(firstRegion).d);
  const [bandwidthId, setBandwidthId] = useState<string | null>(defId(firstRegion.bandwidth));
  const [os, setOs] = useState(DEDICATED_OS[0].id);
  const [term, setTerm] = useState<DedicatedTerm>(1);
  const [label, setLabel] = useState("");
  const orderKey = useRef<string>("");
  if (!orderKey.current) orderKey.current = newKey();
  useEffect(() => { window.scrollTo({ top: 0 }); }, [step]);

  const chooseRegion = (code: string) => {
    const next = build.variants.find((v) => v.region === code);
    if (!next) return;
    const byLabel = (from: OrderOption[], to: OrderOption[], id: string | null): string | null => to.find((o) => o.label === from.find((x) => x.id === id)?.label)?.id ?? defId(to);
    let m: string | null = byLabel(variant.memory, next.memory, memoryId);
    let d: string | null = byLabel(variant.storage, next.storage, storageId);
    if (next.inStock.length && !next.inStock.includes(comboKey(m, d))) {
      const alt = bestPartner(next, "memory", m);
      if (next.inStock.includes(comboKey(m, alt))) d = alt;
      else ({ m, d } = initialCombo(next));
    }
    setRegion(code);
    setMemoryId(m);
    setStorageId(d);
    setBandwidthId(byLabel(variant.bandwidth, next.bandwidth, bandwidthId));
  };
  const chooseMemory = (id: string) => {
    setMemoryId(id);
    if (!variant.inStock.includes(comboKey(id, storageId))) setStorageId(bestPartner(variant, "memory", id));
  };
  const chooseStorage = (id: string) => {
    setStorageId(id);
    if (!variant.inStock.includes(comboKey(memoryId, id))) setMemoryId(bestPartner(variant, "storage", id));
  };

  const inStock = variant.inStock.includes(comboKey(memoryId, storageId));
  const monthly = variant.prices[priceKey(memoryId, storageId, bandwidthId)] ?? null;
  const memOk = (id: string) => variant.inStock.some((k) => k.startsWith(`${id}|`));
  const diskOk = (id: string) => variant.inStock.some((k) => k.endsWith(`|${id}`));

  const intent = useMemo(() => ({
    itemId: variant.itemId, region, os, termMonths: term, memoryId, storageId, bandwidthId, label: label.trim(), orderKey: orderKey.current,
  }), [variant.itemId, region, os, term, memoryId, storageId, bandwidthId, label]);

  /* ---------- review: the server's quote ---------- */
  const [quote, setQuote] = useState<DedicatedQuoteResult | null>(null);
  const [quoting, startQuote] = useTransition();
  const runQuote = useCallback(() => startQuote(async () => setQuote(await quoteDedicatedOrderAction(intent, true))), [intent]);
  useEffect(() => { if (step === 2) runQuote(); }, [step, runQuote]);
  const q = quote && quote.ok ? quote : null;
  const total = q?.quote.money.totalCents ?? 0;

  /* ---------- pay ---------- */
  const canWallet = balanceCents >= total && total > 0;
  const canSplit = balanceCents > 0 && balanceCents < total;
  const [method, setMethod] = useState<Method>("card");
  useEffect(() => { if (step === 3) setMethod(canWallet ? "wallet" : "card"); }, [step, canWallet]);
  const useWallet = method !== "card";
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string; cardCents: number; walletApplied: number; method: Method } | null>(null);
  const [payError, setPayError] = useState<string | null>(null);
  const [paying, setPaying] = useState(false);
  const [preparing, startPrep] = useTransition();
  const cardConfirm = useRef<(() => Promise<void>) | null>(null);
  const [canConfirm, setCanConfirm] = useState(false);
  const onConfirmReady = useCallback((fn: (() => Promise<void>) | null) => { cardConfirm.current = fn; setCanConfirm(!!fn); }, []);
  const onBusy = useCallback((b: boolean, err: string | null) => { setPaying(b); setPayError(err); }, []);

  // Open the card session for the chosen method (card or wallet+card) once per method.
  useEffect(() => {
    if (step !== 3 || method === "wallet" || !q) return;
    if (checkout && checkout.method === method) return;
    setCheckout(null);
    setCanConfirm(false);
    setPayError(null);
    startPrep(async () => {
      const r = await payDedicatedOrder(intent, method === "split");
      if (!r.ok) setPayError(r.error);
      else if ("checkout" in r) setCheckout({ ...r.checkout, cardCents: r.cardCents, walletApplied: r.walletApplied, method });
      else router.push(`/dashboard/dedicated/${r.serverId}?ordered=1`);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step, method, q]);

  const payNow = () => {
    setPayError(null);
    if (method === "wallet") {
      setPaying(true);
      startPrep(async () => {
        const r = await payDedicatedOrder(intent, true);
        if (!r.ok) { setPayError(r.error); setPaying(false); return; }
        if ("serverId" in r) router.push(`/dashboard/dedicated/${r.serverId}?ordered=1`);
        else { setCheckout({ ...r.checkout, cardCents: r.cardCents, walletApplied: r.walletApplied, method: "split" }); setMethod("split"); setPaying(false); }
      });
      return;
    }
    void cardConfirm.current?.();
  };

  const mem = variant.memory.find((o) => o.id === memoryId);
  const disk = variant.storage.find((o) => o.id === storageId);
  const bw = variant.bandwidth.find((o) => o.id === bandwidthId);
  const osObj = DEDICATED_OS.find((o) => o.id === os)!;
  const canContinue = inStock && monthly != null;
  const cardDue = method === "card" ? total : method === "split" ? (checkout?.method === "split" ? checkout.cardCents : Math.max(0, total - balanceCents)) : 0;
  const walletDue = method === "wallet" ? total : method === "split" ? (checkout?.method === "split" ? checkout.walletApplied : Math.min(balanceCents, total)) : 0;

  return (
    <div className="bm-enter flex flex-col gap-5">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <button type="button" onClick={step === 1 ? onBack : () => setStep(step - 1)} className="bm-btn-ghost">
          <span aria-hidden>←</span>{step === 1 ? "All builds" : "Back"}
        </button>
        <Stepper at={step} onJump={(i) => (i === 0 ? onBack() : setStep(i))} />
      </div>

      <BuildHeader build={build} />

      {step === 1 && (
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_370px]">
          <div className="flex min-w-0 flex-col gap-4">
            <Section n={1} title="Location" help="Only locations with this build in stock can be ordered.">
              <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3">
                {build.variants.map((v) => {
                  const ok = v.inStock.length > 0;
                  const from = ok ? Math.min(...Object.values(v.prices)) : null;
                  return (
                    <button key={v.region} type="button" className="bm-pick flex items-center gap-3 p-3" aria-pressed={v.region === region} disabled={!ok} onClick={() => ok && chooseRegion(v.region)}>
                      <Flag country={v.country} width={24} />
                      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                        <span className="trunc text-[13.5px] font-bold bm-ink">{v.label}</span>
                        <span className="flex items-center gap-1.5 text-[11.5px] bm-ink-3"><StockDot on={ok} />{ok ? `from ${usd(from!)}/mo` : "Sold out here"}</span>
                      </span>
                    </button>
                  );
                })}
              </div>
            </Section>
            {variant.memory.length > 0 && (
              <Section n={2} title="Memory" help="Dedicated RAM, installed before handover.">
                <Options list={variant.memory} on={memoryId} ok={memOk} pick={chooseMemory} />
              </Section>
            )}
            {variant.storage.length > 0 && (
              <Section n={3} title="Storage" help="Disks in software RAID unless the option says otherwise.">
                <Options list={variant.storage} on={storageId} ok={diskOk} pick={chooseStorage} />
              </Section>
            )}
            {variant.bandwidth.length > 1 && (
              <Section n={4} title="Network" help="Unmetered public bandwidth. DDoS protection is always included.">
                <Options list={variant.bandwidth} on={bandwidthId} ok={() => true} pick={setBandwidthId} />
              </Section>
            )}
            <Section n={5} title="Operating system" help="Installed and hardened by our team. You get full root.">
              <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3">
                {DEDICATED_OS.map((o) => (
                  <button key={o.id} type="button" className="bm-pick flex items-center gap-3 p-3" aria-pressed={o.id === os} onClick={() => setOs(o.id)}>
                    <Icon name="terminal" size={14} tone="inherit" className="bm-ink-3" />
                    <span className="flex min-w-0 flex-col gap-0.5">
                      <span className="trunc text-[13.5px] font-bold bm-ink">{o.label}</span>
                      <span className="trunc text-[11.5px] bm-ink-3">{o.note}</span>
                    </span>
                  </button>
                ))}
              </div>
            </Section>
            <Section n={6} title="Billing term" help="Pay monthly, or a year up front. Renews at the same price.">
              <div className="grid gap-2.5 sm:grid-cols-2">
                {([1, 12] as const).map((t) => (
                  <button key={t} type="button" className="bm-pick flex flex-col gap-1 p-3.5" aria-pressed={term === t} onClick={() => setTerm(t)}>
                    <span className="text-[14px] font-extrabold bm-ink">{t === 1 ? "Monthly" : "Annual"}</span>
                    <span className="bm-num text-[13px] font-bold bm-ink-2">{monthly != null ? renewalLabel(monthly, t) : "—"}</span>
                    <span className="text-[11.5px] bm-ink-3">{t === 1 ? "Billed every month." : "Billed once a year, up front."}</span>
                  </button>
                ))}
              </div>
            </Section>
            <Section n={7} title="Name it" help="Optional. Shown on your dashboard and invoices.">
              <input value={label} onChange={(e) => setLabel(e.target.value.slice(0, 40))} placeholder="e.g. Production database" className="bm-field max-w-[420px]" aria-label="Server name" />
            </Section>
          </div>
          <aside className="xl:sticky xl:top-4 xl:self-start">
            <section className="bm-card flex flex-col gap-4 p-5">
              <span className="text-[15px] font-extrabold bm-ink">Your server</span>
              <ul className="flex flex-col gap-2.5 text-[13px] bm-ink-2">
                <Li icon={<BrandLogo brand={cpuBrandOf(build.cpu)} h={11} />}>{build.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1")} · {build.cores}c / {build.threads}t</Li>
                {build.gpu && <Li icon={<BrandLogo brand={gpuBrandOf(build.gpu)} h={11} />}>{build.gpu}</Li>}
                <Li icon={<Icon name="ram" size={13} tone="inherit" />}>{mem ? mem.label : `${build.ramGb} GB`}</Li>
                <Li icon={<Icon name="database" size={13} tone="inherit" />}>{disk ? disk.label : build.storage}</Li>
                {(bw || build.bandwidth) && <Li icon={<Icon name="nodes" size={13} tone="inherit" />}>{bw ? bw.label : build.bandwidth}</Li>}
                <Li icon={<Flag country={variant.country} width={16} />}>{variant.label}</Li>
                <Li icon={<Icon name="terminal" size={13} tone="inherit" />}>{osObj.label}</Li>
              </ul>
              <div className="bm-hr" />
              {canContinue ? (
                <div className="flex flex-col gap-1.5">
                  <div className="flex items-baseline justify-between"><span className="text-[12px] bm-ink-3">{term === 12 ? "Annual" : "Monthly"}</span><span className="bm-price text-[24px]">{renewalLabel(monthly!, term)}</span></div>
                  <div className="flex items-baseline justify-between text-[12.5px]"><span className="bm-ink-3">One-time setup</span><span className="font-bold bm-ink-2">{variant.setupCents > 0 ? usd(variant.setupCents) : "Free"}</span></div>
                  <span className="mt-1 flex items-center gap-1.5 text-[11.5px] font-semibold bm-ok"><Icon name="clock" size={11} tone="inherit" />Online within 24 hours</span>
                </div>
              ) : (
                <p className="rounded-[11px] px-3 py-2.5 text-[12.5px]" style={{ background: "var(--bm-warn-soft)", color: "var(--bm-warn)" }}>
                  This combination isn&apos;t in stock in {variant.label}. Pick another memory or storage option, or another location.
                </p>
              )}
              <button type="button" disabled={!canContinue} onClick={() => setStep(2)} className="bm-btn w-full">Review order <span aria-hidden>→</span></button>
              <span className="text-center text-[11px] bm-ink-4">Tax, if any, is shown on the next step.</span>
            </section>
          </aside>
        </div>
      )}

      {step === 2 && (
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]">
          <section className="bm-card flex min-w-0 flex-col gap-4 p-5">
            <div className="flex items-start justify-between gap-3">
              <div>
                <span className="text-[17px] font-extrabold bm-ink">Review your order</span>
                <p className="text-[12px] bm-ink-3">Priced just now from live stock.</p>
              </div>
              <button type="button" onClick={() => setStep(1)} className="bm-btn-ghost">Change</button>
            </div>
            {!quote || quoting ? (
              <div className="grid gap-3 sm:grid-cols-2" aria-busy="true" aria-label="Pricing your order">{Array.from({ length: 6 }, (_, i) => <div key={i} className="bm-skel h-[64px]" />)}</div>
            ) : !quote.ok ? (
              <ErrorBox msg={quote.error} onBack={() => setStep(1)} onRetry={runQuote} />
            ) : (
              <>
                <dl className="grid gap-3 sm:grid-cols-2">
                  {[
                    ["Server", quote.quote.spec.name, NX_FAMILY_INFO[quote.quote.spec.family].blurb],
                    ["Processor", quote.quote.spec.cpu, `${quote.quote.spec.cores} cores · ${quote.quote.spec.threads} threads`],
                    ["Memory", `${quote.quote.spec.ramGb} GB`, "Dedicated to you"],
                    ["Storage", quote.quote.spec.storage, "Your own disks"],
                    ["Network", quote.quote.spec.bandwidth || "—", "DDoS protection included"],
                    ["Location", quote.quote.regionLabel, ""],
                    ["Operating system", quote.quote.osLabel, "Full root access"],
                    ...(quote.quote.spec.gpu ? [["GPU", quote.quote.spec.gpu, "Dedicated to you"]] : []),
                  ].map(([k, v, sub]) => (
                    <div key={k} className="bm-sub px-3.5 py-3">
                      <dt className="bm-label">{k}</dt>
                      <dd className="mt-0.5 text-[13.5px] font-bold bm-ink">{v}</dd>
                      {sub && <dd className="text-[11.5px] bm-ink-3">{sub}</dd>}
                    </div>
                  ))}
                </dl>
                <WhatNext />
              </>
            )}
          </section>
          <aside className="xl:self-start">
            <section className="bm-card flex flex-col gap-3 p-5">
              <span className="text-[15px] font-extrabold bm-ink">Order summary</span>
              {q ? (
                <>
                  <Money rows={[
                    [`${q.quote.termLabel} term`, usd(q.quote.money.termCents)],
                    ["One-time setup", q.quote.money.setupCents ? usd(q.quote.money.setupCents) : "Free"],
                    ...(q.quote.money.taxCents ? [[`Tax (${q.quote.money.taxRatePercent}%${q.quote.money.taxCountry ? ` ${q.quote.money.taxCountry}` : ""})`, usd(q.quote.money.taxCents)] as [string, string]] : []),
                  ]} total={["Total today", usd(q.quote.money.totalCents)]} />
                  <p className="text-[12px] bm-ink-3">Renews at <b className="bm-ink-2">{q.quote.renewal}</b>{q.quote.money.taxCents ? " plus tax" : ""}.</p>
                  <button type="button" onClick={() => setStep(3)} className="bm-btn w-full">Continue to payment <span aria-hidden>→</span></button>
                  <span className="flex items-center justify-center gap-1.5 text-[11px] bm-ink-4"><Icon name="card" size={11} tone="inherit" />Card or wallet balance on the next step</span>
                </>
              ) : (
                <div className="flex flex-col gap-2" aria-hidden><div className="bm-skel h-4" /><div className="bm-skel h-4 w-2/3" /><div className="bm-skel h-10" /></div>
              )}
            </section>
          </aside>
        </div>
      )}

      {step === 3 && q && (
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]">
          <section className="bm-card flex min-w-0 flex-col gap-4 p-5">
            <div className="flex items-center gap-2.5">
              <Icon name="lock" size={16} tone="inherit" className="bm-accent" />
              <div>
                <span className="text-[17px] font-extrabold bm-ink">How would you like to pay?</span>
                <p className="text-[12px] bm-ink-3">Card details are handled by our payment processor and never touch our servers.</p>
              </div>
            </div>
            <div className="grid gap-2.5 sm:grid-cols-3" role="radiogroup" aria-label="Payment method">
              <MethodTile on={method === "card"} onPick={() => setMethod("card")} icon="card" title="Card" sub={`${usd(total)} by credit or debit card`} />
              <MethodTile on={method === "wallet"} onPick={() => setMethod("wallet")} disabled={!canWallet} icon="gift" title="Wallet balance"
                          sub={canWallet ? `${usd(total)} from your ${usd(balanceCents)} balance` : `Balance ${usd(balanceCents)} — not enough on its own`} />
              {canSplit && <MethodTile on={method === "split"} onPick={() => setMethod("split")} icon="swap" title="Balance + card" sub={`${usd(Math.min(balanceCents, total))} from balance, the rest by card`} />}
            </div>
            <div className="bm-sub min-h-[200px] p-4">
              {method === "wallet" ? (
                <div className="flex h-full flex-col items-center justify-center gap-1.5 py-8 text-center">
                  <Icon name="checkcircle" size={24} tone="inherit" className="bm-ok" />
                  <span className="text-[14px] font-bold bm-ink">Covered by your balance</span>
                  <span className="text-[12px] bm-ink-3">{usd(total)} will be taken from your {usd(balanceCents)} balance when you press Pay.</span>
                </div>
              ) : checkout && checkout.method === method ? (
                <NxCardFields clientSecret={checkout.clientSecret} publishableKey={checkout.publishableKey} onConfirmReady={onConfirmReady} onBusy={onBusy} />
              ) : payError ? null : (
                <div className="flex flex-col items-center gap-2 py-10 text-center" aria-busy="true">
                  <Icon name="lock" size={22} tone="inherit" className="bm-ink-3" />
                  <span className="text-[13.5px] font-bold bm-ink">Preparing your secure card form…</span>
                </div>
              )}
              {payError && <ErrorBox msg={payError} onBack={() => setStep(2)} />}
            </div>
          </section>
          <aside className="xl:self-start">
            <section className="bm-card flex flex-col gap-3 p-5">
              <span className="text-[15px] font-extrabold bm-ink">Order summary</span>
              <p className="text-[12.5px] bm-ink-2"><b className="bm-ink">{q.quote.spec.name}</b> · {q.quote.spec.ramGb} GB · {q.quote.regionLabel}</p>
              <Money rows={[
                ["Total today", usd(total)],
                ...(walletDue > 0 ? [["From wallet", `−${usd(walletDue)}`] as [string, string]] : []),
              ]} total={[method === "wallet" ? "From wallet" : "To pay by card", usd(method === "wallet" ? total : cardDue)]} />
              <p className="text-[12px] bm-ink-3">Renews at <b className="bm-ink-2">{q.quote.renewal}</b>.</p>
              <button type="button" onClick={payNow} disabled={paying || preparing || (method !== "wallet" && !canConfirm)} className="bm-btn w-full">
                {paying ? "Processing…" : `Pay ${usd(method === "wallet" ? total : cardDue)}`}
              </button>
              <span className="text-center text-[10.5px] bm-ink-4">Signed in as {email}</span>
            </section>
          </aside>
        </div>
      )}
    </div>
  );
}

function BuildHeader({ build }: { build: OrderBuild }) {
  return (
    <section className="bm-card flex flex-wrap items-end justify-between gap-4 p-5">
      <div className="min-w-0">
        <span className="flex items-center gap-2"><span className="bm-eyebrow">{build.family}</span><Tags tags={build.tags} /></span>
        <h2 className="mt-1 text-[26px] font-extrabold tracking-[-0.03em] bm-ink sm:text-[30px]">{build.name}</h2>
        <p className="mt-1 flex flex-wrap items-center gap-2 text-[13px] bm-ink-2">
          <BrandLogo brand={cpuBrandOf(build.cpu)} h={13} />
          <span className="font-semibold bm-ink">{build.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1")}</span>
          <span className="bm-ink-3">· {build.cores} cores · {build.threads} threads{build.baseGhz ? ` · ${build.baseGhz} GHz` : ""}{build.boostGhz ? ` (boost ${build.boostGhz} GHz)` : ""}</span>
        </p>
        {build.gpu && <p className="mt-1.5 flex items-center gap-2 text-[13px] font-bold bm-ink"><BrandLogo brand={gpuBrandOf(build.gpu)} h={13} />{build.gpu}</p>}
      </div>
      <div className="text-right">
        <div className="bm-label">from</div>
        <div><span className="bm-price text-[28px]">{usd(build.fromMonthlyCents)}</span><span className="text-[12px] bm-ink-3">/mo</span></div>
      </div>
    </section>
  );
}

function Section({ n, title, help, children }: { n: number; title: string; help: string; children: React.ReactNode }) {
  return (
    <section className="bm-card p-5">
      <div className="mb-3.5 flex items-start gap-3">
        <span className="grid h-6 w-6 flex-none place-items-center rounded-full text-[11px] font-extrabold" style={{ background: "var(--bm-card-3)", color: "var(--bm-ink-2)" }}>{n}</span>
        <span className="flex flex-col">
          <span className="text-[15px] font-extrabold bm-ink">{title}</span>
          <span className="text-[12px] bm-ink-3">{help}</span>
        </span>
      </div>
      {children}
    </section>
  );
}

function Options({ list, on, ok, pick }: { list: OrderOption[]; on: string | null; ok: (id: string) => boolean; pick: (id: string) => void }) {
  return (
    <div className="grid gap-2.5 sm:grid-cols-2">
      {list.map((o) => {
        const avail = ok(o.id);
        return (
          <button key={o.id} type="button" className="bm-pick flex items-center gap-3 p-3" aria-pressed={o.id === on} disabled={!avail} onClick={() => avail && pick(o.id)}>
            <span className="grid h-[17px] w-[17px] flex-none place-items-center rounded-full" style={{ border: `1.5px solid ${o.id === on ? "var(--bm-accent)" : "var(--bm-line-2)"}` }} aria-hidden>
              {o.id === on && <span className="h-[8px] w-[8px] rounded-full" style={{ background: "var(--bm-accent)" }} />}
            </span>
            <span className="flex min-w-0 flex-1 flex-col gap-0.5">
              <span className="text-[13px] font-bold leading-snug bm-ink">{o.label}</span>
              {!avail && <span className="text-[11px] bm-ink-3">Not in stock here</span>}
            </span>
            <span className="flex-none text-[12.5px] font-bold bm-ink-2">{o.isDefault ? "Included" : o.extraMonthlyCents === 0 ? "No extra cost" : `+${usd(o.extraMonthlyCents)}/mo`}</span>
          </button>
        );
      })}
    </div>
  );
}

function MethodTile({ on, onPick, disabled, icon, title, sub }: { on: boolean; onPick: () => void; disabled?: boolean; icon: string; title: string; sub: string }) {
  return (
    <button type="button" role="radio" aria-checked={on} disabled={disabled} onClick={onPick} className="bm-pick flex items-start gap-3 p-3.5">
      <span className="grid h-9 w-9 flex-none place-items-center rounded-[10px]" style={{ background: on ? "var(--bm-grad)" : "var(--bm-card-3)", color: on ? "#fff" : "var(--bm-ink-2)" }}>
        <Icon name={icon} size={15} tone="inherit" />
      </span>
      <span className="flex min-w-0 flex-col gap-0.5">
        <span className="text-[13.5px] font-extrabold bm-ink">{title}</span>
        <span className="text-[11.5px] leading-snug bm-ink-3">{sub}</span>
      </span>
    </button>
  );
}

function Li({ icon, children }: { icon: React.ReactNode; children: React.ReactNode }) {
  return <li className="flex items-center gap-2.5"><span className="grid w-5 flex-none place-items-center bm-ink-3">{icon}</span><span className="min-w-0">{children}</span></li>;
}

function Money({ rows, total }: { rows: [string, string][]; total: [string, string] }) {
  return (
    <dl className="flex flex-col gap-1.5 text-[13px]">
      {rows.map(([k, v]) => <div key={k} className="flex items-baseline justify-between gap-3"><dt className="bm-ink-3">{k}</dt><dd className="bm-num font-semibold bm-ink-2">{v}</dd></div>)}
      <div className="mt-1 flex items-baseline justify-between gap-3 border-t pt-2.5 bm-rule"><dt className="font-bold bm-ink">{total[0]}</dt><dd className="bm-price text-[22px]">{total[1]}</dd></div>
    </dl>
  );
}

function WhatNext() {
  const steps = [
    { t: "You pay", d: "Your machine is reserved the moment payment clears." },
    { t: "We build it", d: "Our engineers install your OS, harden it and run burn-in checks." },
    { t: "Online within 24 hours", d: "Its IP addresses and your login appear on its dashboard." },
  ];
  return (
    <div className="bm-sub p-4">
      <span className="bm-label">What happens next</span>
      <ol className="mt-3 grid gap-3 sm:grid-cols-3">
        {steps.map((s, i) => (
          <li key={s.t} className="flex items-start gap-2.5">
            <span className="grid h-6 w-6 flex-none place-items-center rounded-full text-[11px] font-extrabold text-[#fff]" style={{ background: "var(--bm-grad)" }}>{i + 1}</span>
            <span className="min-w-0"><span className="block text-[12.5px] font-bold bm-ink">{s.t}</span><span className="block text-[11.5px] bm-ink-3">{s.d}</span></span>
          </li>
        ))}
      </ol>
    </div>
  );
}

function ErrorBox({ msg, onBack, onRetry }: { msg: string; onBack: () => void; onRetry?: () => void }) {
  return (
    <div className="flex flex-col items-start gap-2 rounded-[12px] p-4" style={{ background: "var(--bm-bad-soft)", border: "1px solid color-mix(in srgb, var(--bm-bad) 35%, transparent)" }}>
      <span className="flex items-center gap-2 text-[13px] font-bold bm-ink"><Icon name="warntriangle" size={14} tone="inherit" className="bm-bad" />We couldn&apos;t continue</span>
      <span className="text-[12.5px] bm-ink-2">{msg}</span>
      <div className="flex flex-wrap gap-2">
        <button type="button" onClick={onBack} className="bm-btn-ghost">Change the order</button>
        {onRetry && <button type="button" onClick={onRetry} className="bm-btn-ghost">Try again</button>}
        <Link href="/dashboard/support" className="bm-btn-ghost">Contact support</Link>
      </div>
    </div>
  );
}

toolu_01TqZEv9wpZ3Njg6hkffAArm.content:
"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): steps 2-4 of the bare-metal flow —
 * Configure (location, memory, storage, network, OS, term, name) -> Review (the
 * server's own quote) -> Pay (card or wallet).
 *
 * Every price on Review/Pay is the SERVER quote (lib/actions-dedicated-order.ts);
 * the Configure figures come from the same server-computed price table, so
 * displayed === charged.
 *
 * Payment: the portal's standard card path — the same Stripe Custom Checkout
 * session + inline card form (components/nx/NxCardFields) the VPS / game
 * deploy wizard uses — or the wallet balance, or both (balance first, card
 * for the rest). The customer picks; nothing is charged before they press Pay.
 */
import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import type { OrderBuild, OrderOption, OrderVariant } from "@/lib/dedicated/order";
import type { DedicatedQuoteResult } from "@/lib/actions-dedicated-order";
import { payDedicatedOrder, quoteDedicatedOrderAction } from "@/lib/actions-dedicated-order";
import { DEDICATED_OS, renewalLabel, type DedicatedTerm } from "@/lib/dedicated/order-core";
import { NX_FAMILY_INFO } from "@/lib/dedicated/nx-names";
import { cpuBrandOf, gpuBrandOf } from "@/lib/dedicated/brand";
import { Icon } from "@/components/nx/Icon";
import { NxCardFields } from "@/components/nx/NxCardFields";
import { BrandLogo } from "../BrandLogo";
import { Flag, StockDot, Tags, usd } from "../ui";

export const FLOW_STEPS = ["Choose a build", "Configure", "Review", "Pay"] as const;

function newKey(): string {
  const a = new Uint8Array(16);
  crypto.getRandomValues(a);
  return Array.from(a, (b) => b.toString(16).padStart(2, "0")).join("");
}

const comboKey = (m: string | null, d: string | null) => `${m ?? ""}|${d ?? ""}`;
const priceKey = (m: string | null, d: string | null, b: string | null) => `${m ?? ""}|${d ?? ""}|${b ?? ""}`;
const defId = (list: OrderOption[]) => list.find((o) => o.isDefault)?.id ?? list[0]?.id ?? null;

function bestPartner(v: OrderVariant, fixed: "memory" | "storage", id: string | null): string | null {
  const other = fixed === "memory" ? v.storage : v.memory;
  if (!other.length) return null;
  const ok = other.filter((o) => v.inStock.includes(fixed === "memory" ? comboKey(id, o.id) : comboKey(o.id, id)));
  return (ok[0] ?? other.find((o) => o.isDefault) ?? other[0]).id;
}

type Method = "card" | "wallet" | "split";

export function Stepper({ at, onJump }: { at: number; onJump: (i: number) => void }) {
  return (
    <ol className="flex items-center gap-1.5 overflow-x-auto noscroll" aria-label="Order progress">
      {FLOW_STEPS.map((s, i) => {
        const done = i < at, on = i === at;
        return (
          <li key={s} className="flex flex-none items-center gap-1.5">
            <button type="button" disabled={i > at} onClick={() => onJump(i)} aria-current={on ? "step" : undefined}
                    className={"flex items-center gap-2 rounded-full px-2.5 py-1.5 text-[12px] font-bold transition " + (on ? "bm-ink" : done ? "bm-ink-2 hover:bm-ink" : "bm-ink-4")}
                    style={on ? { background: "var(--bm-accent-soft)", boxShadow: "0 0 0 1px var(--bm-accent) inset" } : undefined}>
              <span className="grid h-5 w-5 place-items-center rounded-full text-[10.5px]"
                    style={{ background: done ? "var(--bm-ok-soft)" : on ? "var(--bm-grad)" : "var(--bm-card-3)", color: done ? "var(--bm-ok)" : on ? "#fff" : "var(--bm-ink-3)" }}>
                {done ? <Icon name="check" size={9} tone="inherit" /> : i + 1}
              </span>
              <span className={i === at ? "" : "hidden sm:inline"}>{s}</span>
            </button>
            {i < FLOW_STEPS.length - 1 && <span aria-hidden className="h-px w-4 flex-none sm:w-8" style={{ background: "var(--bm-line-2)" }} />}
          </li>
        );
      })}
    </ol>
  );
}

export function Configurator({ build, initialRegion, balanceCents, email, onBack }: {
  build: OrderBuild; initialRegion: string | null; balanceCents: number; email: string; onBack: () => void;
}) {
  const router = useRouter();
  const firstRegion = build.variants.find((v) => v.region === initialRegion && v.inStock.length) ?? build.variants.find((v) => v.inStock.length) ?? build.variants[0];
  const [step, setStep] = useState(1);
  const [region, setRegion] = useState(firstRegion.region);
  const variant = build.variants.find((v) => v.region === region) ?? firstRegion;
  const initialCombo = (v: OrderVariant): { m: string | null; d: string | null } => {
    const m = defId(v.memory), d = defId(v.storage);
    if (v.inStock.includes(comboKey(m, d)) || !v.inStock.length) return { m, d };
    const [mm, dd] = v.inStock[0].split("|");
    return { m: mm || null, d: dd || null };
  };
  const [memoryId, setMemoryId] = useState<string | null>(initialCombo(firstRegion).m);
  const [storageId, setStorageId] = useState<string | null>(initialCombo(firstRegion).d);
  const [bandwidthId, setBandwidthId] = useState<string | null>(defId(firstRegion.bandwidth));
  const [os, setOs] = useState(DEDICATED_OS[0].id);
  const [term, setTerm] = useState<DedicatedTerm>(1);
  const [label, setLabel] = useState("");
  const orderKey = useRef<string>("");
  if (!orderKey.current) orderKey.current = newKey();
  useEffect(() => { window.scrollTo({ top: 0 }); }, [step]);

  const chooseRegion = (code: string) => {
    const next = build.variants.find((v) => v.region === code);
    if (!next) return;
    const byLabel = (from: OrderOption[], to: OrderOption[], id: string | null): string | null => to.find((o) => o.label === from.find((x) => x.id === id)?.label)?.id ?? defId(to);
    let m: string | null = byLabel(variant.memory, next.memory, memoryId);
    let d: string | null = byLabel(variant.storage, next.storage, storageId);
    if (next.inStock.length && !next.inStock.includes(comboKey(m, d))) {
      const alt = bestPartner(next, "memory", m);
      if (next.inStock.includes(comboKey(m, alt))) d = alt;
      else ({ m, d } = initialCombo(next));
    }
    setRegion(code);
    setMemoryId(m);
    setStorageId(d);
    setBandwidthId(byLabel(variant.bandwidth, next.bandwidth, bandwidthId));
  };
  const chooseMemory = (id: string) => {
    setMemoryId(id);
    if (!variant.inStock.includes(comboKey(id, storageId))) setStorageId(bestPartner(variant, "memory", id));
  };
  const chooseStorage = (id: string) => {
    setStorageId(id);
    if (!variant.inStock.includes(comboKey(memoryId, id))) setMemoryId(bestPartner(variant, "storage", id));
  };

  const inStock = variant.inStock.includes(comboKey(memoryId, storageId));
  const monthly = variant.prices[priceKey(memoryId, storageId, bandwidthId)] ?? null;
  const memOk = (id: string) => variant.inStock.some((k) => k.startsWith(`${id}|`));
  const diskOk = (id: string) => variant.inStock.some((k) => k.endsWith(`|${id}`));

  const intent = useMemo(() => ({
    itemId: variant.itemId, region, os, termMonths: term, memoryId, storageId, bandwidthId, label: label.trim(), orderKey: orderKey.current,
  }), [variant.itemId, region, os, term, memoryId, storageId, bandwidthId, label]);

  /* ---------- review: the server's quote ---------- */
  const [quote, setQuote] = useState<DedicatedQuoteResult | null>(null);
  const [quoting, startQuote] = useTransition();
  const runQuote = useCallback(() => startQuote(async () => setQuote(await quoteDedicatedOrderAction(intent, true))), [intent]);
  useEffect(() => { if (step === 2) runQuote(); }, [step, runQuote]);
  const q = quote && quote.ok ? quote : null;
  const total = q?.quote.money.totalCents ?? 0;

  /* ---------- pay ---------- */
  const canWallet = balanceCents >= total && total > 0;
  const canSplit = balanceCents > 0 && balanceCents < total;
  const [method, setMethod] = useState<Method>("card");
  useEffect(() => { if (step === 3) setMethod(canWallet ? "wallet" : "card"); }, [step, canWallet]);
  const useWallet = method !== "card";
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string; cardCents: number; walletApplied: number; method: Method } | null>(null);
  const [payError, setPayError] = useState<string | null>(null);
  const [paying, setPaying] = useState(false);
  const [preparing, startPrep] = useTransition();
  const cardConfirm = useRef<(() => Promise<void>) | null>(null);
  const [canConfirm, setCanConfirm] = useState(false);
  const onConfirmReady = useCallback((fn: (() => Promise<void>) | null) => { cardConfirm.current = fn; setCanConfirm(!!fn); }, []);
  const onBusy = useCallback((b: boolean, err: string | null) => { setPaying(b); setPayError(err); }, []);

  // Open the card session for the chosen method (card or wallet+card) once per method.
  useEffect(() => {
    if (step !== 3 || method === "wallet" || !q) return;
    if (checkout && checkout.method === method) return;
    setCheckout(null);
    setCanConfirm(false);
    setPayError(null);
    startPrep(async () => {
      const r = await payDedicatedOrder(intent, method === "split");
      if (!r.ok) setPayError(r.error);
      else if ("checkout" in r) setCheckout({ ...r.checkout, cardCents: r.cardCents, walletApplied: r.walletApplied, method });
      else router.push(`/dashboard/dedicated/${r.serverId}?ordered=1`);
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step, method, q]);

  const payNow = () => {
    setPayError(null);
    if (method === "wallet") {
      setPaying(true);
      startPrep(async () => {
        const r = await payDedicatedOrder(intent, true);
        if (!r.ok) { setPayError(r.error); setPaying(false); return; }
        if ("serverId" in r) router.push(`/dashboard/dedicated/${r.serverId}?ordered=1`);
        else { setCheckout({ ...r.checkout, cardCents: r.cardCents, walletApplied: r.walletApplied, method: "split" }); setMethod("split"); setPaying(false); }
      });
      return;
    }
    void cardConfirm.current?.();
  };

  const mem = variant.memory.find((o) => o.id === memoryId);
  const disk = variant.storage.find((o) => o.id === storageId);
  const bw = variant.bandwidth.find((o) => o.id === bandwidthId);
  const osObj = DEDICATED_OS.find((o) => o.id === os)!;
  const canContinue = inStock && monthly != null;
  const cardDue = method === "card" ? total : method === "split" ? (checkout?.method === "split" ? checkout.cardCents : Math.max(0, total - balanceCents)) : 0;
  const walletDue = method === "wallet" ? total : method === "split" ? (checkout?.method === "split" ? checkout.walletApplied : Math.min(balanceCents, total)) : 0;

  return (
    <div className="bm-enter flex flex-col gap-5">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <button type="button" onClick={step === 1 ? onBack : () => setStep(step - 1)} className="bm-btn-ghost">
          <span aria-hidden>←</span>{step === 1 ? "All builds" : "Back"}
        </button>
        <Stepper at={step} onJump={(i) => (i === 0 ? onBack() : setStep(i))} />
      </div>

      <BuildHeader build={build} />

      {step === 1 && (
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_370px]">
          <div className="flex min-w-0 flex-col gap-4">
            <Section n={1} title="Location" help="Only locations with this build in stock can be ordered.">
              <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3">
                {build.variants.map((v) => {
                  const ok = v.inStock.length > 0;
                  const from = ok ? Math.min(...Object.values(v.prices)) : null;
                  return (
                    <button key={v.region} type="button" className="bm-pick flex items-center gap-3 p-3" aria-pressed={v.region === region} disabled={!ok} onClick={() => ok && chooseRegion(v.region)}>
                      <Flag country={v.country} width={24} />
                      <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                        <span className="trunc text-[13.5px] font-bold bm-ink">{v.label}</span>
                        <span className="flex items-center gap-1.5 text-[11.5px] bm-ink-3"><StockDot on={ok} />{ok ? `from ${usd(from!)}/mo` : "Sold out here"}</span>
                      </span>
                    </button>
                  );
                })}
              </div>
            </Section>
            {variant.memory.length > 0 && (
              <Section n={2} title="Memory" help="Dedicated RAM, installed before handover.">
                <Options list={variant.memory} on={memoryId} ok={memOk} pick={chooseMemory} />
              </Section>
            )}
            {variant.storage.length > 0 && (
              <Section n={3} title="Storage" help="Disks in software RAID unless the option says otherwise.">
                <Options list={variant.storage} on={storageId} ok={diskOk} pick={chooseStorage} />
              </Section>
            )}
            {variant.bandwidth.length > 1 && (
              <Section n={4} title="Network" help="Unmetered public bandwidth. DDoS protection is always included.">
                <Options list={variant.bandwidth} on={bandwidthId} ok={() => true} pick={setBandwidthId} />
              </Section>
            )}
            <Section n={5} title="Operating system" help="Installed and hardened by our team. You get full root.">
              <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3">
                {DEDICATED_OS.map((o) => (
                  <button key={o.id} type="button" className="bm-pick flex items-center gap-3 p-3" aria-pressed={o.id === os} onClick={() => setOs(o.id)}>
                    <Icon name="terminal" size={14} tone="inherit" className="bm-ink-3" />
                    <span className="flex min-w-0 flex-col gap-0.5">
                      <span className="trunc text-[13.5px] font-bold bm-ink">{o.label}</span>
                      <span className="trunc text-[11.5px] bm-ink-3">{o.note}</span>
                    </span>
                  </button>
                ))}
              </div>
            </Section>
            <Section n={6} title="Billing term" help="Pay monthly, or a year up front. Renews at the same price.">
              <div className="grid gap-2.5 sm:grid-cols-2">
                {([1, 12] as const).map((t) => (
                  <button key={t} type="button" className="bm-pick flex flex-col gap-1 p-3.5" aria-pressed={term === t} onClick={() => setTerm(t)}>
                    <span className="text-[14px] font-extrabold bm-ink">{t === 1 ? "Monthly" : "Annual"}</span>
                    <span className="bm-num text-[13px] font-bold bm-ink-2">{monthly != null ? renewalLabel(monthly, t) : "—"}</span>
                    <span className="text-[11.5px] bm-ink-3">{t === 1 ? "Billed every month." : "Billed once a year, up front."}</span>
                  </button>
                ))}
              </div>
            </Section>
            <Section n={7} title="Name it" help="Optional. Shown on your dashboard and invoices.">
              <input value={label} onChange={(e) => setLabel(e.target.value.slice(0, 40))} placeholder="e.g. Production database" className="bm-field max-w-[420px]" aria-label="Server name" />
            </Section>
          </div>
          <aside className="xl:sticky xl:top-4 xl:self-start">
            <section className="bm-card flex flex-col gap-4 p-5">
              <span className="text-[15px] font-extrabold bm-ink">Your server</span>
              <ul className="flex flex-col gap-2.5 text-[13px] bm-ink-2">
                <Li icon={<BrandLogo brand={cpuBrandOf(build.cpu)} h={11} />}>{build.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1")} · {build.cores}c / {build.threads}t</Li>
                {build.gpu && <Li icon={<BrandLogo brand={gpuBrandOf(build.gpu)} h={11} />}>{build.gpu}</Li>}
                <Li icon={<Icon name="ram" size={13} tone="inherit" />}>{mem ? mem.label : `${build.ramGb} GB`}</Li>
                <Li icon={<Icon name="database" size={13} tone="inherit" />}>{disk ? disk.label : build.storage}</Li>
                {(bw || build.bandwidth) && <Li icon={<Icon name="nodes" size={13} tone="inherit" />}>{bw ? bw.label : build.bandwidth}</Li>}
                <Li icon={<Flag country={variant.country} width={16} />}>{variant.label}</Li>
                <Li icon={<Icon name="terminal" size={13} tone="inherit" />}>{osObj.label}</Li>
              </ul>
              <div className="bm-hr" />
              {canContinue ? (
                <div className="flex flex-col gap-1.5">
                  <div className="flex items-baseline justify-between"><span className="text-[12px] bm-ink-3">{term === 12 ? "Annual" : "Monthly"}</span><span className="bm-price text-[24px]">{renewalLabel(monthly!, term)}</span></div>
                  <div className="flex items-baseline justify-between text-[12.5px]"><span className="bm-ink-3">One-time setup</span><span className="font-bold bm-ink-2">{variant.setupCents > 0 ? usd(variant.setupCents) : "Free"}</span></div>
                  <span className="mt-1 flex items-center gap-1.5 text-[11.5px] font-semibold bm-ok"><Icon name="clock" size={11} tone="inherit" />Online within 24 hours</span>
                </div>
              ) : (
                <p className="rounded-[11px] px-3 py-2.5 text-[12.5px]" style={{ background: "var(--bm-warn-soft)", color: "var(--bm-warn)" }}>
                  This combination isn&apos;t in stock in {variant.label}. Pick another memory or storage option, or another location.
                </p>
              )}
              <button type="button" disabled={!canContinue} onClick={() => setStep(2)} className="bm-btn w-full">Review order <span aria-hidden>→</span></button>
              <span className="text-center text-[11px] bm-ink-4">Tax, if any, is shown on the next step.</span>
            </section>
          </aside>
        </div>
      )}

      {step === 2 && (
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]">
          <section className="bm-card flex min-w-0 flex-col gap-4 p-5">
            <div className="flex items-start justify-between gap-3">
              <div>
                <span className="text-[17px] font-extrabold bm-ink">Review your order</span>
                <p className="text-[12px] bm-ink-3">Priced just now from live stock.</p>
              </div>
              <button type="button" onClick={() => setStep(1)} className="bm-btn-ghost">Change</button>
            </div>
            {!quote || quoting ? (
              <div className="grid gap-3 sm:grid-cols-2" aria-busy="true" aria-label="Pricing your order">{Array.from({ length: 6 }, (_, i) => <div key={i} className="bm-skel h-[64px]" />)}</div>
            ) : !quote.ok ? (
              <ErrorBox msg={quote.error} onBack={() => setStep(1)} onRetry={runQuote} />
            ) : (
              <>
                <dl className="grid gap-3 sm:grid-cols-2">
                  {[
                    ["Server", quote.quote.spec.name, NX_FAMILY_INFO[quote.quote.spec.family].blurb],
                    ["Processor", quote.quote.spec.cpu, `${quote.quote.spec.cores} cores · ${quote.quote.spec.threads} threads`],
                    ["Memory", `${quote.quote.spec.ramGb} GB`, "Dedicated to you"],
                    ["Storage", quote.quote.spec.storage, "Your own disks"],
                    ["Network", quote.quote.spec.bandwidth || "—", "DDoS protection included"],
                    ["Location", quote.quote.regionLabel, ""],
                    ["Operating system", quote.quote.osLabel, "Full root access"],
                    ...(quote.quote.spec.gpu ? [["GPU", quote.quote.spec.gpu, "Dedicated to you"]] : []),
                  ].map(([k, v, sub]) => (
                    <div key={k} className="bm-sub px-3.5 py-3">
                      <dt className="bm-label">{k}</dt>
                      <dd className="mt-0.5 text-[13.5px] font-bold bm-ink">{v}</dd>
                      {sub && <dd className="text-[11.5px] bm-ink-3">{sub}</dd>}
                    </div>
                  ))}
                </dl>
                <WhatNext />
              </>
            )}
          </section>
          <aside className="xl:self-start">
            <section className="bm-card flex flex-col gap-3 p-5">
              <span className="text-[15px] font-extrabold bm-ink">Order summary</span>
              {q ? (
                <>
                  <Money rows={[
                    [`${q.quote.termLabel} term`, usd(q.quote.money.termCents)],
                    ["One-time setup", q.quote.money.setupCents ? usd(q.quote.money.setupCents) : "Free"],
                    ...(q.quote.money.taxCents ? [[`Tax (${q.quote.money.taxRatePercent}%${q.quote.money.taxCountry ? ` ${q.quote.money.taxCountry}` : ""})`, usd(q.quote.money.taxCents)] as [string, string]] : []),
                  ]} total={["Total today", usd(q.quote.money.totalCents)]} />
                  <p className="text-[12px] bm-ink-3">Renews at <b className="bm-ink-2">{q.quote.renewal}</b>{q.quote.money.taxCents ? " plus tax" : ""}.</p>
                  <button type="button" onClick={() => setStep(3)} className="bm-btn w-full">Continue to payment <span aria-hidden>→</span></button>
                  <span className="flex items-center justify-center gap-1.5 text-[11px] bm-ink-4"><Icon name="card" size={11} tone="inherit" />Card or wallet balance on the next step</span>
                </>
              ) : (
                <div className="flex flex-col gap-2" aria-hidden><div className="bm-skel h-4" /><div className="bm-skel h-4 w-2/3" /><div className="bm-skel h-10" /></div>
              )}
            </section>
          </aside>
        </div>
      )}

      {step === 3 && q && (
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_380px]">
          <section className="bm-card flex min-w-0 flex-col gap-4 p-5">
            <div className="flex items-center gap-2.5">
              <Icon name="lock" size={16} tone="inherit" className="bm-accent" />
              <div>
                <span className="text-[17px] font-extrabold bm-ink">How would you like to pay?</span>
                <p className="text-[12px] bm-ink-3">Card details are handled by our payment processor and never touch our servers.</p>
              </div>
            </div>
            <div className="grid gap-2.5 sm:grid-cols-3" role="radiogroup" aria-label="Payment method">
              <MethodTile on={method === "card"} onPick={() => setMethod("card")} icon="card" title="Card" sub={`${usd(total)} by credit or debit card`} />
              <MethodTile on={method === "wallet"} onPick={() => setMethod("wallet")} disabled={!canWallet} icon="gift" title="Wallet balance"
                          sub={canWallet ? `${usd(total)} from your ${usd(balanceCents)} balance` : `Balance ${usd(balanceCents)} — not enough on its own`} />
              {canSplit && <MethodTile on={method === "split"} onPick={() => setMethod("split")} icon="swap" title="Balance + card" sub={`${usd(Math.min(balanceCents, total))} from balance, the rest by card`} />}
            </div>
            <div className="bm-sub min-h-[200px] p-4">
              {method === "wallet" ? (
                <div className="flex h-full flex-col items-center justify-center gap-1.5 py-8 text-center">
                  <Icon name="checkcircle" size={24} tone="inherit" className="bm-ok" />
                  <span className="text-[14px] font-bold bm-ink">Covered by your balance</span>
                  <span className="text-[12px] bm-ink-3">{usd(total)} will be taken from your {usd(balanceCents)} balance when you press Pay.</span>
                </div>
              ) : checkout && checkout.method === method ? (
                <NxCardFields clientSecret={checkout.clientSecret} publishableKey={checkout.publishableKey} onConfirmReady={onConfirmReady} onBusy={onBusy} />
              ) : payError ? null : (
                <div className="flex flex-col items-center gap-2 py-10 text-center" aria-busy="true">
                  <Icon name="lock" size={22} tone="inherit" className="bm-ink-3" />
                  <span className="text-[13.5px] font-bold bm-ink">Preparing your secure card form…</span>
                </div>
              )}
              {payError && <ErrorBox msg={payError} onBack={() => setStep(2)} />}
            </div>
          </section>
          <aside className="xl:self-start">
            <section className="bm-card flex flex-col gap-3 p-5">
              <span className="text-[15px] font-extrabold bm-ink">Order summary</span>
              <p className="text-[12.5px] bm-ink-2"><b className="bm-ink">{q.quote.spec.name}</b> · {q.quote.spec.ramGb} GB · {q.quote.regionLabel}</p>
              <Money rows={[
                ["Total today", usd(total)],
                ...(walletDue > 0 ? [["From wallet", `−${usd(walletDue)}`] as [string, string]] : []),
              ]} total={[method === "wallet" ? "From wallet" : "To pay by card", usd(method === "wallet" ? total : cardDue)]} />
              <p className="text-[12px] bm-ink-3">Renews at <b className="bm-ink-2">{q.quote.renewal}</b>.</p>
              <button type="button" onClick={payNow} disabled={paying || preparing || (method !== "wallet" && !canConfirm)} className="bm-btn w-full">
                {paying ? "Processing…" : `Pay ${usd(method === "wallet" ? total : cardDue)}`}
              </button>
              <span className="text-center text-[10.5px] bm-ink-4">Signed in as {email}</span>
            </section>
          </aside>
        </div>
      )}
    </div>
  );
}

function BuildHeader({ build }: { build: OrderBuild }) {
  return (
    <section className="bm-card flex flex-wrap items-end justify-between gap-4 p-5">
      <div className="min-w-0">
        <span className="flex items-center gap-2"><span className="bm-eyebrow">{build.family}</span><Tags tags={build.tags} /></span>
        <h2 className="mt-1 text-[26px] font-extrabold tracking-[-0.03em] bm-ink sm:text-[30px]">{build.name}</h2>
        <p className="mt-1 flex flex-wrap items-center gap-2 text-[13px] bm-ink-2">
          <BrandLogo brand={cpuBrandOf(build.cpu)} h={13} />
          <span className="font-semibold bm-ink">{build.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1")}</span>
          <span className="bm-ink-3">· {build.cores} cores · {build.threads} threads{build.baseGhz ? ` · ${build.baseGhz} GHz` : ""}{build.boostGhz ? ` (boost ${build.boostGhz} GHz)` : ""}</span>
