input.content:
"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): /dashboard/dedicated IS the order flow
 * (catalogue -> configure -> review -> pay). One client component holds it so
 * moving between the catalogue and a build never re-renders the page on the
 * server:
 *
 *   - the catalogue stays mounted (hidden) while a build is configured, so its
 *     filters, layout and scroll position come back instantly;
 *   - opening a build pushes `?build=<id>` (and `&region=`) onto history, so the
 *     browser Back button, a refresh and a shared link all work;
 *   - build data comes from a gated server action, prefetched when a card is
 *     hovered or focused, and kept in memory for the visit.
 */
import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";
import type { OrderBuild, OrderCatalogCard } from "@/lib/dedicated/order";
import { loadDedicatedBuildAction } from "@/lib/actions-dedicated-order";
import { Catalogue } from "./Catalogue";
import { Configurator, Stepper } from "./Configurator";

type Open = { id: string; region: string | null };

function readUrl(): Open | null {
  const sp = new URLSearchParams(window.location.search);
  const id = sp.get("build");
  return id ? { id, region: sp.get("region") } : null;
}

export function BareMetalFlow({ cards, initialOpen, initialBuild, balanceCents, email, preview, previewAll, hero, notice }: {
  cards: OrderCatalogCard[];
  initialOpen: Open | null;
  initialBuild: OrderBuild | null;
  balanceCents: number;
  email: string;
  preview: boolean;
  previewAll: boolean;
  hero: ReactNode;
  notice?: ReactNode;
}) {
  const cache = useRef(new Map<string, Promise<OrderBuild | null>>());
  if (initialBuild && !cache.current.has(initialBuild.id)) cache.current.set(initialBuild.id, Promise.resolve(initialBuild));
  const [open, setOpen] = useState<Open | null>(initialOpen);
  const [build, setBuild] = useState<OrderBuild | null | undefined>(initialOpen ? initialBuild ?? undefined : undefined);
  const scrollY = useRef(0);

  const fetchBuild = useCallback((id: string) => {
    let p = cache.current.get(id);
    if (!p) {
      p = loadDedicatedBuildAction(id).catch(() => null);
      cache.current.set(id, p);
      // a failed/empty fetch should not be cached forever
      void p.then((b) => { if (!b) cache.current.delete(id); });
    }
    return p;
  }, []);

  // Resolve whichever build is open.
  useEffect(() => {
    if (!open) { setBuild(undefined); return; }
    let live = true;
    setBuild((b) => (b && b.id === open.id ? b : undefined));
    void fetchBuild(open.id).then((b) => { if (live) setBuild(b); });
    return () => { live = false; };
  }, [open, fetchBuild]);

  // Browser Back / Forward.
  useEffect(() => {
    const onPop = () => {
      const next = readUrl();
      setOpen(next);
      if (!next) requestAnimationFrame(() => window.scrollTo({ top: scrollY.current }));
    };
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);

  const configure = (id: string, region: string | null) => {
    scrollY.current = window.scrollY;
    const url = new URL(window.location.href);
    url.searchParams.set("build", id);
    if (region) url.searchParams.set("region", region); else url.searchParams.delete("region");
    window.history.pushState({ bm: 1 }, "", url);
    setOpen({ id, region });
    window.scrollTo({ top: 0 });
  };

  const back = () => {
    // If we pushed the entry, go back through history so Forward still works.
    if (window.history.state?.bm) { window.history.back(); return; }
    const url = new URL(window.location.href);
    url.searchParams.delete("build");
    url.searchParams.delete("region");
    window.history.replaceState(null, "", url);
    setOpen(null);
    requestAnimationFrame(() => window.scrollTo({ top: scrollY.current }));
  };

  return (
    <div className="bm mx-auto flex w-full max-w-[1480px] flex-col gap-5">
      {notice}
      <div hidden={!!open}>
        <Catalogue cards={cards} preview={preview} previewAll={previewAll} hero={hero} onConfigure={configure} onPrefetch={(id) => void fetchBuild(id)} />
      </div>
      {open && (
        build === undefined ? (
          <ConfigureSkeleton onBack={back} />
        ) : build === null ? (
          <section className="bm-card flex flex-col items-center gap-2 px-6 py-14 text-center">
            <span className="text-[16px] font-extrabold bm-ink">This build is no longer available</span>
            <span className="max-w-[48ch] text-[13px] bm-ink-3">It sold out or was withdrawn while you were browsing. Pick another in-stock build.</span>
            <button type="button" onClick={back} className="bm-btn bm-btn-sm mt-2">Back to all builds</button>
          </section>
        ) : (
          <Configurator key={build.id} build={build} initialRegion={open.region} balanceCents={balanceCents} email={email} onBack={back} />
        )
      )}
    </div>
  );
}

export function ConfigureSkeleton({ onBack }: { onBack?: () => void }) {
  return (
    <div className="flex flex-col gap-5" aria-busy="true" aria-label="Loading this build">
      <div className="flex flex-wrap items-center justify-between gap-3">
        {onBack ? <button type="button" onClick={onBack} className="bm-btn-ghost"><span aria-hidden>←</span>All builds</button> : <span className="bm-skel h-9 w-28" />}
        <Stepper at={1} onJump={() => {}} />
      </div>
      <div className="bm-card flex flex-col gap-3 p-5"><span className="bm-skel h-3 w-24" /><span className="bm-skel h-8 w-64" /><span className="bm-skel h-3 w-96 max-w-full" /></div>
      <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_370px]">
        <div className="flex flex-col gap-4">
          {[0, 1, 2].map((i) => (
            <div key={i} className="bm-card p-5"><span className="bm-skel block h-4 w-40" /><div className="mt-4 grid gap-2.5 sm:grid-cols-3">{[0, 1, 2].map((j) => <span key={j} className="bm-skel block h-[58px]" />)}</div></div>
          ))}
        </div>
        <div className="bm-card flex h-fit flex-col gap-3 p-5"><span className="bm-skel h-4 w-28" />{[0, 1, 2, 3, 4].map((i) => <span key={i} className="bm-skel h-3" />)}<span className="bm-skel h-10" /></div>
      </div>
    </div>
  );
}

