input.content:
/**
 * CUSTOMER-FACING (brand-voice checked): the hero at the top of the bare-metal
 * catalogue. Every number comes from the live catalogue the page was rendered
 * with (no invented stats). Always dark (bm-island) because it sits on the art.
 */
import type { OrderCatalogCard } from "@/lib/dedicated/order";
import { BareMetalHeroArt } from "../HeroArt";

const usd0 = (c: number) => `$${(c / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

export function CatalogueHero({ cards }: { cards: OrderCatalogCard[] }) {
  const live = cards.filter((c) => c.regions.some((r) => r.inStock));
  const locs = new Set(live.flatMap((c) => c.regions.filter((r) => r.inStock).map((r) => r.label)));
  const from = live.length ? Math.min(...live.map((c) => c.fromMonthlyCents)) : null;
  const maxCores = live.length ? Math.max(...live.map((c) => c.cores)) : null;
  const hasGpu = live.some((c) => c.gpu);
  const stats = [
    { k: "Builds in stock", v: String(live.length) },
    { k: "Locations", v: String(locs.size) },
    ...(maxCores ? [{ k: "Up to", v: `${maxCores} cores` }] : []),
    ...(from != null ? [{ k: "From", v: `${usd0(from)}/mo` }] : []),
  ];
  return (
    <header className="bm-hero bm-island">
      <span className="bm-hero-grid" aria-hidden />
      <div className="grid items-center gap-2 lg:grid-cols-[minmax(0,1.05fr)_minmax(0,1fr)]">
        <div className="relative z-[1] flex flex-col gap-4 p-6 sm:p-8 lg:py-10 lg:pl-10">
          <span className="bm-eyebrow">Bare Metal Dedicated Servers</span>
          <h1 className="text-[32px] font-extrabold leading-[1.04] tracking-[-0.04em] sm:text-[44px]" style={{ color: "var(--bm-ink)" }}>
            Bare metal that is<br />
            <span style={{ background: "linear-gradient(96deg,#b9a8ff,#7ea6ff 55%,#7ce3ff)", WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" }}>yours alone.</span>
          </h1>
          <p className="max-w-[54ch] text-[14.5px] leading-relaxed bm-ink-2">
