"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): automated controls for a delivered
 * bare-metal server — live status, power, rescue, OS reinstall, reverse DNS,
 * firewall and extra IPs. Every button ENQUEUES a job
 * (lib/actions-dedicated-ops.ts); the worker carries it out (dry run unless an
 * admin turns Setting dedicated_ovh_dry_run off) and this panel polls its
 * progress. Nothing here talks to an upstream API.
 *
 * Exposed as a hook (`useDedicatedControls`) plus one component per section so
 * the server dashboard (DedicatedServerDashboard) can place them in its own
 * tabs while sharing ONE live state, ONE poller and ONE message line.
 *
 * Performance: the page no longer waits for the live read. The hook loads the
 * panel after the page has painted (`initial` may be null) and shows skeletons
 * meanwhile.
 */
import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import type { CustomerJob, DedicatedPanel } from "@/lib/actions-dedicated-ops";
import type { LiveIp } from "@/lib/dedicated/live";
import { enqueueDedicatedAction, loadDedicatedPanel, payDedicatedExtraIps, pollDedicatedJobs, quoteDedicatedExtraIps, revealDedicatedRescueSecret } from "@/lib/actions-dedicated-ops";
import { isTerminal, JOB_STATUS_LABEL } from "@/lib/dedicated/ops-core";
import { Icon } from "@/components/nx/Icon";
import { NxCardFields } from "@/components/nx/NxCardFields";
import { usd } from "./ui";

const when = (iso: string) => new Date(iso).toLocaleString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });

function newKey(): string {
  const a = new Uint8Array(16);
  crypto.getRandomValues(a);
  return Array.from(a, (b) => b.toString(16).padStart(2, "0")).join("");
}

export type Run = (kind: string, input?: Record<string, unknown>, okText?: string) => void;
export type Controls = {
  panel: DedicatedPanel | null;
  loading: boolean;
  failed: boolean;
  jobs: CustomerJob[];
  busy: boolean;
  active: boolean;
  msg: { tone: "ok" | "bad"; text: string } | null;
  run: Run;
  refresh: (fresh?: boolean) => Promise<void>;
};

export function useDedicatedControls(serverId: string, initial: DedicatedPanel | null, enabled: boolean): Controls {
  const router = useRouter();
  const [panel, setPanel] = useState<DedicatedPanel | null>(initial);
  const [loading, setLoading] = useState(enabled && !initial);
  const [failed, setFailed] = useState(false);
  const [jobs, setJobs] = useState<CustomerJob[]>(initial?.jobs ?? []);
  const [msg, setMsg] = useState<Controls["msg"]>(null);
  const [pending, start] = useTransition();
  const active = jobs.some((j) => !isTerminal(j.status));

  const refresh = useCallback(async (fresh = true) => {
    const p = await loadDedicatedPanel(serverId, fresh);
    if (p.ok) { setPanel(p); setJobs(p.jobs); setFailed(false); } else setFailed(true);
    setLoading(false);
  }, [serverId]);

  // Lazy first load: the page paints first, the live read follows.
  useEffect(() => { if (enabled && !initial) void refresh(false); }, [enabled, initial, refresh]);

  const wasActive = useRef(active);
  useEffect(() => {
    if (!active) {
      if (wasActive.current) void refresh(true);
      wasActive.current = false;
      return;
    }
    wasActive.current = true;
    const t = setInterval(async () => {
      const r = await pollDedicatedJobs(serverId);
      if (r.ok) setJobs(r.jobs);
    }, 3500);
    return () => clearInterval(t);
  }, [active, serverId, refresh]);

  const run: Run = (kind, input = {}, okText) =>
    start(async () => {
      setMsg(null);
      const r = await enqueueDedicatedAction(serverId, kind, input);
      if (!r.ok) { setMsg({ tone: "bad", text: r.error }); return; }
      setMsg({ tone: "ok", text: okText ?? "Started. Progress shows under Recent actions." });
      const p = await pollDedicatedJobs(serverId);
      if (p.ok) setJobs(p.jobs);
      router.refresh();
    });

  return { panel, loading, failed, jobs, busy: pending || active, active, msg, run, refresh };
}

/* ---------------- shared bits ---------------- */

export function ModeBadge({ c }: { c: Controls }) {
  const m = c.panel?.mode;
  if (!m || m === "live") return null;
  return (
    <span className="bm-tag bm-tag-performance" title={m === "dry" ? "Actions are recorded but nothing is sent to the machine yet." : "Demo machine: actions run against a simulated server."}>
      {m === "mock" ? "Demo machine" : m === "dry" ? "Test mode: nothing is sent" : "Controls unavailable"}
    </span>
  );
}

export function ControlsMessage({ c }: { c: Controls }) {
  if (!c.msg) return null;
  return (
    <p role="status" className="rounded-[11px] px-3.5 py-2.5 text-[12.5px]"
       style={c.msg.tone === "ok" ? { background: "var(--bm-ok-soft)", color: "var(--bm-ink-2)" } : { background: "var(--bm-bad-soft)", color: "var(--bm-bad)" }}>
      {c.msg.text}
    </p>
  );
}

export function ControlsGate({ c, children }: { c: Controls; children: React.ReactNode }) {
  if (c.loading) return <div className="flex flex-col gap-3" aria-busy="true"><span className="bm-skel h-16" /><span className="bm-skel h-16" /></div>;
  if (!c.panel) {
    return (
      <p className="text-[13px] bm-ink-3">Controls are unavailable right now. <Link href="/dashboard/support" className="bm-link">Contact support</Link> if you need anything done on this server.</p>
    );
  }
  return <>{children}</>;
}

function Stat({ icon, k, v, sub }: { icon: string; k: string; v: React.ReactNode; sub?: string }) {
  return (
    <div className="bm-sub flex min-w-0 items-start gap-2.5 px-3.5 py-3">
      <Icon name={icon} size={14} tone="inherit" className="mt-[2px] bm-ink-3" />
      <div className="min-w-0">
        <div className="bm-label">{k}</div>
        <div className="trunc text-[13.5px] font-bold bm-ink">{v}</div>
        {sub && <div className="trunc text-[11.5px] bm-ink-3">{sub}</div>}
      </div>
    </div>
  );
}

const mbps = (n: number) => (n >= 1000 ? `${n / 1000} Gbps` : `${n} Mbps`);

/* ---------------- live status ---------------- */

export function LiveStatus({ c }: { c: Controls }) {
  if (c.loading) return <div className="grid grid-cols-2 gap-2.5 lg:grid-cols-4" aria-busy="true">{[0, 1, 2, 3].map((i) => <span key={i} className="bm-skel h-[62px]" />)}</div>;
  const l = c.panel?.live;
  if (!l) return <p className="text-[12.5px] bm-ink-3">{c.panel?.liveError ?? "Live status will appear here shortly."}</p>;
  const net = l.network;
  return (
    <div className="flex flex-col gap-2.5">
      <div className="grid grid-cols-2 gap-2.5 lg:grid-cols-4">
        <Stat icon="bolt" k="Power" v={<span className="flex items-center gap-1.5"><span className={"bm-dot " + (l.power === "on" ? "" : "bm-dot-off")} />{l.power === "on" ? "On" : l.power === "off" ? "Off" : "Unknown"}</span>} />
        <Stat icon="database" k="Boots from" v={l.bootMode === "rescue" ? "Rescue system" : l.bootMode === "disk" ? "Disk" : "Unknown"} sub={l.bootMode === "rescue" ? "Boot back to disk when done" : undefined} />
        <Stat icon="nodes" k="Network port" v={net?.linkMbps ? mbps(net.linkMbps) : "—"} sub={net?.outMbps ? `${mbps(net.outMbps)} public bandwidth` : undefined} />
        <Stat icon="linechart" k="Traffic" v={!net ? "—" : net.throttled ? "Limited" : net.unmetered ? "Unmetered" : `${net.usedPercent ?? 0}% of quota`} sub={net?.resetDate ? `Resets ${new Date(net.resetDate).toLocaleDateString("en-US", { month: "short", day: "numeric" })}` : undefined} />
      </div>
      {l.hardware && (
        <div className="bm-sub px-3.5 py-3">
          <div className="bm-label">Hardware detected on the machine</div>
          <div className="mt-1 text-[12.5px] bm-ink-2">
            {[l.hardware.cpu, l.hardware.cores ? `${l.hardware.cores} cores / ${l.hardware.threads ?? "?"} threads` : null, l.hardware.ramGb ? `${l.hardware.ramGb} GB RAM` : null, ...l.hardware.disks].filter(Boolean).join(" · ")}
          </div>
        </div>
      )}
    </div>
  );
}

/* ---------------- power & rescue ---------------- */

function KeySelect({ keys, value, onChange, optional }: { keys: { id: string; name: string }[]; value: string; onChange: (v: string) => void; optional?: boolean }) {
  if (!keys.length) return <p className="text-[12px] bm-ink-3">No SSH keys on your account. <Link href="/dashboard/settings?tab=ssh" className="bm-link">Add one in Settings</Link>.</p>;
  return (
    <select value={value} onChange={(e) => onChange(e.target.value)} className="bm-field cursor-pointer" aria-label="SSH key">
      {optional && <option value="">No key</option>}
      {keys.map((k) => <option key={k.id} value={k.id}>{k.name}</option>)}
    </select>
  );
}

export function PowerRescue({ c, serverId, primaryIp }: { c: Controls; serverId: string; primaryIp: string | null }) {
  const panel = c.panel!;
  const [confirmReboot, setConfirmReboot] = useState(false);
  const [keyId, setKeyId] = useState(panel.sshKeys[0]?.id ?? "");
  const [secret, setSecret] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const inRescue = panel.live?.bootMode === "rescue";
  return (
    <div className="grid gap-3 lg:grid-cols-2">
      <div className="bm-sub flex flex-col gap-2.5 p-4">
        <span className="flex items-center gap-2 text-[14px] font-extrabold bm-ink"><Icon name="refresh" size={14} tone="inherit" className="bm-accent" />Hard reboot</span>
        <span className="text-[12px] bm-ink-3">Power-cycles the machine, like pressing its reset button. Unsaved data in memory is lost.</span>
        {confirmReboot ? (
          <div className="flex flex-wrap gap-2">
            <button type="button" disabled={c.busy} onClick={() => { setConfirmReboot(false); c.run("REBOOT_HARD", {}, "Rebooting. It usually takes 2 to 5 minutes."); }} className="bm-btn bm-btn-sm">Yes, reboot now</button>
            <button type="button" onClick={() => setConfirmReboot(false)} className="bm-btn-ghost">Cancel</button>
          </div>
        ) : (
          <button type="button" disabled={c.busy} onClick={() => setConfirmReboot(true)} className="bm-btn-ghost w-fit">Reboot</button>
        )}
        <span className="text-[11.5px] bm-ink-4">A graceful restart is best done from inside the OS (<code className="bm-mono">sudo reboot</code>).</span>
      </div>
      <div className="bm-sub flex flex-col gap-2.5 p-4">
        <span className="flex items-center gap-2 text-[14px] font-extrabold bm-ink"><Icon name="lifebuoy" size={14} tone="inherit" className="bm-accent" />Rescue mode</span>
        {inRescue ? (
          <>
            <span className="text-[12px] bm-ink-3">Running the rescue system. Your disks are untouched; mount them to repair or copy data.</span>
            {primaryIp && <code className="bm-mono rounded-[8px] px-2.5 py-1.5 text-[12px] bm-ink" style={{ background: "var(--bm-card-3)" }}>ssh root@{primaryIp}</code>}
            {panel.rescueSecretStored && (secret ? <code className="bm-mono break-all rounded-[8px] px-2.5 py-1.5 text-[12px] bm-ink" style={{ background: "var(--bm-card-3)" }}>{secret}</code> : (
              <button type="button" className="bm-btn-ghost w-fit" onClick={async () => { const r = await revealDedicatedRescueSecret(serverId); if (r.ok) setSecret(r.secret); else setErr(r.error); }}>Show rescue password</button>
            ))}
            <button type="button" disabled={c.busy} onClick={() => c.run("RESCUE_OFF", {}, "Booting back from disk.")} className="bm-btn bm-btn-sm w-fit">Boot back to disk</button>
          </>
        ) : (
          <>
            <span className="text-[12px] bm-ink-3">Restarts into a recovery system loaded over the network. Log in with your SSH key.</span>
            <KeySelect keys={panel.sshKeys} value={keyId} onChange={setKeyId} optional />
            <button type="button" disabled={c.busy} onClick={() => c.run("RESCUE_ON", { sshKeyId: keyId || undefined }, "Booting into rescue mode.")} className="bm-btn-ghost w-fit">Boot into rescue</button>
          </>
        )}
        {err && <span className="text-[11.5px] bm-bad">{err}</span>}
      </div>
      <div className="flex flex-col gap-1.5 rounded-[13px] p-4 lg:col-span-2" style={{ border: "1px dashed var(--bm-line-2)" }}>
        <span className="flex items-center gap-2 text-[13px] font-bold bm-ink"><Icon name="monitor" size={14} tone="inherit" className="bm-ink-3" />Remote console</span>
        <span className="text-[12px] bm-ink-3">Need the screen and keyboard (for example if the network config is broken)? Our engineers open the out-of-band console for you. <Link href="/dashboard/support" className="bm-link">Open a ticket</Link>.</span>
      </div>
    </div>
  );
}

/* ---------------- reinstall ---------------- */

export function ReinstallPanel({ c, label }: { c: Controls; label: string }) {
  const panel = c.panel!;
  const templates = panel.live?.templates ?? [];
  const [tpl, setTpl] = useState(templates[0]?.name ?? "");
  useEffect(() => { if (!tpl && templates[0]) setTpl(templates[0].name); }, [templates, tpl]);
  const [host, setHost] = useState("");
  const [keyId, setKeyId] = useState(panel.sshKeys[0]?.id ?? "");
  const [typed, setTyped] = useState("");
  const ok = !!tpl && !!host.trim() && !!keyId && typed.trim() === label;
  return (
    <div className="flex flex-col gap-3.5 rounded-[14px] p-4" style={{ border: "1px solid color-mix(in srgb, var(--bm-bad) 35%, transparent)", background: "var(--bm-bad-soft)" }}>
      <span className="flex items-center gap-2 text-[14px] font-extrabold bm-ink"><Icon name="warntriangle" size={14} tone="inherit" className="bm-bad" />Reinstall the operating system</span>
      <span className="text-[12.5px] bm-ink-2">This erases every disk on the server. Back up anything you need first. You log in afterwards as <b>root</b> with the SSH key you pick; no password is set.</span>
      <div className="grid gap-3 sm:grid-cols-3">
        <label className="flex flex-col gap-1"><span className="bm-label">Operating system</span>
          <select value={tpl} onChange={(e) => setTpl(e.target.value)} className="bm-field cursor-pointer">
            {templates.length === 0 && <option value="">Loading…</option>}
            {templates.map((t) => <option key={t.name} value={t.name}>{t.label}</option>)}
          </select>
        </label>
        <label className="flex flex-col gap-1"><span className="bm-label">Hostname</span>
          <input value={host} onChange={(e) => setHost(e.target.value)} placeholder="db1.example.com" className="bm-field" />
        </label>
        <label className="flex flex-col gap-1"><span className="bm-label">SSH key</span>
          <KeySelect keys={panel.sshKeys} value={keyId} onChange={setKeyId} />
        </label>
      </div>
      <label className="flex flex-col gap-1"><span className="bm-label">Type <b className="bm-ink">{label}</b> to confirm</span>
        <input value={typed} onChange={(e) => setTyped(e.target.value)} className="bm-field max-w-[360px]" autoComplete="off" aria-label="Type the server name to confirm" />
      </label>
      <button type="button" disabled={!ok || c.busy} onClick={() => c.run("REINSTALL", { templateName: tpl, hostname: host, sshKeyId: keyId, confirm: typed }, "Reinstall started. It usually takes 10 to 20 minutes.")} className="bm-btn bm-btn-sm w-fit">Erase and reinstall</button>
    </div>
  );
}

/* ---------------- network: rDNS + firewall ---------------- */

export function NetworkPanel({ c }: { c: Controls }) {
  const ips = c.panel?.live?.ips ?? [];
  const v4 = ips.filter((i) => i.version === 4 && i.cidr.endsWith("/32"));
  const [open, setOpen] = useState<string | null>(null);
  return (
    <div className="flex flex-col gap-3">
      <div className="bm-sub flex flex-col">
        {ips.length === 0 && <p className="p-4 text-[12.5px] bm-ink-3">No addresses found yet.</p>}
        {ips.map((ip, i) => (
          <div key={ip.cidr} className={i ? "border-t bm-rule" : ""}>
            <IpRow ip={ip} open={open === ip.cidr} onToggle={() => setOpen(open === ip.cidr ? null : ip.cidr)} c={c} />
          </div>
        ))}
      </div>
      {v4.length > 0 && <p className="text-[11.5px] bm-ink-4">The network firewall filters traffic before it reaches your server, on top of DDoS protection. Rules apply per IPv4 address.</p>}
    </div>
  );
}

function IpRow({ ip, open, onToggle, c }: { ip: LiveIp; open: boolean; onToggle: () => void; c: Controls }) {
  const [rev, setRev] = useState(ip.reverse?.replace(/\.$/, "") ?? "");
  const [rule, setRule] = useState({ sequence: "0", action: "permit", protocol: "tcp", ports: "22", source: "" });
  const single = ip.version === 4 && ip.cidr.endsWith("/32");
  const fw = ip.firewall;
  return (
    <div className="flex flex-col gap-2 p-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <span className="flex min-w-0 flex-wrap items-center gap-2">
          <span className="bm-mono trunc text-[13px] font-semibold bm-ink">{single ? ip.ip : ip.cidr}</span>
          <span className="bm-tag bm-tag-gpu">{ip.version === 6 ? "IPv6" : single ? "IPv4" : "Block"}</span>
          {fw?.exists && <span className={"bm-tag " + (fw.enabled ? "bm-tag-value" : "bm-tag-gpu")}>{fw.enabled ? "Firewall on" : "Firewall off"}</span>}
        </span>
        {single && <button type="button" onClick={onToggle} className="bm-btn-ghost">{open ? "Close" : "Manage"}</button>}
      </div>
      {single && !open && <span className="trunc text-[11.5px] bm-ink-3">Reverse DNS: {ip.reverse ? ip.reverse.replace(/\.$/, "") : "not set"}</span>}
      {single && open && (
        <div className="flex flex-col gap-4 rounded-[11px] p-3.5" style={{ background: "var(--bm-card)" }}>
          <div className="flex flex-col gap-1.5">
            <span className="bm-label">Reverse DNS (PTR)</span>
            <div className="flex flex-wrap gap-2">
              <input value={rev} onChange={(e) => setRev(e.target.value)} placeholder="mail.example.com" className="bm-field max-w-[320px] flex-1" />
              <button type="button" disabled={c.busy || !rev.trim()} onClick={() => c.run("REVERSE_SET", { ip: ip.ip, reverse: rev }, "Saving reverse DNS.")} className="bm-btn-ghost">Save</button>
            </div>
            <span className="text-[11px] bm-ink-4">The hostname must already resolve to {ip.ip}.</span>
          </div>
          <div className="flex flex-col gap-2">
            <span className="flex items-center justify-between gap-2">
              <span className="bm-label">Network firewall</span>
              <button type="button" disabled={c.busy} onClick={() => c.run(fw?.enabled ? "FW_DISABLE" : "FW_ENABLE", { ip: ip.ip }, fw?.enabled ? "Turning the firewall off." : "Turning the firewall on.")} className="bm-btn-ghost">{fw?.enabled ? "Turn off" : "Turn on"}</button>
            </span>
            {fw?.rules.length ? (
              <ul className="flex flex-col gap-1">
                {fw.rules.map((r) => (
                  <li key={String(r.sequence)} className="bm-sub flex items-center justify-between gap-2 px-3 py-2 text-[12px]">
                    <span className="trunc bm-ink-2"><b className="bm-ink">#{r.sequence}</b> {r.action === "permit" ? "allow" : "block"} {r.protocol}{r.port ? ` ${r.port}` : ""}{r.source && r.source !== "0.0.0.0/0" ? ` from ${r.source}` : ""}</span>
                    <button type="button" disabled={c.busy} onClick={() => c.run("FW_RULE_REMOVE", { ip: ip.ip, sequence: String(r.sequence) }, "Removing the rule.")} className="flex-none text-[11.5px] font-bold bm-bad">Remove</button>
                  </li>
                ))}
              </ul>
            ) : <span className="text-[11.5px] bm-ink-3">No rules yet. With the firewall on and no rules, traffic is allowed.</span>}
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-6">
              <input value={rule.sequence} onChange={(e) => setRule({ ...rule, sequence: e.target.value })} className="bm-field" aria-label="Order (0-19)" placeholder="#" />
              <select value={rule.action} onChange={(e) => setRule({ ...rule, action: e.target.value })} className="bm-field" aria-label="Action"><option value="permit">Allow</option><option value="deny">Block</option></select>
              <select value={rule.protocol} onChange={(e) => setRule({ ...rule, protocol: e.target.value })} className="bm-field" aria-label="Protocol">{["tcp", "udp", "icmp", "ipv4"].map((p) => <option key={p} value={p}>{p.toUpperCase()}</option>)}</select>
              <input value={rule.ports} onChange={(e) => setRule({ ...rule, ports: e.target.value })} className="bm-field" placeholder="Port(s)" aria-label="Ports" disabled={rule.protocol !== "tcp" && rule.protocol !== "udp"} />
              <input value={rule.source} onChange={(e) => setRule({ ...rule, source: e.target.value })} className="bm-field" placeholder="From (any)" aria-label="Source" />
              <button type="button" disabled={c.busy} onClick={() => c.run("FW_RULE_ADD", { ip: ip.ip, rule: { ...rule, ports: rule.protocol === "tcp" || rule.protocol === "udp" ? rule.ports : "" } }, "Adding the rule.")} className="bm-btn-ghost h-[40px]">Add rule</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ---------------- buy extra IPs ---------------- */

export function ExtraIps({ c, serverId, balanceCents }: { c: Controls; serverId: string; balanceCents: number }) {
  const panel = c.panel!;
  const router = useRouter();
  const [qty, setQty] = useState<1 | 4 | 8>(1);
  const [useWallet, setUseWallet] = useState(balanceCents > 0);
  const [quote, setQuote] = useState<{ chargeCents: number; renewalAfter: string; monthlyCents: number; walletApplied: number; cardCents: number; balanceCents: number } | null>(null);
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string; cardCents: number } | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [busy, start] = useTransition();
  const key = useMemo(() => newKey(), []);
  const confirmRef = useRef<(() => Promise<void>) | null>(null);
  const [canConfirm, setCanConfirm] = useState(false);
  const open = panel.ipOrders.find((o) => ["PAID", "APPROVED", "ORDERING"].includes(o.status));

  useEffect(() => {
    setCheckout(null);
    start(async () => {
      const r = await quoteDedicatedExtraIps(serverId, qty, useWallet);
      if (r.ok) { setQuote({ ...r.quote, walletApplied: r.walletApplied, cardCents: r.cardCents, balanceCents: r.balanceCents }); setErr(null); } else setErr(r.error);
    });
  }, [qty, serverId, useWallet]);

  const pay = () => start(async () => {
    setErr(null);
    const r = await payDedicatedExtraIps(serverId, qty, key, useWallet);
    if (!r.ok) { setErr(r.error); return; }
    if ("orderId" in r) { await c.refresh(true); router.refresh(); return; }
    setCheckout({ ...r.checkout, cardCents: r.cardCents });
  });

  const STATUS: Record<string, string> = { PAID: "Paid, awaiting our team", APPROVED: "Being ordered", ORDERING: "Being delivered", DONE: "Added", REJECTED: "Refunded", FAILED: "Delayed, our team is on it" };
  return (
    <div className="flex flex-col gap-3">
      {panel.ipOrders.length > 0 && (
        <ul className="bm-sub flex flex-col">
          {panel.ipOrders.map((o, i) => (
            <li key={o.id} className={"flex flex-wrap items-center justify-between gap-2 px-4 py-3 text-[12.5px] " + (i ? "border-t bm-rule" : "")}>
              <span className="bm-ink-2">{o.quantity === 1 ? "1 address" : `${o.quantity} addresses`} · {usd(o.chargedCents)} · {when(o.createdAt)}</span>
              <span className={"bm-tag " + (o.status === "DONE" ? "bm-tag-value" : o.status === "REJECTED" ? "bm-tag-gpu" : "bm-tag-recommended")}>{STATUS[o.status] ?? o.status}</span>
              {o.ips.length > 0 && <span className="bm-mono w-full text-[11.5px] bm-ink-3">{o.ips.join(", ")}</span>}
            </li>
          ))}
        </ul>
      )}
      {open ? (
        <p className="text-[12.5px] bm-ink-3">Your order is with our team. The addresses appear here once they are routed to this server.</p>
      ) : (
        <div className="flex flex-col gap-3">
          <div className="grid gap-2.5 sm:grid-cols-3" role="radiogroup" aria-label="How many addresses">
            {([1, 4, 8] as const).map((n) => (
              <button key={n} type="button" role="radio" aria-checked={qty === n} onClick={() => setQty(n)} className="bm-pick flex flex-col gap-0.5 p-3">
                <span className="text-[14px] font-extrabold bm-ink">{n === 1 ? "1 address" : `Block of ${n}`}</span>
                <span className="text-[11.5px] bm-ink-3">{n === 1 ? "A single extra IPv4" : `${n} consecutive IPv4s`}</span>
              </button>
            ))}
          </div>
          {quote ? (
            <dl className="bm-sub flex flex-col gap-1.5 p-4 text-[13px]">
              <div className="flex justify-between gap-3"><dt className="bm-ink-3">Today (prorated to your renewal)</dt><dd className="bm-num font-bold bm-ink">{usd(quote.chargeCents)}</dd></div>
              <div className="flex justify-between gap-3"><dt className="bm-ink-3">Then your server renews at</dt><dd className="bm-num font-bold bm-ink">{quote.renewalAfter}</dd></div>
              {quote.walletApplied > 0 && <div className="flex justify-between gap-3"><dt className="bm-ink-3">From your wallet</dt><dd className="bm-num font-semibold bm-ok">−{usd(quote.walletApplied)}</dd></div>}
              {quote.cardCents > 0 && <div className="flex justify-between gap-3"><dt className="bm-ink-3">By card</dt><dd className="bm-num font-semibold bm-ink">{usd(quote.cardCents)}</dd></div>}
            </dl>
          ) : <span className="bm-skel h-[70px]" />}
          {balanceCents > 0 && (
            <label className="flex cursor-pointer items-center gap-2.5 text-[12.5px] bm-ink-2">
              <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} />
              Use my wallet balance ({usd(balanceCents)})
            </label>
          )}
          {checkout ? (
            <div className="flex flex-col gap-3">
              <NxCardFields clientSecret={checkout.clientSecret} publishableKey={checkout.publishableKey} onConfirmReady={(fn) => { confirmRef.current = fn; setCanConfirm(!!fn); }} onBusy={(_b, e) => setErr(e)} />
              <button type="button" disabled={!canConfirm} onClick={() => void confirmRef.current?.()} className="bm-btn bm-btn-sm w-fit">Pay {usd(checkout.cardCents)}</button>
            </div>
          ) : (
            <button type="button" disabled={busy || !quote} onClick={pay} className="bm-btn bm-btn-sm w-fit">{quote && quote.cardCents === 0 ? `Pay ${usd(quote.chargeCents)} from wallet` : "Continue to card payment"}</button>
          )}
          <span className="text-[11.5px] bm-ink-4">Our team confirms availability in your location before the addresses are added. If they can&apos;t be added, the full amount goes back to your wallet.</span>
        </div>
      )}
      {err && <span className="text-[12px] bm-bad">{err}</span>}
    </div>
  );
}

/* ---------------- recent actions ---------------- */

export function RecentActions({ jobs }: { jobs: CustomerJob[] }) {
  if (!jobs.length) return <p className="text-[12.5px] bm-ink-3">Nothing yet. Reboots, reinstalls and network changes you make show here with their progress.</p>;
  return (
    <ul className="flex flex-col gap-2">
      {jobs.slice(0, 8).map((j) => (
        <li key={j.id} className="bm-sub flex flex-col gap-1.5 px-3.5 py-3">
          <span className="flex flex-wrap items-center justify-between gap-2">
            <span className="text-[13px] font-bold bm-ink">{j.label}</span>
            <span className={"bm-tag " + (j.status === "DONE" ? "bm-tag-value" : j.status === "FAILED" ? "bm-tag-performance" : "bm-tag-recommended")}>{JOB_STATUS_LABEL[j.status] ?? j.status}</span>
          </span>
          {!isTerminal(j.status) && <span className="block h-[4px] overflow-hidden rounded-full" style={{ background: "var(--bm-card-3)" }}><span className="block h-full rounded-full transition-[width] duration-700" style={{ width: `${Math.max(6, j.progress)}%`, background: "var(--bm-grad)" }} /></span>}
          <span className="text-[11.5px] bm-ink-3" suppressHydrationWarning>{j.error ?? j.step} · {when(j.createdAt)}</span>
        </li>
      ))}
    </ul>
  );
}

