"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): automated controls for a delivered
 * bare-metal server — live status, power, rescue, OS reinstall, reverse DNS,
 * firewall and extra IPs. Every button ENQUEUES a job
 * (lib/actions-dedicated-ops.ts); the worker carries it out (dry run unless an
 * admin turns Setting dedicated_ovh_dry_run off) and this panel polls its
 * progress. Nothing here talks to an upstream API.
 *
 * Exposed as a hook (`useDedicatedControls`) plus one component per section so
 * the server dashboard (DedicatedServerDashboard) can place them in its own
 * tabs while sharing ONE live state, ONE poller and ONE message line.
 *
 * Performance: the page no longer waits for the live read. The hook loads the
 * panel after the page has painted (`initial` may be null) and shows skeletons
 * meanwhile.
 */
import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import type { CustomerJob, DedicatedPanel } from "@/lib/actions-dedicated-ops";
import type { LiveIp } from "@/lib/dedicated/live";
import { enqueueDedicatedAction, loadDedicatedPanel, payDedicatedExtraIps, pollDedicatedJobs, quoteDedicatedExtraIps, revealDedicatedRescueSecret } from "@/lib/actions-dedicated-ops";
import { isTerminal, JOB_STATUS_LABEL } from "@/lib/dedicated/ops-core";
import { Icon } from "@/components/nx/Icon";
import { NxCardFields } from "@/components/nx/NxCardFields";
import { usd } from "./ui";

const when = (iso: string) => new Date(iso).toLocaleString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });

function newKey(): string {
  const a = new Uint8Array(16);
  crypto.getRandomValues(a);
  return Array.from(a, (b) => b.toString(16).padStart(2, "0")).join("");
}

export type Run = (kind: string, input?: Record<string, unknown>, okText?: string) => void;
export type Controls = {
  panel: DedicatedPanel | null;
  loading: boolean;
  jobs: CustomerJob[];
  busy: boolean;
  active: boolean;
  msg: { tone: "ok" | "bad"; text: string } | null;
  run: Run;
  refresh: (fresh?: boolean) => Promise<void>;
};

export function useDedicatedControls(serverId: string, initial: DedicatedPanel | null, enabled: boolean): Controls {
  const router = useRouter();
  const [panel, setPanel] = useState<DedicatedPanel | null>(initial);
  const [loading, setLoading] = useState(enabled && !initial);
  const [jobs, setJobs] = useState<CustomerJob[]>(initial?.jobs ?? []);
  const [msg, setMsg] = useState<Controls["msg"]>(null);
  const [pending, start] = useTransition();
  const active = jobs.some((j) => !isTerminal(j.status));

  const refresh = useCallback(async (fresh = true) => {
    const p = await loadDedicatedPanel(serverId, fresh);
    if (p.ok) { setPanel(p); setJobs(p.jobs); }
    setLoading(false);
  }, [serverId]);

  // Lazy first load: the page paints first, the live read follows.
  useEffect(() => { if (enabled && !initial) void refresh(false); }, [enabled, initial, refresh]);

  const wasActive = useRef(active);
  useEffect(() => {
    if (!active) {
      if (wasActive.current) void refresh(true);
      wasActive.current = false;
      return;
    }
    wasActive.current = true;
    const t = setInterval(async () => {
      const r = await pollDedicatedJobs(serverId);
      if (r.ok) setJobs(r.jobs);
    }, 3500);
    return () => clearInterval(t);
  }, [active, serverId, refresh]);

  const run: Run = (kind, input = {}, okText) =>
    start(async () => {
      setMsg(null);
      const r = await enqueueDedicatedAction(serverId, kind, input);
      if (!r.ok) { setMsg({ tone: "bad", text: r.error }); return; }
      setMsg({ tone: "ok", text: okText ?? "Started. Progress shows under Recent actions." });
      const p = await pollDedicatedJobs(serverId);
      if (p.ok) setJobs(p.jobs);
      router.refresh();
    });

  return { panel, loading, jobs, busy: pending || active, active, msg, run, refresh };
}

/* ---------------- shared bits ---------------- */

export function ModeBadge({ c }: { c: Controls }) {
  const m = c.panel?.mode;
  if (!m || m === "live") return null;
  return (
    <span className="bm-tag bm-tag-performance" title={m === "dry" ? "Actions are recorded but nothing is sent to the machine yet." : "Demo machine: actions run against a simulated server."}>
      {m === "mock" ? "Demo machine" : m === "dry" ? "Test mode: nothing is sent" : "Controls unavailable"}
    </span>
  );
}

export function ControlsMessage({ c }: { c: Controls }) {
  if (!c.msg) return null;
  return (
    <p role="status" className="rounded-[11px] px-3.5 py-2.5 text-[12.5px]"
       style={c.msg.tone === "ok" ? { background: "var(--bm-ok-soft)", color: "var(--bm-ink-2)" } : { background: "var(--bm-bad-soft)", color: "var(--bm-bad)" }}>
      {c.msg.text}
    </p>
  );
}

export function ControlsGate({ c, children }: { c: Controls; children: React.ReactNode }) {
  if (c.loading) return <div className="flex flex-col gap-3" aria-busy="true"><span className="bm-skel block h-16" /><span className="bm-skel block h-16" /></div>;
  if (!c.panel) {
    return (
      <p className="text-[13px] bm-ink-3">Controls are unavailable right now. <Link href="/dashboard/support" className="bm-link">Contact support</Link> if you need anything done on this server.</p>
    );
  }
  return <>{children}</>;
}

function Stat({ icon, k, v, sub }: { icon: string; k: string; v: React.ReactNode; sub?: string }) {
  return (
    <div className="bm-sub flex min-w-0 items-start gap-2.5 px-3.5 py-3">
      <Icon name={icon} size={14} tone="inherit" className="mt-[2px] bm-ink-3" />
      <div className="min-w-0">
        <div className="bm-label">{k}</div>
        <div className="trunc text-[13.5px] font-bold bm-ink">{v}</div>
        {sub && <div className="trunc text-[11.5px] bm-ink-3">{sub}</div>}
      </div>
    </div>
  );
}

const mbps = (n: number) => (n >= 1000 ? `${n / 1000} Gbps` : `${n} Mbps`);

/* ---------------- live status ---------------- */

export function LiveStatus({ c }: { c: Controls }) {
  if (c.loading) return <div className="grid grid-cols-2 gap-2.5 lg:grid-cols-4" aria-busy="true">{[0, 1, 2, 3].map((i) => <span key={i} className="bm-skel block h-[62px]" />)}</div>;
  const l = c.panel?.live;
  if (!l) return <p className="text-[12.5px] bm-ink-3">{c.panel?.liveError ?? "Live status will appear here shortly."}</p>;
  const net = l.network;
  return (
    <div className="flex flex-col gap-2.5">
      <div className="grid grid-cols-2 gap-2.5 lg:grid-cols-4">
        <Stat icon="bolt" k="Power" v={<span className="flex items-center gap-1.5"><span className={"bm-dot " + (l.power === "on" ? "" : "bm-dot-off")} />{l.power === "on" ? "On" : l.power === "off" ? "Off" : "Unknown"}</span>} />
        <Stat icon="database" k="Boots from" v={l.bootMode === "rescue" ? "Rescue system" : l.bootMode === "disk" ? "Disk" : "Unknown"} sub={l.bootMode === "rescue" ? "Boot back to disk when done" : undefined} />
        <Stat icon="nodes" k="Network port" v={net?.linkMbps ? mbps(net.linkMbps) : "—"} sub={net?.outMbps ? `${mbps(net.outMbps)} public bandwidth` : undefined} />
        <Stat icon="linechart" k="Traffic" v={!net ? "—" : net.throttled ? "Limited" : net.unmetered ? "Unmetered" : `${net.usedPercent ?? 0}% of quota`} sub={net?.resetDate ? `Resets ${new Date(net.resetDate).toLocaleDateString("en-US", { month: "short", day: "numeric" })}` : undefined} />
      </div>
      {l.hardware && (
        <div className="bm-sub px-3.5 py-3">
          <div className="bm-label">Hardware detected on the machine</div>
          <div className="mt-1 text-[12.5px] bm-ink-2">
            {[l.hardware.cpu, l.hardware.cores ? `${l.hardware.cores} cores / ${l.hardware.threads ?? "?"} threads` : null, l.hardware.ramGb ? `${l.hardware.ramGb} GB RAM` : null, ...l.hardware.disks].filter(Boolean).join(" · ")}
          </div>
        </div>
      )}
    </div>
  );
}

/* ---------------- power & rescue ---------------- */

function KeySelect({ keys, value, onChange, optional }: { keys: { id: string; name: string }[]; value: string; onChange: (v: string) => void; optional?: boolean }) {
  if (!keys.length) return <p className="text-[12px] bm-ink-3">No SSH keys on your account. <Link href="/dashboard/settings?tab=ssh" className="bm-link">Add one in Settings</Link>.</p>;
  return (
    <select value={value} onChange={(e) => onChange(e.target.value)} className="bm-field cursor-pointer" aria-label="SSH key">
      {optional && <option value="">No key</option>}
      {keys.map((k) => <option key={k.id} value={k.id}>{k.name}</option>)}
    </select>
  );
}

export function PowerRescue({ c, serverId, primaryIp }: { c: Controls; serverId: string; primaryIp: string | null }) {
  const panel = c.panel!;
  const [confirmReboot, setConfirmReboot] = useState(false);
  const [keyId, setKeyId] = useState(panel.sshKeys[0]?.id ?? "");
  const [secret, setSecret] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const inRescue = panel.live?.bootMode === "rescue";
  const codeBox = { background: "var(--bm-card-3)" };
  return (
    <div className="grid gap-3 lg:grid-cols-2">
      <div className="bm-sub flex flex-col gap-2.5 p-4">
        <span className="flex items-center gap-2 text-[14px] font-extrabold bm-ink"><Icon name="refresh" size={14} tone="inherit" className="bm-accent" />Hard reboot</span>
        <span className="text-[12px] bm-ink-3">Power-cycles the machine, like pressing its reset button. Unsaved data in memory is lost.</span>
        {confirmReboot ? (
          <div className="flex flex-wrap gap-2">
            <button type="button" disabled={c.busy} onClick={() => { setConfirmReboot(false); c.run("REBOOT_HARD", {}, "Rebooting. It usually takes 2 to 5 minutes."); }} className="bm-btn bm-btn-sm">Yes, reboot now</button>
            <button type="button" onClick={() => setConfirmReboot(false)} className="bm-btn-ghost">Cancel</button>
          </div>
        ) : (
          <button type="button" disabled={c.busy} onClick={() => setConfirmReboot(true)} className="bm-btn-ghost w-fit">Reboot</button>
        )}
        <span className="text-[11.5px] bm-ink-4">A graceful restart is best done from inside the OS (<code className="bm-mono">sudo reboot</code>).</span>
      </div>
      <div className="bm-sub flex flex-col gap-2.5 p-4">
        <span className="flex items-center gap-2 text-[14px] font-extrabold bm-ink"><Icon name="lifebuoy" size={14} tone="inherit" className="bm-accent" />Rescue mode</span>
        {inRescue ? (
          <>
            <span className="text-[12px] bm-ink-3">Running the rescue system. Your disks are untouched; mount them to repair or copy data.</span>
            {primaryIp && <code className="bm-mono rounded-[8px] px-2.5 py-1.5 text-[12px] bm-ink" style={codeBox}>ssh root@{primaryIp}</code>}
            {panel.rescueSecretStored && (secret ? <code className="bm-mono break-all rounded-[8px] px-2.5 py-1.5 text-[12px] bm-ink" style={codeBox}>{secret}</code> : (
              <button type="button" className="bm-btn-ghost w-fit" onClick={async () => { const r = await revealDedicatedRescueSecret(serverId); if (r.ok) setSecret(r.secret); else setErr(r.error); }}>Show rescue password</button>
            ))}
            <button type="button" disabled={c.busy} onClick={() => c.run("RESCUE_OFF", {}, "Booting back from disk.")} className="bm-btn bm-btn-sm w-fit">Boot back to disk</button>
          </>
        ) : (
          <>
            <span className="text-[12px] bm-ink-3">Restarts into a recovery system loaded over the network. Log in with your SSH key.</span>
            <KeySelect keys={panel.sshKeys} value={keyId} onChange={setKeyId} optional />
            <button type="button" disabled={c.busy} onClick={() => c.run("RESCUE_ON", { sshKeyId: keyId || undefined }, "Booting into rescue mode.")} className="bm-btn-ghost w-fit">Boot into rescue</button>
          </>
        )}
        {err && <span className="text-[11.5px] bm-bad">{err}</span>}
      </div>
      <div className="flex flex-col gap-1.5 rounded-[13px] p-4 lg:col-span-2" style={{ border: "1px dashed var(--bm-line-2)" }}>
        <span className="flex items-center gap-2 text-[13px] font-bold bm-ink"><Icon name="monitor" size={14} tone="inherit" className="bm-ink-3" />Remote console</span>
        <span className="text-[12px] bm-ink-3">Need the screen and keyboard (for example if the network config is broken)? Our engineers open the out-of-band console for you. <Link href="/dashboard/support" className="bm-link">Open a ticket</Link>.</span>
      </div>
    </div>
  );
}

/* ---------------- reinstall ---------------- */

export function ReinstallPanel({ c, label }: { c: Controls; label: string }) {
  const panel = c.panel!;
  const templates = useMemo(() => panel.live?.templates ?? [], [panel.live]);
  const [tpl, setTpl] = useState(templates[0]?.name ?? "");
  useEffect(() => { if (!tpl && templates[0]) setTpl(templates[0].name); }, [templates, tpl]);
  const [host, setHost] = useState("");
  const [keyId, setKeyId] = useState(panel.sshKeys[0]?.id ?? "");
  const [typed, setTyped] = useState("");
  const ok = !!tpl && !!host.trim() && !!keyId && typed.trim() === label;
  return (
    <div className="flex flex-col gap-3.5 rounded-[14px] p-4" style={{ border: "1px solid color-mix(in srgb, var(--bm-bad) 35%, transparent)", background: "var(--bm-bad-soft)" }}>
      <span className="flex items-center gap-2 text-[14px] font-extrabold bm-ink"><Icon name="warntriangle" size={14} tone="inherit" className="bm-bad" />Reinstall the operating system</span>
      <span className="text-[12.5px] bm-ink-2">This erases every disk on the server. Back up anything you need first. You log in afterwards as <b>root</b> with the SSH key you pick; no password is set.</span>
      <div className="grid gap-3 sm:grid-cols-3">
        <label className="flex flex-col gap-1"><span className="bm-label">Operating system</span>
          <select value={tpl} onChange={(e) => setTpl(e.target.value)} className="bm-field cursor-pointer">
            {templates.length === 0 && <option value="">Loading…</option>}
            {templates.map((t) => <option key={t.name} value={t.name}>{t.label}</option>)}
          </select>
        </label>
        <label className="flex flex-col gap-1"><span className="bm-label">Hostname</span>
          <input value={host} onChange={(e) => setHost(e.target.value)} placeholder="db1.example.com" className="bm-field" />
        </label>
        <label className="flex flex-col gap-1"><span className="bm-label">SSH key</span>
          <KeySelect keys={panel.sshKeys} value={keyId} onChange={setKeyId} />
        </label>
      </div>
      <label className="flex flex-col gap-1"><span className="bm-label">Type <b className="bm-ink">{label}</b> to confirm</span>
        <input value={typed} onChange={(e) => setTyped(e.target.value)} className="bm-field max-w-[360px]" autoComplete="off" aria-label="Type the server name to confirm" />
      </label>
      <button type="button" disabled={!ok || c.busy} onClick={() => c.run("REINSTALL", { templateName: tpl, hostname: host, sshKeyId: keyId, confirm: typed }, "Reinstall started. It usually takes 10 to 20 minutes.")} className="bm-btn bm-btn-sm w-fit">Erase and reinstall</button>
    </div>
  );
}

/* ---------------- network: rDNS + firewall ---------------- */

export function NetworkPanel({ c }: { c: Controls }) {
  const ips = c.panel?.live?.ips ?? [];
  const v4 = ips.filter((i) => i.version === 4 && i.cidr.endsWith("/32"));
  const [open, setOpen] = useState<string | null>(null);
  return (
    <div className="flex flex-col gap-3">
      <div className="bm-sub flex flex-col">
        {ips.length === 0 && <p className="p-4 text-[12.5px] bm-ink-3">No addresses found yet.</p>}
        {ips.map((ip, i) => (
          <div key={ip.cidr} className={i ? "border-t bm-rule" : ""}>
            <IpRow ip={ip} open={open === ip.cidr} onToggle={() => setOpen(open === ip.cidr ? null : ip.cidr)} c={c} />
          </div>
        ))}
      </div>
      {v4.length > 0 && <p className="text-[11.5px] bm-ink-4">The network firewall filters traffic before it reaches your server, on top of DDoS protection. Rules apply per IPv4 address.</p>}
    </div>
  );
}

function IpRow({ ip, open, onToggle, c }: { ip: LiveIp; open: boolean; onToggle: () => void; c: Controls }) {
  const [rev, setRev] = useState(ip.reverse?.replace(/\.$/, "") ?? "");
  const [rule, setRule] = useState({ sequence: "0", action: "permit", protocol: "tcp", ports: "22", source: "" });
  const single = ip.version === 4 && ip.cidr.endsWith("/32");
  const fw = ip.firewall;
  return (
    <div className="flex flex-col gap-2 p-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <span className="flex min-w-0 flex-wrap items-center gap-2">
          <span className="bm-mono trunc text-[13px] font-semibold bm-ink">{single ? ip.ip : ip.cidr}</span>
          <span className="bm-tag bm-tag-gpu">{ip.version === 6 ? "IPv6" : single ? "IPv4" : "Block"}</span>
          {fw?.exists && <span className={"bm-tag " + (fw.enabled ? "bm-tag-value" : "bm-tag-gpu")}>{fw.enabled ? "Firewall on" : "Firewall off"}</span>}
        </span>
        {single && <button type="button" onClick={onToggle} className="bm-btn-ghost">{open ? "Close" : "Manage"}</button>}
      </div>
      {single && !open && <span className="trunc text-[11.5px] bm-ink-3">Reverse DNS: {ip.reverse ? ip.reverse.replace(/\.$/, "") : "not set"}</span>}
      {single && open && (
        <div className="flex flex-col gap-4 rounded-[11px] p-3.5" style={{ background: "var(--bm-card)" }}>
          <div className="flex flex-col gap-1.5">
            <span className="bm-label">Reverse DNS (PTR)</span>
            <div className="flex flex-wrap gap-2">
              <input value={rev} onChange={(e) => setRev(e.target.value)} placeholder="mail.example.com" className="bm-field max-w-[320px] flex-1" />
              <button type="button" disabled={c.busy || !rev.trim()} onClick={() => c.run("REVERSE_SET", { ip: ip.ip, reverse: rev }, "Saving reverse DNS.")} className="bm-btn-ghost">Save</button>
            </div>
            <span className="text-[11px] bm-ink-4">The hostname must already resolve to {ip.ip}.</span>
          </div>
          <div className="flex flex-col gap-2">
            <span className="flex items-center justify-between gap-2">
              <span className="bm-label">Network firewall</span>
              <button type="button" disabled={c.busy} onClick={() => c.run(fw?.enabled ? "FW_DISABLE" : "FW_ENABLE", { ip: ip.ip }, fw?.enabled ? "Turning the firewall off." : "Turning the firewall on.")} className="bm-btn-ghost">{fw?.enabled ? "Turn off" : "Turn on"}</button>
            </span>
            {fw?.rules.length ? (
              <ul className="flex flex-col gap-1">
                {fw.rules.map((r) => (
                  <li key={String(r.sequence)} className="bm-sub flex items-center justify-between gap-2 px-3 py-2 text-[12px]">
                    <span className="trunc bm-ink-2"><b className="bm-ink">#{r.sequence}</b> {r.action === "permit" ? "allow" : "block"} {r.protocol}{r.port ? ` ${r.port}` : ""}{r.source && r.source !== "0.0.0.0/0" ? ` from ${r.source}` : ""}</span>
                    <button type="button" disabled={c.busy} onClick={() => c.run("FW_RULE_REMOVE", { ip: ip.ip, sequence: String(r.sequence) }, "Removing the rule.")} className="flex-none text-[11.5px] font-bold bm-bad">Remove</button>
                  </li>
                ))}
              </ul>
            ) : <span className="text-[11.5px] bm-ink-3">No rules yet. With the firewall on and no rules, traffic is allowed.</span>}
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-6">
              <input value={rule.sequence} onChange={(e) => setRule({ ...rule, sequence: e.target.value })} className="bm-field" aria-label="Order (0-19)" placeholder="#" />
              <select value={rule.action} onChange={(e) => setRule({ ...rule, action: e.target.value })} className="bm-field" aria-label="Action"><option value="permit">Allow</option><option value="deny">Block</option></select>
              <select value={rule.protocol} onChange={(e) => setRule({ ...rule, protocol: e.target.value })} className="bm-field" aria-label="Protocol">{["tcp", "udp", "icmp", "ipv4"].map((p) => <option key={p} value={p}>{p.toUpperCase()}</option>)}</select>
              <input value={rule.ports} onChange={(e) => setRule({ ...rule, ports: e.target.value })} className="bm-field" placeholder="Port(s)" aria-label="Ports" disabled={rule.protocol !== "tcp" && rule.protocol !== "udp"} />
              <input value={rule.source} onChange={(e) => setRule({ ...rule, source: e.target.value })} className="bm-field" placeholder="From (any)" aria-label="Source" />
              <button type="button" disabled={c.busy} onClick={() => c.run("FW_RULE_ADD", { ip: ip.ip, rule: { ...rule, ports: rule.protocol === "tcp" || rule.protocol === "udp" ? rule.ports : "" } }, "Adding the rule.")} className="bm-btn-ghost h-[40px]">Add rule</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ---------------- buy extra IPs ---------------- */

export function ExtraIps({ c, serverId, balanceCents }: { c: Controls; serverId: string; balanceCents: number }) {
  const panel = c.panel!;
  const router = useRouter();
  const [qty, setQty] = useState<1 | 4 | 8>(1);
  const [useWallet, setUseWallet] = useState(balanceCents > 0);
  const [quote, setQuote] = useState<{ chargeCents: number; renewalAfter: string; monthlyCents: number; walletApplied: number; cardCents: number; balanceCents: number } | null>(null);
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string; cardCents: number } | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [busy, start] = useTransition();
  const key = useMemo(() => newKey(), []);
  const confirmRef = useRef<(() => Promise<void>) | null>(null);
  const [canConfirm, setCanConfirm] = useState(false);
  const open = panel.ipOrders.find((o) => ["PAID", "APPROVED", "ORDERING"].includes(o.status));

  useEffect(() => {
    setCheckout(null);
    start(async () => {
      const r = await quoteDedicatedExtraIps(serverId, qty, useWallet);
      if (r.ok) { setQuote({ ...r.quote, walletApplied: r.walletApplied, cardCents: r.cardCents, balanceCents: r.balanceCents }); setErr(null); } else setErr(r.error);
    });
  }, [qty, serverId, useWallet]);

  const pay = () => start(async () => {
    setErr(null);
    const r = await payDedicatedExtraIps(serverId, qty, key, useWallet);
    if (!r.ok) { setErr(r.error); return; }
    if ("orderId" in r) { await c.refresh(true); router.refresh(); return; }
    setCheckout({ ...r.checkout, cardCents: r.cardCents });
  });

  const STATUS: Record<string, string> = { PAID: "Paid, awaiting our team", APPROVED: "Being ordered", ORDERING: "Being delivered", DONE: "Added", REJECTED: "Refunded", FAILED: "Delayed, our team is on it" };
  return (
    <div className="flex flex-col gap-3">
      {panel.ipOrders.length > 0 && (
        <ul className="bm-sub flex flex-col">
          {panel.ipOrders.map((o, i) => (
            <li key={o.id} className={"flex flex-wrap items-center justify-between gap-2 px-4 py-3 text-[12.5px] " + (i ? "border-t bm-rule" : "")}>
              <span className="bm-ink-2">{o.quantity === 1 ? "1 address" : `${o.quantity} addresses`} · {usd(o.chargedCents)} · {when(o.createdAt)}</span>
              <span className={"bm-tag " + (o.status === "DONE" ? "bm-tag-value" : o.status === "REJECTED" ? "bm-tag-gpu" : "bm-tag-recommended")}>{STATUS[o.status] ?? o.status}</span>
              {o.ips.length > 0 && <span className="bm-mono w-full text-[11.5px] bm-ink-3">{o.ips.join(", ")}</span>}
            </li>
          ))}
        </ul>
      )}
      {open ? (
        <p className="text-[12.5px] bm-ink-3">Your order is with our team. The addresses appear here once they are routed to this server.</p>
      ) : (
        <div className="flex flex-col gap-3">
          <div className="grid gap-2.5 sm:grid-cols-3" role="radiogroup" aria-label="How many addresses">
            {([1, 4, 8] as const).map((n) => (
              <button key={n} type="button" role="radio" aria-checked={qty === n} onClick={() => setQty(n)} className="bm-pick flex flex-col gap-0.5 p-3">
                <span className="text-[14px] font-extrabold bm-ink">{n === 1 ? "1 address" : `Block of ${n}`}</span>
                <span className="text-[11.5px] bm-ink-3">{n === 1 ? "A single extra IPv4" : `${n} consecutive IPv4s`}</span>
              </button>
            ))}
          </div>
          {quote ? (
            <dl className="bm-sub flex flex-col gap-1.5 p-4 text-[13px]">
              <div className="flex justify-between gap-3"><dt className="bm-ink-3">Today (prorated to your renewal)</dt><dd className="bm-num font-bold bm-ink">{usd(quote.chargeCents)}</dd></div>
              <div className="flex justify-between gap-3"><dt className="bm-ink-3">Then your server renews at</dt><dd className="bm-num font-bold bm-ink">{quote.renewalAfter}</dd></div>
              {quote.walletApplied > 0 && <div className="flex justify-between gap-3"><dt className="bm-ink-3">From your wallet</dt><dd className="bm-num font-semibold bm-ok">−{usd(quote.walletApplied)}</dd></div>}
              {quote.cardCents > 0 && <div className="flex justify-between gap-3"><dt className="bm-ink-3">By card</dt><dd className="bm-num font-semibold bm-ink">{usd(quote.cardCents)}</dd></div>}
            </dl>
          ) : <span className="bm-skel block h-[70px]" />}
          {balanceCents > 0 && (
            <label className="flex cursor-pointer items-center gap-2.5 text-[12.5px] bm-ink-2">
              <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} />
              Use my wallet balance ({usd(balanceCents)})
            </label>
          )}
          {checkout ? (
            <div className="flex flex-col gap-3">
              <NxCardFields clientSecret={checkout.clientSecret} publishableKey={checkout.publishableKey} onConfirmReady={(fn) => { confirmRef.current = fn; setCanConfirm(!!fn); }} onBusy={(_b, e) => setErr(e)} />
              <button type="button" disabled={!canConfirm} onClick={() => void confirmRef.current?.()} className="bm-btn bm-btn-sm w-fit">Pay {usd(checkout.cardCents)}</button>
            </div>
          ) : (
            <button type="button" disabled={busy || !quote} onClick={pay} className="bm-btn bm-btn-sm w-fit">{quote && quote.cardCents === 0 ? `Pay ${usd(quote.chargeCents)} from wallet` : "Continue to card payment"}</button>
          )}
          <span className="text-[11.5px] bm-ink-4">Our team confirms availability in your location before the addresses are added. If they can&apos;t be added, the full amount goes back to your wallet.</span>
        </div>
      )}
      {err && <span className="text-[12px] bm-bad">{err}</span>}
    </div>
  );
}

/* ---------------- recent actions ---------------- */

export function RecentActions({ jobs }: { jobs: CustomerJob[] }) {
  if (!jobs.length) return <p className="text-[12.5px] bm-ink-3">Nothing yet. Reboots, reinstalls and network changes you make show here with their progress.</p>;
  return (
    <ul className="flex flex-col gap-2">
      {jobs.slice(0, 8).map((j) => (
        <li key={j.id} className="bm-sub flex flex-col gap-1.5 px-3.5 py-3">
          <span className="flex flex-wrap items-center justify-between gap-2">
            <span className="text-[13px] font-bold bm-ink">{j.label}</span>
            <span className={"bm-tag " + (j.status === "DONE" ? "bm-tag-value" : j.status === "FAILED" ? "bm-tag-performance" : "bm-tag-recommended")}>{JOB_STATUS_LABEL[j.status] ?? j.status}</span>
          </span>
          {!isTerminal(j.status) && <span className="block h-[4px] overflow-hidden rounded-full" style={{ background: "var(--bm-card-3)" }}><span className="block h-full rounded-full transition-[width] duration-700" style={{ width: `${Math.max(6, j.progress)}%`, background: "var(--bm-grad)" }} /></span>}
          <span className="text-[11.5px] bm-ink-3" suppressHydrationWarning>{j.error ?? j.step} · {when(j.createdAt)}</span>
        </li>
      ))}
    </ul>
  );
}

toolu_01PubrsR24gcvUgvpEH2rGE4.content:
"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): automated controls for a delivered
 * bare-metal server — live status, power, rescue, OS reinstall, reverse DNS,
 * firewall and extra IPs. Every button ENQUEUES a job
 * (lib/actions-dedicated-ops.ts); the worker carries it out (dry run unless an
 * admin turns Setting dedicated_ovh_dry_run off) and this panel polls its
 * progress. Nothing here talks to an upstream API.
 *
 * Exposed as a hook (`useDedicatedControls`) plus one component per section so
 * the server dashboard (DedicatedServerDashboard) can place them in its own
 * tabs while sharing ONE live state, ONE poller and ONE message line.
 *
 * Performance: the page no longer waits for the live read. The hook loads the
 * panel after the page has painted (`initial` may be null) and shows skeletons
 * meanwhile.
 */
import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import type { CustomerJob, DedicatedPanel } from "@/lib/actions-dedicated-ops";
import type { LiveIp } from "@/lib/dedicated/live";
import { enqueueDedicatedAction, loadDedicatedPanel, payDedicatedExtraIps, pollDedicatedJobs, quoteDedicatedExtraIps, revealDedicatedRescueSecret } from "@/lib/actions-dedicated-ops";
import { isTerminal, JOB_STATUS_LABEL } from "@/lib/dedicated/ops-core";
import { Icon } from "@/components/nx/Icon";
import { NxCardFields } from "@/components/nx/NxCardFields";
import { usd } from "./ui";

const when = (iso: string) => new Date(iso).toLocaleString("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });

function newKey(): string {
  const a = new Uint8Array(16);
  crypto.getRandomValues(a);
  return Array.from(a, (b) => b.toString(16).padStart(2, "0")).join("");
}

export type Run = (kind: string, input?: Record<string, unknown>, okText?: string) => void;
export type Controls = {
  panel: DedicatedPanel | null;
  loading: boolean;
  jobs: CustomerJob[];
  busy: boolean;
  active: boolean;
  msg: { tone: "ok" | "bad"; text: string } | null;
  run: Run;
  refresh: (fresh?: boolean) => Promise<void>;
};

export function useDedicatedControls(serverId: string, initial: DedicatedPanel | null, enabled: boolean): Controls {
  const router = useRouter();
  const [panel, setPanel] = useState<DedicatedPanel | null>(initial);
  const [loading, setLoading] = useState(enabled && !initial);
  const [jobs, setJobs] = useState<CustomerJob[]>(initial?.jobs ?? []);
  const [msg, setMsg] = useState<Controls["msg"]>(null);
  const [pending, start] = useTransition();
  const active = jobs.some((j) => !isTerminal(j.status));

  const refresh = useCallback(async (fresh = true) => {
    const p = await loadDedicatedPanel(serverId, fresh);
    if (p.ok) { setPanel(p); setJobs(p.jobs); }
    setLoading(false);
  }, [serverId]);

  // Lazy first load: the page paints first, the live read follows.
  useEffect(() => { if (enabled && !initial) void refresh(false); }, [enabled, initial, refresh]);

  const wasActive = useRef(active);
  useEffect(() => {
    if (!active) {
      if (wasActive.current) void refresh(true);
      wasActive.current = false;
      return;
    }
    wasActive.current = true;
    const t = setInterval(async () => {
      const r = await pollDedicatedJobs(serverId);
      if (r.ok) setJobs(r.jobs);
    }, 3500);
    return () => clearInterval(t);
  }, [active, serverId, refresh]);

  const run: Run = (kind, input = {}, okText) =>
    start(async () => {
      setMsg(null);
      const r = await enqueueDedicatedAction(serverId, kind, input);
      if (!r.ok) { setMsg({ tone: "bad", text: r.error }); return; }
      setMsg({ tone: "ok", text: okText ?? "Started. Progress shows under Recent actions." });
      const p = await pollDedicatedJobs(serverId);
      if (p.ok) setJobs(p.jobs);
      router.refresh();
    });

  return { panel, loading, jobs, busy: pending || active, active, msg, run, refresh };
}

/* ---------------- shared bits ---------------- */

export function ModeBadge({ c }: { c: Controls }) {
  const m = c.panel?.mode;
  if (!m || m === "live") return null;
  return (
    <span className="bm-tag bm-tag-performance" title={m === "dry" ? "Actions are recorded but nothing is sent to the machine yet." : "Demo machine: actions run against a simulated server."}>
      {m === "mock" ? "Demo machine" : m === "dry" ? "Test mode: nothing is sent" : "Controls unavailable"}
    </span>
  );
}

export function ControlsMessage({ c }: { c: Controls }) {
  if (!c.msg) return null;
  return (
    <p role="status" className="rounded-[11px] px-3.5 py-2.5 text-[12.5px]"
       style={c.msg.tone === "ok" ? { background: "var(--bm-ok-soft)", color: "var(--bm-ink-2)" } : { background: "var(--bm-bad-soft)", color: "var(--bm-bad)" }}>
      {c.msg.text}
    </p>
  );
}

export function ControlsGate({ c, children }: { c: Controls; children: React.ReactNode }) {
  if (c.loading) return <div className="flex flex-col gap-3" aria-busy="true"><span className="bm-skel block h-16" /><span className="bm-skel block h-16" /></div>;
  if (!c.panel) {
    return (
      <p className="text-[13px] bm-ink-3">Controls are unavailable right now. <Link href="/dashboard/support" className="bm-link">Contact support</Link> if you need anything done on this server.</p>
    );
  }
  return <>{children}</>;
}

function Stat({ icon, k, v, sub }: { icon: string; k: string; v: React.ReactNode; sub?: string }) {
  return (
    <div className="bm-sub flex min-w-0 items-start gap-2.5 px-3.5 py-3">
      <Icon name={icon} size={14} tone="inherit" className="mt-[2px] bm-ink-3" />
      <div className="min-w-0">
        <div className="bm-label">{k}</div>
        <div className="trunc text-[13.5px] font-bold bm-ink">{v}</div>
        {sub && <div className="trunc text-[11.5px] bm-ink-3">{sub}</div>}
      </div>
    </div>
  );
}

const mbps = (n: number) => (n >= 1000 ? `${n / 1000} Gbps` : `${n} Mbps`);

/* ---------------- live status ---------------- */

export function LiveStatus({ c }: { c: Controls }) {
  if (c.loading) return <div className="grid grid-cols-2 gap-2.5 lg:grid-cols-4" aria-busy="true">{[0, 1, 2, 3].map((i) => <span key={i} className="bm-skel block h-[62px]" />)}</div>;
  const l = c.panel?.live;
  if (!l) return <p className="text-[12.5px] bm-ink-3">{c.panel?.liveError ?? "Live status will appear here shortly."}</p>;
  const net = l.network;
  return (
    <div className="flex flex-col gap-2.5">
      <div className="grid grid-cols-2 gap-2.5 lg:grid-cols-4">
        <Stat icon="bolt" k="Power" v={<span className="flex items-center gap-1.5"><span className={"bm-dot " + (l.power === "on" ? "" : "bm-dot-off")} />{l.power === "on" ? "On" : l.power === "off" ? "Off" : "Unknown"}</span>} />
        <Stat icon="database" k="Boots from" v={l.bootMode === "rescue" ? "Rescue system" : l.bootMode === "disk" ? "Disk" : "Unknown"} sub={l.bootMode === "rescue" ? "Boot back to disk when done" : undefined} />
        <Stat icon="nodes" k="Network port" v={net?.linkMbps ? mbps(net.linkMbps) : "—"} sub={net?.outMbps ? `${mbps(net.outMbps)} public bandwidth` : undefined} />
        <Stat icon="linechart" k="Traffic" v={!net ? "—" : net.throttled ? "Limited" : net.unmetered ? "Unmetered" : `${net.usedPercent ?? 0}% of quota`} sub={net?.resetDate ? `Resets ${new Date(net.resetDate).toLocaleDateString("en-US", { month: "short", day: "numeric" })}` : undefined} />
      </div>
      {l.hardware && (
        <div className="bm-sub px-3.5 py-3">
          <div className="bm-label">Hardware detected on the machine</div>
          <div className="mt-1 text-[12.5px] bm-ink-2">
            {[l.hardware.cpu, l.hardware.cores ? `${l.hardware.cores} cores / ${l.hardware.threads ?? "?"} threads` : null, l.hardware.ramGb ? `${l.hardware.ramGb} GB RAM` : null, ...l.hardware.disks].filter(Boolean).join(" · ")}
          </div>
        </div>
      )}
    </div>
  );
}

/* ---------------- power & rescue ---------------- */

function KeySelect({ keys, value, onChange, optional }: { keys: { id: string; name: string }[]; value: string; onChange: (v: string) => void; optional?: boolean }) {
  if (!keys.length) return <p className="text-[12px] bm-ink-3">No SSH keys on your account. <Link href="/dashboard/settings?tab=ssh" className="bm-link">Add one in Settings</Link>.</p>;
  return (
    <select value={value} onChange={(e) => onChange(e.target.value)} className="bm-field cursor-pointer" aria-label="SSH key">
      {optional && <option value="">No key</option>}
      {keys.map((k) => <option key={k.id} value={k.id}>{k.name}</option>)}
    </select>
  );
}

export function PowerRescue({ c, serverId, primaryIp }: { c: Controls; serverId: string; primaryIp: string | null }) {
  const panel = c.panel!;
  const [confirmReboot, setConfirmReboot] = useState(false);
  const [keyId, setKeyId] = useState(panel.sshKeys[0]?.id ?? "");
  const [secret, setSecret] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const inRescue = panel.live?.bootMode === "rescue";
  const codeBox = { background: "var(--bm-card-3)" };
  return (
    <div className="grid gap-3 lg:grid-cols-2">
      <div className="bm-sub flex flex-col gap-2.5 p-4">
        <span className="flex items-center gap-2 text-[14px] font-extrabold bm-ink"><Icon name="refresh" size={14} tone="inherit" className="bm-accent" />Hard reboot</span>
        <span className="text-[12px] bm-ink-3">Power-cycles the machine, like pressing its reset button. Unsaved data in memory is lost.</span>
        {confirmReboot ? (
          <div className="flex flex-wrap gap-2">
            <button type="button" disabled={c.busy} onClick={() => { setConfirmReboot(false); c.run("REBOOT_HARD", {}, "Rebooting. It usually takes 2 to 5 minutes."); }} className="bm-btn bm-btn-sm">Yes, reboot now</button>
            <button type="button" onClick={() => setConfirmReboot(false)} className="bm-btn-ghost">Cancel</button>
          </div>
        ) : (
          <button type="button" disabled={c.busy} onClick={() => setConfirmReboot(true)} className="bm-btn-ghost w-fit">Reboot</button>
        )}
        <span className="text-[11.5px] bm-ink-4">A graceful restart is best done from inside the OS (<code className="bm-mono">sudo reboot</code>).</span>
      </div>
      <div className="bm-sub flex flex-col gap-2.5 p-4">
        <span className="flex items-center gap-2 text-[14px] font-extrabold bm-ink"><Icon name="lifebuoy" size={14} tone="inherit" className="bm-accent" />Rescue mode</span>
        {inRescue ? (
          <>
            <span className="text-[12px] bm-ink-3">Running the rescue system. Your disks are untouched; mount them to repair or copy data.</span>
            {primaryIp && <code className="bm-mono rounded-[8px] px-2.5 py-1.5 text-[12px] bm-ink" style={codeBox}>ssh root@{primaryIp}</code>}
            {panel.rescueSecretStored && (secret ? <code className="bm-mono break-all rounded-[8px] px-2.5 py-1.5 text-[12px] bm-ink" style={codeBox}>{secret}</code> : (
              <button type="button" className="bm-btn-ghost w-fit" onClick={async () => { const r = await revealDedicatedRescueSecret(serverId); if (r.ok) setSecret(r.secret); else setErr(r.error); }}>Show rescue password</button>
            ))}
            <button type="button" disabled={c.busy} onClick={() => c.run("RESCUE_OFF", {}, "Booting back from disk.")} className="bm-btn bm-btn-sm w-fit">Boot back to disk</button>
          </>
        ) : (
          <>
            <span className="text-[12px] bm-ink-3">Restarts into a recovery system loaded over the network. Log in with your SSH key.</span>
            <KeySelect keys={panel.sshKeys} value={keyId} onChange={setKeyId} optional />
            <button type="button" disabled={c.busy} onClick={() => c.run("RESCUE_ON", { sshKeyId: keyId || undefined }, "Booting into rescue mode.")} className="bm-btn-ghost w-fit">Boot into rescue</button>
          </>
        )}
        {err && <span className="text-[11.5px] bm-bad">{err}</span>}
      </div>
      <div className="flex flex-col gap-1.5 rounded-[13px] p-4 lg:col-span-2" style={{ border: "1px dashed var(--bm-line-2)" }}>
        <span className="flex items-center gap-2 text-[13px] font-bold bm-ink"><Icon name="monitor" size={14} tone="inherit" className="bm-ink-3" />Remote console</span>
        <span className="text-[12px] bm-ink-3">Need the screen and keyboard (for example if the network config is broken)? Our engineers open the out-of-band console for you. <Link href="/dashboard/support" className="bm-link">Open a ticket</Link>.</span>
      </div>
    </div>
  );
}

/* ---------------- reinstall ---------------- */

export function ReinstallPanel({ c, label }: { c: Controls; label: string }) {
  const panel = c.panel!;
  const templates = useMemo(() => panel.live?.templates ?? [], [panel.live]);
  const [tpl, setTpl] = useState(templates[0]?.name ?? "");
  useEffect(() => { if (!tpl && templates[0]) setTpl(templates[0].name); }, [templates, tpl]);
  const [host, setHost] = useState("");
  const [keyId, setKeyId] = useState(panel.sshKeys[0]?.id ?? "");
  const [typed, setTyped] = useState("");
  const ok = !!tpl && !!host.trim() && !!keyId && typed.trim() === label;
  return (
    <div className="flex flex-col gap-3.5 rounded-[14px] p-4" style={{ border: "1px solid color-mix(in srgb, var(--bm-bad) 35%, transparent)", background: "var(--bm-bad-soft)" }}>
      <span className="flex items-center gap-2 text-[14px] font-extrabold bm-ink"><Icon name="warntriangle" size={14} tone="inherit" className="bm-bad" />Reinstall the operating system</span>
      <span className="text-[12.5px] bm-ink-2">This erases every disk on the server. Back up anything you need first. You log in afterwards as <b>root</b> with the SSH key you pick; no password is set.</span>
      <div className="grid gap-3 sm:grid-cols-3">
        <label className="flex flex-col gap-1"><span className="bm-label">Operating system</span>
          <select value={tpl} onChange={(e) => setTpl(e.target.value)} className="bm-field cursor-pointer">
            {templates.length === 0 && <option value="">Loading…</option>}
            {templates.map((t) => <option key={t.name} value={t.name}>{t.label}</option>)}
          </select>
        </label>
        <label className="flex flex-col gap-1"><span className="bm-label">Hostname</span>
          <input value={host} onChange={(e) => setHost(e.target.value)} placeholder="db1.example.com" className="bm-field" />
        </label>
        <label className="flex flex-col gap-1"><span className="bm-label">SSH key</span>
          <KeySelect keys={panel.sshKeys} value={keyId} onChange={setKeyId} />
        </label>
      </div>
      <label className="flex flex-col gap-1"><span className="bm-label">Type <b className="bm-ink">{label}</b> to confirm</span>
        <input value={typed} onChange={(e) => setTyped(e.target.value)} className="bm-field max-w-[360px]" autoComplete="off" aria-label="Type the server name to confirm" />
      </label>
      <button type="button" disabled={!ok || c.busy} onClick={() => c.run("REINSTALL", { templateName: tpl, hostname: host, sshKeyId: keyId, confirm: typed }, "Reinstall started. It usually takes 10 to 20 minutes.")} className="bm-btn bm-btn-sm w-fit">Erase and reinstall</button>
    </div>
  );
}

/* ---------------- network: rDNS + firewall ---------------- */

export function NetworkPanel({ c }: { c: Controls }) {
  const ips = c.panel?.live?.ips ?? [];
  const v4 = ips.filter((i) => i.version === 4 && i.cidr.endsWith("/32"));
  const [open, setOpen] = useState<string | null>(null);
  return (
    <div className="flex flex-col gap-3">
      <div className="bm-sub flex flex-col">
        {ips.length === 0 && <p className="p-4 text-[12.5px] bm-ink-3">No addresses found yet.</p>}
        {ips.map((ip, i) => (
          <div key={ip.cidr} className={i ? "border-t bm-rule" : ""}>
            <IpRow ip={ip} open={open === ip.cidr} onToggle={() => setOpen(open === ip.cidr ? null : ip.cidr)} c={c} />
          </div>
        ))}
      </div>
      {v4.length > 0 && <p className="text-[11.5px] bm-ink-4">The network firewall filters traffic before it reaches your server, on top of DDoS protection. Rules apply per IPv4 address.</p>}
    </div>
  );
}

function IpRow({ ip, open, onToggle, c }: { ip: LiveIp; open: boolean; onToggle: () => void; c: Controls }) {
  const [rev, setRev] = useState(ip.reverse?.replace(/\.$/, "") ?? "");
  const [rule, setRule] = useState({ sequence: "0", action: "permit", protocol: "tcp", ports: "22", source: "" });
  const single = ip.version === 4 && ip.cidr.endsWith("/32");
  const fw = ip.firewall;
  return (
    <div className="flex flex-col gap-2 p-4">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <span className="flex min-w-0 flex-wrap items-center gap-2">
          <span className="bm-mono trunc text-[13px] font-semibold bm-ink">{single ? ip.ip : ip.cidr}</span>
          <span className="bm-tag bm-tag-gpu">{ip.version === 6 ? "IPv6" : single ? "IPv4" : "Block"}</span>
          {fw?.exists && <span className={"bm-tag " + (fw.enabled ? "bm-tag-value" : "bm-tag-gpu")}>{fw.enabled ? "Firewall on" : "Firewall off"}</span>}
        </span>
        {single && <button type="button" onClick={onToggle} className="bm-btn-ghost">{open ? "Close" : "Manage"}</button>}
      </div>
      {single && !open && <span className="trunc text-[11.5px] bm-ink-3">Reverse DNS: {ip.reverse ? ip.reverse.replace(/\.$/, "") : "not set"}</span>}
      {single && open && (
        <div className="flex flex-col gap-4 rounded-[11px] p-3.5" style={{ background: "var(--bm-card)" }}>
          <div className="flex flex-col gap-1.5">
            <span className="bm-label">Reverse DNS (PTR)</span>
            <div className="flex flex-wrap gap-2">
              <input value={rev} onChange={(e) => setRev(e.target.value)} placeholder="mail.example.com" className="bm-field max-w-[320px] flex-1" />
              <button type="button" disabled={c.busy || !rev.trim()} onClick={() => c.run("REVERSE_SET", { ip: ip.ip, reverse: rev }, "Saving reverse DNS.")} className="bm-btn-ghost">Save</button>
            </div>
            <span className="text-[11px] bm-ink-4">The hostname must already resolve to {ip.ip}.</span>
          </div>
          <div className="flex flex-col gap-2">
            <span className="flex items-center justify-between gap-2">
              <span className="bm-label">Network firewall</span>
              <button type="button" disabled={c.busy} onClick={() => c.run(fw?.enabled ? "FW_DISABLE" : "FW_ENABLE", { ip: ip.ip }, fw?.enabled ? "Turning the firewall off." : "Turning the firewall on.")} className="bm-btn-ghost">{fw?.enabled ? "Turn off" : "Turn on"}</button>
            </span>
            {fw?.rules.length ? (
              <ul className="flex flex-col gap-1">
                {fw.rules.map((r) => (
                  <li key={String(r.sequence)} className="bm-sub flex items-center justify-between gap-2 px-3 py-2 text-[12px]">
                    <span className="trunc bm-ink-2"><b className="bm-ink">#{r.sequence}</b> {r.action === "permit" ? "allow" : "block"} {r.protocol}{r.port ? ` ${r.port}` : ""}{r.source && r.source !== "0.0.0.0/0" ? ` from ${r.source}` : ""}</span>
                    <button type="button" disabled={c.busy} onClick={() => c.run("FW_RULE_REMOVE", { ip: ip.ip, sequence: String(r.sequence) }, "Removing the rule.")} className="flex-none text-[11.5px] font-bold bm-bad">Remove</button>
                  </li>
                ))}
              </ul>
            ) : <span className="text-[11.5px] bm-ink-3">No rules yet. With the firewall on and no rules, traffic is allowed.</span>}
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-6">
              <input value={rule.sequence} onChange={(e) => setRule({ ...rule, sequence: e.target.value })} className="bm-field" aria-label="Order (0-19)" placeholder="#" />
              <select value={rule.action} onChange={(e) => setRule({ ...rule, action: e.target.value })} className="bm-field" aria-label="Action"><option value="permit">Allow</option><option value="deny">Block</option></select>
              <select value={rule.protocol} onChange={(e) => setRule({ ...rule, protocol: e.target.value })} className="bm-field" aria-label="Protocol">{["tcp", "udp", "icmp", "ipv4"].map((p) => <option key={p} value={p}>{p.toUpperCase()}</option>)}</select>
              <input value={rule.ports} onChange={(e) => setRule({ ...rule, ports: e.target.value })} className="bm-field" placeholder="Port(s)" aria-label="Ports" disabled={rule.protocol !== "tcp" && rule.protocol !== "udp"} />
              <input value={rule.source} onChange={(e) => setRule({ ...rule, source: e.target.value })} className="bm-field" placeholder="From (any)" aria-label="Source" />
              <button type="button" disabled={c.busy} onClick={() => c.run("FW_RULE_ADD", { ip: ip.ip, rule: { ...rule, ports: rule.protocol === "tcp" || rule.protocol === "udp" ? rule.ports : "" } }, "Adding the rule.")} className="bm-btn-ghost h-[40px]">Add rule</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* ---------------- buy extra IPs ---------------- */

export function ExtraIps({ c, serverId, balanceCents }: { c: Controls; serverId: string; balanceCents: number }) {
  const panel = c.panel!;
  const router = useRouter();
  const [qty, setQty] = useState<1 | 4 | 8>(1);
  const [useWallet, setUseWallet] = useState(balanceCents > 0);
  const [quote, setQuote] = useState<{ chargeCents: number; renewalAfter: string; monthlyCents: number; walletApplied: number; cardCents: number; balanceCents: number } | null>(null);
  const [checkout, setCheckout] = useState<{ clientSecret: string; publishableKey: string; cardCents: number } | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [busy, start] = useTransition();
  const key = useMemo(() => newKey(), []);
  const confirmRef = useRef<(() => Promise<void>) | null>(null);
  const [canConfirm, setCanConfirm] = useState(false);
  const open = panel.ipOrders.find((o) => ["PAID", "APPROVED", "ORDERING"].includes(o.status));

  useEffect(() => {
    setCheckout(null);
    start(async () => {
      const r = await quoteDedicatedExtraIps(serverId, qty, useWallet);
      if (r.ok) { setQuote({ ...r.quote, walletApplied: r.walletApplied, cardCents: r.cardCents, balanceCents: r.balanceCents }); setErr(null); } else setErr(r.error);
    });
  }, [qty, serverId, useWallet]);

  const pay = () => start(async () => {
    setErr(null);
    const r = await payDedicatedExtraIps(serverId, qty, key, useWallet);
    if (!r.ok) { setErr(r.error); return; }
    if ("orderId" in r) { await c.refresh(true); router.refresh(); return; }
    setCheckout({ ...r.checkout, cardCents: r.cardCents });
  });

  const STATUS: Record<string, string> = { PAID: "Paid, awaiting our team", APPROVED: "Being ordered", ORDERING: "Being delivered", DONE: "Added", REJECTED: "Refunded", FAILED: "Delayed, our team is on it" };
  return (
    <div className="flex flex-col gap-3">
      {panel.ipOrders.length > 0 && (
        <ul className="bm-sub flex flex-col">
          {panel.ipOrders.map((o, i) => (
            <li key={o.id} className={"flex flex-wrap items-center justify-between gap-2 px-4 py-3 text-[12.5px] " + (i ? "border-t bm-rule" : "")}>
              <span className="bm-ink-2">{o.quantity === 1 ? "1 address" : `${o.quantity} addresses`} · {usd(o.chargedCents)} · {when(o.createdAt)}</span>
              <span className={"bm-tag " + (o.status === "DONE" ? "bm-tag-value" : o.status === "REJECTED" ? "bm-tag-gpu" : "bm-tag-recommended")}>{STATUS[o.status] ?? o.status}</span>
              {o.ips.length > 0 && <span className="bm-mono w-full text-[11.5px] bm-ink-3">{o.ips.join(", ")}</span>}
            </li>
          ))}
        </ul>
      )}
      {open ? (
        <p className="text-[12.5px] bm-ink-3">Your order is with our team. The addresses appear here once they are routed to this server.</p>
      ) : (
        <div className="flex flex-col gap-3">
          <div className="grid gap-2.5 sm:grid-cols-3" role="radiogroup" aria-label="How many addresses">
            {([1, 4, 8] as const).map((n) => (
              <button key={n} type="button" role="radio" aria-checked={qty === n} onClick={() => setQty(n)} className="bm-pick flex flex-col gap-0.5 p-3">
                <span className="text-[14px] font-extrabold bm-ink">{n === 1 ? "1 address" : `Block of ${n}`}</span>
                <span className="text-[11.5px] bm-ink-3">{n === 1 ? "A single extra IPv4" : `${n} consecutive IPv4s`}</span>
              </button>
            ))}
          </div>
          {quote ? (
            <dl className="bm-sub flex flex-col gap-1.5 p-4 text-[13px]">
              <div className="flex justify-between gap-3"><dt className="bm-ink-3">Today (prorated to your renewal)</dt><dd className="bm-num font-bold bm-ink">{usd(quote.chargeCents)}</dd></div>
              <div className="flex justify-between gap-3"><dt className="bm-ink-3">Then your server renews at</dt><dd className="bm-num font-bold bm-ink">{quote.renewalAfter}</dd></div>
              {quote.walletApplied > 0 && <div className="flex justify-between gap-3"><dt className="bm-ink-3">From your wallet</dt><dd className="bm-num font-semibold bm-ok">−{usd(quote.walletApplied)}</dd></div>}
              {quote.cardCents > 0 && <div className="flex justify-between gap-3"><dt className="bm-ink-3">By card</dt><dd className="bm-num font-semibold bm-ink">{usd(quote.cardCents)}</dd></div>}
            </dl>
          ) : <span className="bm-skel block h-[70px]" />}
          {balanceCents > 0 && (
            <label className="flex cursor-pointer items-center gap-2.5 text-[12.5px] bm-ink-2">
              <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} />
              Use my wallet balance ({usd(balanceCents)})
            </label>
          )}
          {checkout ? (
            <div className="flex flex-col gap-3">
              <NxCardFields clientSecret={checkout.clientSecret} publishableKey={checkout.publishableKey} onConfirmReady={(fn) => { confirmRef.current = fn; setCanConfirm(!!fn); }} onBusy={(_b, e) => setErr(e)} />
              <button type="button" disabled={!canConfirm} onClick={() => void confirmRef.current?.()} className="bm-btn bm-btn-sm w-fit">Pay {usd(checkout.cardCents)}</button>
            </div>
          ) : (
            <button type="button" disabled={busy || !quote} onClick={pay} className="bm-btn bm-btn-sm w-fit">{quote && quote.cardCents === 0 ? `Pay ${usd(quote.chargeCents)} from wallet` : "Continue to card payment"}</button>
          )}
          <span className="text-[11.5px] bm-ink-4">Our team confirms availability in your location before the addresses are added. If they can&apos;t be added, the full amount goes back to your wallet.</span>
        </div>
      )}
      {err && <span className="text-[12px] bm-bad">{err}</span>}
    </div>
  );
}

/* ---------------- recent actions ---------------- */

export function RecentActions({ jobs }: { jobs: CustomerJob[] }) {
  if (!jobs.length) return <p className="text-[12.5px] bm-ink-3">Nothing yet. Reboots, reinstalls and network changes you make show here with their progress.</p>;
  return (
    <ul className="flex flex-col gap-2">
      {jobs.slice(0, 8).map((j) => (
        <li key={j.id} className="bm-sub flex flex-col gap-1.5 px-3.5 py-3">
          <span className="flex flex-wrap items-center justify-between gap-2">
            <span className="text-[13px] font-bold bm-ink">{j.label}</span>
            <span className={"bm-tag " + (j.status === "DONE" ? "bm-tag-value" : j.status === "FAILED" ? "bm-tag-performance" : "bm-tag-recommended")}>{JOB_STATUS_LABEL[j.status] ?? j.status}</span>
          </span>
          {!isTerminal(j.status) && <span className="block h-[4px] overflow-hidden rounded-full" style={{ background: "var(--bm-card-3)" }}><span className="block h-full rounded-full transition-[width] duration-700" style={{ width: `${Math.max(6, j.progress)}%`, background: "var(--bm-grad)" }} /></span>}
          <span className="text-[11.5px] bm-ink-3" suppressHydrationWarning>{j.error ?? j.step} · {when(j.createdAt)}</span>
        </li>
      ))}
    </ul>
  );
}

input.content:
"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): one bare-metal server's dashboard.
 *
 * Same shape as the VPS and game panels (components/customer/vpspanel/v2/
 * VpsPanelShell): a pinned identity hero, a tab rail synced to `?tab=`, one tab
 * at a time. Tabs: Overview · Power & rescue · Reinstall · Network & IPs ·
 * Plan & billing · Support. Takes only the brand-safe CustomerServerView
 * (lib/dedicated/customer-view.ts).
 *
 * Automated controls (reboot, rescue, reinstall, rDNS, firewall, extra IPs)
 * ENQUEUE jobs the worker runs — in dry run unless an admin switches it off.
 * A server without automation (or not online yet) falls back to REQUESTS that
 * open a support ticket. In `preview` (admin preview) nothing is sent.
 */
import { useEffect, useState, useTransition } from "react";
import Link from "next/link";
import type { CustomerInvoiceRow, CustomerServerView, RequestKind } from "@/lib/dedicated/customer-view";
import { REQUEST_LABEL } from "@/lib/dedicated/customer-view";
import { serverTimeline, SETUP_ETA } from "@/lib/dedicated/order-core";
import { requestDedicatedAction, revealDedicatedCredentials } from "@/lib/actions-dedicated-customer";
import type { DedicatedPanel } from "@/lib/actions-dedicated-ops";
import { cpuBrandOf } from "@/lib/dedicated/brand";
import { Icon } from "@/components/nx/Icon";
import { BrandLogo } from "./BrandLogo";
import { Flag, usd } from "./ui";
import {
  ControlsGate, ControlsMessage, ExtraIps, LiveStatus, ModeBadge, NetworkPanel, PowerRescue, RecentActions, ReinstallPanel, useDedicatedControls,
} from "./DedicatedControlPanel";

const day = (iso: string) => new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });

type TabKey = "overview" | "power" | "reinstall" | "network" | "billing" | "support";
const TABS: { key: TabKey; label: string; icon: string }[] = [
  { key: "overview", label: "Overview", icon: "donut" },
  { key: "power", label: "Power & rescue", icon: "bolt" },
  { key: "reinstall", label: "Reinstall", icon: "terminal" },
  { key: "network", label: "Network & IPs", icon: "nodes" },
  { key: "billing", label: "Plan & billing", icon: "card" },
  { key: "support", label: "Support", icon: "lifebuoy" },
];
const resolveTab = (raw: string | null | undefined): TabKey => (TABS.some((t) => t.key === raw) ? (raw as TabKey) : "overview");

const STATUS_TONE: Record<string, { color: string; bg: string; live: boolean }> = {
  ACTIVE: { color: "var(--bm-ok)", bg: "var(--bm-ok-soft)", live: true },
  PENDING: { color: "var(--bm-accent-ink)", bg: "var(--bm-accent-soft)", live: true },
  PROVISIONING: { color: "var(--bm-accent-ink)", bg: "var(--bm-accent-soft)", live: true },
  SUSPENDED: { color: "var(--bm-warn)", bg: "var(--bm-warn-soft)", live: false },
  CANCELLED: { color: "var(--bm-ink-3)", bg: "var(--bm-card-3)", live: false },
};

function Card({ title, sub, action, children, className = "" }: { title: string; sub?: string; action?: React.ReactNode; children: React.ReactNode; className?: string }) {
  return (
    <section className={"bm-card flex min-w-0 flex-col " + className}>
      <div className="flex items-start gap-3 border-b px-5 py-3.5 bm-rule">
        <span className="flex min-w-0 flex-col">
          <h3 className="text-[14.5px] font-extrabold bm-ink">{title}</h3>
          {sub && <span className="text-[12px] bm-ink-3">{sub}</span>}
        </span>
        {action && <span className="ml-auto flex-none">{action}</span>}
      </div>
      <div className="min-w-0 flex-1 p-5">{children}</div>
    </section>
  );
}

function Copy({ value, label }: { value: string; label?: string }) {
  const [done, setDone] = useState(false);
  return (
    <button type="button" title="Copy" onClick={() => { void navigator.clipboard?.writeText(value); setDone(true); setTimeout(() => setDone(false), 1200); }}
            className="group inline-flex min-w-0 items-center gap-2 rounded-[9px] px-2.5 py-1.5 text-left" style={{ background: "rgba(255,255,255,0.05)", border: "1px solid var(--bm-line)" }}>
      {label && <span className="text-[10px] font-bold uppercase tracking-[0.1em] bm-ink-3">{label}</span>}
      <span className="bm-mono trunc text-[13px] font-semibold bm-ink">{value}</span>
      <span className="flex-none text-[10.5px] font-semibold bm-ink-3">{done ? "Copied" : <Icon name="copy" size={11} tone="inherit" />}</span>
    </button>
  );
}

export function DedicatedServerDashboard({ view, invoices, preview = false, justOrdered = false, panel = null, balanceCents = 0, initialTab }: {
  view: CustomerServerView; invoices: CustomerInvoiceRow[]; preview?: boolean; justOrdered?: boolean;
  /** Live controls when already loaded; null = load after paint (or none). */
  panel?: DedicatedPanel | null;
  balanceCents?: number;
  initialTab?: string;
}) {
  const live = view.statusKey === "ACTIVE";
  const building = view.statusKey === "PENDING" || view.statusKey === "PROVISIONING";
  const automated = live && view.automated && !preview;
  const c = useDedicatedControls(view.id, panel, automated);
  const [tab, setTab] = useState<TabKey>(() => resolveTab(initialTab));
  useEffect(() => {
    const onPop = () => setTab(resolveTab(new URLSearchParams(window.location.search).get("tab")));
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);
  const go = (t: TabKey) => {
    setTab(t);
    if (preview) return;
    const url = new URL(window.location.href);
    url.searchParams.set("tab", t);
    url.searchParams.delete("ordered");
    window.history.pushState(null, "", url);
  };
  const tone = STATUS_TONE[view.statusKey] ?? STATUS_TONE.PENDING;
  const storageMain = view.storage.split("(")[0].trim() || "—";
  const storageSub = view.storage.match(/\(([^)]+)\)/)?.[1] ?? "Your own disks";
  const net = /\d+(?:\.\d+)?\s?[GM]bps/i.exec(view.bandwidth)?.[0].replace(/(\d)([GM])/i, "$1 $2") ?? (view.bandwidth || "—");

  return (
    <div className="bm mx-auto flex w-full max-w-[1480px] flex-col gap-4">
      {/* ── identity hero (always dark, like the VPS/game heroes) ── */}
      <div className="z-20 -mx-1 flex flex-col gap-2 px-1 pb-2 pt-1 lg:sticky lg:top-0" style={{ background: "color-mix(in srgb, var(--color-bg) 82%, transparent)", backdropFilter: "blur(18px)" }}>
        <header className="bm-hero bm-island">
          <span className="bm-hero-grid" aria-hidden />
          <div className="relative z-[1] flex flex-wrap items-start justify-between gap-x-6 gap-y-4 px-5 py-4">
            <div className="flex min-w-0 flex-1 items-start gap-4">
              <span className="grid h-[58px] w-[58px] flex-none place-items-center rounded-[16px]" style={{ background: "linear-gradient(140deg,rgba(139,108,255,.35),rgba(79,125,255,.2))", border: "1px solid rgba(255,255,255,0.12)" }}>
                <Icon name="bmrack" size={24} tone="inherit" className="text-[#fff]" />
              </span>
              <div className="min-w-0 flex-1">
                <Link href={preview ? "#" : "/dashboard/services"} className="text-[11.5px] font-semibold bm-ink-3 hover:underline">← My Services</Link>
                <div className="mt-0.5 flex flex-wrap items-center gap-2.5">
                  <h1 className="truncate text-[24px] font-extrabold leading-[1.05] tracking-[-0.03em] sm:text-[28px]" style={{ color: "var(--bm-ink)" }}>{view.label}</h1>
                  <span className="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11.5px] font-bold" style={{ color: tone.color, background: tone.bg }}>
                    <span className="h-1.5 w-1.5 rounded-full" style={{ background: tone.color, boxShadow: tone.live ? `0 0 8px ${tone.color}` : undefined }} />{view.status}
                  </span>
                  {view.planName && <span className="bm-tag bm-tag-recommended">{view.planName}</span>}
                  {c.panel && <ModeBadge c={c} />}
                </div>
                <div className="mt-2.5 flex flex-wrap items-center gap-x-4 gap-y-2">
                  {view.ipv4[0] && <Copy label="IP" value={view.ipv4[0]} />}
                  {view.os && <span className="flex items-center gap-2 text-[12.5px] font-semibold bm-ink-2"><Icon name="terminal" size={13} tone="inherit" />{view.os}</span>}
                  <span className="flex items-center gap-2 text-[12.5px] font-semibold bm-ink-2"><Flag country={view.regionCountry} width={18} />{view.region}</span>
                  {view.hostname && <span className="bm-mono text-[12px] bm-ink-3">{view.hostname}</span>}
                </div>
                <div className="mt-3 flex flex-wrap items-center gap-x-6 gap-y-2">
                  <HeroSpec icon={<BrandLogo brand={cpuBrandOf(view.cpu)} h={11} />} value={`${view.cores} cores`} label={view.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1")} />
                  <HeroSpec icon={<Icon name="ram" size={14} tone="inherit" />} value={`${view.ramGb} GB`} label="Memory" />
                  <HeroSpec icon={<Icon name="database" size={14} tone="inherit" />} value={storageMain} label="Storage" />
                  <HeroSpec icon={<Icon name="nodes" size={14} tone="inherit" />} value={net} label="Network" />
                </div>
              </div>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              {automated && <button type="button" onClick={() => go("power")} className="bm-btn-ghost" style={{ background: "rgba(255,255,255,0.06)", color: "var(--bm-ink)" }}><Icon name="refresh" size={12} tone="inherit" />Reboot or rescue</button>}
              <Link href={preview ? "#" : "/dashboard/support"} className="bm-btn bm-btn-sm"><Icon name="lifebuoy" size={12} tone="inherit" />Get help</Link>
            </div>
          </div>
        </header>
        <nav className="flex gap-1 overflow-x-auto rounded-[14px] p-1.5 bm-card noscroll" aria-label="Server sections">
          {TABS.map((t) => {
            const on = tab === t.key;
            return (
              <button key={t.key} type="button" onClick={() => go(t.key)} aria-current={on ? "page" : undefined}
                      className="inline-flex flex-none items-center gap-2 whitespace-nowrap rounded-[10px] px-3.5 py-2 text-[13px] font-bold transition"
                      style={on ? { background: "var(--bm-accent-soft)", color: "var(--bm-ink)", boxShadow: "0 0 0 1px var(--bm-accent) inset" } : { color: "var(--bm-ink-3)" }}>
                <Icon name={t.icon} size={13} tone="inherit" />{t.label}
              </button>
            );
          })}
        </nav>
      </div>

      {justOrdered && (
        <section className="flex items-start gap-3 rounded-[14px] p-4" role="status" style={{ background: "var(--bm-ok-soft)", border: "1px solid color-mix(in srgb, var(--bm-ok) 35%, transparent)" }}>
          <Icon name="checkcircle" size={18} tone="inherit" className="bm-ok" />
          <div>
            <div className="text-[14px] font-extrabold bm-ink">Order confirmed. Thank you.</div>
            <div className="text-[12.5px] bm-ink-2">Our team is building your server now. It will be {SETUP_ETA.toLowerCase()}; we&apos;ll notify you and post its IP addresses and login right here.</div>
          </div>
        </section>
      )}
      {view.statusKey === "SUSPENDED" && (
        <p className="rounded-[12px] px-4 py-3 text-[12.5px]" style={{ background: "var(--bm-warn-soft)", color: "var(--bm-warn)" }}>
          This server is suspended{view.suspendReason ? `: ${view.suspendReason}` : "."} <Link href={preview ? "#" : "/dashboard/support"} className="font-bold underline">Contact support</Link> to restore it.
        </p>
      )}
      <ControlsMessage c={c} />

      <div className="bm-enter min-w-0" key={tab}>
        {tab === "overview" && <Overview view={view} invoices={invoices} c={c} automated={automated} building={building} preview={preview} go={go} />}
        {tab === "power" && (
          automated ? <Card title="Power & rescue" sub="Carried out automatically, usually within a minute or two."><ControlsGate c={c}><PowerRescue c={c} serverId={view.id} primaryIp={view.ipv4[0] ?? null} /></ControlsGate></Card>
            : <Requests view={view} kinds={["REBOOT", "RESCUE"]} preview={preview} />
        )}
        {tab === "reinstall" && (
          automated ? <Card title="Reinstall" sub="A fresh operating system, installed automatically."><ControlsGate c={c}><ReinstallPanel c={c} label={view.label} /></ControlsGate></Card>
            : <Requests view={view} kinds={["REINSTALL"]} preview={preview} />
        )}
        {tab === "network" && <Network view={view} c={c} automated={automated} balanceCents={balanceCents} />}
        {tab === "billing" && <Billing view={view} invoices={invoices} preview={preview} />}
        {tab === "support" && <Support view={view} preview={preview} />}
      </div>
    </div>
  );
}

function HeroSpec({ icon, value, label }: { icon: React.ReactNode; value: string; label: string }) {
  return (
    <span className="flex items-center gap-2">
      <span className="grid w-5 flex-none place-items-center bm-ink-3">{icon}</span>
      <span className="flex min-w-0 flex-col leading-tight">
        <span className="bm-num text-[13px] font-bold" style={{ color: "var(--bm-ink)" }}>{value}</span>
        <span className="max-w-[220px] truncate text-[10px] font-bold uppercase tracking-[0.1em] bm-ink-3">{label}</span>
      </span>
    </span>
  );
}

/* ---------------- tabs ---------------- */

function Overview({ view, invoices, c, automated, building, preview, go }: {
  view: CustomerServerView; invoices: CustomerInvoiceRow[]; c: ReturnType<typeof useDedicatedControls>; automated: boolean; building: boolean; preview: boolean; go: (t: TabKey) => void;
}) {
  const timeline = serverTimeline({ statusKey: view.statusKey, orderedAt: view.orderedAt, provisionedAt: view.provisionedAt });
  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)]">
      <div className="flex min-w-0 flex-col gap-4">
        {view.statusKey !== "CANCELLED" && (building || !automated) && (
          <Card title="Status" sub={building ? `${SETUP_ETA} of your order` : view.provisionedAt ? `Online since ${day(view.provisionedAt)}` : undefined}>
            <ol className="grid gap-4 sm:grid-cols-3">
              {timeline.map((t, i) => (
                <li key={t.key} className="flex items-start gap-3">
                  <span className="grid h-7 w-7 flex-none place-items-center rounded-full text-[12px] font-extrabold"
                        style={t.state === "done" ? { background: "var(--bm-ok-soft)", color: "var(--bm-ok)" } : t.state === "current" ? { background: "var(--bm-grad)", color: "#fff" } : { border: "1px solid var(--bm-line-2)", color: "var(--bm-ink-4)" }}>
                    {t.state === "done" ? <Icon name="check" size={11} tone="inherit" /> : i + 1}
                  </span>
                  <span className="min-w-0">
                    <span className={"block text-[13px] font-bold " + (t.state === "todo" ? "bm-ink-4" : "bm-ink")}>{t.label}{t.state === "current" && <span className="ml-1.5 text-[11px] font-semibold bm-accent motion-safe:animate-pulse">in progress</span>}</span>
                    <span className="block text-[11.5px] bm-ink-3" suppressHydrationWarning>{t.at ? `${day(t.at)} · ` : ""}{t.note}</span>
                  </span>
                </li>
              ))}
            </ol>
          </Card>
        )}
        {automated && <Card title="Live status" action={<button type="button" onClick={() => void c.refresh(true)} className="bm-btn-ghost"><Icon name="refresh" size={11} tone="inherit" />Refresh</button>}><LiveStatus c={c} /></Card>}
        <section aria-label="Hardware" className="grid grid-cols-2 gap-3 xl:grid-cols-4">
          <SpecTile k="Processor" v={`${view.cores} cores`} sub={`${view.threads} threads · ${view.cpu}`} icon={<BrandLogo brand={cpuBrandOf(view.cpu)} h={11} />} />
          <SpecTile k="Memory" v={`${view.ramGb} GB`} sub="Dedicated to you" icon={<Icon name="ram" size={14} tone="inherit" />} />
          <SpecTile k="Storage" v={view.storage.split("(")[0].trim() || "—"} sub={view.storage.match(/\(([^)]+)\)/)?.[1] ?? "Your own disks"} icon={<Icon name="database" size={14} tone="inherit" />} />
          <SpecTile k="Network" v={view.bandwidth || "—"} sub="DDoS protection included" icon={<Icon name="nodes" size={14} tone="inherit" />} />
        </section>
        <Card title="IP addresses" action={view.ipv4.length > 0 ? <button type="button" onClick={() => go("network")} className="bm-btn-ghost">Manage</button> : undefined}>
          <IpList view={view} building={building} />
        </Card>
        {automated && <Card title="Recent actions"><RecentActions jobs={c.jobs} /></Card>}
      </div>
      <div className="flex min-w-0 flex-col gap-4">
        <Login view={view} preview={preview} />
        <Card title="Your plan" action={<button type="button" onClick={() => go("billing")} className="bm-btn-ghost">Details</button>}>
          <PlanFacts view={view} compact />
          {invoices[0] && <p className="mt-3 text-[11.5px] bm-ink-3" suppressHydrationWarning>Last invoice #{invoices[0].number} · {usd(invoices[0].amountCents)} · {day(invoices[0].createdAt)}</p>}
        </Card>
        <HelpCard preview={preview} />
      </div>
    </div>
  );
}

function SpecTile({ k, v, sub, icon }: { k: string; v: string; sub: string; icon: React.ReactNode }) {
  return (
    <div className="bm-card flex min-w-0 flex-col gap-1 p-4">
      <span className="flex items-center gap-2 bm-ink-3"><span className="grid w-5 place-items-center">{icon}</span><span className="bm-label">{k}</span></span>
      <span className="trunc text-[16px] font-extrabold bm-ink">{v}</span>
      <span className="trunc text-[11.5px] bm-ink-3" title={sub}>{sub}</span>
    </div>
  );
}

function IpList({ view, building }: { view: CustomerServerView; building: boolean }) {
  if (view.ipv4.length + view.ipv6.length === 0) {
    return (
      <div className="flex items-center gap-3 rounded-[11px] px-4 py-4" style={{ border: "1px dashed var(--bm-line-2)" }}>
        <Icon name="globe" size={16} tone="inherit" className="bm-ink-3" />
        <span className="text-[12.5px] bm-ink-3">{building ? "Your addresses are assigned while the machine is built. They appear here at handover." : "No addresses assigned."}</span>
      </div>
    );
  }
  return (
    <ul className="flex flex-col">
      {view.ipv4.map((ip, i) => <li key={ip} className={"flex items-center justify-between gap-3 py-2.5 " + (i ? "border-t bm-rule" : "")}><Copy value={ip} /><span className="bm-tag bm-tag-gpu">IPv4{i === 0 ? " · primary" : ""}</span></li>)}
      {view.ipv6.map((ip) => <li key={ip} className="flex items-center justify-between gap-3 border-t py-2.5 bm-rule"><Copy value={ip} /><span className="bm-tag bm-tag-gpu">IPv6</span></li>)}
    </ul>
  );
}

function Login({ view, preview }: { view: CustomerServerView; preview: boolean }) {
  const [cred, setCred] = useState<{ username: string; secret: string } | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const live = view.statusKey === "ACTIVE";
  const reveal = () => start(async () => {
    if (preview) { setCred({ username: view.credentialsUser ?? "root", secret: "•••• preview ••••" }); return; }
    const r = await revealDedicatedCredentials(view.id);
    if (r.ok) setCred({ username: r.username, secret: r.secret }); else setErr(r.error);
  });
  return (
    <Card title="Login details">
      {view.credentialsReady ? (
        cred ? (
          <dl className="flex flex-col gap-2 text-[13px]">
            <div className="flex justify-between gap-3"><dt className="bm-ink-3">Username</dt><dd className="bm-mono bm-ink">{cred.username}</dd></div>
            <div className="flex justify-between gap-3"><dt className="bm-ink-3">Password</dt><dd className="bm-mono break-all bm-ink">{cred.secret}</dd></div>
            <p className="pt-1 text-[11.5px] bm-ink-4">Change this password after your first login.</p>
          </dl>
        ) : (
          <div className="flex flex-col items-start gap-2.5">
            <p className="text-[12.5px] bm-ink-3">Your login is ready. It is stored encrypted and shown only to you.</p>
            <button type="button" className="bm-btn bm-btn-sm" disabled={pending} onClick={reveal}><Icon name="key" size={12} tone="inherit" />Show login details</button>
          </div>
        )
      ) : live && view.credentialsUser ? (
        <div className="flex flex-col gap-2">
          <p className="text-[12.5px] bm-ink-3">Log in as <b className="bm-ink">{view.credentialsUser}</b> with the SSH key you chose. No password is set.</p>
          {view.ipv4[0] && <code className="bm-mono w-fit rounded-[8px] px-2.5 py-1.5 text-[12px] bm-ink" style={{ background: "var(--bm-card-3)" }}>ssh {view.credentialsUser}@{view.ipv4[0]}</code>}
        </div>
      ) : (
        <p className="flex items-center gap-2 text-[12.5px] bm-ink-3"><Icon name="lock" size={13} tone="inherit" />Delivered here, encrypted, as soon as your server is handed over.</p>
      )}
      {err && <p className="mt-2 text-[12px] bm-bad">{err}</p>}
    </Card>
  );
}

function PlanFacts({ view, compact = false }: { view: CustomerServerView; compact?: boolean }) {
  const rows: [string, React.ReactNode][] = [
    ...(view.planName ? [["Build", view.planName] as [string, React.ReactNode]] : []),
    ["Billing term", view.termLabel],
    ["Renews at", <b key="r" className="bm-ink">{view.renewal ?? "—"}</b>],
    ["Next renewal", <span key="d" suppressHydrationWarning>{view.renewalDate ? day(view.renewalDate) : "—"}</span>],
    ...(!compact && view.extraIpMonthlyCents > 0 ? [["Included extra IPs", `${usd(view.extraIpMonthlyCents)}/mo`] as [string, React.ReactNode]] : []),
    ...(!compact ? [["Setup fee paid", view.setupFeeCents > 0 ? usd(view.setupFeeCents) : "None"] as [string, React.ReactNode]] : []),
    ...(!compact ? [["Ordered", <span key="o" suppressHydrationWarning>{day(view.orderedAt)}</span>] as [string, React.ReactNode]] : []),
  ];
  return (
    <dl className="flex flex-col gap-2 text-[13px]">
      {rows.map(([k, v]) => <div key={k} className="flex justify-between gap-3"><dt className="bm-ink-3">{k}</dt><dd className="text-right bm-ink-2">{v}</dd></div>)}
    </dl>
  );
}

function Network({ view, c, automated, balanceCents }: { view: CustomerServerView; c: ReturnType<typeof useDedicatedControls>; automated: boolean; balanceCents: number }) {
  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)]">
      <div className="flex min-w-0 flex-col gap-4">
        <Card title="Addresses" sub="Your public IPv4 and IPv6 addresses."><IpList view={view} building={view.statusKey !== "ACTIVE"} /></Card>
        {automated && <Card title="Reverse DNS & firewall" sub="Per-address PTR records and a network firewall in front of your server."><ControlsGate c={c}><NetworkPanel c={c} /></ControlsGate></Card>}
      </div>
      <Card title="Buy more IPv4 addresses" sub="Prorated to your next renewal, then added to it.">
        {automated ? <ControlsGate c={c}><ExtraIps c={c} serverId={view.id} balanceCents={balanceCents} /></ControlsGate>
          : <p className="text-[12.5px] bm-ink-3">Extra addresses can be added once your server is online.</p>}
      </Card>
    </div>
  );
}

function Billing({ view, invoices, preview }: { view: CustomerServerView; invoices: CustomerInvoiceRow[]; preview: boolean }) {
  const cancelRequested = view.openRequests.some((r) => r.kind === "CANCEL");
  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
      <div className="flex min-w-0 flex-col gap-4">
        <Card title="Plan terms">
          <PlanFacts view={view} />
          <p className="mt-3 text-[11.5px] bm-ink-4">The renewal price is shown exactly as it is charged{view.termMonths === 12 ? " (once a year)" : ""}. We send a renewal invoice before the date above.</p>
        </Card>
        <Card title="Cancellation" sub="Stop this server from renewing.">
          {view.statusKey === "CANCELLED" ? <p className="text-[12.5px] bm-ink-3">This server has been cancelled.</p>
            : cancelRequested ? <p className="text-[12.5px] bm-ink-2">Your cancellation request is with our team. They will confirm the date service ends in your support ticket.</p>
            : <RequestForm view={view} kind="CANCEL" preview={preview} intro={`Our team confirms the date service ends${view.renewalDate ? ` (your current term is paid until ${day(view.renewalDate)})` : ""} in a support ticket. Nothing stops until they confirm with you.`} button="Request cancellation" />}
        </Card>
      </div>
      <Card title="Invoices">
        {invoices.length === 0 ? <p className="text-[12.5px] bm-ink-3">No invoices yet.</p> : (
          <ul className="flex flex-col">
            {invoices.map((inv, i) => (
              <li key={inv.id} className={"flex items-center justify-between gap-3 py-2.5 text-[13px] " + (i ? "border-t bm-rule" : "")}>
                <span className="flex min-w-0 flex-col">
                  {preview ? <span className="font-semibold bm-ink" suppressHydrationWarning>#{inv.number} · {day(inv.createdAt)}</span>
                    : <Link href={`/dashboard/invoices/${inv.id}`} className="font-semibold bm-ink hover:underline" suppressHydrationWarning>#{inv.number} · {day(inv.createdAt)}</Link>}
                  <span className="trunc text-[11.5px] bm-ink-3">{inv.description}</span>
                </span>
                <span className="flex flex-none items-center gap-2"><span className="bm-num font-bold bm-ink">{usd(inv.amountCents)}</span><span className={"bm-tag " + (inv.status === "PAID" ? "bm-tag-value" : "bm-tag-gpu")}>{inv.status.toLowerCase()}</span></span>
              </li>
            ))}
          </ul>
        )}
      </Card>
    </div>
  );
}

const REQUEST_HINT: Record<RequestKind, string> = {
  REBOOT: "A clean restart of the machine.",
  REINSTALL: "Wipes the disks and installs a fresh OS.",
  RESCUE: "Boots a recovery system to repair or copy data.",
  CANCEL: "Stops the server from renewing.",
};

function Requests({ view, kinds, preview }: { view: CustomerServerView; kinds: RequestKind[]; preview: boolean }) {
  const live = view.statusKey === "ACTIVE";
  return (
    <Card title={kinds.includes("REINSTALL") ? "Reinstall" : "Power & rescue"} sub={live ? "Our engineers carry these out. Each one opens a support ticket you can follow." : "Available once your server is online."}>
      <div className="flex flex-col gap-3">
        {kinds.map((k) => <RequestForm key={k} view={view} kind={k} preview={preview} intro={REQUEST_HINT[k]} button={REQUEST_LABEL[k]} disabled={!live} />)}
      </div>
    </Card>
  );
}

function RequestForm({ view, kind, preview, intro, button, disabled = false }: { view: CustomerServerView; kind: RequestKind; preview: boolean; intro: string; button: string; disabled?: boolean }) {
  const [open, setOpen] = useState(false);
  const [note, setNote] = useState("");
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const requested = view.openRequests.some((r) => r.kind === kind);
  const send = () => start(async () => {
    if (preview) { setMsg(`Preview: a "${REQUEST_LABEL[kind]}" request would open a support ticket. Nothing was sent.`); setOpen(false); return; }
    const r = await requestDedicatedAction(view.id, kind, note);
    setMsg(r.ok ? "Request sent. Our team has it as a support ticket and will update you there." : r.error);
    if (r.ok) { setOpen(false); setNote(""); }
  });
  return (
    <div className="bm-sub flex flex-col gap-2.5 p-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <span className="flex min-w-0 flex-col">
          <span className="text-[13.5px] font-extrabold bm-ink">{requested ? `${REQUEST_LABEL[kind]} · requested` : REQUEST_LABEL[kind]}</span>
          <span className="text-[12px] bm-ink-3">{intro}</span>
        </span>
        {!open && <button type="button" disabled={disabled || requested || pending} onClick={() => setOpen(true)} className="bm-btn-ghost">{button}</button>}
      </div>
      {open && (
        <div className="flex flex-col gap-2">
          <label className="text-[12px] font-bold bm-ink" htmlFor={`req-${kind}`}>Anything we should know?</label>
          <textarea id={`req-${kind}`} value={note} onChange={(e) => setNote(e.target.value)} rows={3} maxLength={2000} placeholder={kind === "REINSTALL" ? "e.g. Ubuntu 24.04, keep the same hostname" : "Optional"} className="bm-field h-auto py-2" />
          {kind === "REINSTALL" && <p className="text-[11.5px] bm-warn">A reinstall erases everything on the disks.</p>}
          <div className="flex gap-2">
            <button type="button" className="bm-btn bm-btn-sm" disabled={pending} onClick={send}>Send request</button>
            <button type="button" className="bm-btn-ghost" onClick={() => setOpen(false)}>Cancel</button>
          </div>
        </div>
      )}
      {msg && <p className="text-[12px] bm-ink-2" role="status">{msg}</p>}
    </div>
  );
}

function Support({ view, preview }: { view: CustomerServerView; preview: boolean }) {
  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <HelpCard preview={preview} big />
      <Card title="Open requests">
        {view.openRequests.length === 0 ? <p className="text-[12.5px] bm-ink-3">No open requests for this server.</p> : (
          <ul className="flex flex-col gap-2">
            {view.openRequests.map((r) => <li key={r.id} className="bm-sub px-3.5 py-2.5 text-[12.5px] bm-ink-2" suppressHydrationWarning><b className="bm-ink">{REQUEST_LABEL[r.kind as RequestKind] ?? r.kind}</b> · requested {day(r.createdAt)} · with our team</li>)}
          </ul>
        )}
        <p className="mt-3 text-[11.5px] bm-ink-4">Need the out-of-band console? Our engineers open it for you from a ticket.</p>
      </Card>
    </div>
  );
}

function HelpCard({ preview, big = false }: { preview: boolean; big?: boolean }) {
  return (
    <section className={"bm-card flex items-center gap-4 " + (big ? "p-6" : "p-5")}>
      <span className="grid h-11 w-11 flex-none place-items-center rounded-[13px] bm-sub"><Icon name="lifebuoy" size={18} tone="inherit" className="bm-accent" /></span>
      <div className="min-w-0 flex-1">
        <div className="text-[14px] font-extrabold bm-ink">Need a hand with this server?</div>
        <div className="text-[12px] bm-ink-3">The same support team that runs the rest of your Nxeon services.</div>
      </div>
      <Link href={preview ? "#" : "/dashboard/support"} className="bm-btn-ghost flex-none">Open a ticket</Link>
    </section>
  );
}

toolu_014DZeK2M1MMkra8q2h2aTLt.content:
"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): one bare-metal server's dashboard.
 *
 * Same shape as the VPS and game panels (components/customer/vpspanel/v2/
 * VpsPanelShell): a pinned identity hero, a tab rail synced to `?tab=`, one tab
 * at a time. Tabs: Overview · Power & rescue · Reinstall · Network & IPs ·
 * Plan & billing · Support. Takes only the brand-safe CustomerServerView
 * (lib/dedicated/customer-view.ts).
 *
 * Automated controls (reboot, rescue, reinstall, rDNS, firewall, extra IPs)
 * ENQUEUE jobs the worker runs — in dry run unless an admin switches it off.
 * A server without automation (or not online yet) falls back to REQUESTS that
 * open a support ticket. In `preview` (admin preview) nothing is sent.
 */
import { useEffect, useState, useTransition } from "react";
import Link from "next/link";
import type { CustomerInvoiceRow, CustomerServerView, RequestKind } from "@/lib/dedicated/customer-view";
import { REQUEST_LABEL } from "@/lib/dedicated/customer-view";
import { serverTimeline, SETUP_ETA } from "@/lib/dedicated/order-core";
import { requestDedicatedAction, revealDedicatedCredentials } from "@/lib/actions-dedicated-customer";
import type { DedicatedPanel } from "@/lib/actions-dedicated-ops";
import { cpuBrandOf } from "@/lib/dedicated/brand";
import { Icon } from "@/components/nx/Icon";
import { BrandLogo } from "./BrandLogo";
import { Flag, usd } from "./ui";
import {
  ControlsGate, ControlsMessage, ExtraIps, LiveStatus, ModeBadge, NetworkPanel, PowerRescue, RecentActions, ReinstallPanel, useDedicatedControls,
} from "./DedicatedControlPanel";

const day = (iso: string) => new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });

type TabKey = "overview" | "power" | "reinstall" | "network" | "billing" | "support";
const TABS: { key: TabKey; label: string; icon: string }[] = [
  { key: "overview", label: "Overview", icon: "donut" },
  { key: "power", label: "Power & rescue", icon: "bolt" },
  { key: "reinstall", label: "Reinstall", icon: "terminal" },
  { key: "network", label: "Network & IPs", icon: "nodes" },
  { key: "billing", label: "Plan & billing", icon: "card" },
  { key: "support", label: "Support", icon: "lifebuoy" },
];
const resolveTab = (raw: string | null | undefined): TabKey => (TABS.some((t) => t.key === raw) ? (raw as TabKey) : "overview");

const STATUS_TONE: Record<string, { color: string; bg: string; live: boolean }> = {
  ACTIVE: { color: "var(--bm-ok)", bg: "var(--bm-ok-soft)", live: true },
  PENDING: { color: "var(--bm-accent-ink)", bg: "var(--bm-accent-soft)", live: true },
  PROVISIONING: { color: "var(--bm-accent-ink)", bg: "var(--bm-accent-soft)", live: true },
  SUSPENDED: { color: "var(--bm-warn)", bg: "var(--bm-warn-soft)", live: false },
  CANCELLED: { color: "var(--bm-ink-3)", bg: "var(--bm-card-3)", live: false },
};

function Card({ title, sub, action, children, className = "" }: { title: string; sub?: string; action?: React.ReactNode; children: React.ReactNode; className?: string }) {
  return (
    <section className={"bm-card flex min-w-0 flex-col " + className}>
      <div className="flex items-start gap-3 border-b px-5 py-3.5 bm-rule">
        <span className="flex min-w-0 flex-col">
          <h3 className="text-[14.5px] font-extrabold bm-ink">{title}</h3>
          {sub && <span className="text-[12px] bm-ink-3">{sub}</span>}
        </span>
        {action && <span className="ml-auto flex-none">{action}</span>}
      </div>
      <div className="min-w-0 flex-1 p-5">{children}</div>
    </section>
  );
}

function Copy({ value, label }: { value: string; label?: string }) {
  const [done, setDone] = useState(false);
  return (
    <button type="button" title="Copy" onClick={() => { void navigator.clipboard?.writeText(value); setDone(true); setTimeout(() => setDone(false), 1200); }}
            className="group inline-flex min-w-0 items-center gap-2 rounded-[9px] px-2.5 py-1.5 text-left" style={{ background: "rgba(255,255,255,0.05)", border: "1px solid var(--bm-line)" }}>
      {label && <span className="text-[10px] font-bold uppercase tracking-[0.1em] bm-ink-3">{label}</span>}
      <span className="bm-mono trunc text-[13px] font-semibold bm-ink">{value}</span>
      <span className="flex-none text-[10.5px] font-semibold bm-ink-3">{done ? "Copied" : <Icon name="copy" size={11} tone="inherit" />}</span>
    </button>
  );
}

export function DedicatedServerDashboard({ view, invoices, preview = false, justOrdered = false, panel = null, balanceCents = 0, initialTab }: {
  view: CustomerServerView; invoices: CustomerInvoiceRow[]; preview?: boolean; justOrdered?: boolean;
  /** Live controls when already loaded; null = load after paint (or none). */
  panel?: DedicatedPanel | null;
  balanceCents?: number;
  initialTab?: string;
}) {
  const live = view.statusKey === "ACTIVE";
  const building = view.statusKey === "PENDING" || view.statusKey === "PROVISIONING";
  const automated = live && view.automated && !preview;
  const c = useDedicatedControls(view.id, panel, automated);
  const [tab, setTab] = useState<TabKey>(() => resolveTab(initialTab));
  useEffect(() => {
    const onPop = () => setTab(resolveTab(new URLSearchParams(window.location.search).get("tab")));
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);
  const go = (t: TabKey) => {
    setTab(t);
    if (preview) return;
    const url = new URL(window.location.href);
    url.searchParams.set("tab", t);
    url.searchParams.delete("ordered");
    window.history.pushState(null, "", url);
  };
  const tone = STATUS_TONE[view.statusKey] ?? STATUS_TONE.PENDING;
  const storageMain = view.storage.split("(")[0].trim() || "—";
  const storageSub = view.storage.match(/\(([^)]+)\)/)?.[1] ?? "Your own disks";
  const net = /\d+(?:\.\d+)?\s?[GM]bps/i.exec(view.bandwidth)?.[0].replace(/(\d)([GM])/i, "$1 $2") ?? (view.bandwidth || "—");

  return (
    <div className="bm mx-auto flex w-full max-w-[1480px] flex-col gap-4">
      {/* ── identity hero (always dark, like the VPS/game heroes) ── */}
      <div className="z-20 -mx-1 flex flex-col gap-2 px-1 pb-2 pt-1 lg:sticky lg:top-0" style={{ background: "color-mix(in srgb, var(--color-bg) 82%, transparent)", backdropFilter: "blur(18px)" }}>
        <header className="bm-hero bm-island">
          <span className="bm-hero-grid" aria-hidden />
          <div className="relative z-[1] flex flex-wrap items-start justify-between gap-x-6 gap-y-4 px-5 py-4">
            <div className="flex min-w-0 flex-1 items-start gap-4">
              <span className="grid h-[58px] w-[58px] flex-none place-items-center rounded-[16px]" style={{ background: "linear-gradient(140deg,rgba(139,108,255,.35),rgba(79,125,255,.2))", border: "1px solid rgba(255,255,255,0.12)" }}>
                <Icon name="bmrack" size={24} tone="inherit" className="text-[#fff]" />
              </span>
              <div className="min-w-0 flex-1">
                <Link href={preview ? "#" : "/dashboard/services"} className="text-[11.5px] font-semibold bm-ink-3 hover:underline">← My Services</Link>
                <div className="mt-0.5 flex flex-wrap items-center gap-2.5">
                  <h1 className="truncate text-[24px] font-extrabold leading-[1.05] tracking-[-0.03em] sm:text-[28px]" style={{ color: "var(--bm-ink)" }}>{view.label}</h1>
                  <span className="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11.5px] font-bold" style={{ color: tone.color, background: tone.bg }}>
                    <span className="h-1.5 w-1.5 rounded-full" style={{ background: tone.color, boxShadow: tone.live ? `0 0 8px ${tone.color}` : undefined }} />{view.status}
                  </span>
                  {view.planName && <span className="bm-tag bm-tag-recommended">{view.planName}</span>}
                  {c.panel && <ModeBadge c={c} />}
                </div>
                <div className="mt-2.5 flex flex-wrap items-center gap-x-4 gap-y-2">
                  {view.ipv4[0] && <Copy label="IP" value={view.ipv4[0]} />}
                  {view.os && <span className="flex items-center gap-2 text-[12.5px] font-semibold bm-ink-2"><Icon name="terminal" size={13} tone="inherit" />{view.os}</span>}
                  <span className="flex items-center gap-2 text-[12.5px] font-semibold bm-ink-2"><Flag country={view.regionCountry} width={18} />{view.region}</span>
                  {view.hostname && <span className="bm-mono text-[12px] bm-ink-3">{view.hostname}</span>}
                </div>
                <div className="mt-3 flex flex-wrap items-center gap-x-6 gap-y-2">
                  <HeroSpec icon={<BrandLogo brand={cpuBrandOf(view.cpu)} h={11} />} value={`${view.cores} cores`} label={view.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1")} />
                  <HeroSpec icon={<Icon name="ram" size={14} tone="inherit" />} value={`${view.ramGb} GB`} label="Memory" />
                  <HeroSpec icon={<Icon name="database" size={14} tone="inherit" />} value={storageMain} label="Storage" />
                  <HeroSpec icon={<Icon name="nodes" size={14} tone="inherit" />} value={net} label="Network" />
                </div>
              </div>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              {automated && <button type="button" onClick={() => go("power")} className="bm-btn-ghost" style={{ background: "rgba(255,255,255,0.06)", color: "var(--bm-ink)" }}><Icon name="refresh" size={12} tone="inherit" />Reboot or rescue</button>}
              <Link href={preview ? "#" : "/dashboard/support"} className="bm-btn bm-btn-sm"><Icon name="lifebuoy" size={12} tone="inherit" />Get help</Link>
            </div>
          </div>
        </header>
        <nav className="flex gap-1 overflow-x-auto rounded-[14px] p-1.5 bm-card noscroll" aria-label="Server sections">
          {TABS.map((t) => {
            const on = tab === t.key;
            return (
              <button key={t.key} type="button" onClick={() => go(t.key)} aria-current={on ? "page" : undefined}
                      className="inline-flex flex-none items-center gap-2 whitespace-nowrap rounded-[10px] px-3.5 py-2 text-[13px] font-bold transition"
                      style={on ? { background: "var(--bm-accent-soft)", color: "var(--bm-ink)", boxShadow: "0 0 0 1px var(--bm-accent) inset" } : { color: "var(--bm-ink-3)" }}>
                <Icon name={t.icon} size={13} tone="inherit" />{t.label}
              </button>
            );
          })}
        </nav>
      </div>

      {justOrdered && (
        <section className="flex items-start gap-3 rounded-[14px] p-4" role="status" style={{ background: "var(--bm-ok-soft)", border: "1px solid color-mix(in srgb, var(--bm-ok) 35%, transparent)" }}>
          <Icon name="checkcircle" size={18} tone="inherit" className="bm-ok" />
          <div>
            <div className="text-[14px] font-extrabold bm-ink">Order confirmed. Thank you.</div>
            <div className="text-[12.5px] bm-ink-2">Our team is building your server now. It will be {SETUP_ETA.toLowerCase()}; we&apos;ll notify you and post its IP addresses and login right here.</div>
          </div>
        </section>
      )}
      {view.statusKey === "SUSPENDED" && (
        <p className="rounded-[12px] px-4 py-3 text-[12.5px]" style={{ background: "var(--bm-warn-soft)", color: "var(--bm-warn)" }}>
          This server is suspended{view.suspendReason ? `: ${view.suspendReason}` : "."} <Link href={preview ? "#" : "/dashboard/support"} className="font-bold underline">Contact support</Link> to restore it.
        </p>
      )}
      <ControlsMessage c={c} />

      <div className="bm-enter min-w-0" key={tab}>
        {tab === "overview" && <Overview view={view} invoices={invoices} c={c} automated={automated} building={building} preview={preview} go={go} />}
        {tab === "power" && (
          automated ? <Card title="Power & rescue" sub="Carried out automatically, usually within a minute or two."><ControlsGate c={c}><PowerRescue c={c} serverId={view.id} primaryIp={view.ipv4[0] ?? null} /></ControlsGate></Card>
            : <Requests view={view} kinds={["REBOOT", "RESCUE"]} preview={preview} />
        )}
        {tab === "reinstall" && (
          automated ? <Card title="Reinstall" sub="A fresh operating system, installed automatically."><ControlsGate c={c}><ReinstallPanel c={c} label={view.label} /></ControlsGate></Card>
            : <Requests view={view} kinds={["REINSTALL"]} preview={preview} />
        )}
        {tab === "network" && <Network view={view} c={c} automated={automated} balanceCents={balanceCents} />}
        {tab === "billing" && <Billing view={view} invoices={invoices} preview={preview} />}
        {tab === "support" && <Support view={view} preview={preview} />}
      </div>
    </div>
  );
}

function HeroSpec({ icon, value, label }: { icon: React.ReactNode; value: string; label: string }) {
  return (
    <span className="flex items-center gap-2">
      <span className="grid w-5 flex-none place-items-center bm-ink-3">{icon}</span>
      <span className="flex min-w-0 flex-col leading-tight">
        <span className="bm-num text-[13px] font-bold" style={{ color: "var(--bm-ink)" }}>{value}</span>
        <span className="max-w-[220px] truncate text-[10px] font-bold uppercase tracking-[0.1em] bm-ink-3">{label}</span>
      </span>
    </span>
  );
}

/* ---------------- tabs ---------------- */

function Overview({ view, invoices, c, automated, building, preview, go }: {
  view: CustomerServerView; invoices: CustomerInvoiceRow[]; c: ReturnType<typeof useDedicatedControls>; automated: boolean; building: boolean; preview: boolean; go: (t: TabKey) => void;
}) {
  const timeline = serverTimeline({ statusKey: view.statusKey, orderedAt: view.orderedAt, provisionedAt: view.provisionedAt });
  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)]">
      <div className="flex min-w-0 flex-col gap-4">
        {view.statusKey !== "CANCELLED" && (building || !automated) && (
          <Card title="Status" sub={building ? `${SETUP_ETA} of your order` : view.provisionedAt ? `Online since ${day(view.provisionedAt)}` : undefined}>
            <ol className="grid gap-4 sm:grid-cols-3">
              {timeline.map((t, i) => (
                <li key={t.key} className="flex items-start gap-3">
                  <span className="grid h-7 w-7 flex-none place-items-center rounded-full text-[12px] font-extrabold"
                        style={t.state === "done" ? { background: "var(--bm-ok-soft)", color: "var(--bm-ok)" } : t.state === "current" ? { background: "var(--bm-grad)", color: "#fff" } : { border: "1px solid var(--bm-line-2)", color: "var(--bm-ink-4)" }}>
                    {t.state === "done" ? <Icon name="check" size={11} tone="inherit" /> : i + 1}
                  </span>
                  <span className="min-w-0">
                    <span className={"block text-[13px] font-bold " + (t.state === "todo" ? "bm-ink-4" : "bm-ink")}>{t.label}{t.state === "current" && <span className="ml-1.5 text-[11px] font-semibold bm-accent motion-safe:animate-pulse">in progress</span>}</span>
                    <span className="block text-[11.5px] bm-ink-3" suppressHydrationWarning>{t.at ? `${day(t.at)} · ` : ""}{t.note}</span>
                  </span>
                </li>
              ))}
            </ol>
          </Card>
        )}
        {automated && <Card title="Live status" action={<button type="button" onClick={() => void c.refresh(true)} className="bm-btn-ghost"><Icon name="refresh" size={11} tone="inherit" />Refresh</button>}><LiveStatus c={c} /></Card>}
        <section aria-label="Hardware" className="grid grid-cols-2 gap-3 xl:grid-cols-4">
          <SpecTile k="Processor" v={`${view.cores} cores`} sub={`${view.threads} threads · ${view.cpu}`} icon={<BrandLogo brand={cpuBrandOf(view.cpu)} h={11} />} />
          <SpecTile k="Memory" v={`${view.ramGb} GB`} sub="Dedicated to you" icon={<Icon name="ram" size={14} tone="inherit" />} />
          <SpecTile k="Storage" v={view.storage.split("(")[0].trim() || "—"} sub={view.storage.match(/\(([^)]+)\)/)?.[1] ?? "Your own disks"} icon={<Icon name="database" size={14} tone="inherit" />} />
          <SpecTile k="Network" v={view.bandwidth || "—"} sub="DDoS protection included" icon={<Icon name="nodes" size={14} tone="inherit" />} />
        </section>
        <Card title="IP addresses" action={view.ipv4.length > 0 ? <button type="button" onClick={() => go("network")} className="bm-btn-ghost">Manage</button> : undefined}>
          <IpList view={view} building={building} />
        </Card>
        {automated && <Card title="Recent actions"><RecentActions jobs={c.jobs} /></Card>}
      </div>
      <div className="flex min-w-0 flex-col gap-4">
        <Login view={view} preview={preview} />
        <Card title="Your plan" action={<button type="button" onClick={() => go("billing")} className="bm-btn-ghost">Details</button>}>
          <PlanFacts view={view} compact />
          {invoices[0] && <p className="mt-3 text-[11.5px] bm-ink-3" suppressHydrationWarning>Last invoice #{invoices[0].number} · {usd(invoices[0].amountCents)} · {day(invoices[0].createdAt)}</p>}
        </Card>
        <HelpCard preview={preview} />
      </div>
    </div>
  );
}

function SpecTile({ k, v, sub, icon }: { k: string; v: string; sub: string; icon: React.ReactNode }) {
  return (
    <div className="bm-card flex min-w-0 flex-col gap-1 p-4">
      <span className="flex items-center gap-2 bm-ink-3"><span className="grid w-5 place-items-center">{icon}</span><span className="bm-label">{k}</span></span>
      <span className="trunc text-[16px] font-extrabold bm-ink">{v}</span>
      <span className="trunc text-[11.5px] bm-ink-3" title={sub}>{sub}</span>
    </div>
  );
}

function IpList({ view, building }: { view: CustomerServerView; building: boolean }) {
  if (view.ipv4.length + view.ipv6.length === 0) {
    return (
      <div className="flex items-center gap-3 rounded-[11px] px-4 py-4" style={{ border: "1px dashed var(--bm-line-2)" }}>
        <Icon name="globe" size={16} tone="inherit" className="bm-ink-3" />
        <span className="text-[12.5px] bm-ink-3">{building ? "Your addresses are assigned while the machine is built. They appear here at handover." : "No addresses assigned."}</span>
      </div>
    );
  }
  return (
    <ul className="flex flex-col">
      {view.ipv4.map((ip, i) => <li key={ip} className={"flex items-center justify-between gap-3 py-2.5 " + (i ? "border-t bm-rule" : "")}><Copy value={ip} /><span className="bm-tag bm-tag-gpu">IPv4{i === 0 ? " · primary" : ""}</span></li>)}
      {view.ipv6.map((ip) => <li key={ip} className="flex items-center justify-between gap-3 border-t py-2.5 bm-rule"><Copy value={ip} /><span className="bm-tag bm-tag-gpu">IPv6</span></li>)}
    </ul>
  );
}

function Login({ view, preview }: { view: CustomerServerView; preview: boolean }) {
  const [cred, setCred] = useState<{ username: string; secret: string } | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const live = view.statusKey === "ACTIVE";
  const reveal = () => start(async () => {
    if (preview) { setCred({ username: view.credentialsUser ?? "root", secret: "•••• preview ••••" }); return; }
    const r = await revealDedicatedCredentials(view.id);
    if (r.ok) setCred({ username: r.username, secret: r.secret }); else setErr(r.error);
  });
  return (
    <Card title="Login details">
      {view.credentialsReady ? (
        cred ? (
          <dl className="flex flex-col gap-2 text-[13px]">
            <div className="flex justify-between gap-3"><dt className="bm-ink-3">Username</dt><dd className="bm-mono bm-ink">{cred.username}</dd></div>
            <div className="flex justify-between gap-3"><dt className="bm-ink-3">Password</dt><dd className="bm-mono break-all bm-ink">{cred.secret}</dd></div>
            <p className="pt-1 text-[11.5px] bm-ink-4">Change this password after your first login.</p>
          </dl>
        ) : (
          <div className="flex flex-col items-start gap-2.5">
            <p className="text-[12.5px] bm-ink-3">Your login is ready. It is stored encrypted and shown only to you.</p>
            <button type="button" className="bm-btn bm-btn-sm" disabled={pending} onClick={reveal}><Icon name="key" size={12} tone="inherit" />Show login details</button>
          </div>
        )
      ) : live && view.credentialsUser ? (
        <div className="flex flex-col gap-2">
          <p className="text-[12.5px] bm-ink-3">Log in as <b className="bm-ink">{view.credentialsUser}</b> with the SSH key you chose. No password is set.</p>
          {view.ipv4[0] && <code className="bm-mono w-fit rounded-[8px] px-2.5 py-1.5 text-[12px] bm-ink" style={{ background: "var(--bm-card-3)" }}>ssh {view.credentialsUser}@{view.ipv4[0]}</code>}
        </div>
      ) : (
        <p className="flex items-center gap-2 text-[12.5px] bm-ink-3"><Icon name="lock" size={13} tone="inherit" />Delivered here, encrypted, as soon as your server is handed over.</p>
      )}
      {err && <p className="mt-2 text-[12px] bm-bad">{err}</p>}
    </Card>
  );
}

function PlanFacts({ view, compact = false }: { view: CustomerServerView; compact?: boolean }) {
  const rows: [string, React.ReactNode][] = [
    ...(view.planName ? [["Build", view.planName] as [string, React.ReactNode]] : []),
    ["Billing term", view.termLabel],
    ["Renews at", <b key="r" className="bm-ink">{view.renewal ?? "—"}</b>],
    ["Next renewal", <span key="d" suppressHydrationWarning>{view.renewalDate ? day(view.renewalDate) : "—"}</span>],
    ...(!compact && view.extraIpMonthlyCents > 0 ? [["Included extra IPs", `${usd(view.extraIpMonthlyCents)}/mo`] as [string, React.ReactNode]] : []),
    ...(!compact ? [["Setup fee paid", view.setupFeeCents > 0 ? usd(view.setupFeeCents) : "None"] as [string, React.ReactNode]] : []),
    ...(!compact ? [["Ordered", <span key="o" suppressHydrationWarning>{day(view.orderedAt)}</span>] as [string, React.ReactNode]] : []),
  ];
  return (
    <dl className="flex flex-col gap-2 text-[13px]">
      {rows.map(([k, v]) => <div key={k} className="flex justify-between gap-3"><dt className="bm-ink-3">{k}</dt><dd className="text-right bm-ink-2">{v}</dd></div>)}
    </dl>
  );
}

function Network({ view, c, automated, balanceCents }: { view: CustomerServerView; c: ReturnType<typeof useDedicatedControls>; automated: boolean; balanceCents: number }) {
  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)]">
      <div className="flex min-w-0 flex-col gap-4">
        <Card title="Addresses" sub="Your public IPv4 and IPv6 addresses."><IpList view={view} building={view.statusKey !== "ACTIVE"} /></Card>
        {automated && <Card title="Reverse DNS & firewall" sub="Per-address PTR records and a network firewall in front of your server."><ControlsGate c={c}><NetworkPanel c={c} /></ControlsGate></Card>}
      </div>
      <Card title="Buy more IPv4 addresses" sub="Prorated to your next renewal, then added to it.">
        {automated ? <ControlsGate c={c}><ExtraIps c={c} serverId={view.id} balanceCents={balanceCents} /></ControlsGate>
          : <p className="text-[12.5px] bm-ink-3">Extra addresses can be added once your server is online.</p>}
      </Card>
    </div>
  );
}

function Billing({ view, invoices, preview }: { view: CustomerServerView; invoices: CustomerInvoiceRow[]; preview: boolean }) {
  const cancelRequested = view.openRequests.some((r) => r.kind === "CANCEL");
  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
      <div className="flex min-w-0 flex-col gap-4">
        <Card title="Plan terms">
          <PlanFacts view={view} />
          <p className="mt-3 text-[11.5px] bm-ink-4">The renewal price is shown exactly as it is charged{view.termMonths === 12 ? " (once a year)" : ""}. We send a renewal invoice before the date above.</p>
        </Card>
        <Card title="Cancellation" sub="Stop this server from renewing.">
          {view.statusKey === "CANCELLED" ? <p className="text-[12.5px] bm-ink-3">This server has been cancelled.</p>
            : cancelRequested ? <p className="text-[12.5px] bm-ink-2">Your cancellation request is with our team. They will confirm the date service ends in your support ticket.</p>
            : <RequestForm view={view} kind="CANCEL" preview={preview} intro={`Our team confirms the date service ends${view.renewalDate ? ` (your current term is paid until ${day(view.renewalDate)})` : ""} in a support ticket. Nothing stops until they confirm with you.`} button="Request cancellation" />}
        </Card>
      </div>
      <Card title="Invoices">
        {invoices.length === 0 ? <p className="text-[12.5px] bm-ink-3">No invoices yet.</p> : (
          <ul className="flex flex-col">
            {invoices.map((inv, i) => (
              <li key={inv.id} className={"flex items-center justify-between gap-3 py-2.5 text-[13px] " + (i ? "border-t bm-rule" : "")}>
                <span className="flex min-w-0 flex-col">
                  {preview ? <span className="font-semibold bm-ink" suppressHydrationWarning>#{inv.number} · {day(inv.createdAt)}</span>
                    : <Link href={`/dashboard/invoices/${inv.id}`} className="font-semibold bm-ink hover:underline" suppressHydrationWarning>#{inv.number} · {day(inv.createdAt)}</Link>}
                  <span className="trunc text-[11.5px] bm-ink-3">{inv.description}</span>
                </span>
                <span className="flex flex-none items-center gap-2"><span className="bm-num font-bold bm-ink">{usd(inv.amountCents)}</span><span className={"bm-tag " + (inv.status === "PAID" ? "bm-tag-value" : "bm-tag-gpu")}>{inv.status.toLowerCase()}</span></span>
              </li>
            ))}
          </ul>
        )}
      </Card>
    </div>
  );
}

const REQUEST_HINT: Record<RequestKind, string> = {
  REBOOT: "A clean restart of the machine.",
  REINSTALL: "Wipes the disks and installs a fresh OS.",
  RESCUE: "Boots a recovery system to repair or copy data.",
  CANCEL: "Stops the server from renewing.",
};

function Requests({ view, kinds, preview }: { view: CustomerServerView; kinds: RequestKind[]; preview: boolean }) {
  const live = view.statusKey === "ACTIVE";
  return (
    <Card title={kinds.includes("REINSTALL") ? "Reinstall" : "Power & rescue"} sub={live ? "Our engineers carry these out. Each one opens a support ticket you can follow." : "Available once your server is online."}>
      <div className="flex flex-col gap-3">
        {kinds.map((k) => <RequestForm key={k} view={view} kind={k} preview={preview} intro={REQUEST_HINT[k]} button={REQUEST_LABEL[k]} disabled={!live} />)}
      </div>
    </Card>
  );
}

function RequestForm({ view, kind, preview, intro, button, disabled = false }: { view: CustomerServerView; kind: RequestKind; preview: boolean; intro: string; button: string; disabled?: boolean }) {
  const [open, setOpen] = useState(false);
  const [note, setNote] = useState("");
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const requested = view.openRequests.some((r) => r.kind === kind);
  const send = () => start(async () => {
    if (preview) { setMsg(`Preview: a "${REQUEST_LABEL[kind]}" request would open a support ticket. Nothing was sent.`); setOpen(false); return; }
    const r = await requestDedicatedAction(view.id, kind, note);
    setMsg(r.ok ? "Request sent. Our team has it as a support ticket and will update you there." : r.error);
    if (r.ok) { setOpen(false); setNote(""); }
  });
  return (
    <div className="bm-sub flex flex-col gap-2.5 p-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <span className="flex min-w-0 flex-col">
          <span className="text-[13.5px] font-extrabold bm-ink">{requested ? `${REQUEST_LABEL[kind]} · requested` : REQUEST_LABEL[kind]}</span>
          <span className="text-[12px] bm-ink-3">{intro}</span>
        </span>
        {!open && <button type="button" disabled={disabled || requested || pending} onClick={() => setOpen(true)} className="bm-btn-ghost">{button}</button>}
      </div>
      {open && (
        <div className="flex flex-col gap-2">
          <label className="text-[12px] font-bold bm-ink" htmlFor={`req-${kind}`}>Anything we should know?</label>
          <textarea id={`req-${kind}`} value={note} onChange={(e) => setNote(e.target.value)} rows={3} maxLength={2000} placeholder={kind === "REINSTALL" ? "e.g. Ubuntu 24.04, keep the same hostname" : "Optional"} className="bm-field h-auto py-2" />
          {kind === "REINSTALL" && <p className="text-[11.5px] bm-warn">A reinstall erases everything on the disks.</p>}
          <div className="flex gap-2">
            <button type="button" className="bm-btn bm-btn-sm" disabled={pending} onClick={send}>Send request</button>
            <button type="button" className="bm-btn-ghost" onClick={() => setOpen(false)}>Cancel</button>
          </div>
        </div>
      )}
      {msg && <p className="text-[12px] bm-ink-2" role="status">{msg}</p>}
    </div>
  );
}

function Support({ view, preview }: { view: CustomerServerView; preview: boolean }) {
  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <HelpCard preview={preview} big />
      <Card title="Open requests">
        {view.openRequests.length === 0 ? <p className="text-[12.5px] bm-ink-3">No open requests for this server.</p> : (
          <ul className="flex flex-col gap-2">
            {view.openRequests.map((r) => <li key={r.id} className="bm-sub px-3.5 py-2.5 text-[12.5px] bm-ink-2" suppressHydrationWarning><b className="bm-ink">{REQUEST_LABEL[r.kind as RequestKind] ?? r.kind}</b> · requested {day(r.createdAt)} · with our team</li>)}
          </ul>
        )}
        <p className="mt-3 text-[11.5px] bm-ink-4">Need the out-of-band console? Our engineers open it for you from a ticket.</p>
      </Card>
    </div>
  );
}

function HelpCard({ preview, big = false }: { preview: boolean; big?: boolean }) {
  return (
    <section className={"bm-card flex items-center gap-4 " + (big ? "p-6" : "p-5")}>
      <span className="grid h-11 w-11 flex-none place-items-center rounded-[13px] bm-sub"><Icon name="lifebuoy" size={18} tone="inherit" className="bm-accent" /></span>
      <div className="min-w-0 flex-1">
        <div className="text-[14px] font-extrabold bm-ink">Need a hand with this server?</div>
        <div className="text-[12px] bm-ink-3">The same support team that runs the rest of your Nxeon services.</div>
      </div>
      <Link href={preview ? "#" : "/dashboard/support"} className="bm-btn-ghost flex-none">Open a ticket</Link>
    </section>
  );
}

input.content:
"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): one bare-metal server's dashboard.
 *
 * Same shape as the VPS and game panels (components/customer/vpspanel/v2/
 * VpsPanelShell): a pinned identity hero, a tab rail synced to `?tab=`, one tab
 * at a time. Tabs: Overview · Power & rescue · Reinstall · Network & IPs ·
 * Plan & billing · Support. Takes only the brand-safe CustomerServerView
 * (lib/dedicated/customer-view.ts).
 *
 * Automated controls (reboot, rescue, reinstall, rDNS, firewall, extra IPs)
 * ENQUEUE jobs the worker runs — in dry run unless an admin switches it off.
 * A server without automation (or not online yet) falls back to REQUESTS that
 * open a support ticket. In `preview` (admin preview) nothing is sent.
 */
import { useEffect, useState, useTransition } from "react";
import Link from "next/link";
import type { CustomerInvoiceRow, CustomerServerView, RequestKind } from "@/lib/dedicated/customer-view";
import { REQUEST_LABEL } from "@/lib/dedicated/customer-view";
import { serverTimeline, SETUP_ETA } from "@/lib/dedicated/order-core";
import { requestDedicatedAction, revealDedicatedCredentials } from "@/lib/actions-dedicated-customer";
import type { DedicatedPanel } from "@/lib/actions-dedicated-ops";
import { cpuBrandOf } from "@/lib/dedicated/brand";
import { Icon } from "@/components/nx/Icon";
import { BrandLogo } from "./BrandLogo";
import { Flag, usd } from "./ui";
import {
  ControlsGate, ControlsMessage, ExtraIps, LiveStatus, ModeBadge, NetworkPanel, PowerRescue, RecentActions, ReinstallPanel, useDedicatedControls,
  type Controls,
} from "./DedicatedControlPanel";

const day = (iso: string) => new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });

type TabKey = "overview" | "power" | "reinstall" | "network" | "billing" | "support";
const TABS: { key: TabKey; label: string; icon: string }[] = [
  { key: "overview", label: "Overview", icon: "donut" },
  { key: "power", label: "Power & rescue", icon: "bolt" },
  { key: "reinstall", label: "Reinstall", icon: "terminal" },
  { key: "network", label: "Network & IPs", icon: "nodes" },
  { key: "billing", label: "Plan & billing", icon: "card" },
  { key: "support", label: "Support", icon: "lifebuoy" },
];
const resolveTab = (raw: string | null | undefined): TabKey => (TABS.some((t) => t.key === raw) ? (raw as TabKey) : "overview");

const STATUS_TONE: Record<string, { color: string; bg: string; live: boolean }> = {
  ACTIVE: { color: "var(--bm-ok)", bg: "var(--bm-ok-soft)", live: true },
  PENDING: { color: "var(--bm-accent-ink)", bg: "var(--bm-accent-soft)", live: true },
  PROVISIONING: { color: "var(--bm-accent-ink)", bg: "var(--bm-accent-soft)", live: true },
  SUSPENDED: { color: "var(--bm-warn)", bg: "var(--bm-warn-soft)", live: false },
  CANCELLED: { color: "var(--bm-ink-3)", bg: "var(--bm-card-3)", live: false },
};

function Card({ title, sub, action, children, className = "" }: { title: string; sub?: string; action?: React.ReactNode; children: React.ReactNode; className?: string }) {
  return (
    <section className={"bm-card flex min-w-0 flex-col " + className}>
      <div className="flex items-start gap-3 border-b px-5 py-3.5 bm-rule">
        <span className="flex min-w-0 flex-col">
          <h3 className="text-[14.5px] font-extrabold bm-ink">{title}</h3>
          {sub && <span className="text-[12px] bm-ink-3">{sub}</span>}
        </span>
        {action && <span className="ml-auto flex-none">{action}</span>}
      </div>
      <div className="min-w-0 flex-1 p-5">{children}</div>
    </section>
  );
}

function Copy({ value, label }: { value: string; label?: string }) {
  const [done, setDone] = useState(false);
  return (
    <button type="button" title="Copy" onClick={() => { void navigator.clipboard?.writeText(value); setDone(true); setTimeout(() => setDone(false), 1200); }}
            className="inline-flex min-w-0 items-center gap-2 rounded-[9px] px-2.5 py-1.5 text-left" style={{ background: "color-mix(in srgb, var(--bm-ink) 5%, transparent)", border: "1px solid var(--bm-line)" }}>
      {label && <span className="text-[10px] font-bold uppercase tracking-[0.1em] bm-ink-3">{label}</span>}
      <span className="bm-mono trunc text-[13px] font-semibold bm-ink">{value}</span>
      <span className="flex-none text-[10.5px] font-semibold bm-ink-3">{done ? "Copied" : <Icon name="copy" size={11} tone="inherit" />}</span>
    </button>
  );
}

export function DedicatedServerDashboard({ view, invoices, preview = false, justOrdered = false, panel = null, balanceCents = 0, initialTab }: {
  view: CustomerServerView; invoices: CustomerInvoiceRow[]; preview?: boolean; justOrdered?: boolean;
  /** Live controls when already loaded; null = load after paint (or none). */
  panel?: DedicatedPanel | null;
  balanceCents?: number;
  initialTab?: string;
}) {
  const live = view.statusKey === "ACTIVE";
  const building = view.statusKey === "PENDING" || view.statusKey === "PROVISIONING";
  const automated = live && view.automated && !preview;
  const c = useDedicatedControls(view.id, panel, automated);
  const [tab, setTab] = useState<TabKey>(() => resolveTab(initialTab));
  useEffect(() => {
    const onPop = () => setTab(resolveTab(new URLSearchParams(window.location.search).get("tab")));
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);
  const go = (t: TabKey) => {
    setTab(t);
    if (preview) return;
    const url = new URL(window.location.href);
    url.searchParams.set("tab", t);
    url.searchParams.delete("ordered");
    window.history.pushState(null, "", url);
  };
  const tone = STATUS_TONE[view.statusKey] ?? STATUS_TONE.PENDING;
  const storageMain = view.storage.split("(")[0].trim() || "—";
  const net = /\d+(?:\.\d+)?\s?[GM]bps/i.exec(view.bandwidth)?.[0].replace(/(\d)([GM])/i, "$1 $2") ?? (view.bandwidth || "—");

  return (
    <div className="bm mx-auto flex w-full max-w-[1480px] flex-col gap-4">
      {/* identity hero (always dark, like the VPS/game heroes) + tab rail, pinned on desktop */}
      <div className="z-20 -mx-1 flex flex-col gap-2 px-1 pb-2 pt-1 lg:sticky lg:top-0" style={{ background: "color-mix(in srgb, var(--color-bg) 82%, transparent)", backdropFilter: "blur(18px)" }}>
        <header className="bm-hero bm-island">
          <span className="bm-hero-grid" aria-hidden />
          <div className="relative z-[1] flex flex-wrap items-start justify-between gap-x-6 gap-y-4 px-5 py-4">
            <div className="flex min-w-0 flex-1 items-start gap-4">
              <span className="grid h-[58px] w-[58px] flex-none place-items-center rounded-[16px]" style={{ background: "linear-gradient(140deg,rgba(139,108,255,.35),rgba(79,125,255,.2))", border: "1px solid rgba(255,255,255,0.12)" }}>
                <Icon name="bmrack" size={24} tone="inherit" className="text-[#fff]" />
              </span>
              <div className="min-w-0 flex-1">
                <Link href={preview ? "#" : "/dashboard/services"} className="text-[11.5px] font-semibold bm-ink-3 hover:underline">← My Services</Link>
                <div className="mt-0.5 flex flex-wrap items-center gap-2.5">
                  <h1 className="truncate text-[24px] font-extrabold leading-[1.05] tracking-[-0.03em] sm:text-[28px]" style={{ color: "var(--bm-ink)" }}>{view.label}</h1>
                  <span className="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11.5px] font-bold" style={{ color: tone.color, background: tone.bg }}>
                    <span className="h-1.5 w-1.5 rounded-full" style={{ background: tone.color, boxShadow: tone.live ? `0 0 8px ${tone.color}` : undefined }} />{view.status}
                  </span>
                  {view.planName && <span className="bm-tag bm-tag-recommended">{view.planName}</span>}
                  {c.panel && <ModeBadge c={c} />}
                </div>
                <div className="mt-2.5 flex flex-wrap items-center gap-x-4 gap-y-2">
                  {view.ipv4[0] && <Copy label="IP" value={view.ipv4[0]} />}
                  {view.os && <span className="flex items-center gap-2 text-[12.5px] font-semibold bm-ink-2"><Icon name="terminal" size={13} tone="inherit" />{view.os}</span>}
                  <span className="flex items-center gap-2 text-[12.5px] font-semibold bm-ink-2"><Flag country={view.regionCountry} width={18} />{view.region}</span>
                  {view.hostname && <span className="bm-mono text-[12px] bm-ink-3">{view.hostname}</span>}
                </div>
                <div className="mt-3 flex flex-wrap items-center gap-x-6 gap-y-2">
                  <HeroSpec icon={<BrandLogo brand={cpuBrandOf(view.cpu)} h={11} />} value={`${view.cores} cores`} label={view.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1")} />
                  <HeroSpec icon={<Icon name="ram" size={14} tone="inherit" />} value={`${view.ramGb} GB`} label="Memory" />
                  <HeroSpec icon={<Icon name="database" size={14} tone="inherit" />} value={storageMain} label="Storage" />
                  <HeroSpec icon={<Icon name="nodes" size={14} tone="inherit" />} value={net} label="Network" />
                </div>
              </div>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              {automated && <button type="button" onClick={() => go("power")} className="bm-btn-ghost" style={{ background: "rgba(255,255,255,0.06)", color: "var(--bm-ink)" }}><Icon name="refresh" size={12} tone="inherit" />Reboot or rescue</button>}
              <Link href={preview ? "#" : "/dashboard/support"} className="bm-btn bm-btn-sm"><Icon name="lifebuoy" size={12} tone="inherit" />Get help</Link>
            </div>
          </div>
        </header>
        <nav className="bm-card noscroll flex gap-1 overflow-x-auto rounded-[14px] p-1.5" aria-label="Server sections">
          {TABS.map((t) => {
            const on = tab === t.key;
            return (
              <button key={t.key} type="button" onClick={() => go(t.key)} aria-current={on ? "page" : undefined}
                      className="inline-flex flex-none items-center gap-2 whitespace-nowrap rounded-[10px] px-3.5 py-2 text-[13px] font-bold transition"
                      style={on ? { background: "var(--bm-accent-soft)", color: "var(--bm-ink)", boxShadow: "0 0 0 1px var(--bm-accent) inset" } : { color: "var(--bm-ink-3)" }}>
                <Icon name={t.icon} size={13} tone="inherit" />{t.label}
              </button>
            );
          })}
        </nav>
      </div>

      {justOrdered && (
        <section className="flex items-start gap-3 rounded-[14px] p-4" role="status" style={{ background: "var(--bm-ok-soft)", border: "1px solid color-mix(in srgb, var(--bm-ok) 35%, transparent)" }}>
          <Icon name="checkcircle" size={18} tone="inherit" className="bm-ok" />
          <div>
            <div className="text-[14px] font-extrabold bm-ink">Order confirmed. Thank you.</div>
            <div className="text-[12.5px] bm-ink-2">Our team is building your server now. It will be {SETUP_ETA.toLowerCase()}; we&apos;ll notify you and post its IP addresses and login right here.</div>
          </div>
        </section>
      )}
      {view.statusKey === "SUSPENDED" && (
        <p className="rounded-[12px] px-4 py-3 text-[12.5px]" style={{ background: "var(--bm-warn-soft)", color: "var(--bm-warn)" }}>
          This server is suspended{view.suspendReason ? `: ${view.suspendReason}` : "."} <Link href={preview ? "#" : "/dashboard/support"} className="font-bold underline">Contact support</Link> to restore it.
        </p>
      )}
      <ControlsMessage c={c} />

      <div className="bm-enter min-w-0" key={tab}>
        {tab === "overview" && <Overview view={view} invoices={invoices} c={c} automated={automated} building={building} preview={preview} go={go} />}
        {tab === "power" && (
          automated ? <Card title="Power & rescue" sub="Carried out automatically, usually within a minute or two."><ControlsGate c={c}><PowerRescue c={c} serverId={view.id} primaryIp={view.ipv4[0] ?? null} /></ControlsGate></Card>
            : <Requests view={view} kinds={["REBOOT", "RESCUE"]} preview={preview} />
        )}
        {tab === "reinstall" && (
          automated ? <Card title="Reinstall" sub="A fresh operating system, installed automatically."><ControlsGate c={c}><ReinstallPanel c={c} label={view.label} /></ControlsGate></Card>
            : <Requests view={view} kinds={["REINSTALL"]} preview={preview} />
        )}
        {tab === "network" && <Network view={view} c={c} automated={automated} balanceCents={balanceCents} />}
        {tab === "billing" && <Billing view={view} invoices={invoices} preview={preview} />}
        {tab === "support" && <Support view={view} preview={preview} />}
      </div>
    </div>
  );
}

function HeroSpec({ icon, value, label }: { icon: React.ReactNode; value: string; label: string }) {
  return (
    <span className="flex items-center gap-2">
      <span className="grid w-5 flex-none place-items-center bm-ink-3">{icon}</span>
      <span className="flex min-w-0 flex-col leading-tight">
        <span className="bm-num text-[13px] font-bold" style={{ color: "var(--bm-ink)" }}>{value}</span>
        <span className="max-w-[220px] truncate text-[10px] font-bold uppercase tracking-[0.1em] bm-ink-3">{label}</span>
      </span>
    </span>
  );
}

/* ---------------- tabs ---------------- */

function Overview({ view, invoices, c, automated, building, preview, go }: {
  view: CustomerServerView; invoices: CustomerInvoiceRow[]; c: Controls; automated: boolean; building: boolean; preview: boolean; go: (t: TabKey) => void;
}) {
  const timeline = serverTimeline({ statusKey: view.statusKey, orderedAt: view.orderedAt, provisionedAt: view.provisionedAt });
  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)]">
      <div className="flex min-w-0 flex-col gap-4">
        {view.statusKey !== "CANCELLED" && (building || !automated) && (
          <Card title="Status" sub={building ? `${SETUP_ETA} of your order` : view.provisionedAt ? `Online since ${day(view.provisionedAt)}` : undefined}>
            <ol className="grid gap-4 sm:grid-cols-3">
              {timeline.map((t, i) => (
                <li key={t.key} className="flex items-start gap-3">
                  <span className="grid h-7 w-7 flex-none place-items-center rounded-full text-[12px] font-extrabold"
                        style={t.state === "done" ? { background: "var(--bm-ok-soft)", color: "var(--bm-ok)" } : t.state === "current" ? { background: "var(--bm-grad)", color: "#fff" } : { border: "1px solid var(--bm-line-2)", color: "var(--bm-ink-4)" }}>
                    {t.state === "done" ? <Icon name="check" size={11} tone="inherit" /> : i + 1}
                  </span>
                  <span className="min-w-0">
                    <span className={"block text-[13px] font-bold " + (t.state === "todo" ? "bm-ink-4" : "bm-ink")}>{t.label}{t.state === "current" && <span className="ml-1.5 text-[11px] font-semibold bm-accent motion-safe:animate-pulse">in progress</span>}</span>
                    <span className="block text-[11.5px] bm-ink-3" suppressHydrationWarning>{t.at ? `${day(t.at)} · ` : ""}{t.note}</span>
                  </span>
                </li>
              ))}
            </ol>
          </Card>
        )}
        {automated && <Card title="Live status" action={<button type="button" onClick={() => void c.refresh(true)} className="bm-btn-ghost"><Icon name="refresh" size={11} tone="inherit" />Refresh</button>}><LiveStatus c={c} /></Card>}
        <section aria-label="Hardware" className="grid grid-cols-2 gap-3 xl:grid-cols-4">
          <SpecTile k="Processor" v={`${view.cores} cores`} sub={`${view.threads} threads · ${view.cpu}`} icon={<BrandLogo brand={cpuBrandOf(view.cpu)} h={11} />} />
          <SpecTile k="Memory" v={`${view.ramGb} GB`} sub="Dedicated to you" icon={<Icon name="ram" size={14} tone="inherit" />} />
          <SpecTile k="Storage" v={view.storage.split("(")[0].trim() || "—"} sub={view.storage.match(/\(([^)]+)\)/)?.[1] ?? "Your own disks"} icon={<Icon name="database" size={14} tone="inherit" />} />
          <SpecTile k="Network" v={view.bandwidth || "—"} sub="DDoS protection included" icon={<Icon name="nodes" size={14} tone="inherit" />} />
        </section>
        <Card title="IP addresses" action={view.ipv4.length > 0 ? <button type="button" onClick={() => go("network")} className="bm-btn-ghost">Manage</button> : undefined}>
          <IpList view={view} building={building} />
        </Card>
        {automated && <Card title="Recent actions"><RecentActions jobs={c.jobs} /></Card>}
      </div>
      <div className="flex min-w-0 flex-col gap-4">
        <Login view={view} preview={preview} />
        <Card title="Your plan" action={<button type="button" onClick={() => go("billing")} className="bm-btn-ghost">Details</button>}>
          <PlanFacts view={view} compact />
          {invoices[0] && <p className="mt-3 text-[11.5px] bm-ink-3" suppressHydrationWarning>Last invoice #{invoices[0].number} · {usd(invoices[0].amountCents)} · {day(invoices[0].createdAt)}</p>}
        </Card>
        <HelpCard preview={preview} />
      </div>
    </div>
  );
}

function SpecTile({ k, v, sub, icon }: { k: string; v: string; sub: string; icon: React.ReactNode }) {
  return (
    <div className="bm-card flex min-w-0 flex-col gap-1 p-4">
      <span className="flex items-center gap-2 bm-ink-3"><span className="grid w-5 place-items-center">{icon}</span><span className="bm-label">{k}</span></span>
      <span className="trunc text-[16px] font-extrabold bm-ink">{v}</span>
      <span className="trunc text-[11.5px] bm-ink-3" title={sub}>{sub}</span>
    </div>
  );
}

function IpList({ view, building }: { view: CustomerServerView; building: boolean }) {
  if (view.ipv4.length + view.ipv6.length === 0) {
    return (
      <div className="flex items-center gap-3 rounded-[11px] px-4 py-4" style={{ border: "1px dashed var(--bm-line-2)" }}>
        <Icon name="globe" size={16} tone="inherit" className="bm-ink-3" />
        <span className="text-[12.5px] bm-ink-3">{building ? "Your addresses are assigned while the machine is built. They appear here at handover." : "No addresses assigned."}</span>
      </div>
    );
  }
  return (
    <ul className="flex flex-col">
      {view.ipv4.map((ip, i) => <li key={ip} className={"flex items-center justify-between gap-3 py-2.5 " + (i ? "border-t bm-rule" : "")}><Copy value={ip} /><span className="bm-tag bm-tag-gpu">IPv4{i === 0 ? " · primary" : ""}</span></li>)}
      {view.ipv6.map((ip) => <li key={ip} className="flex items-center justify-between gap-3 border-t py-2.5 bm-rule"><Copy value={ip} /><span className="bm-tag bm-tag-gpu">IPv6</span></li>)}
    </ul>
  );
}

function Login({ view, preview }: { view: CustomerServerView; preview: boolean }) {
  const [cred, setCred] = useState<{ username: string; secret: string } | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const live = view.statusKey === "ACTIVE";
  const reveal = () => start(async () => {
    if (preview) { setCred({ username: view.credentialsUser ?? "root", secret: "•••• preview ••••" }); return; }
    const r = await revealDedicatedCredentials(view.id);
    if (r.ok) setCred({ username: r.username, secret: r.secret }); else setErr(r.error);
  });
  return (
    <Card title="Login details">
      {view.credentialsReady ? (
        cred ? (
          <dl className="flex flex-col gap-2 text-[13px]">
            <div className="flex justify-between gap-3"><dt className="bm-ink-3">Username</dt><dd className="bm-mono bm-ink">{cred.username}</dd></div>
            <div className="flex justify-between gap-3"><dt className="bm-ink-3">Password</dt><dd className="bm-mono break-all bm-ink">{cred.secret}</dd></div>
            <p className="pt-1 text-[11.5px] bm-ink-4">Change this password after your first login.</p>
          </dl>
        ) : (
          <div className="flex flex-col items-start gap-2.5">
            <p className="text-[12.5px] bm-ink-3">Your login is ready. It is stored encrypted and shown only to you.</p>
            <button type="button" className="bm-btn bm-btn-sm" disabled={pending} onClick={reveal}><Icon name="key" size={12} tone="inherit" />Show login details</button>
          </div>
        )
      ) : live && view.credentialsUser ? (
        <div className="flex flex-col gap-2">
          <p className="text-[12.5px] bm-ink-3">Log in as <b className="bm-ink">{view.credentialsUser}</b> with the SSH key you chose. No password is set.</p>
          {view.ipv4[0] && <code className="bm-mono w-fit rounded-[8px] px-2.5 py-1.5 text-[12px] bm-ink" style={{ background: "var(--bm-card-3)" }}>ssh {view.credentialsUser}@{view.ipv4[0]}</code>}
        </div>
      ) : (
        <p className="flex items-center gap-2 text-[12.5px] bm-ink-3"><Icon name="lock" size={13} tone="inherit" />Delivered here, encrypted, as soon as your server is handed over.</p>
      )}
      {err && <p className="mt-2 text-[12px] bm-bad">{err}</p>}
    </Card>
  );
}

function PlanFacts({ view, compact = false }: { view: CustomerServerView; compact?: boolean }) {
  const rows: [string, React.ReactNode][] = [
    ...(view.planName ? [["Build", view.planName] as [string, React.ReactNode]] : []),
    ["Billing term", view.termLabel],
    ["Renews at", <b key="r" className="bm-ink">{view.renewal ?? "—"}</b>],
    ["Next renewal", <span key="d" suppressHydrationWarning>{view.renewalDate ? day(view.renewalDate) : "—"}</span>],
    ...(!compact && view.extraIpMonthlyCents > 0 ? [["Included extra IPs", `${usd(view.extraIpMonthlyCents)}/mo`] as [string, React.ReactNode]] : []),
    ...(!compact ? [["Setup fee paid", view.setupFeeCents > 0 ? usd(view.setupFeeCents) : "None"] as [string, React.ReactNode]] : []),
    ...(!compact ? [["Ordered", <span key="o" suppressHydrationWarning>{day(view.orderedAt)}</span>] as [string, React.ReactNode]] : []),
  ];
  return (
    <dl className="flex flex-col gap-2 text-[13px]">
      {rows.map(([k, v]) => <div key={k} className="flex justify-between gap-3"><dt className="bm-ink-3">{k}</dt><dd className="text-right bm-ink-2">{v}</dd></div>)}
    </dl>
  );
}

function Network({ view, c, automated, balanceCents }: { view: CustomerServerView; c: Controls; automated: boolean; balanceCents: number }) {
  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)]">
      <div className="flex min-w-0 flex-col gap-4">
        <Card title="Addresses" sub="Your public IPv4 and IPv6 addresses."><IpList view={view} building={view.statusKey !== "ACTIVE"} /></Card>
        {automated && <Card title="Reverse DNS & firewall" sub="Per-address PTR records and a network firewall in front of your server."><ControlsGate c={c}><NetworkPanel c={c} /></ControlsGate></Card>}
      </div>
      <Card title="Buy more IPv4 addresses" sub="Prorated to your next renewal, then added to it.">
        {automated ? <ControlsGate c={c}><ExtraIps c={c} serverId={view.id} balanceCents={balanceCents} /></ControlsGate>
          : <p className="text-[12.5px] bm-ink-3">Extra addresses can be added once your server is online.</p>}
      </Card>
    </div>
  );
}

function Billing({ view, invoices, preview }: { view: CustomerServerView; invoices: CustomerInvoiceRow[]; preview: boolean }) {
  const cancelRequested = view.openRequests.some((r) => r.kind === "CANCEL");
  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
      <div className="flex min-w-0 flex-col gap-4">
        <Card title="Plan terms">
          <PlanFacts view={view} />
          <p className="mt-3 text-[11.5px] bm-ink-4">The renewal price is shown exactly as it is charged{view.termMonths === 12 ? " (once a year)" : ""}. We send a renewal invoice before the date above.</p>
        </Card>
        <Card title="Cancellation" sub="Stop this server from renewing.">
          {view.statusKey === "CANCELLED" ? <p className="text-[12.5px] bm-ink-3">This server has been cancelled.</p>
            : cancelRequested ? <p className="text-[12.5px] bm-ink-2">Your cancellation request is with our team. They will confirm the date service ends in your support ticket.</p>
            : <RequestForm view={view} kind="CANCEL" preview={preview} intro={`Our team confirms the date service ends${view.renewalDate ? ` (your current term is paid until ${day(view.renewalDate)})` : ""} in a support ticket. Nothing stops until they confirm with you.`} button="Request cancellation" />}
        </Card>
      </div>
      <Card title="Invoices">
        {invoices.length === 0 ? <p className="text-[12.5px] bm-ink-3">No invoices yet.</p> : (
          <ul className="flex flex-col">
            {invoices.map((inv, i) => (
              <li key={inv.id} className={"flex items-center justify-between gap-3 py-2.5 text-[13px] " + (i ? "border-t bm-rule" : "")}>
                <span className="flex min-w-0 flex-col">
                  {preview ? <span className="font-semibold bm-ink" suppressHydrationWarning>#{inv.number} · {day(inv.createdAt)}</span>
                    : <Link href={`/dashboard/invoices/${inv.id}`} className="font-semibold bm-ink hover:underline" suppressHydrationWarning>#{inv.number} · {day(inv.createdAt)}</Link>}
                  <span className="trunc text-[11.5px] bm-ink-3">{inv.description}</span>
                </span>
                <span className="flex flex-none items-center gap-2"><span className="bm-num font-bold bm-ink">{usd(inv.amountCents)}</span><span className={"bm-tag " + (inv.status === "PAID" ? "bm-tag-value" : "bm-tag-gpu")}>{inv.status.toLowerCase()}</span></span>
              </li>
            ))}
          </ul>
        )}
      </Card>
    </div>
  );
}

const REQUEST_HINT: Record<RequestKind, string> = {
  REBOOT: "A clean restart of the machine.",
  REINSTALL: "Wipes the disks and installs a fresh OS.",
  RESCUE: "Boots a recovery system to repair or copy data.",
  CANCEL: "Stops the server from renewing.",
};

function Requests({ view, kinds, preview }: { view: CustomerServerView; kinds: RequestKind[]; preview: boolean }) {
  const live = view.statusKey === "ACTIVE";
  return (
    <Card title={kinds.includes("REINSTALL") ? "Reinstall" : "Power & rescue"} sub={live ? "Our engineers carry these out. Each one opens a support ticket you can follow." : "Available once your server is online."}>
      <div className="flex flex-col gap-3">
        {kinds.map((k) => <RequestForm key={k} view={view} kind={k} preview={preview} intro={REQUEST_HINT[k]} button={REQUEST_LABEL[k]} disabled={!live} />)}
      </div>
    </Card>
  );
}

function RequestForm({ view, kind, preview, intro, button, disabled = false }: { view: CustomerServerView; kind: RequestKind; preview: boolean; intro: string; button: string; disabled?: boolean }) {
  const [open, setOpen] = useState(false);
  const [note, setNote] = useState("");
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const requested = view.openRequests.some((r) => r.kind === kind);
  const send = () => start(async () => {
    if (preview) { setMsg(`Preview: a "${REQUEST_LABEL[kind]}" request would open a support ticket. Nothing was sent.`); setOpen(false); return; }
    const r = await requestDedicatedAction(view.id, kind, note);
    setMsg(r.ok ? "Request sent. Our team has it as a support ticket and will update you there." : r.error);
    if (r.ok) { setOpen(false); setNote(""); }
  });
  return (
    <div className="bm-sub flex flex-col gap-2.5 p-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <span className="flex min-w-0 flex-col">
          <span className="text-[13.5px] font-extrabold bm-ink">{requested ? `${REQUEST_LABEL[kind]} · requested` : REQUEST_LABEL[kind]}</span>
          <span className="text-[12px] bm-ink-3">{intro}</span>
        </span>
        {!open && <button type="button" disabled={disabled || requested || pending} onClick={() => setOpen(true)} className="bm-btn-ghost">{button}</button>}
      </div>
      {open && (
        <div className="flex flex-col gap-2">
          <label className="text-[12px] font-bold bm-ink" htmlFor={`req-${kind}`}>Anything we should know?</label>
          <textarea id={`req-${kind}`} value={note} onChange={(e) => setNote(e.target.value)} rows={3} maxLength={2000} placeholder={kind === "REINSTALL" ? "e.g. Ubuntu 24.04, keep the same hostname" : "Optional"} className="bm-field h-auto py-2" />
          {kind === "REINSTALL" && <p className="text-[11.5px] bm-warn">A reinstall erases everything on the disks.</p>}
          <div className="flex gap-2">
            <button type="button" className="bm-btn bm-btn-sm" disabled={pending} onClick={send}>Send request</button>
            <button type="button" className="bm-btn-ghost" onClick={() => setOpen(false)}>Cancel</button>
          </div>
        </div>
      )}
      {msg && <p className="text-[12px] bm-ink-2" role="status">{msg}</p>}
    </div>
  );
}

function Support({ view, preview }: { view: CustomerServerView; preview: boolean }) {
  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <HelpCard preview={preview} big />
      <Card title="Open requests">
        {view.openRequests.length === 0 ? <p className="text-[12.5px] bm-ink-3">No open requests for this server.</p> : (
          <ul className="flex flex-col gap-2">
            {view.openRequests.map((r) => <li key={r.id} className="bm-sub px-3.5 py-2.5 text-[12.5px] bm-ink-2" suppressHydrationWarning><b className="bm-ink">{REQUEST_LABEL[r.kind as RequestKind] ?? r.kind}</b> · requested {day(r.createdAt)} · with our team</li>)}
          </ul>
        )}
        <p className="mt-3 text-[11.5px] bm-ink-4">Need the out-of-band console? Our engineers open it for you from a ticket.</p>
      </Card>
    </div>
  );
}

function HelpCard({ preview, big = false }: { preview: boolean; big?: boolean }) {
  return (
    <section className={"bm-card flex items-center gap-4 " + (big ? "p-6" : "p-5")}>
      <span className="bm-sub grid h-11 w-11 flex-none place-items-center rounded-[13px]"><Icon name="lifebuoy" size={18} tone="inherit" className="bm-accent" /></span>
      <div className="min-w-0 flex-1">
        <div className="text-[14px] font-extrabold bm-ink">Need a hand with this server?</div>
        <div className="text-[12px] bm-ink-3">The same support team that runs the rest of your Nxeon services.</div>
      </div>
      <Link href={preview ? "#" : "/dashboard/support"} className="bm-btn-ghost flex-none">Open a ticket</Link>
    </section>
  );
}

toolu_01UFxkjWRXCc8w1vhFxJX6GG.content:
"use client";

/**
 * CUSTOMER-FACING (brand-voice checked): one bare-metal server's dashboard.
 *
 * Same shape as the VPS and game panels (components/customer/vpspanel/v2/
 * VpsPanelShell): a pinned identity hero, a tab rail synced to `?tab=`, one tab
 * at a time. Tabs: Overview · Power & rescue · Reinstall · Network & IPs ·
 * Plan & billing · Support. Takes only the brand-safe CustomerServerView
 * (lib/dedicated/customer-view.ts).
 *
 * Automated controls (reboot, rescue, reinstall, rDNS, firewall, extra IPs)
 * ENQUEUE jobs the worker runs — in dry run unless an admin switches it off.
 * A server without automation (or not online yet) falls back to REQUESTS that
 * open a support ticket. In `preview` (admin preview) nothing is sent.
 */
import { useEffect, useState, useTransition } from "react";
import Link from "next/link";
import type { CustomerInvoiceRow, CustomerServerView, RequestKind } from "@/lib/dedicated/customer-view";
import { REQUEST_LABEL } from "@/lib/dedicated/customer-view";
import { serverTimeline, SETUP_ETA } from "@/lib/dedicated/order-core";
import { requestDedicatedAction, revealDedicatedCredentials } from "@/lib/actions-dedicated-customer";
import type { DedicatedPanel } from "@/lib/actions-dedicated-ops";
import { cpuBrandOf } from "@/lib/dedicated/brand";
import { Icon } from "@/components/nx/Icon";
import { BrandLogo } from "./BrandLogo";
import { Flag, usd } from "./ui";
import {
  ControlsGate, ControlsMessage, ExtraIps, LiveStatus, ModeBadge, NetworkPanel, PowerRescue, RecentActions, ReinstallPanel, useDedicatedControls,
  type Controls,
} from "./DedicatedControlPanel";

const day = (iso: string) => new Date(iso).toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });

type TabKey = "overview" | "power" | "reinstall" | "network" | "billing" | "support";
const TABS: { key: TabKey; label: string; icon: string }[] = [
  { key: "overview", label: "Overview", icon: "donut" },
  { key: "power", label: "Power & rescue", icon: "bolt" },
  { key: "reinstall", label: "Reinstall", icon: "terminal" },
  { key: "network", label: "Network & IPs", icon: "nodes" },
  { key: "billing", label: "Plan & billing", icon: "card" },
  { key: "support", label: "Support", icon: "lifebuoy" },
];
const resolveTab = (raw: string | null | undefined): TabKey => (TABS.some((t) => t.key === raw) ? (raw as TabKey) : "overview");

const STATUS_TONE: Record<string, { color: string; bg: string; live: boolean }> = {
  ACTIVE: { color: "var(--bm-ok)", bg: "var(--bm-ok-soft)", live: true },
  PENDING: { color: "var(--bm-accent-ink)", bg: "var(--bm-accent-soft)", live: true },
  PROVISIONING: { color: "var(--bm-accent-ink)", bg: "var(--bm-accent-soft)", live: true },
  SUSPENDED: { color: "var(--bm-warn)", bg: "var(--bm-warn-soft)", live: false },
  CANCELLED: { color: "var(--bm-ink-3)", bg: "var(--bm-card-3)", live: false },
};

function Card({ title, sub, action, children, className = "" }: { title: string; sub?: string; action?: React.ReactNode; children: React.ReactNode; className?: string }) {
  return (
    <section className={"bm-card flex min-w-0 flex-col " + className}>
      <div className="flex items-start gap-3 border-b px-5 py-3.5 bm-rule">
        <span className="flex min-w-0 flex-col">
          <h3 className="text-[14.5px] font-extrabold bm-ink">{title}</h3>
          {sub && <span className="text-[12px] bm-ink-3">{sub}</span>}
        </span>
        {action && <span className="ml-auto flex-none">{action}</span>}
      </div>
      <div className="min-w-0 flex-1 p-5">{children}</div>
    </section>
  );
}

function Copy({ value, label }: { value: string; label?: string }) {
  const [done, setDone] = useState(false);
  return (
    <button type="button" title="Copy" onClick={() => { void navigator.clipboard?.writeText(value); setDone(true); setTimeout(() => setDone(false), 1200); }}
            className="inline-flex min-w-0 items-center gap-2 rounded-[9px] px-2.5 py-1.5 text-left" style={{ background: "color-mix(in srgb, var(--bm-ink) 5%, transparent)", border: "1px solid var(--bm-line)" }}>
      {label && <span className="text-[10px] font-bold uppercase tracking-[0.1em] bm-ink-3">{label}</span>}
      <span className="bm-mono trunc text-[13px] font-semibold bm-ink">{value}</span>
      <span className="flex-none text-[10.5px] font-semibold bm-ink-3">{done ? "Copied" : <Icon name="copy" size={11} tone="inherit" />}</span>
    </button>
  );
}

export function DedicatedServerDashboard({ view, invoices, preview = false, justOrdered = false, panel = null, balanceCents = 0, initialTab }: {
  view: CustomerServerView; invoices: CustomerInvoiceRow[]; preview?: boolean; justOrdered?: boolean;
  /** Live controls when already loaded; null = load after paint (or none). */
  panel?: DedicatedPanel | null;
  balanceCents?: number;
  initialTab?: string;
}) {
  const live = view.statusKey === "ACTIVE";
  const building = view.statusKey === "PENDING" || view.statusKey === "PROVISIONING";
  const automated = live && view.automated && !preview;
  const c = useDedicatedControls(view.id, panel, automated);
  const [tab, setTab] = useState<TabKey>(() => resolveTab(initialTab));
  useEffect(() => {
    const onPop = () => setTab(resolveTab(new URLSearchParams(window.location.search).get("tab")));
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);
  const go = (t: TabKey) => {
    setTab(t);
    if (preview) return;
    const url = new URL(window.location.href);
    url.searchParams.set("tab", t);
    url.searchParams.delete("ordered");
    window.history.pushState(null, "", url);
  };
  const tone = STATUS_TONE[view.statusKey] ?? STATUS_TONE.PENDING;
  const storageMain = view.storage.split("(")[0].trim() || "—";
  const net = /\d+(?:\.\d+)?\s?[GM]bps/i.exec(view.bandwidth)?.[0].replace(/(\d)([GM])/i, "$1 $2") ?? (view.bandwidth || "—");

  return (
    <div className="bm mx-auto flex w-full max-w-[1480px] flex-col gap-4">
      {/* identity hero (always dark, like the VPS/game heroes) + tab rail, pinned on desktop */}
      <div className="z-20 -mx-1 flex flex-col gap-2 px-1 pb-2 pt-1 lg:sticky lg:top-0" style={{ background: "color-mix(in srgb, var(--color-bg) 82%, transparent)", backdropFilter: "blur(18px)" }}>
        <header className="bm-hero bm-island">
          <span className="bm-hero-grid" aria-hidden />
          <div className="relative z-[1] flex flex-wrap items-start justify-between gap-x-6 gap-y-4 px-5 py-4">
            <div className="flex min-w-0 flex-1 items-start gap-4">
              <span className="grid h-[58px] w-[58px] flex-none place-items-center rounded-[16px]" style={{ background: "linear-gradient(140deg,rgba(139,108,255,.35),rgba(79,125,255,.2))", border: "1px solid rgba(255,255,255,0.12)" }}>
                <Icon name="bmrack" size={24} tone="inherit" className="text-[#fff]" />
              </span>
              <div className="min-w-0 flex-1">
                <Link href={preview ? "#" : "/dashboard/services"} className="text-[11.5px] font-semibold bm-ink-3 hover:underline">← My Services</Link>
                <div className="mt-0.5 flex flex-wrap items-center gap-2.5">
                  <h1 className="truncate text-[24px] font-extrabold leading-[1.05] tracking-[-0.03em] sm:text-[28px]" style={{ color: "var(--bm-ink)" }}>{view.label}</h1>
                  <span className="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11.5px] font-bold" style={{ color: tone.color, background: tone.bg }}>
                    <span className="h-1.5 w-1.5 rounded-full" style={{ background: tone.color, boxShadow: tone.live ? `0 0 8px ${tone.color}` : undefined }} />{view.status}
                  </span>
                  {view.planName && <span className="bm-tag bm-tag-recommended">{view.planName}</span>}
                  {c.panel && <ModeBadge c={c} />}
                </div>
                <div className="mt-2.5 flex flex-wrap items-center gap-x-4 gap-y-2">
                  {view.ipv4[0] && <Copy label="IP" value={view.ipv4[0]} />}
                  {view.os && <span className="flex items-center gap-2 text-[12.5px] font-semibold bm-ink-2"><Icon name="terminal" size={13} tone="inherit" />{view.os}</span>}
                  <span className="flex items-center gap-2 text-[12.5px] font-semibold bm-ink-2"><Flag country={view.regionCountry} width={18} />{view.region}</span>
                  {view.hostname && <span className="bm-mono text-[12px] bm-ink-3">{view.hostname}</span>}
                </div>
                <div className="mt-3 flex flex-wrap items-center gap-x-6 gap-y-2">
                  <HeroSpec icon={<BrandLogo brand={cpuBrandOf(view.cpu)} h={11} />} value={`${view.cores} cores`} label={view.cpu.replace(/^(\d+x\s+)?(AMD|Intel)\s+/i, "$1")} />
                  <HeroSpec icon={<Icon name="ram" size={14} tone="inherit" />} value={`${view.ramGb} GB`} label="Memory" />
                  <HeroSpec icon={<Icon name="database" size={14} tone="inherit" />} value={storageMain} label="Storage" />
                  <HeroSpec icon={<Icon name="nodes" size={14} tone="inherit" />} value={net} label="Network" />
                </div>
              </div>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              {automated && <button type="button" onClick={() => go("power")} className="bm-btn-ghost" style={{ background: "rgba(255,255,255,0.06)", color: "var(--bm-ink)" }}><Icon name="refresh" size={12} tone="inherit" />Reboot or rescue</button>}
              <Link href={preview ? "#" : "/dashboard/support"} className="bm-btn bm-btn-sm"><Icon name="lifebuoy" size={12} tone="inherit" />Get help</Link>
            </div>
          </div>
        </header>
        <nav className="bm-card noscroll flex gap-1 overflow-x-auto rounded-[14px] p-1.5" aria-label="Server sections">
          {TABS.map((t) => {
            const on = tab === t.key;
            return (
              <button key={t.key} type="button" onClick={() => go(t.key)} aria-current={on ? "page" : undefined}
                      className="inline-flex flex-none items-center gap-2 whitespace-nowrap rounded-[10px] px-3.5 py-2 text-[13px] font-bold transition"
                      style={on ? { background: "var(--bm-accent-soft)", color: "var(--bm-ink)", boxShadow: "0 0 0 1px var(--bm-accent) inset" } : { color: "var(--bm-ink-3)" }}>
                <Icon name={t.icon} size={13} tone="inherit" />{t.label}
              </button>
            );
          })}
        </nav>
      </div>

      {justOrdered && (
        <section className="flex items-start gap-3 rounded-[14px] p-4" role="status" style={{ background: "var(--bm-ok-soft)", border: "1px solid color-mix(in srgb, var(--bm-ok) 35%, transparent)" }}>
          <Icon name="checkcircle" size={18} tone="inherit" className="bm-ok" />
          <div>
            <div className="text-[14px] font-extrabold bm-ink">Order confirmed. Thank you.</div>
            <div className="text-[12.5px] bm-ink-2">Our team is building your server now. It will be {SETUP_ETA.toLowerCase()}; we&apos;ll notify you and post its IP addresses and login right here.</div>
          </div>
        </section>
      )}
      {view.statusKey === "SUSPENDED" && (
        <p className="rounded-[12px] px-4 py-3 text-[12.5px]" style={{ background: "var(--bm-warn-soft)", color: "var(--bm-warn)" }}>
          This server is suspended{view.suspendReason ? `: ${view.suspendReason}` : "."} <Link href={preview ? "#" : "/dashboard/support"} className="font-bold underline">Contact support</Link> to restore it.
        </p>
      )}
      <ControlsMessage c={c} />

      <div className="bm-enter min-w-0" key={tab}>
        {tab === "overview" && <Overview view={view} invoices={invoices} c={c} automated={automated} building={building} preview={preview} go={go} />}
        {tab === "power" && (
          automated ? <Card title="Power & rescue" sub="Carried out automatically, usually within a minute or two."><ControlsGate c={c}><PowerRescue c={c} serverId={view.id} primaryIp={view.ipv4[0] ?? null} /></ControlsGate></Card>
            : <Requests view={view} kinds={["REBOOT", "RESCUE"]} preview={preview} />
        )}
        {tab === "reinstall" && (
          automated ? <Card title="Reinstall" sub="A fresh operating system, installed automatically."><ControlsGate c={c}><ReinstallPanel c={c} label={view.label} /></ControlsGate></Card>
            : <Requests view={view} kinds={["REINSTALL"]} preview={preview} />
        )}
        {tab === "network" && <Network view={view} c={c} automated={automated} balanceCents={balanceCents} />}
        {tab === "billing" && <Billing view={view} invoices={invoices} preview={preview} />}
        {tab === "support" && <Support view={view} preview={preview} />}
      </div>
    </div>
  );
}

function HeroSpec({ icon, value, label }: { icon: React.ReactNode; value: string; label: string }) {
  return (
    <span className="flex items-center gap-2">
      <span className="grid w-5 flex-none place-items-center bm-ink-3">{icon}</span>
      <span className="flex min-w-0 flex-col leading-tight">
        <span className="bm-num text-[13px] font-bold" style={{ color: "var(--bm-ink)" }}>{value}</span>
        <span className="max-w-[220px] truncate text-[10px] font-bold uppercase tracking-[0.1em] bm-ink-3">{label}</span>
      </span>
    </span>
  );
}

/* ---------------- tabs ---------------- */

function Overview({ view, invoices, c, automated, building, preview, go }: {
  view: CustomerServerView; invoices: CustomerInvoiceRow[]; c: Controls; automated: boolean; building: boolean; preview: boolean; go: (t: TabKey) => void;
}) {
  const timeline = serverTimeline({ statusKey: view.statusKey, orderedAt: view.orderedAt, provisionedAt: view.provisionedAt });
  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1.5fr)_minmax(0,1fr)]">
      <div className="flex min-w-0 flex-col gap-4">
        {view.statusKey !== "CANCELLED" && (building || !automated) && (
          <Card title="Status" sub={building ? `${SETUP_ETA} of your order` : view.provisionedAt ? `Online since ${day(view.provisionedAt)}` : undefined}>
            <ol className="grid gap-4 sm:grid-cols-3">
              {timeline.map((t, i) => (
                <li key={t.key} className="flex items-start gap-3">
                  <span className="grid h-7 w-7 flex-none place-items-center rounded-full text-[12px] font-extrabold"
                        style={t.state === "done" ? { background: "var(--bm-ok-soft)", color: "var(--bm-ok)" } : t.state === "current" ? { background: "var(--bm-grad)", color: "#fff" } : { border: "1px solid var(--bm-line-2)", color: "var(--bm-ink-4)" }}>
                    {t.state === "done" ? <Icon name="check" size={11} tone="inherit" /> : i + 1}
                  </span>
                  <span className="min-w-0">
                    <span className={"block text-[13px] font-bold " + (t.state === "todo" ? "bm-ink-4" : "bm-ink")}>{t.label}{t.state === "current" && <span className="ml-1.5 text-[11px] font-semibold bm-accent motion-safe:animate-pulse">in progress</span>}</span>
                    <span className="block text-[11.5px] bm-ink-3" suppressHydrationWarning>{t.at ? `${day(t.at)} · ` : ""}{t.note}</span>
                  </span>
                </li>
              ))}
            </ol>
          </Card>
        )}
        {automated && <Card title="Live status" action={<button type="button" onClick={() => void c.refresh(true)} className="bm-btn-ghost"><Icon name="refresh" size={11} tone="inherit" />Refresh</button>}><LiveStatus c={c} /></Card>}
        <section aria-label="Hardware" className="grid grid-cols-2 gap-3 xl:grid-cols-4">
          <SpecTile k="Processor" v={`${view.cores} cores`} sub={`${view.threads} threads · ${view.cpu}`} icon={<BrandLogo brand={cpuBrandOf(view.cpu)} h={11} />} />
          <SpecTile k="Memory" v={`${view.ramGb} GB`} sub="Dedicated to you" icon={<Icon name="ram" size={14} tone="inherit" />} />
          <SpecTile k="Storage" v={view.storage.split("(")[0].trim() || "—"} sub={view.storage.match(/\(([^)]+)\)/)?.[1] ?? "Your own disks"} icon={<Icon name="database" size={14} tone="inherit" />} />
          <SpecTile k="Network" v={view.bandwidth || "—"} sub="DDoS protection included" icon={<Icon name="nodes" size={14} tone="inherit" />} />
        </section>
        <Card title="IP addresses" action={view.ipv4.length > 0 ? <button type="button" onClick={() => go("network")} className="bm-btn-ghost">Manage</button> : undefined}>
          <IpList view={view} building={building} />
        </Card>
        {automated && <Card title="Recent actions"><RecentActions jobs={c.jobs} /></Card>}
      </div>
      <div className="flex min-w-0 flex-col gap-4">
        <Login view={view} preview={preview} />
        <Card title="Your plan" action={<button type="button" onClick={() => go("billing")} className="bm-btn-ghost">Details</button>}>
          <PlanFacts view={view} compact />
          {invoices[0] && <p className="mt-3 text-[11.5px] bm-ink-3" suppressHydrationWarning>Last invoice #{invoices[0].number} · {usd(invoices[0].amountCents)} · {day(invoices[0].createdAt)}</p>}
        </Card>
        <HelpCard preview={preview} />
      </div>
    </div>
  );
}

function SpecTile({ k, v, sub, icon }: { k: string; v: string; sub: string; icon: React.ReactNode }) {
  return (
    <div className="bm-card flex min-w-0 flex-col gap-1 p-4">
      <span className="flex items-center gap-2 bm-ink-3"><span className="grid w-5 place-items-center">{icon}</span><span className="bm-label">{k}</span></span>
      <span className="trunc text-[16px] font-extrabold bm-ink">{v}</span>
      <span className="trunc text-[11.5px] bm-ink-3" title={sub}>{sub}</span>
    </div>
  );
}

function IpList({ view, building }: { view: CustomerServerView; building: boolean }) {
  if (view.ipv4.length + view.ipv6.length === 0) {
    return (
      <div className="flex items-center gap-3 rounded-[11px] px-4 py-4" style={{ border: "1px dashed var(--bm-line-2)" }}>
        <Icon name="globe" size={16} tone="inherit" className="bm-ink-3" />
        <span className="text-[12.5px] bm-ink-3">{building ? "Your addresses are assigned while the machine is built. They appear here at handover." : "No addresses assigned."}</span>
      </div>
    );
  }
  return (
    <ul className="flex flex-col">
      {view.ipv4.map((ip, i) => <li key={ip} className={"flex items-center justify-between gap-3 py-2.5 " + (i ? "border-t bm-rule" : "")}><Copy value={ip} /><span className="bm-tag bm-tag-gpu">IPv4{i === 0 ? " · primary" : ""}</span></li>)}
      {view.ipv6.map((ip) => <li key={ip} className="flex items-center justify-between gap-3 border-t py-2.5 bm-rule"><Copy value={ip} /><span className="bm-tag bm-tag-gpu">IPv6</span></li>)}
    </ul>
  );
}

function Login({ view, preview }: { view: CustomerServerView; preview: boolean }) {
  const [cred, setCred] = useState<{ username: string; secret: string } | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const live = view.statusKey === "ACTIVE";
  const reveal = () => start(async () => {
    if (preview) { setCred({ username: view.credentialsUser ?? "root", secret: "•••• preview ••••" }); return; }
    const r = await revealDedicatedCredentials(view.id);
    if (r.ok) setCred({ username: r.username, secret: r.secret }); else setErr(r.error);
  });
  return (
    <Card title="Login details">
      {view.credentialsReady ? (
        cred ? (
          <dl className="flex flex-col gap-2 text-[13px]">
            <div className="flex justify-between gap-3"><dt className="bm-ink-3">Username</dt><dd className="bm-mono bm-ink">{cred.username}</dd></div>
            <div className="flex justify-between gap-3"><dt className="bm-ink-3">Password</dt><dd className="bm-mono break-all bm-ink">{cred.secret}</dd></div>
            <p className="pt-1 text-[11.5px] bm-ink-4">Change this password after your first login.</p>
          </dl>
        ) : (
          <div className="flex flex-col items-start gap-2.5">
            <p className="text-[12.5px] bm-ink-3">Your login is ready. It is stored encrypted and shown only to you.</p>
            <button type="button" className="bm-btn bm-btn-sm" disabled={pending} onClick={reveal}><Icon name="key" size={12} tone="inherit" />Show login details</button>
          </div>
        )
      ) : live && view.credentialsUser ? (
        <div className="flex flex-col gap-2">
          <p className="text-[12.5px] bm-ink-3">Log in as <b className="bm-ink">{view.credentialsUser}</b> with the SSH key you chose. No password is set.</p>
          {view.ipv4[0] && <code className="bm-mono w-fit rounded-[8px] px-2.5 py-1.5 text-[12px] bm-ink" style={{ background: "var(--bm-card-3)" }}>ssh {view.credentialsUser}@{view.ipv4[0]}</code>}
        </div>
      ) : (
        <p className="flex items-center gap-2 text-[12.5px] bm-ink-3"><Icon name="lock" size={13} tone="inherit" />Delivered here, encrypted, as soon as your server is handed over.</p>
      )}
      {err && <p className="mt-2 text-[12px] bm-bad">{err}</p>}
    </Card>
  );
}

function PlanFacts({ view, compact = false }: { view: CustomerServerView; compact?: boolean }) {
  const rows: [string, React.ReactNode][] = [
    ...(view.planName ? [["Build", view.planName] as [string, React.ReactNode]] : []),
    ["Billing term", view.termLabel],
    ["Renews at", <b key="r" className="bm-ink">{view.renewal ?? "—"}</b>],
    ["Next renewal", <span key="d" suppressHydrationWarning>{view.renewalDate ? day(view.renewalDate) : "—"}</span>],
    ...(!compact && view.extraIpMonthlyCents > 0 ? [["Included extra IPs", `${usd(view.extraIpMonthlyCents)}/mo`] as [string, React.ReactNode]] : []),
    ...(!compact ? [["Setup fee paid", view.setupFeeCents > 0 ? usd(view.setupFeeCents) : "None"] as [string, React.ReactNode]] : []),
    ...(!compact ? [["Ordered", <span key="o" suppressHydrationWarning>{day(view.orderedAt)}</span>] as [string, React.ReactNode]] : []),
  ];
  return (
    <dl className="flex flex-col gap-2 text-[13px]">
      {rows.map(([k, v]) => <div key={k} className="flex justify-between gap-3"><dt className="bm-ink-3">{k}</dt><dd className="text-right bm-ink-2">{v}</dd></div>)}
    </dl>
  );
}

function Network({ view, c, automated, balanceCents }: { view: CustomerServerView; c: Controls; automated: boolean; balanceCents: number }) {
  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)]">
      <div className="flex min-w-0 flex-col gap-4">
        <Card title="Addresses" sub="Your public IPv4 and IPv6 addresses."><IpList view={view} building={view.statusKey !== "ACTIVE"} /></Card>
        {automated && <Card title="Reverse DNS & firewall" sub="Per-address PTR records and a network firewall in front of your server."><ControlsGate c={c}><NetworkPanel c={c} /></ControlsGate></Card>}
      </div>
      <Card title="Buy more IPv4 addresses" sub="Prorated to your next renewal, then added to it.">
        {automated ? <ControlsGate c={c}><ExtraIps c={c} serverId={view.id} balanceCents={balanceCents} /></ControlsGate>
          : <p className="text-[12.5px] bm-ink-3">Extra addresses can be added once your server is online.</p>}
      </Card>
    </div>
  );
}

function Billing({ view, invoices, preview }: { view: CustomerServerView; invoices: CustomerInvoiceRow[]; preview: boolean }) {
  const cancelRequested = view.openRequests.some((r) => r.kind === "CANCEL");
  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]">
      <div className="flex min-w-0 flex-col gap-4">
        <Card title="Plan terms">
          <PlanFacts view={view} />
          <p className="mt-3 text-[11.5px] bm-ink-4">The renewal price is shown exactly as it is charged{view.termMonths === 12 ? " (once a year)" : ""}. We send a renewal invoice before the date above.</p>
        </Card>
        <Card title="Cancellation" sub="Stop this server from renewing.">
          {view.statusKey === "CANCELLED" ? <p className="text-[12.5px] bm-ink-3">This server has been cancelled.</p>
            : cancelRequested ? <p className="text-[12.5px] bm-ink-2">Your cancellation request is with our team. They will confirm the date service ends in your support ticket.</p>
            : <RequestForm view={view} kind="CANCEL" preview={preview} intro={`Our team confirms the date service ends${view.renewalDate ? ` (your current term is paid until ${day(view.renewalDate)})` : ""} in a support ticket. Nothing stops until they confirm with you.`} button="Request cancellation" />}
        </Card>
      </div>
      <Card title="Invoices">
        {invoices.length === 0 ? <p className="text-[12.5px] bm-ink-3">No invoices yet.</p> : (
          <ul className="flex flex-col">
            {invoices.map((inv, i) => (
              <li key={inv.id} className={"flex items-center justify-between gap-3 py-2.5 text-[13px] " + (i ? "border-t bm-rule" : "")}>
                <span className="flex min-w-0 flex-col">
                  {preview ? <span className="font-semibold bm-ink" suppressHydrationWarning>#{inv.number} · {day(inv.createdAt)}</span>
                    : <Link href={`/dashboard/invoices/${inv.id}`} className="font-semibold bm-ink hover:underline" suppressHydrationWarning>#{inv.number} · {day(inv.createdAt)}</Link>}
                  <span className="trunc text-[11.5px] bm-ink-3">{inv.description}</span>
                </span>
                <span className="flex flex-none items-center gap-2"><span className="bm-num font-bold bm-ink">{usd(inv.amountCents)}</span><span className={"bm-tag " + (inv.status === "PAID" ? "bm-tag-value" : "bm-tag-gpu")}>{inv.status.toLowerCase()}</span></span>
              </li>
            ))}
          </ul>
        )}
      </Card>
    </div>
  );
}

const REQUEST_HINT: Record<RequestKind, string> = {
  REBOOT: "A clean restart of the machine.",
  REINSTALL: "Wipes the disks and installs a fresh OS.",
  RESCUE: "Boots a recovery system to repair or copy data.",
  CANCEL: "Stops the server from renewing.",
};

function Requests({ view, kinds, preview }: { view: CustomerServerView; kinds: RequestKind[]; preview: boolean }) {
  const live = view.statusKey === "ACTIVE";
  return (
    <Card title={kinds.includes("REINSTALL") ? "Reinstall" : "Power & rescue"} sub={live ? "Our engineers carry these out. Each one opens a support ticket you can follow." : "Available once your server is online."}>
      <div className="flex flex-col gap-3">
        {kinds.map((k) => <RequestForm key={k} view={view} kind={k} preview={preview} intro={REQUEST_HINT[k]} button={REQUEST_LABEL[k]} disabled={!live} />)}
      </div>
    </Card>
  );
}

function RequestForm({ view, kind, preview, intro, button, disabled = false }: { view: CustomerServerView; kind: RequestKind; preview: boolean; intro: string; button: string; disabled?: boolean }) {
  const [open, setOpen] = useState(false);
  const [note, setNote] = useState("");
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const requested = view.openRequests.some((r) => r.kind === kind);
  const send = () => start(async () => {
    if (preview) { setMsg(`Preview: a "${REQUEST_LABEL[kind]}" request would open a support ticket. Nothing was sent.`); setOpen(false); return; }
    const r = await requestDedicatedAction(view.id, kind, note);
    setMsg(r.ok ? "Request sent. Our team has it as a support ticket and will update you there." : r.error);
    if (r.ok) { setOpen(false); setNote(""); }
  });
  return (
    <div className="bm-sub flex flex-col gap-2.5 p-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <span className="flex min-w-0 flex-col">
          <span className="text-[13.5px] font-extrabold bm-ink">{requested ? `${REQUEST_LABEL[kind]} · requested` : REQUEST_LABEL[kind]}</span>
          <span className="text-[12px] bm-ink-3">{intro}</span>
        </span>
        {!open && <button type="button" disabled={disabled || requested || pending} onClick={() => setOpen(true)} className="bm-btn-ghost">{button}</button>}
      </div>
      {open && (
        <div className="flex flex-col gap-2">
          <label className="text-[12px] font-bold bm-ink" htmlFor={`req-${kind}`}>Anything we should know?</label>
          <textarea id={`req-${kind}`} value={note} onChange={(e) => setNote(e.target.value)} rows={3} maxLength={2000} placeholder={kind === "REINSTALL" ? "e.g. Ubuntu 24.04, keep the same hostname" : "Optional"} className="bm-field h-auto py-2" />
          {kind === "REINSTALL" && <p className="text-[11.5px] bm-warn">A reinstall erases everything on the disks.</p>}
          <div className="flex gap-2">
            <button type="button" className="bm-btn bm-btn-sm" disabled={pending} onClick={send}>Send request</button>
            <button type="button" className="bm-btn-ghost" onClick={() => setOpen(false)}>Cancel</button>
          </div>
        </div>
      )}
      {msg && <p className="text-[12px] bm-ink-2" role="status">{msg}</p>}
    </div>
  );
}

function Support({ view, preview }: { view: CustomerServerView; preview: boolean }) {
  return (
    <div className="grid gap-4 lg:grid-cols-2">
      <HelpCard preview={preview} big />
      <Card title="Open requests">
        {view.openRequests.length === 0 ? <p className="text-[12.5px] bm-ink-3">No open requests for this server.</p> : (
          <ul className="flex flex-col gap-2">
            {view.openRequests.map((r) => <li key={r.id} className="bm-sub px-3.5 py-2.5 text-[12.5px] bm-ink-2" suppressHydrationWarning><b className="bm-ink">{REQUEST_LABEL[r.kind as RequestKind] ?? r.kind}</b> · requested {day(r.createdAt)} · with our team</li>)}
          </ul>
        )}
        <p className="mt-3 text-[11.5px] bm-ink-4">Need the out-of-band console? Our engineers open it for you from a ticket.</p>
      </Card>
    </div>
  );
}

function HelpCard({ preview, big = false }: { preview: boolean; big?: boolean }) {
  return (
    <section className={"bm-card flex items-center gap-4 " + (big ? "p-6" : "p-5")}>
      <span className="bm-sub grid h-11 w-11 flex-none place-items-center rounded-[13px]"><Icon name="lifebuoy" size={18} tone="inherit" className="bm-accent" /></span>
      <div className="min-w-0 flex-1">
        <div className="text-[14px] font-extrabold bm-ink">Need a hand with this server?</div>
        <div className="text-[12px] bm-ink-3">The same support team that runs the rest of your Nxeon services.</div>
      </div>
      <Link href={preview ? "#" : "/dashboard/support"} className="bm-btn-ghost flex-none">Open a ticket</Link>
    </section>
  );
}

