/**
 * A customer's bare-metal servers as rows for the estate views: My Services
 * (lib/nx/services.ts -> components/customer/services) and the "Services"
 * card on the dashboard home (app/dashboard/page.tsx).
 *
 * GATED like every dedicated surface: an account that does not pass
 * lib/dedicated/gate.ts gets no rows (fail closed), so nothing about the
 * unreleased product appears outside its own pages. The route strings live in
 * THIS file (the feature) so test/dedicated-gate.test.ts's "nothing outside the
 * feature links to it" rule still holds.
 *
 * Prices are what the renewal charges: renewalMonthlyCents x termMonths (extra
 * IPs are already folded into renewalMonthlyCents by the IP order flow).
 */
import { db } from "../db";
import { dedicatedAccessFor } from "./gate";
import { toCustomerServerView } from "./customer-view";
import { planNameForItem } from "./order";

export const BARE_METAL_TYPE_LABEL = "Bare Metal";
export const BARE_METAL_PREVIEW = "/nx/preview/baremetal.svg";
export const bareMetalHref = (id: string) => `/dashboard/dedicated/${id}`;
export const BARE_METAL_ORDER_HREF = "/dashboard/dedicated";

export type BareMetalRow = {
  id: string;
  name: string;
  href: string;
  planName: string | null;
  address: string | null;
  specs: string;
  cpu: string;
  cores: number;
  ramGb: number;
  storage: string;
  /** DedicatedServer.status (PENDING | PROVISIONING | ACTIVE | SUSPENDED | CANCELLED). */
  statusKey: string;
  statusLabel: string;
  region: string;
  regionCountry: string;
  renewalIso: string | null;
  renewalCents: number | null;
  termMonths: number;
  createdAtIso: string;
};

/** Rows for `user` (empty unless the gate passes). Never throws. */
export async function bareMetalRows(user: { id: string; email?: string | null }): Promise<BareMetalRow[]> {
  try {
    if (!(await dedicatedAccessFor(user)).allowed) return [];
    const rows = await db.dedicatedServer.findMany({ where: { userId: user.id, status: { not: "CANCELLED" } }, orderBy: { createdAt: "desc" } });
    return await Promise.all(rows.map(async (s) => {
      const planName = await planNameForItem(s.catalogItemId).catch(() => null);
      const v = toCustomerServerView(s, [], planName);
      const storage = v.storage.split("(")[0].trim();
      return {
        id: v.id,
        name: v.label,
        href: bareMetalHref(v.id),
        planName: v.planName,
        address: v.ipv4[0] ?? null,
        specs: [v.planName, `${v.cores} cores`, `${v.ramGb} GB`, storage].filter(Boolean).join(" • "),
        cpu: v.cpu,
        cores: v.cores,
        ramGb: v.ramGb,
        storage,
        statusKey: v.statusKey,
        statusLabel: v.status,
        region: v.region,
        regionCountry: v.regionCountry,
        renewalIso: v.renewalDate,
        renewalCents: v.renewalMonthlyCents != null ? v.renewalMonthlyCents * Math.max(1, v.termMonths) : null,
        termMonths: Math.max(1, v.termMonths),
        createdAtIso: v.orderedAt,
      };
    }));
  } catch {
    return [];
  }
}

