test("margin is gross margin on the sell price", () => {
  assert.deepEqual(margin(10700, 13399), { cents: 2699, percent: 20.1 });
  assert.deepEqual(margin(10700, 9900), { cents: -800, percent: -8.1 });
  assert.equal(margin(100, 0).percent, null);
});

test("first-year margin and setup payback when setup is waived", () => {
  const args = { monthlyCost: 10700, monthlySell: 13399, setupCost: 10700, setupSell: 0 };
  assert.deepEqual(firstYearMargin(args), margin(10700 * 13, 13399 * 12));
  assert.equal(setupPaybackMonths(args), 4); // 10700 / 2699 = 3.96 -> 4
  assert.equal(setupPaybackMonths({ ...args, setupSell: 10700 }), 0);
  assert.equal(setupPaybackMonths({ ...args, monthlySell: 10700 }), null);
});

test("rules from settings: parsed, clamped, and fall back on garbage", () => {
  const r = rulesFromSettings({ dedicated_markup_percent: "30", dedicated_markup_fixed_cents: "250", dedicated_rounding: "whole", dedicated_setup_policy: "waived", dedicated_setup_custom_cents: "-5" });
  assert.deepEqual(r, { markupPercent: 30, markupFixedCents: 250, rounding: "whole", setupPolicy: "waived", setupCustomCents: 0 });
  assert.deepEqual(rulesFromSettings({}), DEFAULT_RULES);
  assert.deepEqual(rulesFromSettings({ dedicated_markup_percent: "abc", dedicated_rounding: "weird" }), DEFAULT_RULES);
  assert.equal(clampPercent(5000), 1000);
  assert.equal(clampPercent(-500), -100);
});

test("priceView ties it together for one catalogue item", () => {
  const v = priceView({ monthlyCents: 33100, setupCents: 33100, promoSetupCents: 0 }, R());
  assert.equal(v.costMonthly, 33100);
  assert.equal(v.sellMonthly, 41399); // 413.75 -> 413.99
  assert.equal(v.costSetup, 0);
  assert.equal(v.sellSetup, 0);
  assert.equal(v.margin.cents, 8299);
});

test("money formatting", () => {
  assert.equal(money(13399), "$133.99");
  assert.equal(money(-800), "-$8.00");
  assert.equal(money(123456789), "$1,234,567.89");
  assert.equal(money(500, "EUR"), "€5.00");
});

