import { test } from "node:test";
import assert from "node:assert/strict";
import { disambiguateNames, nxFamily, nxName, NX_FAMILIES } from "../lib/dedicated/nx-names.ts";
import { flagSvg, FLAG_COUNTRIES } from "../lib/dedicated/flags.ts";
import { DEDICATED_DC_REGIONS } from "../lib/dedicated/regions.ts";

/** Nxeon's own build names: deterministic, derived only from the hardware, never a supplier name. */
const f = (cpu: string, cores: number, ramGb = 64, extra: { cpuCount?: number; gpu?: string | null } = {}) => nxFamily({ cpu, cores, ramGb, ...extra });

test("families follow the documented rule order", () => {
  assert.equal(f("AMD EPYC GENOA 9124", 16, 192, { gpu: "2x NVIDIA L4" }), "NX-GPU");
  assert.equal(f("AMD EPYC TURIN 9655", 96), "NX-Titan");
  assert.equal(f("2x Intel Xeon Gold 5515+", 16, 256, { cpuCount: 2 }), "NX-Titan");
  assert.equal(f("2x Intel Xeon E5-2680 v3", 24, 64, { cpuCount: 2 }), "NX-Titan"); // dual socket beats legacy
  assert.equal(f("AMD RYZEN 7 9800X3D", 8), "NX-Pulse");
  assert.equal(f("AMD Ryzen 9 5900X", 12, 32), "NX-Pulse");
  assert.equal(f("AMD EPYC 4344P", 8), "NX-Forge");
  assert.equal(f("Intel Xeon-E 2386G", 6, 32), "NX-Forge");
  assert.equal(f("Intel Xeon Gold 6312U", 24, 128), "NX-Forge");
  assert.equal(f("Intel Xeon 6517P", 16, 128), "NX-Forge");
  assert.equal(f("Intel Xeon-E3 1230v6", 4, 16), "NX-Core");
  assert.equal(f("Intel Core i7-7700K", 4, 32), "NX-Core");
  assert.equal(f("AMD Ryzen 5 Pro 3600", 6, 32), "NX-Core");
