import { test } from "node:test";
import assert from "node:assert/strict";
import { computeTags, POPULAR_MIN_ORDERS, pricePerUnit, type TagInput } from "../lib/dedicated/tags.ts";

/** Catalogue badges: transparent, deterministic rules (lib/dedicated/tags.ts). */
const now = new Date("2026-10-07T00:00:00Z");
const base: Omit<TagInput, "key"> = {
  family: "NX-Forge", cores: 8, threads: 16, ramGb: 64, baseGhz: 3.8, boostGhz: 5.3, gpu: null,
  fromMonthlyCents: 20000, inStock: true, pinned: false, orders: 0, firstSeenAt: "2026-08-01T00:00:00Z",
};
const card = (key: string, o: Partial<TagInput> = {}): TagInput => ({ ...base, key, ...o });

test("an admin pin wins 'Most popular'; otherwise real orders (>= threshold); otherwise a labelled 'Recommended'", () => {
  const rows = [card("a", { orders: 9 }), card("b", { pinned: true }), card("c")];
  assert.deepEqual(computeTags(rows, now).get("b")?.includes("popular"), true);
  assert.equal(computeTags(rows, now).get("a")?.includes("popular"), false);

  const byOrders = computeTags([card("a", { orders: POPULAR_MIN_ORDERS }), card("b", { orders: 1 })], now);
  assert.ok(byOrders.get("a")?.includes("popular"));

  const none = computeTags([card("a", { orders: 1, fromMonthlyCents: 30000 }), card("b", { fromMonthlyCents: 25000 }), card("c", { family: "NX-Core", fromMonthlyCents: 1000 })], now);
  assert.ok(![...none.values()].some((t) => t.includes("popular")), "never claims popularity without the orders");
  assert.ok(none.get("b")?.includes("recommended"), "cheapest in-stock NX-Forge with >= 64 GB");
});

test("best value = lowest price per (cores + RAM/8); high performance = most threads x clock", () => {
  const rows = Array.from({ length: 20 }, (_, i) => card(`k${i}`, { cores: 8 + i, threads: 16 + 2 * i, fromMonthlyCents: 10000 + i * 3000 }));
  const t = computeTags(rows, now);
  const value = [...t].filter(([, v]) => v.includes("value")).map(([k]) => k);
  const perf = [...t].filter(([, v]) => v.includes("performance")).map(([k]) => k);
  assert.equal(value.length, 2, "10% of 20");
  const best = [...rows].sort((a, b) => pricePerUnit(a) - pricePerUnit(b)).slice(0, 2).map((r) => r.key);
  assert.deepEqual(value.sort(), best.sort());
  assert.deepEqual(perf.sort(), ["k18", "k19"]);
});

test("GPU and New; out-of-stock builds never get ranking tags", () => {
