  assert.ok(t.get("fresh")?.includes("new"));
  assert.ok(!t.get("launch")?.includes("new"), "the launch catalogue is not 'New'");
  assert.ok(t.get("gpu")?.includes("gpu"));
  assert.ok(!t.get("gpu")?.includes("value"), "GPU builds are ranked separately");
  assert.deepEqual(t.get("gone"), []);
});

test("deterministic: same input, same output", () => {
  const rows = Array.from({ length: 12 }, (_, i) => card(`k${i}`, { fromMonthlyCents: 9000 + (i % 3) * 100 }));
  assert.deepEqual([...computeTags(rows, now)], [...computeTags([...rows].reverse(), now)].sort((a, b) => Number(a[0].slice(1)) - Number(b[0].slice(1))));
});
