/* ============ Dedicated: live catalogue (data from the page loader, __NXM) ============ */
(function () {
  var D = (typeof __NXM !== 'undefined' && __NXM) || { cards: [], regions: [] };
  var grid = document.getElementById('dd-grid');
  if (!grid) return;
  var esc = function (s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return '&#' + c.charCodeAt(0) + ';'; }); };
  var LOGO = { amd: '/nxm/home/logos-amd.svg', intel: '/nxm/home/logos-intel.svg', nvidia: '/nxm/home/logos-nvidia.svg' };
  var logo = function (b, cls) { return b && LOGO[b] ? '<img class="dd-logo ' + (cls || '') + '" src="' + LOGO[b] + '" alt="' + (b === 'amd' ? 'AMD' : b === 'intel' ? 'Intel' : 'NVIDIA') + '" style="height:18px !important;width:auto !important">' : ''; };
  var st = { brand: 'all', region: 'all', cores: 0, ram: 0, disk: 0, price: 0, limit: 9 };
  var regionSel = document.getElementById('dd-f-region');
  (D.regions || []).forEach(function (r) {
    var o = document.createElement('option');
    o.value = r.code; o.textContent = r.label + (r.inStock ? ' · ' + r.inStock + ' in stock' : ' · sold out');
    regionSel.appendChild(o);
  });
  var bind = function (id, key) { var el = document.getElementById(id); if (el) el.addEventListener('change', function () { st[key] = key === 'region' ? el.value : Number(el.value); st.limit = 9; render(); }); };
  bind('dd-f-region', 'region'); bind('dd-f-cores', 'cores'); bind('dd-f-ram', 'ram'); bind('dd-f-disk', 'disk'); bind('dd-f-price', 'price');
  document.querySelectorAll('.dd-chip[data-brand]').forEach(function (b) {
    b.addEventListener('click', function () {
      document.querySelectorAll('.dd-chip[data-brand]').forEach(function (x) { x.classList.toggle('on', x === b); x.setAttribute('aria-pressed', x === b ? 'true' : 'false'); });
      st.brand = b.getAttribute('data-brand'); st.limit = 9; render();
    });
  });
  var more = document.getElementById('dd-more');
  if (more) more.addEventListener('click', function () { st.limit += 9; render(); });

  function card(c, regs, from) {
    var href = st.region === 'all' ? c.href : c.hrefTpl.replace('__REGION__', encodeURIComponent(regs[0].region));
    return '<li class="au-card dd-card2">' +
      '<div class="dd-ct"><div style="min-width:0"><span class="dd-tier">' + esc(c.tier) + '</span>' +
      '<h3 class="dd-cpu">' + logo(c.cpuBrand) + '<span>' + esc(c.cpuShort) + '</span></h3>' +
      '<div class="dd-sub">' + esc(c.cores) + ' cores · ' + esc(c.threads) + ' threads' + (c.ghz ? ' · ' + esc(c.ghz) + ' GHz' : '') + '</div></div>' +
      '<div class="dd-pr"><small>from</small><b>' + __nxmMoney(from) + '</b><em>/mo</em></div></div>' +
      '<dl class="dd-spec">' +
      '<div><dt>Memory</dt><dd>' + esc(c.ramGb) + ' GB' + (c.maxRamGb > c.ramGb ? '<small>up to ' + esc(c.maxRamGb) + ' GB</small>' : '') + '</dd></div>' +
      '<div><dt>Network</dt><dd>' + esc(c.bandwidth || '—') + '<small>DDoS protection</small></dd></div>' +
      '<div style="grid-column:1/-1"><dt>Storage</dt><dd>' + esc(c.storage || '—') + '</dd></div>' +
      (c.gpu ? '<div class="dd-gpu">' + logo(c.gpuBrand) + esc(c.gpu) + '</div>' : '') +
      '</dl><div class="dd-cf"><ul class="dd-regs">' + regs.slice(0, 5).map(function (r) { return '<li>' + esc(r.label) + '</li>'; }).join('') + (regs.length > 5 ? '<li>+' + (regs.length - 5) + ' more</li>' : '') + '</ul>' +
      '<div class="dd-act"><span><span class="dd-eta">Online within 24 hours</span><br><span class="dd-setup">' + (c.setup > 0 ? __nxmMoney(c.setup) + ' one-time setup' : 'No setup fee') + '</span></span>' +
      '<a class="au-btn sm" href="' + esc(href) + '">Configure</a></div></div></li>';
  }

  function render() {
    var rows = [];
    (D.cards || []).forEach(function (c) {
      var regs = (c.regions || []).filter(function (r) { return r.inStock && (st.region === 'all' || r.code === st.region); });
      if (!regs.length) return;
      var from = Math.min.apply(null, regs.map(function (r) { return r.from; }));
      if (st.brand === 'GPU' ? !c.gpu : st.brand !== 'all' && c.cpuBrandName !== st.brand) return;
      if (c.cores < st.cores || c.maxRamGb < st.ram || c.storageGb < st.disk) return;
      if (st.price && from > st.price) return;
      rows.push({ c: c, regs: regs, from: from });
    });
    rows.sort(function (a, b) { return a.from - b.from; });
    var total = (D.cards || []).length;
    document.getElementById('dd-count').innerHTML = '<b>' + rows.length + '</b> of ' + total + ' in-stock builds · prices per month';
    grid.innerHTML = rows.slice(0, st.limit).map(function (x) { return card(x.c, x.regs, x.from); }).join('');
    more.hidden = rows.length <= st.limit;
    document.getElementById('dd-empty').hidden = rows.length > 0;
  }
  render();
})();
    ? `<ul class="dd-locs">${regionList.map((r) => `<li class="au-glass dd-loc${r.inStock ? " on" : ""}"><small>${esc(r.area)}</small><b>${esc(r.label)}</b><span>${r.inStock ? `${r.inStock} build${r.inStock === 1 ? "" : "s"} in stock` : "Sold out right now"}</span></li>`).join("")}</ul>`
    : `<p class="lede">Locations are being refreshed.</p>`;

  const data = {
    regions: regionList.map((r) => ({ code: r.code, label: r.label, inStock: r.inStock })),
    cards: sorted.map((c) => ({
      id: c.id,
      href: hrefFor(c.id),
      hrefTpl: hrefFor(c.id, "__REGION__"),
      tier: c.tier,
      cpuShort: c.cpu.replace(/^(AMD|Intel)\s+/i, ""),
      cpuBrand: cpuBrandOf(c.cpu),
      cpuBrandName: c.cpuBrand,
      gpu: c.gpu,
      gpuBrand: gpuBrandOf(c.gpu),
      cores: c.cores,
      threads: c.threads,
      ghz: c.baseGhz,
      ramGb: c.ramGb,
      maxRamGb: c.maxRamGb,
      storage: c.storage,
      storageGb: c.storageGb,
      bandwidth: c.bandwidth,
      setup: (c.regions.find((r) => r.inStock)?.setupCents ?? 0) / 100,
      // grouped by location label; the configurator link carries a real region code that is in stock there
      regions: [...new Set(c.regions.map((r) => keyOf(r.label)))].map((k) => {
        const rs = c.regions.filter((r) => keyOf(r.label) === k);
        const best = rs.filter((r) => r.inStock).sort((a, b) => a.fromMonthlyCents - b.fromMonthlyCents)[0] ?? rs[0];
        return { code: k, region: best.code, label: best.label, inStock: rs.some((r) => r.inStock), from: best.fromMonthlyCents / 100 };
      }),
    })),
  };

  const prices = sorted.map(fromOf);
  return {
    slots: {
      count: String(cards.length),
      from: cheapest ? usd(fromOf(cheapest)) : "—",
      maxThreads: String(cards.reduce((m, c) => Math.max(m, c.threads), 0)),
      regions: String(regionsInStock),
      "plate:html": plate,
      "locations:html": locations,
    },
    data,
    crumb: "Dedicated servers",
    jsonLd: prices.length
      ? [{
          "@context": "https://schema.org", "@type": "Product", name: "Nxeon Dedicated Servers (bare metal)",
          description: "Single-tenant bare metal dedicated servers with full root, dedicated IPv4 and DDoS protection, billed monthly or yearly.",
          brand: { "@type": "Brand", name: "Nxeon" },
          offers: { "@type": "AggregateOffer", priceCurrency: "USD", lowPrice: (Math.min(...prices) / 100).toFixed(2), highPrice: (Math.max(...prices) / 100).toFixed(2), offerCount: prices.length, availability: "https://schema.org/InStock", url: APP_URL + "/dedicated-servers" },
        }]
      : [],
  };
}

