import "server-only";
import { notFound } from "next/navigation";
import { currentUser } from "@/lib/auth";
import { dedicatedPublicEnabled, requireDedicatedAccess } from "@/lib/dedicated/gate";
import { loadOrderCatalog, orderPreviewAll, type OrderCatalogCard } from "@/lib/dedicated/order";
import { cpuBrandOf, gpuBrandOf } from "@/lib/dedicated/brand";
import { NX_FAMILIES, NX_FAMILY_INFO } from "@/lib/dedicated/nx-names";
import { TAG_LABEL, TAG_RULE } from "@/lib/dedicated/tags";
import { flagSvg } from "@/lib/dedicated/flags";
import { bareMetalHeroSvg } from "@/lib/dedicated/hero-art";
import { DEDICATED_COUNTRY_PAGES, dedicatedCountryPage, dedicatedCountryPath } from "@/lib/dedicated/regions";
import { APP_URL } from "@/components/marketing/StructuredData";
import { esc, usd, type NxmLoad } from "./lib";

/**
 * /dedicated-servers (Bare Metal Dedicated Servers) and its country pages
 * /dedicated-servers/<country> — the NXM pages. GATED: 404 unless the
 * dedicated gate passes (Setting dedicated_public_enabled, or a private-
 * preview account; lib/dedicated/gate.ts). noindex unless public; the sitemap
 * lists them only when public (lib/sitemap-sections.ts EXCLUDE + dedicatedSitemapPaths).
 *
 * Every figure is real: the same in-stock catalogue + pricing rules the
 * checkout charges (lib/dedicated/order.ts), the NX names and tags the portal
 * shows. Buy links go straight into the portal flow; a signed-out visitor is
 * sent through /register?next=. No reviews, ratings or invented stats.
 */
const FLOW = "/dashboard/dedicated";

async function inStockCards(): Promise<OrderCatalogCard[]> {
  const access = await requireDedicatedAccess();
  const cards = await loadOrderCatalog(await orderPreviewAll(access.preview));
  return cards.filter((c) => c.regions.some((r) => r.inStock));
}

export async function meta(p: Record<string, string>) {
  const on = await dedicatedPublicEnabled();
  const page = p.country ? dedicatedCountryPage(p.country) : null;
  if (page) {
    return {
      title: `Bare Metal Dedicated Servers in ${page.name}`,
      description: `Bare metal dedicated servers in ${page.inName}: single-tenant AMD and Intel hardware with full root, your own IPv4, DDoS protection and reboot, rescue and reinstall from your dashboard. Live stock and monthly prices.`,
      noindex: !on,
      canonical: dedicatedCountryPath(page.slug),
    };
  }
  return {
    title: "Bare Metal Dedicated Servers",
    description: "Bare metal dedicated servers with full root, your own IPv4, DDoS protection and reboot, rescue and reinstall from your dashboard. AMD EPYC, Ryzen and Intel Xeon builds, live stock, monthly prices.",
    noindex: !on,
  };
}

const keyOf = (label: string) => label.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const logoImg = (b: string, h: number, alt: string) => `<img src="/nxm/home/logos-${b}.svg" alt="${alt}" style="height:${h}px !important;width:auto !important">`;

export async function load(p: Record<string, string>): Promise<NxmLoad> {
  const all = await inStockCards();
  const page = p.country ? dedicatedCountryPage(p.country) : null;
  if (p.country && !page) notFound();
  const inCountry = (c: OrderCatalogCard) => !page || c.regions.some((r) => r.inStock && r.country === page.country);
  const cards = all.filter(inCountry);
  if (page && cards.length === 0) notFound(); // nothing offered there: no thin page
  const user = await currentUser();
  const hrefFor = (id: string, region?: string) => {
    const q = new URLSearchParams({ build: id });
    if (region) q.set("region", region);
    const dest = `${FLOW}?${q.toString()}`;
    return user ? dest : `/register?next=${encodeURIComponent(dest)}`;
  };
  const regionsOf = (c: OrderCatalogCard) => c.regions.filter((r) => r.inStock && (!page || r.country === page.country));
  const fromOf = (c: OrderCatalogCard) => Math.min(...regionsOf(c).map((r) => r.fromMonthlyCents));
  const sorted = [...cards].sort((a, b) => fromOf(a) - fromOf(b));
  const cheapest = sorted[0] ?? null;

  // locations, grouped by customer label; several region codes can share one label
  const regions = new Map<string, { code: string; label: string; area: string; country: string; inStock: number; listed: number }>();
  for (const c of all) {
    const seen = new Map<string, boolean>();
    for (const r of c.regions) seen.set(keyOf(r.label), (seen.get(keyOf(r.label)) ?? false) || r.inStock);
    for (const [k, inStock] of seen) {
      const r = c.regions.find((x) => keyOf(x.label) === k)!;
      const e = regions.get(k) ?? { code: k, label: r.label, area: r.area, country: r.country, inStock: 0, listed: 0 };
      e.listed++;
      if (inStock) e.inStock++;
      regions.set(k, e);
    }
  }
  const regionList = [...regions.values()].sort((a, b) => b.inStock - a.inStock || a.label.localeCompare(b.label));
  const countries = new Set(regionList.filter((r) => r.inStock).map((r) => r.country));
  const flags: Record<string, string> = {};
  for (const r of regionList) flags[r.country] = flagSvg(r.country, { width: 22 });

  const families = NX_FAMILIES.map((f) => {
    const list = sorted.filter((c) => c.family === f);
    return { f, count: list.length, from: list.length ? Math.min(...list.map(fromOf)) : null, maxCores: list.reduce((m, c) => Math.max(m, c.cores), 0) };
  }).filter((x) => x.count > 0);
