  const access = await requireDedicatedAccess();
  const cards = await loadOrderCatalog(await orderPreviewAll(access.preview));
  return cards.filter((c) => c.regions.some((r) => r.inStock));
}

export async function meta(p: Record<string, string>) {
  const on = await dedicatedPublicEnabled();
  const page = p.country ? dedicatedCountryPage(p.country) : null;
  if (page) {
    return {
      title: `Bare Metal Dedicated Servers in ${page.name}`,
      description: `Bare metal dedicated servers in ${page.inName}: single-tenant AMD and Intel hardware with full root, your own IPv4, DDoS protection and reboot, rescue and reinstall from your dashboard. Live stock and monthly prices.`,
      noindex: !on,
      canonical: dedicatedCountryPath(page.slug),
    };
  }
  return {
    title: "Bare Metal Dedicated Servers",
    description: "Bare metal dedicated servers with full root, your own IPv4, DDoS protection and reboot, rescue and reinstall from your dashboard. AMD EPYC, Ryzen and Intel Xeon builds, live stock, monthly prices.",
