.dd-countries a:hover{color:#fff;border-color:var(--dd-acc)}
.dd-countries svg{display:block;border-radius:3px}
/* final: the homepage's own bottom-section background (home.css .final), reused verbatim */
.dd-final{position:relative;text-align:left;overflow:hidden;padding-block:clamp(120px,15vw,210px);isolation:isolate;min-height:min(80svh,760px);display:flex;align-items:center}
.dd-final .container{width:100%}
.dd-final .final-img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2;object-position:62% 45%;opacity:1}
.dd-final::after{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,rgba(6,9,19,.94) 0%,rgba(6,9,19,.78) 30%,rgba(6,9,19,.2) 58%,rgba(6,9,19,0) 75%),linear-gradient(180deg,var(--bg) 0%,rgba(6,9,19,0) 22%,rgba(6,9,19,0) 72%,var(--bg) 100%)}
.dd-final h2{font-weight:800;font-size:clamp(2.2rem,4.8vw,4rem);line-height:1.04;letter-spacing:-.03em;margin:0 0 20px;max-width:14ch}
.dd-final p{color:var(--ink-2);font-size:1.1rem;margin:0 0 32px;max-width:44ch}
.dd-final .final-ctas{display:flex;gap:12px;flex-wrap:wrap;justify-content:flex-start}
