.dd-final .nxm-gradtext{background:linear-gradient(100deg,#3EDCF2,#4E8DFF 45%,#9B6BFF);-webkit-background-clip:text;background-clip:text;color:transparent}
.dd-final .nxm-final-note{margin:22px 0 0;font-size:.85rem;color:var(--muted)}
@media (prefers-reduced-motion:no-preference){.dd-final .final-img{transform:scale(1.06);transition:transform 2.4s cubic-bezier(.2,.7,.2,1)}.dd-final.in-view .final-img{transform:none}}
