@media (max-width:1180px){.dd-fams{grid-template-columns:repeat(3,minmax(0,1fr))}.dd-sliders{grid-template-columns:repeat(2,minmax(0,1fr))}.dd-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
