  #dd-locs-f{flex-wrap:nowrap;overflow-x:auto;padding-bottom:4px;margin-inline:-4px;padding-inline:4px}
  .dd-tr{grid-template-columns:1fr 1fr 1fr;padding:12px 14px;font-size:.84rem}
}
