    var k = b.getAttribute('data-fam'), i = st.fams.indexOf(k);
    if (i >= 0) st.fams.splice(i, 1); else st.fams.push(k);
    sync(); render(true);
  });
  document.querySelectorAll('.dd-fam-go[data-family]').forEach(function (b) {
