  famBox.addEventListener('click', function (e) {
    var b = e.target.closest('[data-fam]'); if (!b) return;
    var k = b.getAttribute('data-fam'), i = st.fams.indexOf(k);
    if (i >= 0) st.fams.splice(i, 1); else st.fams.push(k);
    sync(); render(true);
  });
  document.querySelectorAll('.dd-fam-go[data-family]').forEach(function (b) {
    b.addEventListener('click', function () {
      st.fams = [b.getAttribute('data-family')]; sync(); render(true);
      var cat = document.getElementById('catalogue'); if (cat) cat.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  });

  /* sliders (two stacked native ranges per filter: keyboard + screen-reader friendly) */
  var sl = document.getElementById('dd-sliders');
  sl.innerHTML = Object.keys(STEPS).map(function (k) {
    var S = STEPS[k], max = S.s.length - 1;
