import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import path from "node:path";
import {
  HOME_DESCRIPTION_BEFORE, HOME_TITLE_BEFORE, LEGACY_HOME_TITLE_BEFORE, SITE_DESCRIPTION_BEFORE,
  homeDescription, homeTitle, legacyHomeTitle, siteDefaultTitle, siteDescription,
} from "../lib/dedicated/site-title.ts";

/**
 * The site-wide title gains "Dedicated Bare Metal Servers" ONLY at launch
 * (Setting dedicated_public_enabled). Before launch every string is byte-for-byte
 * what the site said before this change.
 */
const ROOT = path.resolve(__dirname, "..");
const read = (p: string) => readFileSync(path.join(ROOT, p), "utf8");

test("before launch: unchanged strings", () => {
  assert.equal(siteDefaultTitle("Nxeon", false), "Nxeon — Cloud VPS Hosting, Game Servers & Domains");
  assert.equal(siteDescription(false), SITE_DESCRIPTION_BEFORE);
  assert.equal(homeTitle(false), HOME_TITLE_BEFORE);
  assert.equal(homeDescription(false), HOME_DESCRIPTION_BEFORE);
  assert.equal(legacyHomeTitle(false), LEGACY_HOME_TITLE_BEFORE);
  // the pre-change literals still match what the registry / legacy page carried
  assert.ok(read("app/nxm/_seo/registry.ts").includes(JSON.stringify(HOME_TITLE_BEFORE)));
});

test("after launch: bare metal is named, the 47-seconds tagline survives in the home description", () => {
  assert.match(siteDefaultTitle("Nxeon", true), /Dedicated Bare Metal Servers/);
  assert.match(siteDescription(true), /dedicated bare metal servers/i);
  assert.match(homeTitle(true), /Dedicated Bare Metal Servers/);
  assert.match(homeDescription(true), /47 seconds/);
  assert.ok(homeTitle(true).length <= 62, "fits a search result title");
  assert.ok(homeDescription(true).length <= 158, "fits a search result description");
});

test("every title site reads the launch flag (never on by default)", () => {
  assert.match(read("app/layout.tsx"), /getSettingBool\("dedicated_public_enabled", false\)/);
  assert.match(read("app/nxm/page.tsx"), /const launched = await dedicatedPublicEnabled\(\)/);
  assert.match(read("app/page.tsx"), /const launched = await dedicatedPublicEnabled\(\)/);
});
EOF
